// gpt-oss models are REASONING models: hidden reasoning tokens count against max_tokens, so small caps
// (100-400) often get used up before any answer is written -> empty replies. Fix once, for every call:
// low reasoning effort + headroom on the cap. If the API rejects reasoning_effort, retry without it.
{
  const _completions = groq.chat.completions;
  const _origCreate = _completions.create.bind(_completions);
  _completions.create = async function (body, opts) {
    if (body && /gpt-oss/i.test(String(body.model || ''))) {
      body = { reasoning_effort: 'low', ...body };
      if (body.max_tokens) body.max_tokens = Math.min(body.max_tokens + 700, 8000);
    }
    try {
      return await _origCreate(body, opts);
    } catch (e) {
      if (body && body.reasoning_effort && /reasoning|unrecognized|unknown|invalid/i.test(String(e.message))) {
        const { reasoning_effort, ...rest } = body;
        return _origCreate(rest, opts);
      }
      throw e;
    }
  };
}
