// ── Fix DB values that exceeded Number.MAX_SAFE_INTEGER (crashes better-sqlite3 reads) ──
// This happens when owner rows get double-applied and a column ends up at 2×MAX_SAFE_INTEGER.
// SQLite handles 64-bit ints natively so the comparison runs safely inside SQLite,
// and the UPDATE result is just a row count — no large number ever touches JS.
try {
  db.prepare("UPDATE users SET cash=999999999999999         WHERE cash         > 999999999999999").run();
  db.prepare("UPDATE users SET bank=999999999999999         WHERE bank         > 999999999999999").run();
  db.prepare("UPDATE users SET total_earned=999999999999999 WHERE total_earned > 999999999999999").run();
  db.prepare("UPDATE users SET total_lost=999999999999999   WHERE total_lost   > 999999999999999").run();
  console.log('[DB] ✅ overflow values clamped to MAX_SAFE_INTEGER');
} catch(e) { console.error('[DB overflow fix]', e.message); }

