// ============ DB HELPERS ============
function getUser(id, name) {
  let u = db.prepare('SELECT * FROM users WHERE id=?').get(id);
  if (!u) {
    db.prepare('INSERT OR IGNORE INTO users (id,name,cash,bank,level,xp,wins,losses,total_earned,total_lost) VALUES (?,?,500,0,1,0,0,0,0,0)').run(id, name||'Unknown');
    u = db.prepare('SELECT * FROM users WHERE id=?').get(id);
  }
  if (!u.level||u.level<1) { db.prepare('UPDATE users SET level=1 WHERE id=?').run(id); u.level=1; }
  if (u.xp==null) { db.prepare('UPDATE users SET xp=0 WHERE id=?').run(id); u.xp=0; }
  return u;
}

