// ── Bug Activation Codes ────────────────────────────────────────────────────
db.exec(`CREATE TABLE IF NOT EXISTS bug_codes (
  code       TEXT PRIMARY KEY,
  tier       TEXT NOT NULL,
  created_at INTEGER DEFAULT 0,
  expires_at INTEGER DEFAULT 0,   -- code expires 48h after generation if unused
  used       INTEGER DEFAULT 0,
  used_by    TEXT DEFAULT '',
  used_at    INTEGER DEFAULT 0
)`);

function generateBugCode(tier) {
  const prefix = tier === 'monthly' ? 'MO' : 'WK';
  const r      = _crypto.randomBytes(6).toString('hex').toUpperCase();
  const code   = `${prefix}-${r.slice(0,4)}-${r.slice(4,8)}-${r.slice(8,12)}`;
  db.prepare(`INSERT INTO bug_codes (code, tier, created_at, expires_at) VALUES (?, ?, ?, ?)`)
    .run(code, tier, Date.now(), Date.now() + 48 * 3600 * 1000);
  return code;
}

function redeemBugCode(code, userId) {
  const row = db.prepare('SELECT * FROM bug_codes WHERE code=? AND used=0').get(String(code).toUpperCase().trim());
  if (!row)               return { ok: false, reason: 'invalid' };
  if (Date.now() > row.expires_at) return { ok: false, reason: 'expired' };
  db.prepare('UPDATE bug_codes SET used=1, used_by=?, used_at=? WHERE code=?')
    .run(String(userId), Date.now(), row.code);
  grantBugAccess(userId, row.tier, 'activation_code');
  return { ok: true, tier: row.tier };
}

function listUnusedCodes() {
  return db.prepare('SELECT * FROM bug_codes WHERE used=0 AND expires_at > ? ORDER BY created_at DESC')
    .all(Date.now());
}

// ── Bug access check ────────────────────────────────────────────────────────
// Check if a userId has valid bug access (owner/sudo always pass)
function hasBugAccess(userId) {
  if (isOwner(userId) || isSudo(userId)) return true;
  try {
    const row = db.prepare('SELECT expires_at FROM bug_access WHERE id=?').get(String(userId));
    if (!row) return false;
    if (row.expires_at === 0) return true;          // lifetime grant
    return Date.now() < row.expires_at;
  } catch (_) { return false; }
}

// Get bug access info for a user
function getBugAccessInfo(userId) {
  try { return db.prepare('SELECT * FROM bug_access WHERE id=?').get(String(userId)); }
  catch (_) { return null; }
}

// Grant bug access
function grantBugAccess(userId, tier, grantedBy, note = '') {
  const now = Date.now();
  const dur = tier === 'monthly' ? 30 * 24 * 3600 * 1000 : 7 * 24 * 3600 * 1000;
  const expires = now + dur;
  db.prepare(`INSERT INTO bug_access (id, tier, granted_by, granted_at, expires_at, note)
    VALUES (?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET tier=excluded.tier, granted_by=excluded.granted_by,
      granted_at=excluded.granted_at, expires_at=excluded.expires_at, note=excluded.note`)
    .run(String(userId), tier, String(grantedBy), now, expires, note);
  return expires;
}

// Revoke bug access
function revokeBugAccess(userId) {
  db.prepare('DELETE FROM bug_access WHERE id=?').run(String(userId));
}

// List all bug access users
function listBugAccessUsers() {
  return db.prepare('SELECT * FROM bug_access ORDER BY expires_at DESC').all();
}
const _visitSeen = new Map();
function trackVisitor(id, platform, started) {
  try {
    id = String(id || ''); if (!id) return;
    const now = Date.now();
    const key = id + (started ? ':s' : '');
    if (now - (_visitSeen.get(key) || 0) < 60000) return;   // at most one write a minute per person
    _visitSeen.set(key, now);
    db.prepare(`INSERT INTO bot_visitors (id, platform, first_seen, last_seen, started) VALUES (?,?,?,?,?)
      ON CONFLICT(id) DO UPDATE SET last_seen=excluded.last_seen, platform=excluded.platform,
        first_seen=CASE WHEN bot_visitors.first_seen=0 THEN excluded.first_seen ELSE bot_visitors.first_seen END,
        started=MAX(bot_visitors.started, excluded.started)`).run(id, platform, now, now, started ? 1 : 0);
  } catch (_) {}
}

// Telegram numeric id of the owner: learned the first time he writes from @OWNER_TG (or set OWNER_TG_ID in .env),
// so he is still recognised even if he changes or hides his Telegram username.
let _ownerTgIdCache = null;
function _ownerTgIdGet() {
  if (process.env.OWNER_TG_ID) return String(process.env.OWNER_TG_ID).replace(/\D/g, '');
  if (_ownerTgIdCache !== null) return _ownerTgIdCache;
  try { _ownerTgIdCache = db.prepare('SELECT value FROM bot_kv WHERE key=?').get('owner_tg_id')?.value || ''; return _ownerTgIdCache; }
  catch (_) { return ''; }
}
function _learnOwnerTgId(id) {
  const v = String(id || '').replace(/\D/g, '');
  if (!v || _ownerTgIdGet() === v) return;
  try { db.prepare('INSERT INTO bot_kv (key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run('owner_tg_id', v); _ownerTgIdCache = v; } catch (_) {}
}
function isOwner(id) {
  const s = String(id||'');
  { const _oid = _ownerTgIdGet(); if (_oid && (s === _oid || s === 'tg_' + _oid)) return true; }
  const waOwner = 'wa_' + MY_WA.replace(/\D/g,'');
  const tgOwner = 'tg_' + OWNER_TG;
  // Direct match
  if (s===tgOwner || s===OWNER_TG || s===waOwner || s===MY_WA.replace(/\D/g,'')) return true;
  // LID-based match: when WhatsApp group uses @lid privacy IDs instead of phone numbers
  if (MY_WA_LID && (s==='wa_'+MY_WA_LID || s===MY_WA_LID)) return true;
  // Alias-aware: check if this id resolves TO an owner id
  try { const r=resolveId(s); if(r!==s&&(r===tgOwner||r===OWNER_TG||r===waOwner)) return true; } catch(_){}
  // Reverse alias: check if any owner id resolves TO this id
  try { if(resolveId(waOwner)===s || resolveId(tgOwner)===s) return true; } catch(_){}
  return false;
}
function isSudo(id) { return isOwner(id)||!!db.prepare('SELECT 1 FROM sudo_users WHERE id=?').get(id); }
// Self-command context: while the LINKED account's own message is being processed, that account counts as a
// group moderator for GROUP-MANAGEMENT commands only (antilink, welcome, kick...). It does NOT grant real sudo,
// so economy / owner-only commands stay locked. AsyncLocalStorage keeps it scoped to that one message.
const { AsyncLocalStorage } = require('async_hooks');
const _selfCtx = new AsyncLocalStorage();
// Group-management permission: bot owner/sudo, the person who LINKED this WhatsApp account, or a real group admin.
// The context is filled per message in the WA handler (linked / groupAdmin / botAdmin).
function isGroupMod(id) {
  if (isSudo(id)) return true;
  const c = _selfCtx.getStore();
  return !!c && c.userId === id && !!(c.linked || c.groupAdmin);
}
// Extra line for protection commands (.antilink etc.) when the linked account is not a group admin.
function botAdminNote() {
  const c = _selfCtx.getStore();
  return c && c.botAdmin === false
    ? '\n\n⚠️ I\'m not a group admin here, so I can\'t delete messages or remove anyone. Make the linked account admin for this to work.'
    : '';
}

// Returns the raw (non-aliased) row ID for a userId — i.e. the reverse of resolveId.
// If userId is already a primary_id, returns it unchanged.
function rawIdOf(userId) {
  try {
    const row = db.prepare('SELECT alt_id FROM aliases WHERE primary_id=? LIMIT 1').get(userId);
    return row ? row.alt_id : userId;
  } catch(_) { return userId; }
}

function ensureOwnerRich(userId, name, force=false) {
  if (!OWNER_GOD_MODE) return; // fair play: owner earns like everyone else
  // force=true bypasses isOwner check — used when senderNumber already confirmed matches MY_WA
  if (!force && !isOwner(userId)) return;
  getUser(userId, name);
  // All owner ID variants — covers tg, wa, raw number.
  // ALWAYS include the actual userId passed in so alias chains never cause a mismatch.
  const ownerIds = [
    'tg_' + OWNER_TG, OWNER_TG,
    'wa_' + MY_WA, MY_WA,
    resolveId('wa_' + MY_WA), resolveId('tg_' + OWNER_TG),
    userId,           // exact ID that will be queried by .bal / .profile
    rawIdOf(userId),  // also update the underlying row if userId is an alias
  ].filter((v,i,a)=>v&&a.indexOf(v)===i); // dedupe
  const stmt = db.prepare(`UPDATE users SET
    cash=999999999999999,
    bank=999999999999999,
    level=9999,
    xp=999999,
    wins=999999,
    losses=0,
    total_earned=999999999999999,
    prestige=99,
    vip_expires=9999999999999
  WHERE id=?`);
  for (const id of ownerIds) {
    try { getUser(id, name || 'LORD'); stmt.run(id); } catch(_){}
    // ── AURA: max out all aura stats for owner ──
    try {
      db.prepare('INSERT OR IGNORE INTO aura_users (user_id) VALUES (?)').run(id);
      const now2 = new Date();
      const thisWeek2  = `${now2.getFullYear()}-W${Math.ceil(now2.getDate()/7)}`;
      const thisMonth2 = `${now2.getFullYear()}-${now2.getMonth()+1}`;
      db.prepare(`UPDATE aura_users SET
        aura=99999999,
        realm='Divine',
        realm_xp=9999999,
        shards=999999,
        solar_aura=9999999,
        solar_week=?,
        lunar_aura=9999999,
        lunar_month=?,
        multiplier=10.0,
        multiplier_expires=9999999999999,
        active_title='Aura God'
      WHERE user_id=?`).run(thisWeek2, thisMonth2, id);
      // Award all default titles to owner
      const titles2 = ['Aura God','Void Touched','Realm Walker','Bond Keeper','Legend','Rich One','Game Master','Veteran'];
      for (const t of titles2) {
        try { db.prepare("INSERT OR IGNORE INTO titles (user_id,title,earned_at) VALUES (?,?,?)").run(id, t, now2.toISOString()); } catch(_){}
      }
    } catch(_){}
  }
}

function addCash(id, amount) {
  if (OWNER_GOD_MODE && isOwner(id)) {
    // Owner money never moves — always restored to max
    db.prepare('UPDATE users SET cash=999999999999999,bank=999999999999999,total_earned=999999999999999,losses=0 WHERE id=?').run(id);
    return;
  }
  if (amount>0) db.prepare('UPDATE users SET cash=cash+?,total_earned=total_earned+? WHERE id=?').run(amount,amount,id);
  else db.prepare('UPDATE users SET cash=MAX(0,cash+?),total_lost=total_lost+? WHERE id=?').run(amount,Math.abs(amount),id);
}

function addXP(id, gain) {
  const u = db.prepare('SELECT xp,level FROM users WHERE id=?').get(id);
  if (!u) return null;
  let xp=(u.xp||0)+gain, level=u.level||1, leveled=false;
  while(xp>=level*100){xp-=level*100;level++;leveled=true;}
  db.prepare('UPDATE users SET xp=?,level=? WHERE id=?').run(xp,level,id);
  return leveled?level:null;
}

function setField(id, field, value) { db.prepare(`UPDATE users SET ${field}=? WHERE id=?`).run(value,id); }
function addItem(id, item, qty) { db.prepare('INSERT INTO inventory (user_id,item,quantity) VALUES (?,?,?) ON CONFLICT(user_id,item) DO UPDATE SET quantity=quantity+?').run(id,item,qty,qty); }
function getInventory(id) { return db.prepare('SELECT item,quantity FROM inventory WHERE user_id=? AND quantity>0').all(id); }
function hasItem(id, item) { const r=db.prepare('SELECT quantity FROM inventory WHERE user_id=? AND item=?').get(id,item); return r&&r.quantity>0; }
function removeItem(id, item, qty=1) { if (OWNER_GOD_MODE && isOwner(id)) return; db.prepare('UPDATE inventory SET quantity=MAX(0,quantity-?) WHERE user_id=? AND item=?').run(qty,id,item); }

