// ============ ACCOUNT PAIRING ============
// Lets a person link their Telegram account and WhatsApp account into one
// shared profile. Any number of users can pair independently — each code
// exchange only ever affects the two accounts involved in it.
//
// resolveId() is used on every platform id BEFORE economy/game lookups so
// paired accounts transparently share one row. The pairing commands
// themselves operate on the RAW unresolved id — that\'s how you can tell
// which account you\'re currently on.

function resolveId(id) {
  const row = db.prepare('SELECT primary_id FROM aliases WHERE alt_id=?').get(id);
  return row ? row.primary_id : id;
}

function generatePairCode(requesterId) {
  db.prepare('DELETE FROM pairing_codes WHERE expires_at < ?').run(Date.now());
  db.prepare('DELETE FROM pairing_codes WHERE requester_id=?').run(requesterId);
  let code;
  do { code = String(randomInt(100000, 999999)); }
  while (db.prepare('SELECT 1 FROM pairing_codes WHERE code=?').get(code));
  db.prepare('INSERT INTO pairing_codes (code,requester_id,expires_at) VALUES (?,?,?)')
    .run(code, requesterId, Date.now() + 10 * 60 * 1000);
  return code;
}

function mergeAccounts(primaryId, secondaryId) {
  const secondary = db.prepare('SELECT * FROM users WHERE id=?').get(secondaryId);
  if (!secondary) return;
  getUser(primaryId, secondary.name);
  db.prepare(`UPDATE users SET
    cash=cash+?, bank=bank+?,
    total_earned=total_earned+?, total_lost=total_lost+?,
    wins=wins+?, losses=losses+?,
    xp=xp+?
  WHERE id=?`).run(
    secondary.cash||0, secondary.bank||0,
    secondary.total_earned||0, secondary.total_lost||0,
    secondary.wins||0, secondary.losses||0,
    secondary.xp||0, primaryId
  );
  for (const it of db.prepare('SELECT item,quantity FROM inventory WHERE user_id=?').all(secondaryId)) {
    addItem(primaryId, it.item, it.quantity);
  }
  db.prepare('DELETE FROM inventory WHERE user_id=?').run(secondaryId);
  db.prepare('DELETE FROM users WHERE id=?').run(secondaryId);
}

function consumePairCode(code, rawConsumerId) {
  db.prepare('DELETE FROM pairing_codes WHERE expires_at < ?').run(Date.now());
  const row = db.prepare('SELECT * FROM pairing_codes WHERE code=?').get(code);
  if (!row) return { ok: false, reason: 'invalid' };

  const primaryId   = resolveId(row.requester_id);
  const secondaryId = resolveId(rawConsumerId);

  if (rawConsumerId === row.requester_id) return { ok: false, reason: 'self' };
  if (primaryId === secondaryId)          return { ok: false, reason: 'already-linked' };

  mergeAccounts(primaryId, secondaryId);
  db.prepare('INSERT OR REPLACE INTO aliases (alt_id,primary_id) VALUES (?,?)').run(secondaryId, primaryId);
  // Flatten any existing aliases that pointed at secondaryId so every alias
  // stays one hop deep and resolveId() never has to chase a chain.
  db.prepare('UPDATE aliases SET primary_id=? WHERE primary_id=?').run(primaryId, secondaryId);
  db.prepare('DELETE FROM pairing_codes WHERE code=?').run(row.code);
  return { ok: true };
}

function unpairAccount(rawId) {
  const asAlt = db.prepare('SELECT primary_id FROM aliases WHERE alt_id=?').get(rawId);
  if (asAlt) {
    db.prepare('DELETE FROM aliases WHERE alt_id=?').run(rawId);
    getUser(rawId, null); // give the now-independent id a fresh row
    return true;
  }
  const hasDependents = db.prepare('SELECT 1 FROM aliases WHERE primary_id=?').get(rawId);
  if (hasDependents) {
    db.prepare('DELETE FROM aliases WHERE primary_id=?').run(rawId);
    return true;
  }
  return false;
}

function handlePairing(cmd, rawUserId, name, args) {
  if (cmd !== '.pair' && cmd !== '.unpair') return null;

  if (cmd === '.unpair') {
    return unpairAccount(rawUserId)
      ? '💗 unlinked. this account stands on its own again.'
      : "...this account isn\'t linked to anything.";
  }

  // .pair with no argument — generate a code for the other platform to redeem
  if (!args[0]) {
    const code = generatePairCode(rawUserId);
    return `🔗 pairing code: *${code}*\n\nexpires in 10 minutes.\n\nfrom your OTHER account (WhatsApp or Telegram), send:\n  .pair ${code}\n\nyour cash, inventory and level will merge into one shared profile.`;
  }

  // .pair <code> — redeem someone else's code
  const result = consumePairCode(args[0].trim(), rawUserId);
  if (!result.ok) {
    const msgs = {
      invalid:        '❄️ invalid or expired code. request a fresh one with .pair',
      self:           "❄️ that\'s your own code. use it from your OTHER account.",
      'already-linked': '💗 those accounts are already linked.',
    };
    return msgs[result.reason] || '❄️ something went wrong. try again.';
  }
  return '💗 linked! your accounts now share one balance and profile.';
}

// ============ UTILS ============
function sleep(ms) { return new Promise(r=>setTimeout(r,ms)); }
function randomInt(min,max) { return Math.floor(Math.random()*(max-min+1))+min; }
function fmt(n) { return '🪙 '+Number(n||0).toLocaleString()+' naura'; }
function fmtUptime() { const s=Math.floor((Date.now()-START_TIME)/1000),d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60); return `${d}d ${h}h ${m}m`; }

