const BOT_PFP_PATH = './seana-pfp.jpg';
_migrateOld('./jinwoo-pfp.jpg', BOT_PFP_PATH);

// ── Sticker System ─────────────────────────────────────────────────────────────
const fs = require('fs');
const path = require('path');
const STICKER_DIR = './seana-stickers';
_migrateOld('./jinwoo-stickers', STICKER_DIR);
const STICKER_PACK_FILE = './sticker-pack.json';
const STICKER_PACK_DEFAULT = process.env.STICKER_PACK || '';   // Telegram sticker pack name
let STICKER_PACK = STICKER_PACK_DEFAULT;
try { if (fs.existsSync(STICKER_PACK_FILE)) { const _sp = JSON.parse(fs.readFileSync(STICKER_PACK_FILE, 'utf8')).pack; if (_sp) STICKER_PACK = _sp; } } catch (_) {}

// A valid WhatsApp-sendable sticker must be a real static WebP (RIFF....WEBP).
// Telegram packs can contain animated (.tgs) / video (.webm) stickers that were being
// saved as ".webp" — WhatsApp shows those as a blank bubble ("Can't view sticker information").
function isValidWebp(buf) {
  return Buffer.isBuffer(buf) && buf.length > 12 &&
    buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WEBP';
}

// Telegram VIDEO stickers are .webm. WhatsApp wants an animated WebP (512x512, under ~500 KB), so convert with ffmpeg.
function isAnimatedWebp(buf) {
  return isValidWebp(buf) && buf.indexOf('ANIM', 12) > -1 && buf.indexOf('ANIM', 12) < 200;
}
async function webmToAnimatedWebp(webmBuf) {
  const os = require('os'), { spawn } = require('child_process');
  let ffmpegPath; try { ffmpegPath = require('ffmpeg-static'); } catch (_) { ffmpegPath = 'ffmpeg'; }
  const id = Date.now() + '_' + Math.floor(Math.random() * 1e6);
  const inP = path.join(os.tmpdir(), `tgv_${id}.webm`), outP = path.join(os.tmpdir(), `tgv_${id}.webp`);
  fs.writeFileSync(inP, webmBuf);
  const run = (args) => new Promise((resolve) => {
    const ff = spawn(ffmpegPath, args); let done = false;
    const t = setTimeout(() => { if (!done) { done = true; try { ff.kill('SIGKILL'); } catch (_) {} resolve(false); } }, 45000);
    ff.on('error', () => { if (!done) { done = true; clearTimeout(t); resolve(false); } });
    ff.on('close', (code) => { if (!done) { done = true; clearTimeout(t); resolve(code === 0); } });
  });
  try {
    // quality/framerate ladder until the file fits WhatsApp's size limit
    for (const [fps, q] of [[15, 60], [12, 45], [10, 30], [8, 20]]) {
      const vf = `fps=${fps},scale=512:512:force_original_aspect_ratio=decrease,pad=512:512:(ow-iw)/2:(oh-ih)/2:color=0x00000000,format=yuva420p`;
      const base = ['-y', '-loglevel', 'error'];
      const tail = ['-vf', vf, '-an', '-loop', '0', '-c:v', 'libwebp_anim', '-lossless', '0', '-q:v', String(q), '-compression_level', '6', '-t', '3', outP];
      // libvpx-vp9 keeps the transparent background; fall back to the default decoder if it isn't built in
      let ok = await run([...base, '-c:v', 'libvpx-vp9', '-i', inP, ...tail]);
      if (!ok) ok = await run([...base, '-i', inP, ...tail]);
      if (!ok || !fs.existsSync(outP)) continue;
      const out = fs.readFileSync(outP);
      if (isValidWebp(out) && out.length <= 500 * 1024) return out;
    }
    return null;
  } finally { try { fs.unlinkSync(inP); } catch (_) {} try { fs.unlinkSync(outP); } catch (_) {} }
}

let _packStats = { total: 0, picture: 0, video: 0, tgs: 0, thumbs: 0, failed: 0 };
// Download and cache the sticker pack from Telegram on startup
async function downloadStickerPack() {
  try {
    if (!fs.existsSync(STICKER_DIR)) fs.mkdirSync(STICKER_DIR, { recursive: true });
    // Purge previously cached broken files (not real WebP)
    for (const f of fs.readdirSync(STICKER_DIR)) {
      const fp = path.join(STICKER_DIR, f);
      try {
        if (!f.endsWith('.webp') || !isValidWebp(fs.readFileSync(fp))) { fs.unlinkSync(fp); console.log('[stickers] removed invalid', f); }
      } catch(_) {}
    }
    if (!STICKER_PACK) return 0;   // no Telegram pack configured: she uses only the stickers you give her
    const existing = fs.readdirSync(STICKER_DIR).filter(f => f.endsWith('.webp') && !/^(custom_|auto_|wed_)/.test(f));
    if (existing.length > 0) {
      console.log(`[stickers] ${existing.length} valid stickers already cached`);
      return existing.length;
    }
    console.log('[stickers] downloading pack from Telegram...');
    const res = await axios.get(`https://api.telegram.org/bot${BOT_TOKEN}/getStickerSet?name=${STICKER_PACK}`);
    const stickers = res.data?.result?.stickers || [];
    let count = 0, skipped = 0;
    _packStats = { total: stickers.length, picture: 0, video: 0, tgs: 0, thumbs: 0, failed: 0 };
    const fetchFile = async (fileId) => {
      const fr = await axios.get(`https://api.telegram.org/bot${BOT_TOKEN}/getFile?file_id=${fileId}`);
      const fp = fr.data?.result?.file_path; if (!fp) return null;
      const rs = await axios.get(`https://api.telegram.org/file/bot${BOT_TOKEN}/${fp}`, { responseType: 'arraybuffer' });
      return { fp, buf: Buffer.from(rs.data) };
    };
    for (const sticker of stickers) {
      try {
        let buf = null;
        if (sticker.is_animated) _packStats.tgs++; else if (sticker.is_video) _packStats.video++; else _packStats.picture++;
        // 1) picture stickers: use as-is. 2) video stickers: convert webm -> animated webp.
        if (!sticker.is_animated) {
          const f = await fetchFile(sticker.file_id);
          if (f && sticker.is_video && f.fp.endsWith('.webm')) buf = await webmToAnimatedWebp(f.buf);
          else if (f && f.fp.endsWith('.webp')) buf = f.buf;
        }
        // 3) animated .tgs (Lottie) or a video that would not convert: use Telegram's still preview so the sticker is not lost
        if (!buf || !isValidWebp(buf)) {
          const th = sticker.thumbnail || sticker.thumb;
          if (th?.file_id) {
            const t = await fetchFile(th.file_id);
            if (t && t.fp.endsWith('.webp') && isValidWebp(t.buf)) { buf = t.buf; _packStats.thumbs++; }
          }
        }
        if (!buf || !isValidWebp(buf)) { skipped++; _packStats.failed++; continue; }
        fs.writeFileSync(path.join(STICKER_DIR, `sticker_${count}.webp`), buf);
        count++;
        await sleep(200); // be nice to the API
      } catch(e) { skipped++; _packStats.failed++; console.error('[sticker dl]', e.message); }
    }
    console.log(`[stickers] downloaded ${count} stickers (skipped ${skipped} unusable)`);
    return count;
  } catch(e) {
    console.error('[sticker pack]', e.message);
  }
}

let _lastStickerFile = null;
function getRandomStickerPath(noAnimated) {
  try {
    if (!fs.existsSync(STICKER_DIR)) return null;
    const files = fs.readdirSync(STICKER_DIR).filter(f => f.endsWith('.webp'))
      .filter(f => { try { const b = fs.readFileSync(path.join(STICKER_DIR, f)); return isValidWebp(b) && !(noAnimated && isAnimatedWebp(b)); } catch(_) { return false; } });
    if (!files.length) return null;
    let pick = files[Math.floor(Math.random() * files.length)];
    if (files.length > 1 && pick === _lastStickerFile) pick = files[(files.indexOf(pick) + 1) % files.length];
    _lastStickerFile = pick;
    return path.join(STICKER_DIR, pick);
  } catch(_) { return null; }
}

