const BOT_PIC_CAPTIONS = [
  "here I am 🥰",
  "you asked, so here's me 💕",
  "this is me, do you like it? 🌸",
  "just for you 😘",
  "took this one earlier, hehe 🙈",
  "how do I look? 😌",
];
function getPicCaption() { return BOT_PIC_CAPTIONS[randomInt(0, BOT_PIC_CAPTIONS.length-1)]; }

function isPicRequest(text) {
  const t = text.toLowerCase();
  return /\b(send|show|share|give|drop|post|see|view|look at)\b.*\b(pic(ture)?s?|photo|image|selfie|face|yourself|how you look)\b/i.test(t)
    || /\b(pic(ture)?s?|photo|selfie|image)\b.*\b(of you|yourself|ur|your)\b/i.test(t)
    || /\byour (pic(ture)?|photo|selfie|face|image)\b/i.test(t)
    || /\bwhat (do )?you look like\b/i.test(t)
    || /\bshow (me |us )?(yourself|your face|your pic)\b/i.test(t)
    || /\bcan i see you\b/i.test(t)
    || /\bi want to see (you|your face)\b/i.test(t)
    || /\bsend (me )?(your )?(pic|photo|selfie)\b/i.test(t)
    || /\b(ur|your) face\b/i.test(t);
}

// Human-like delays: AI runs IN PARALLEL with typing so total wait ≈ max(AI time, typing time)
// This is what makes it feel fast AND human at the same time.
// ============ PER-CHAT QUEUE (commands.js pattern) ============
const _chatQueues = new Map();
function _qTail(id) { return _chatQueues.get(id)??Promise.resolve(); }
function _qSet(id,p) {
  _chatQueues.set(id,p);
  p.finally(()=>{ if(_chatQueues.get(id)===p) _chatQueues.delete(id); });
}
// Plain serialiser — chains tasks for same chat, independent between chats
function queueTask(id, fn) {
  const t = _qTail(id).then(()=>fn().catch(e=>console.error('[queue]',e.message)));
  _qSet(id, t.catch(()=>{}));
  return t;
}

// WhatsApp human-like reply — matches commands.js 4-stage pattern exactly:
//   1. Reading pause (user sees her come online but not yet typing)
//   2. Mark message as read (double tick appears after natural delay)
//   3. Composing indicator runs in parallel with AI fetch
//   4. Send — always send something even if AI returned empty
// Normal replies are serialised per-chat so she never appears to type
// in two conversations at once. Game replies bypass the queue for speed.
// Build a proper WhatsApp mentions[] from any "@<number>" tokens in a reply, using the
// ORIGINAL mention JIDs (LID or phone) the sender tagged — so the client shows a real
// name/tag instead of a raw number like @222342588399660.
function replyMentions(reply, srcJids = []) {
  try {
    const nums = [...new Set([...String(reply || '').matchAll(/@(\d{6,})/g)].map(m => m[1]))];
    if (!nums.length) return undefined;
    const out = [];
    for (const n of nums) {
      const hit = (srcJids || []).find(j => String(j).split('@')[0].split(':')[0] === n);
      out.push(hit || `${n}@s.whatsapp.net`);
    }
    return out;
  } catch (_) { return undefined; }
}

// ── Outbound safety guard: keeps reply speed human-like so WhatsApp does not flag the account ──
const _waSendLog = new WeakMap();   // sock -> { all: [ts], chats: Map<jid,[ts]>, last: ts }
async function _waSendSlot(sock, jid) {
  let st = _waSendLog.get(sock);
  if (!st) { st = { all: [], chats: new Map(), last: 0 }; _waSendLog.set(sock, st); }
  const now = Date.now();
  st.all = st.all.filter(t => now - t < 60000);
  const arr = (st.chats.get(jid) || []).filter(t => now - t < 60000);
  const isGrp = String(jid).endsWith('@g.us');
  if (st.all.length >= 40 || arr.length >= (isGrp ? 20 : 12)) return false;   // too fast: drop this reply
  const gap = 1200 + Math.floor(Math.random() * 900);                       // min gap between any two sends
  const wait = Math.max(0, st.last + gap - now);
  st.last = now + wait;
  st.all.push(now + wait); arr.push(now + wait); st.chats.set(jid, arr);
  if (wait) await sleep(wait);
  return true;
}

async function humanReplyWA(sock, jid, msgOrFn, {mentionJids,isGame=false,msgKey,quotedMsg}={}) {
  const run = async () => {
    // 1. Reading pause — match Telegram's snappier feel
    await sleep(randomInt(800, 1800));

    // 2. Read receipt — double tick appears after the natural reading delay
    if(msgKey){ try{ await sock.readMessages([msgKey]); }catch(_){} }

    // 3. Composing indicator — match Telegram speed (2.5–4.5 s normal, 0.6–1.4 s games)
    const typingMs = isGame ? randomInt(600, 1400) : randomInt(2500, 4500);
    try{ await sock.sendPresenceUpdate('composing', jid); }catch(_){}

    // Keep composing visible — refresh every 4 s like Telegram does
    const refresher = setInterval(() => {
      sock.sendPresenceUpdate('composing', jid).catch(()=>{});
    }, 4000);

    // AI fetch runs in parallel with the typing window so total wait ≈ max(AI, typing)
    let message;
    try {
      [message] = await Promise.all([
        (async()=>{ try{ return typeof msgOrFn==='function' ? await msgOrFn() : msgOrFn; }catch(e){ console.error('[WA fn]',e.message); return null; } })(),
        sleep(typingMs),
      ]);
    } catch(e){ console.error('[WA parallel]', e.message); }
    finally { clearInterval(refresher); }

    // 4. Send — fall back to a random short reply if AI returned empty
    const _isGroupJid = String(jid).endsWith('@g.us');
    const _failedAi = !message || !String(message).trim() || FALLBACKS.some(f => String(message).includes(f));
    if(_failedAi && _isGroupJid){
      // In groups never post "my connection glitched…" style lines in front of everyone: stay quiet instead
      console.warn('[WA] AI had no answer — staying silent in group');
      try{ await sock.sendPresenceUpdate('paused', jid); }catch(_){}
      return;
    }
    if(!message || !String(message).trim()){
      console.warn('[WA] AI returned empty — using fallback');
      message = markAi(FALLBACKS[randomInt(0, FALLBACKS.length-1)]);
    }
    message = styleIfAi(message);

    try{
      const auto = mentionJids?.length ? null : waLid.mentionify(String(message));
      const content = {
        text: String(message),
        ...(mentionJids?.length ? { mentions: mentionJids } : (auto?.mentions?.length ? { mentions: auto.mentions } : {})),
      };
      // Baileys quoted option needs the FULL message object (not just msg.key).
      // Passing msg.key causes "Cannot read properties of undefined (reading 'fromMe')"
      const sendOpts = (quotedMsg && typeof quotedMsg === 'object') ? { quoted: quotedMsg } : {};
      await sock.sendMessage(jid, content, sendOpts);
      console.log(`[WA ✅] to ${jid}: "${String(message).slice(0,60)}"`);
    }catch(e){ console.error('[WA send]', e.message); }
    try{ await sock.sendPresenceUpdate('paused', jid); }catch(_){}
  };

  // Always run directly — queueTask() in the message handler already serialises
  // per-chat. Adding a second queue here on the same jid key caused a deadlock:
  // queueTask sets _chatQueues[jid] = t, then humanReplyWA called _qTail(jid)
  // and got t back, so it waited for t to finish before running — but t was
  // waiting for humanReplyWA to finish first. Neither ever resolved.
  return run();
}

// Telegram human-like reply — typing indicator refreshes every 4 s
// so it stays visible even during slow AI calls (Telegram drops it after 5 s)
async function humanReplyTG(ctx, msgOrFn, {isGame=false}={}) {
  const id = ctx.chat.id.toString();
  const run = async () => {
    await sleep(randomInt(800, 2000));
    const typingMs = isGame ? randomInt(600, 1400) : randomInt(2500, 4500);
    // Start typing indicator and keep refreshing it every 4 s
    try { await ctx.sendChatAction('typing'); } catch(_){}
    const refresher = setInterval(() => {
      ctx.sendChatAction('typing').catch(()=>{});
    }, 4000);
    let message;
    try {
      [message] = await Promise.all([
        (async()=>{ try { return typeof msgOrFn==='function' ? await msgOrFn() : msgOrFn; } catch(e) { return null; } })(),
        sleep(typingMs),
      ]);
    } catch(e) {
      console.error('[TG reply error]', e.message);
    } finally {
      clearInterval(refresher);
    }
    if (!message || !String(message).trim()) message = markAi(FALLBACKS[randomInt(0, FALLBACKS.length-1)]);
    message = styleIfAi(message);
    return ctx.reply(String(message), {reply_to_message_id: ctx.message?.message_id});
  };
  if (isGame) return run();
  const t = _qTail(id).then(() => Promise.race([
    run(),
    new Promise(res => setTimeout(res, 60_000)),   // never let one stuck reply block this chat's queue
  ])).catch(e => console.error('[TG reply queue]', e && e.message));
  _qSet(id, t.catch(()=>{}));
  return t;
}

