const activeGames = {};
const pendingDrops = {};
const pendingDuels = {};
// hackerId → { code, expires, reward, rIdx }  — awaiting typed hack-key
const pendingDutyChallenge = {};

// Generate a job-specific interactive duty challenge.
// Returns { code, prompt, successFlavor, failFlavor }
function generateDutyChallenge(job, rIdx) {
  const hex  = () => Math.random().toString(16).slice(2, 6).toUpperCase();
  const alph = () => Math.random().toString(36).slice(2, 5).toUpperCase();
  const num4 = () => String(Math.floor(Math.random() * 9000) + 1000);
  const num2 = () => String(Math.floor(Math.random() * 90) + 10);
  const TIMEOUT = 30;

  // ── HACKER ────────────────────────────────────────────────────────────────
  if (job === 'hacker') {
    const code = `${hex()}-${alph()}-${num4()}`;
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `💻 *DUTY INITIATED — BREACH PROTOCOL*\n` +
        `\`\`\`\n> CONNECTING TO TARGET...\n> BYPASSING FIREWALL [████████░░] 80%\n` +
        `> DEPLOYING PAYLOAD...\n> AUTHORIZATION KEY REQUIRED\n\`\`\`\n` +
        `🔑 Type this key within *${TIMEOUT}s* to complete the breach:\n\n` +
        `\`${code}\`\n\n⏳ _Failure = mission failed._`,
      successFlavor: `💻 *BREACH COMPLETE*\n\`\`\`\n> KEY ACCEPTED ✓\n> DATA EXFILTRATED\n> LOGS WIPED\n> DISCONNECTING CLEANLY\n\`\`\``,
      failFlavor:    `💻 *BREACH FAILED — TIMEOUT*\n\`\`\`\n> CONNECTION TERMINATED\n> INTRUSION DETECTED\n> TRACE ACTIVE — LAY LOW\n\`\`\``,
      wrongFlavor:   `💻 ❌ Wrong key rejected. Re-enter the correct code before time runs out!`,
    };
  }

  // ── POLICE ── radio codebook lookup (read the codebook, pick the match) ────
  if (job === 'police') {
    const codebook = [
      ['10-4',  'Acknowledged, message received'],
      ['10-20', 'Requesting your location'],
      ['10-33', 'Emergency — all units stand by'],
      ['10-70', 'Fire alarm reported'],
      ['10-80', 'Chase in progress'],
      ['10-99', 'Officer needs help NOW'],
    ];
    const shown  = [...codebook].sort(() => Math.random() - 0.5).slice(0, 3);
    const target = shown[Math.floor(Math.random() * shown.length)];
    const code   = target[0];
    const legend = shown.map(([c, m]) => `\`${c}\` — ${m}`).join('\n');
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `📻 *DISPATCH — RADIO CODE CHECK*\n` +
        `\`\`\`\n> INCOMING REPORT — SECTOR ${alph()}\n\`\`\`\n` +
        `Codebook:\n${legend}\n\n` +
        `📡 Report: *"${target[1]}"*\nWhich code matches? Reply within *${TIMEOUT}s*.`,
      successFlavor: `👮 *CORRECT CODE — DISPATCHED*\n\`\`\`\n> UNIT ON SCENE\n> SUSPECT APPREHENDED\n> SECTOR SECURE\n\`\`\``,
      failFlavor:    `👮 *RADIO SILENCE — DUTY FAILED*\n\`\`\`\n> NO RESPONSE RECEIVED\n> UNIT MARKED AWOL\n> SHIFT DOCKED\n\`\`\``,
      wrongFlavor:   `📻 ❌ Wrong code for that report. Check the codebook and re-enter!`,
    };
  }

  // ── ARMY ── bearing correction math ─────────────────────────────────────
  if (job === 'army') {
    const ops = ['STEELHAWK', 'IRON FIST', 'PHANTOM', 'RED DAWN', 'SILENT WOLF'];
    const opName = ops[Math.floor(Math.random() * ops.length)];
    const base = randomInt(0, 359);
    const corr = randomInt(1, 45) * (Math.random() < 0.5 ? -1 : 1);
    let adj = (base + corr) % 360; if (adj < 0) adj += 360;
    const code = String(adj);
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `🪖 *OPERATION ${opName} — TARGETING*\n` +
        `\`\`\`\n> TARGET BEARING ${base}°\n> WIND CORRECTION ${corr >= 0 ? '+' : ''}${corr}°\n` +
        `> COMPUTE ADJUSTED BEARING\n\`\`\`\n` +
        `🎯 Call the adjusted bearing (0–359) within *${TIMEOUT}s*.`,
      successFlavor: `🪖 *OPERATION SUCCESS — OBJECTIVE SECURED*\n\`\`\`\n> BEARING CONFIRMED\n> STRIKE EXECUTED\n> UNIT RETURNED SAFELY\n\`\`\``,
      failFlavor:    `🪖 *OPERATION SCRUBBED — WINDOW MISSED*\n\`\`\`\n> NO BEARING RECEIVED\n> MISSION ABORTED\n> DEBRIEF REQUIRED\n\`\`\``,
      wrongFlavor:   `🎯 ❌ Wrong bearing — recompute and re-enter before the window closes!`,
    };
  }

  // ── JUDGE ── weigh the evidence, rule the majority verdict ──────────────
  if (job === 'judge') {
    const caseNum = `CASE-${num4()}`;
    const evidencePool = [
      ['Fingerprints found at the scene', 'GUILTY'],
      ['Confirmed alibi with three witnesses', 'NOT-GUILTY'],
      ['Security footage shows the defendant fleeing', 'GUILTY'],
      ['No motive established', 'NOT-GUILTY'],
      ['Murder weapon traced to the defendant', 'GUILTY'],
      ['Contradicting witness statements', 'NOT-GUILTY'],
      ['DNA match at the scene', 'GUILTY'],
      ['Phone records place defendant elsewhere', 'NOT-GUILTY'],
    ];
    const picked = [...evidencePool].sort(() => Math.random() - 0.5).slice(0, 3); // odd count, no ties
    const guiltyCount = picked.filter(e => e[1] === 'GUILTY').length;
    const code = guiltyCount > picked.length / 2 ? 'GUILTY' : 'NOT-GUILTY';
    const list = picked.map(([e]) => `• ${e}`).join('\n');
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `⚖️ *COURT IN SESSION — ${caseNum}*\n` +
        `\`\`\`\n> PROSECUTION RESTS\n> DEFENSE RESTS\n\`\`\`\n` +
        `Evidence presented:\n${list}\n\n` +
        `🖊️ Weigh it and rule *GUILTY* or *NOT-GUILTY* within *${TIMEOUT}s*.`,
      successFlavor: `⚖️ *RULING SIGNED — COURT ADJOURNED*\n\`\`\`\n> VERDICT RECORDED\n> CASE CLOSED\n> JUSTICE SERVED\n\`\`\``,
      failFlavor:    `⚖️ *CONTEMPT — RULING UNSIGNED*\n\`\`\`\n> SESSION EXPIRED\n> CASE DISMISSED\n> BENCH FINE ISSUED\n\`\`\``,
      wrongFlavor:   `⚖️ ❌ Wrong verdict for this evidence — re-weigh it and rule again!`,
    };
  }

  // ── DOCTOR ── patient chart lookup (match symptom to RX code) ───────────
  if (job === 'doctor') {
    const chart = [
      ['RX-1', 'High fever and chills'],
      ['RX-2', 'Suspected bone fracture'],
      ['RX-3', 'Infected wound'],
      ['RX-4', 'Severe allergic reaction'],
      ['RX-5', 'Dehydration'],
      ['RX-6', 'Chest pain, possible cardiac event'],
    ];
    const shown  = [...chart].sort(() => Math.random() - 0.5).slice(0, 3);
    const target = shown[Math.floor(Math.random() * shown.length)];
    const code   = target[0];
    const legend = shown.map(([c, m]) => `\`${c}\` — ${m}`).join('\n');
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `🏥 *PATIENT CHARTS — WARD ${num2()}*\n` +
        `\`\`\`\n> NEW PATIENT ADMITTED\n\`\`\`\n` +
        `Chart:\n${legend}\n\n` +
        `💊 Patient presents: *"${target[1]}"*\nWhich RX code applies? Reply within *${TIMEOUT}s*.`,
      successFlavor: `🏥 *PRESCRIPTION SIGNED — PATIENT TREATED*\n\`\`\`\n> RX AUTHORIZED\n> TREATMENT ADMINISTERED\n> PATIENT RECOVERING\n\`\`\``,
      failFlavor:    `🏥 *RX LAPSED — PATIENT UNTREATED*\n\`\`\`\n> AUTHORIZATION EXPIRED\n> CHART FLAGGED\n> SHIFT DOCKED\n\`\`\``,
      wrongFlavor:   `💊 ❌ Wrong RX for that presentation. Recheck the chart and re-enter!`,
    };
  }

  // ── BUSINESS ── commission math ─────────────────────────────────────────
  if (job === 'business') {
    const dealValue  = randomInt(4, 40) * 1000;
    const pct        = randomInt(5, 20);
    const commission = Math.round(dealValue * pct / 100);
    const code       = String(commission);
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `💼 *BOARD MEETING — CONTRACT PENDING*\n` +
        `\`\`\`\n> DEAL VALUE: ${dealValue.toLocaleString()}\n> YOUR COMMISSION: ${pct}%\n\`\`\`\n` +
        `✍️ Calculate your commission and call it out within *${TIMEOUT}s* _(whole number, no commas)_.`,
      successFlavor: `💼 *DEAL CLOSED — CONTRACT EXECUTED*\n\`\`\`\n> COMMISSION CONFIRMED\n> FUNDS TRANSFERRED\n> PARTNERSHIP ACTIVE\n\`\`\``,
      failFlavor:    `💼 *DEAL DEAD — CONTRACT VOIDED*\n\`\`\`\n> NO FIGURE RECEIVED\n> OTHER PARTY WALKED\n> COMMISSION LOST\n\`\`\``,
      wrongFlavor:   `✍️ ❌ Wrong number — recalculate and re-enter before the deal dies!`,
    };
  }

  // ── TEACHER ── grade the exam question (mental math) ────────────────────
  if (job === 'teacher') {
    const a = Math.floor(Math.random() * 11) + 2;   // 2–12
    const b = Math.floor(Math.random() * 11) + 2;
    const answer = String(a * b);
    return {
      code: answer,
      timeout: TIMEOUT,
      prompt:
        `🍎 *MARKING TIME — EXAM ROOM ${num2()}*\n` +
        `\`\`\`\n> STUDENTS SUBMITTED THEIR WORK\n> GRADE THIS QUESTION TO PROCEED\n\`\`\`\n` +
        `📝 What is *${a} × ${b}*? Answer within *${TIMEOUT}s*:\n\n` +
        `_(type only the number)_\n\n⏳ _Wrong or late = class dismissed._`,
      successFlavor: `🍎 *PAPERS MARKED — CLASS DISMISSED*\n\`\`\`\n> CORRECT ANSWER ACCEPTED\n> GRADES SUBMITTED\n> STUDENTS PASS\n\`\`\``,
      failFlavor:    `🍎 *LESSON FAILED — TIME EXPIRED*\n\`\`\`\n> NO ANSWER RECEIVED\n> EXAM VOIDED\n> CLASS DISMISSED EARLY\n\`\`\``,
      wrongFlavor:   `📝 ❌ Wrong answer! Try again before time runs out!`,
    };
  }

  // ── FIREFIGHTER ── pressure math to hit target PSI ──────────────────────
  if (job === 'firefighter') {
    const eng    = `ENG-${randomInt(1, 9)}`;
    const target = randomInt(150, 250);
    const a      = randomInt(40, target - 20);
    const need   = target - a;
    const code   = String(need);
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `🚒 *DISPATCH — SIGNAL 99 REPORTED*\n` +
        `\`\`\`\n> STRUCTURE FIRE — BUILDING ${alph()}\n> ${eng} ON SCENE AT ${a} PSI\n` +
        `> TARGET PRESSURE: ${target} PSI\n\`\`\`\n` +
        `📡 How many more PSI is needed to hit target? Reply within *${TIMEOUT}s*.`,
      successFlavor: `🚒 *FIRE SUPPRESSED — ALL CLEAR*\n\`\`\`\n> TARGET PRESSURE HIT\n> FIRE CONTAINED\n> CREW RETURNED SAFELY\n\`\`\``,
      failFlavor:    `🚒 *STATION PENALTY — NO RESPONSE*\n\`\`\`\n> PRESSURE MISCALCULATED\n> FIRE UNCONTROLLED\n> SHIFT DOCKED\n\`\`\``,
      wrongFlavor:   `📡 ❌ Wrong PSI — recalculate and re-enter before the window closes!`,
    };
  }

  // ── CRIMINAL ── deduce the safest (lowest-heat) route ───────────────────
  if (job === 'criminal') {
    const shown = ['NORTH', 'SOUTH', 'EAST', 'WEST', 'ALLEY'].sort(() => Math.random() - 0.5).slice(0, 4);
    const heats = shown.map(() => randomInt(1, 9));
    let minIdx = 0;
    for (let i = 1; i < heats.length; i++) if (heats[i] < heats[minIdx]) minIdx = i;
    const code = shown[minIdx];
    const list = shown.map((r, i) => `${r}: heat ${heats[i]}/9`).join('\n');
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `🕶️ *JOB IN PROGRESS — STAY SHARP*\n` +
        `\`\`\`\n> TARGET SECURED\n> HEAT LEVELS BY ROUTE:\n\`\`\`\n${list}\n\n` +
        `🏃 Call out the SAFEST route (lowest heat) within *${TIMEOUT}s*.`,
      successFlavor: `🕶️ *JOB COMPLETE — CLEAN GETAWAY*\n\`\`\`\n> ROUTE CONFIRMED\n> SLIPPED THE HEAT\n> CASH IN HAND\n\`\`\``,
      failFlavor:    `🚔 *PINCHED — BLEW THE GETAWAY*\n\`\`\`\n> NO CALL-OUT RECEIVED\n> PATROL CLOSED IN\n> CAUGHT AT THE SCENE\n\`\`\``,
      wrongFlavor:   `🕶️ ❌ Wrong route — that one's hot! Re-check the heat levels and call again!`,
    };
  }

  // ── MAFIA ── total up the collection run ────────────────────────────────
  if (job === 'mafia') {
    const block   = `BLOCK-${num2()}`;
    const n       = randomInt(3, 4);
    const amounts = Array.from({ length: n }, () => randomInt(50, 400));
    const code    = String(amounts.reduce((a, b) => a + b, 0));
    const list    = amounts.map((a, i) => `Associate ${i + 1}: ${a}`).join('\n');
    return {
      code,
      timeout: TIMEOUT,
      prompt:
        `🕴️ *COLLECTION RUN — DON'S ORDERS*\n` +
        `\`\`\`\n> ${block} — PROTECTION DUE\n\`\`\`\n${list}\n\n` +
        `🤫 Total up the collections and report the sum within *${TIMEOUT}s*.`,
      successFlavor: `🕴️ *COLLECTION MADE — DON IS PLEASED*\n\`\`\`\n> TOTAL CONFIRMED\n> PROTECTION PAID\n> BLOCK UNDER CONTROL\n\`\`\``,
      failFlavor:    `🕴️ *DON IS DISPLEASED — COLLECTION FAILED*\n\`\`\`\n> NO TOTAL GIVEN\n> ASSOCIATE GOT NERVOUS\n> COLLECTION ABORTED\n\`\`\``,
      wrongFlavor:   `🤫 ❌ Wrong total — recount and re-enter before the window closes!`,
    };
  }

  // ── FALLBACK (civilian / unknown) ────────────────────────────────────────
  const code = `${alph()}-${num4()}`;
  return {
    code,
    timeout: TIMEOUT,
    prompt:  `🔑 Type this code within *${TIMEOUT}s* to confirm your shift:\n\n\`${code}\``,
    successFlavor: `✅ *SHIFT CONFIRMED*\n\`\`\`\n> CODE ACCEPTED\n> CLOCKED IN\n\`\`\``,
    failFlavor:    `❌ *SHIFT MISSED*\n\`\`\`\n> CODE NOT RECEIVED\n> NOT CLOCKED IN\n\`\`\``,
    wrongFlavor:   `❌ Wrong code. Re-enter before time runs out!`,
  };
}
