function occDutyBasics() {
  return `📘 *HOW DUTY WORKS (all jobs)*\n` +
    `1️⃣ *.enlist <job>* to join a career\n` +
    `2️⃣ Type *.duty* — the bot gives you a challenge\n` +
    `3️⃣ Reply with the answer as a *normal message* (no dot) within *30 seconds*, typed exactly\n` +
    `4️⃣ Correct = cash + 30 XP. A wrong answer lets you try again until time runs out. Too late = duty failed\n` +
    `5️⃣ You can do duty once every ${OCC_DUTY_COOLDOWN_MIN} minutes\n\n` +
    `📈 *Ranks* come from XP: ${OCC_RANK_XP.join(' / ')} XP. Pay grows with rank (300 + 250 per rank, plus a bonus).\n` +
    `🔒 *In jail?* You can't do duty. *.bail* costs 100 per minute left.`;
}
function occJobGuide(key) {
  const j = JOBS[key], g = JOB_GUIDE[key];
  if (!j || !g) return null;
  return `${j.emoji} *${j.label.toUpperCase()} — JOB GUIDE*\n━━━━━━━━━━━━━━━━━━\n` +
    `🎖️ *Ranks:* ${j.ranks.join(' → ')}\n\n` +
    `🛠️ *YOUR DUTY (.duty)*\n${g.duty}\n\n` +
    `📝 *EXAMPLE*\n${g.example}\n\n` +
    `⚡ *SPECIAL POWERS*\n${g.special}\n\n` +
    `💡 *TIP:* ${g.tip}\n\n` +
    `⏱️ Answer within 30s as a normal message · duty every ${OCC_DUTY_COOLDOWN_MIN} min\n` +
    `▸ .jobguide basics — how duty works for everyone`;
}

// Every successful presidential decree is written to a public log (.decrees)
const _LOGGED_DECREES = new Set(['tax','pardon','appoint','promote','demote','fire','jail','amnesty','martiallaw','holiday','stimulus','bonus','grant','bounty','bailout','lottery','medal','emergency','address','speech']);
function _logDecree(text) {
  try {
    let log = []; try { log = JSON.parse(occKV('occ_decree_log', '[]')); } catch (_) {}
    log.push({ t: Date.now(), x: String(text).slice(0, 140) });
    setOccKV('occ_decree_log', JSON.stringify(log.slice(-15)));
  } catch (_) {}
}
function handleOccupations(cmd, userId, name, chatId, args, mentionedJids = []) {
  const r = _handleOccupationsCore(cmd, userId, name, chatId, args, mentionedJids);
  try {
    if (cmd === '.decree' && typeof r === 'string' && _LOGGED_DECREES.has(String(args[0] || '').toLowerCase()) && !/^(\u274c|\u{1F612}|\u26a0)/u.test(r)) {
      _logDecree(r.split('\n')[0].replace(/[*_]/g, ''));
    }
  } catch (_) {}
  return r;
}
function _handleOccupationsCore(cmd, userId, name, chatId, args, mentionedJids = []) {
  const own = isOwner(userId) && OWNER_GOD_MODE;
  const u = getUser(userId, name);
  const now = new Date();

  if (['.careers', '.occupations', '.jobslist'].includes(cmd)) return occupationsMenu();

  if (['.decrees', '.decreelog', '.news'].includes(cmd)) {
    let log = []; try { log = JSON.parse(occKV('occ_decree_log', '[]')); } catch (_) {}
    if (!log.length) return `\ud83d\udcdc No presidential decrees yet.`;
    return `\ud83d\udcdc *RECENT DECREES*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n` + log.slice(-10).reverse().map(e => `\u2022 ${e.x}\n   _${new Date(e.t).toISOString().slice(0, 16).replace('T', ' ')} UTC_`).join('\n');
  }
  if (['.bounties', '.wanted'].includes(cmd)) {
    const rows = db.prepare("SELECT key, value FROM bot_kv WHERE key LIKE 'occ_bounty_%'").all()
      .map(r => ({ id: r.key.slice('occ_bounty_'.length), amt: parseInt(r.value) || 0 })).filter(r => r.amt > 0).sort((a, b) => b.amt - a.amt).slice(0, 10);
    if (!rows.length) return `\ud83c\udfaf No bounties right now.`;
    return `\ud83c\udfaf *MOST WANTED*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n` + rows.map((r, i) => {
      const nm = (db.prepare('SELECT name FROM users WHERE id=?').get(r.id) || {}).name || r.id.replace(/^wa_/, '+');
      return `${i + 1}. ${nm} \u2014 ${fmt(r.amt)}`;
    }).join('\n') + `\n\nPolice: .arrest <name> to collect.`;
  }

  if (['.nation', '.government', '.laws'].includes(cmd)) {
    const nowIso = now.toISOString();
    const jobs = db.prepare("SELECT job, COUNT(*) c FROM occupations WHERE job != 'civilian' GROUP BY job").all();
    const total = jobs.reduce((n, r) => n + r.c, 0);
    const jailed = db.prepare('SELECT COUNT(*) c FROM occupations WHERE jailed_until IS NOT NULL AND jailed_until > ?').get(nowIso).c;
    let pres = 'the Owner';
    try { const r = db.prepare('SELECT name FROM users WHERE id=?').get('wa_' + MY_WA.replace(/\D/g, '')); if (r && r.name) pres = r.name; } catch (_) {}
    const on = (k) => occKV(k, 'off') === 'on';
    return `🏛️ *STATE OF THE NATION*\n━━━━━━━━━━━━━━━━━━\n👑 President: ${pres}\n🏦 Treasury: ${fmt(parseInt(occKV('occ_treasury', '0')) || 0)}\n🧾 Business tax: ${parseInt(occKV('occ_tax_rate', '10'))}%\n🚨 Martial law: ${on('occ_martial_law') ? 'ON' : 'off'}\n🎉 National holiday (2× pay): ${on('occ_holiday') ? 'ON' : 'off'}\n\n👥 Working citizens: ${total}\n🔒 In jail now: ${jailed}\n${jobs.length ? jobs.map(r => (JOBS[r.job]?.emoji || '•') + ' ' + (JOBS[r.job]?.label || r.job) + ': ' + r.c).join('  ·  ') : ''}`;
  }

  if (['.jobguide', '.dutyguide', '.howtowork', '.jobinfo'].includes(cmd)) {
    let key = (args[0] || '').toLowerCase().replace(/[^a-z]/g, '');
    key = JOB_ALIASES[key] || key;
    if (['basics', 'basic', 'duty', 'help', 'how'].includes(key)) return occDutyBasics();
    if (!key) {
      const occ = getOcc(userId);
      if (occ && JOB_GUIDE[occ.job]) return occJobGuide(occ.job);
      return `${occDutyBasics()}\n\n*Pick a job to see its guide:*\n${Object.keys(JOBS).map(k => `${JOBS[k].emoji} .jobguide ${k}`).join('\n')}`;
    }
    const g = occJobGuide(key);
    if (g) return g;
    return `😒 I don't know a job called "${args[0]}".\n\nTry: ${Object.keys(JOBS).map(k => JOBS[k].emoji + ' ' + k).join(', ')}`;
  }

  if (cmd === '.enlist') {
    if (isOwner(userId)) return `👑 You already rule the nation, my President. No need to enlist.`;
    const job = (args[0] || '').toLowerCase();
    if (!JOBS[job]) return `😒 .enlist <job>\n\nAvailable: ${Object.keys(JOBS).map(k => JOBS[k].emoji + ' ' + k).join(', ')}`;
    const existing = getOcc(userId);
    if (existing) return `❌ you're already ${JOBS[existing.job].label} (${JOBS[existing.job].ranks[occRankIndex(existing.xp)]}). Use .resign first.`;
    db.prepare('INSERT INTO occupations (user_id, job, rank, xp, joined_at) VALUES (?,?,0,0,?)').run(userId, job, now.toISOString());
    return `${JOBS[job].emoji} Welcome to the ${JOBS[job].label} force, ${name}!\nRank: ${JOBS[job].ranks[0]}\n\nUse .duty to get to work.`;
  }

  if (cmd === '.resign') {
    const existing = getOcc(userId);
    if (!existing) return `😒 you don't have a job. .enlist <job> first.`;
    db.prepare('DELETE FROM occupations WHERE user_id=?').run(userId);
    return `📤 resigned from the ${JOBS[existing.job].label}.`;
  }

  if (['.myrank', '.myoccupation'].includes(cmd)) {
    if (isOwner(userId)) return `👑 *PRESIDENT* ${name}\nAbsolute authority. Use .decree to govern.`;
    const occ = getOcc(userId);
    if (!occ) return `😒 no occupation yet. .careers to see the list, .enlist <job> to join.`;
    const rIdx = occRankIndex(occ.xp);
    const job = JOBS[occ.job];
    const nextXp = OCC_RANK_XP[rIdx + 1];
    const jailLine = occIsJailed(occ) ? `\n🔒 JAILED — ${occJailMinsLeft(occ)} min left (.bail to pay out)` : '';
    return `${job.emoji} *${job.label}* — ${job.ranks[rIdx]}\nXP: ${occ.xp}${nextXp != null ? ` (${nextXp - occ.xp} to next rank)` : ' (max rank)'}${jailLine}`;
  }

  if (cmd === '.duty') {
    if (isOwner(userId)) return `👑 The President doesn't clock in. Use .decree.`;
    const occ = getOcc(userId);
    if (!occ) return `😒 no occupation. .enlist <job> first.`;
    if (occIsJailed(occ)) return `🔒 you're in jail for ${occJailMinsLeft(occ)} more min. Can't work. .bail to get out early.`;
    const mins = occ.last_duty ? (now - new Date(occ.last_duty)) / 60000 : 999;
    if (mins < OCC_DUTY_COOLDOWN_MIN && !own) return `😒 on break — ${Math.ceil(OCC_DUTY_COOLDOWN_MIN - mins)} more min.`;
    db.prepare('UPDATE occupations SET last_duty=? WHERE user_id=?').run(now.toISOString(), userId);

    const rIdx = occRankIndex(occ.xp);
    const job = JOBS[occ.job];
    const basePay = 300 + rIdx * 250;

    // ── Criminal / Mafia: jail-risk check FIRST, then challenge ──────────────
    if (occ.job === 'criminal' || occ.job === 'mafia') {
      const martialLaw = occKV('occ_martial_law', 'off') === 'on';
      if (martialLaw) return `🚨 Martial law is in effect. The President has shut down the streets. Try later.`;
      const policeCount = db.prepare("SELECT COUNT(*) c FROM occupations WHERE job='police'").get().c;
      const catchChance = Math.min(0.6, 0.15 + policeCount * 0.08);
      if (!own && Math.random() < catchChance) {
        const jailMins = 10 + rIdx * 5;
        db.prepare('UPDATE occupations SET jailed_until=? WHERE user_id=?').run(new Date(now.getTime() + jailMins * 60000).toISOString(), userId);
        return occ.job === 'mafia'
          ? `🚔 The family got made. ${name} jailed for ${jailMins} min.\n.bail to pay your way out early.`
          : `🚔 Busted! A patrol caught you in the act.\n🔒 Jailed for ${jailMins} min. .bail to pay your way out early.`;
      }
    }

    // ── Compute reward (business tax still applies) ───────────────────────
    let amt, taxLine = '';
    if (occ.job === 'criminal' || occ.job === 'mafia') {
      const mult = occ.job === 'mafia' ? 1.3 : 1;
      amt = Math.floor(randomInt(basePay, basePay * 2) * mult) * (own ? 5 : 1);
    } else {
      amt = randomInt(basePay, basePay + 400) * (own ? 5 : 1);
      if (occ.job === 'business') {
        const taxRate = parseInt(occKV('occ_tax_rate', '10'));
        const tax = Math.floor(amt * (taxRate / 100));
        if (tax > 0 && !own) {
          amt -= tax;
          const treasury = parseInt(occKV('occ_treasury', '0')) + tax;
          setOccKV('occ_treasury', treasury);
          taxLine = `\n🏛️ ${fmt(tax)} paid in taxes (${taxRate}%).`;
        }
      }
    }

    // National holiday (president decree): double pay
    if (occKV('occ_holiday', 'off') === 'on') { amt *= 2; taxLine += '\n🎉 National holiday: double pay!'; }

    // ── ALL JOBS: issue a timed challenge ─────────────────────────────────
    const challenge = generateDutyChallenge(occ.job, rIdx);
    pendingDutyChallenge[userId] = {
      code:         challenge.code,
      expires:      Date.now() + challenge.timeout * 1000,
      reward:       amt,
      taxLine,
      rIdx,
      job:          occ.job,
      successFlavor: challenge.successFlavor,
      failFlavor:    challenge.failFlavor,
      wrongFlavor:   challenge.wrongFlavor,
    };
    return challenge.prompt;
  }

  if (cmd === '.arrest') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'police') return `❌ police only. .enlist police to join the force.`;
    if (occIsJailed(occ)) return `🔒 you're in jail yourself. Can't arrest anyone.`;
    const target = args[0];
    if (!target) return '😒 .arrest <@mention or name>';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    if (victim.id === userId) return `😒 can't arrest yourself.`;
    if (isOwner(victim.id)) return `👑 The President is untouchable. That arrest attempt has been noted, officer.`;
    const victimOcc = getOcc(victim.id);
    if (occIsJailed(victimOcc)) return `😒 ${victim.name} is already in jail.`;
    const rIdx = occRankIndex(occ.xp);
    const jailMins = 15 + rIdx * 5;
    db.prepare('INSERT INTO occupations (user_id, job, rank, xp, jailed_until, joined_at) VALUES (?, COALESCE((SELECT job FROM occupations WHERE user_id=?), \'civilian\'), 0, COALESCE((SELECT xp FROM occupations WHERE user_id=?),0), ?, ?) ON CONFLICT(user_id) DO UPDATE SET jailed_until=excluded.jailed_until')
      .run(victim.id, victim.id, victim.id, new Date(now.getTime() + jailMins * 60000).toISOString(), now.toISOString());
    const reward = 200 + rIdx * 150;
    addCash(userId, reward); addXP(userId, 25);
    const _bKey = 'occ_bounty_' + victim.id;
    const _bountyPaid = parseInt(occKV(_bKey, '0')) || 0;
    if (_bountyPaid > 0) { addCash(userId, _bountyPaid); setOccKV(_bKey, 0); }
    db.prepare('UPDATE occupations SET xp=xp+25 WHERE user_id=?').run(userId);
    return `🚔 *ARRESTED* ${victim.name}!\n🔒 Jailed for ${jailMins} min.\nReward: +${fmt(reward)}${_bountyPaid ? `\n\ud83c\udfaf BOUNTY collected: +${fmt(_bountyPaid)}` : ''}`;
  }

  if (cmd === '.raid') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'army') return `❌ army only. .enlist army to join.`;
    const target = args[0];
    if (!target) return '😒 .raid <@mention or name>';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    if (victim.id === userId) return `😒 can't raid yourself.`;
    if (isOwner(victim.id)) {
      const penalty = Math.floor((u.cash || 0) * 0.2);
      if (penalty > 0 && !own) addCash(userId, -penalty);
      return `👑 You raided the President's palace. Big mistake.\nLost ${fmt(penalty)} in the retaliation.`;
    }
    const rIdx = occRankIndex(occ.xp);
    const successChance = Math.min(0.75, 0.35 + rIdx * 0.1);
    if (own || Math.random() < successChance) {
      const stolen = Math.min(randomInt(300, 1500) + rIdx * 200, victim.cash);
      if (stolen <= 0) return `❄️ ${victim.name} has nothing worth raiding.`;
      addCash(userId, stolen); addCash(victim.id, -stolen); addXP(userId, 35);
      db.prepare('UPDATE occupations SET xp=xp+35 WHERE user_id=?').run(userId);
      return `🪖 *RAID SUCCESSFUL* on ${victim.name}!\n+${fmt(stolen)}`;
    }
    const fine = Math.floor((u.cash || 0) * 0.15);
    if (!own) addCash(userId, -fine);
    return `❄️ Raid on ${victim.name} failed. Lost ${fmt(fine)} in the retreat.`;
  }

  if (cmd === '.treat') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'doctor') return `❌ doctor only. .enlist doctor to join.`;
    const target = args[0];
    if (!target) return '😒 .treat <@mention or name>';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    const victimOcc = getOcc(victim.id);
    if (!occIsJailed(victimOcc)) return `😒 ${victim.name} isn't jailed — nothing to treat.`;
    const rIdx = occRankIndex(occ.xp);
    const remainingMs = new Date(victimOcc.jailed_until) - now;
    const newRelease = new Date(now.getTime() + remainingMs * 0.5);
    db.prepare('UPDATE occupations SET jailed_until=? WHERE user_id=?').run(newRelease.toISOString(), victim.id);
    const reward = 150 + rIdx * 100;
    addCash(userId, reward); addXP(userId, 20);
    db.prepare('UPDATE occupations SET xp=xp+20 WHERE user_id=?').run(userId);
    return `🏥 Treated ${victim.name} — jail time cut in half.\nReward: +${fmt(reward)}`;
  }

  if (cmd === '.extort') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'mafia') return `❌ mafia only. .enlist mafia to join the family.`;
    if (occIsJailed(occ)) return `🔒 you're in jail yourself. Can't run the racket from a cell.`;
    const target = args[0];
    if (!target) return '😒 .extort <@mention or name>';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    if (victim.id === userId) return `😒 can't extort yourself.`;
    if (isOwner(victim.id)) return `👑 The President has federal protection. That attempt has been logged, made you a target.`;
    const rIdx = occRankIndex(occ.xp);
    const martialLaw = occKV('occ_martial_law', 'off') === 'on';
    const policeCount = db.prepare("SELECT COUNT(*) c FROM occupations WHERE job='police'").get().c;
    const catchChance = martialLaw ? 0.75 : Math.min(0.5, 0.1 + policeCount * 0.07);
    if (!own && Math.random() < catchChance) {
      const jailMins = 15 + rIdx * 5;
      db.prepare('INSERT INTO occupations (user_id, job, rank, xp, jailed_until, joined_at) VALUES (?,?,0,?,?,?) ON CONFLICT(user_id) DO UPDATE SET jailed_until=excluded.jailed_until')
        .run(userId, occ.job, occ.xp, new Date(now.getTime() + jailMins * 60000).toISOString(), now.toISOString());
      return `🚔 The family got made. ${name} jailed for ${jailMins} min.\n.bail to pay your way out early.`;
    }
    const cut = Math.min(randomInt(150, 600) + rIdx * 100, victim.cash);
    if (cut <= 0) return `❄️ ${victim.name} has nothing left to squeeze.`;
    addCash(userId, cut); addCash(victim.id, -cut); addXP(userId, 30);
    db.prepare('UPDATE occupations SET xp=xp+30 WHERE user_id=?').run(userId);
    return `🕴️ *EXTORTED* ${victim.name} for protection money.\n+${fmt(cut)}`;
  }

  if (cmd === '.hack') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'hacker') return `❌ hacker only. .enlist hacker to join.`;
    const target = args[0];
    if (!target) return '😒 .hack <@mention or name>';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    if (victim.id === userId) return `😒 can't hack yourself.`;
    if (isOwner(victim.id)) return `👑 Access denied. The President's servers are federally hardened.`;
    const rIdx = occRankIndex(occ.xp);
    const successChance = Math.min(0.9, 0.5 + rIdx * 0.1);
    if (own || Math.random() < successChance) {
      const stolen = Math.min(randomInt(200, 900) + rIdx * 150, victim.cash);
      if (stolen <= 0) return `❄️ ${victim.name}'s account is empty. Nothing to drain.`;
      addCash(userId, stolen); addCash(victim.id, -stolen); addXP(userId, 35);
      db.prepare('UPDATE occupations SET xp=xp+35 WHERE user_id=?').run(userId);
      return `💻 *HACK SUCCESSFUL* — drained ${victim.name}'s account.\n+${fmt(stolen)}`;
    }
    const fine = Math.floor((u.cash || 0) * 0.1);
    if (!own) addCash(userId, -fine);
    return `❄️ Hack failed — traced back to you. Fined ${fmt(fine)} in legal fees.`;
  }

  if (cmd === '.tutor') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'teacher') return `❌ teacher only. .enlist teacher to join.`;
    const target = args[0];
    if (!target) return '😒 .tutor <@mention or name>';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    if (victim.id === userId) return `😒 can't tutor yourself.`;
    const victimOcc = getOcc(victim.id);
    if (!victimOcc) return `😒 ${victim.name} doesn't have a job yet — nothing to study for.`;
    const rIdx = occRankIndex(occ.xp);
    const bonus = 40 + rIdx * 15;
    db.prepare('UPDATE occupations SET xp=xp+? WHERE user_id=?').run(bonus, victim.id);
    const reward = 100 + rIdx * 60;
    addCash(userId, reward); addXP(userId, 20);
    db.prepare('UPDATE occupations SET xp=xp+20 WHERE user_id=?').run(userId);
    return `🍎 Tutored ${victim.name} — +${bonus} XP toward their next rank.\nReward: +${fmt(reward)}`;
  }

  if (cmd === '.trial') {
    const occ = getOcc(userId);
    if (!occ || occ.job !== 'judge') return `❌ judge only. .enlist judge to join.`;
    const target = args[0];
    const ruling = (args[1] || '').toLowerCase();
    if (!target || !['pardon', 'sentence'].includes(ruling)) return '😒 .trial <@mention> pardon|sentence';
    const victim = occResolveTarget(target, mentionedJids);
    if (!victim) return `❄️ can't find "${target}".`;
    const victimOcc = getOcc(victim.id);
    if (!occIsJailed(victimOcc)) return `😒 ${victim.name} isn't jailed.`;
    const rIdx = occRankIndex(occ.xp);
    if (ruling === 'pardon') {
      db.prepare('UPDATE occupations SET jailed_until=NULL WHERE user_id=?').run(victim.id);
      addXP(userId, 20); db.prepare('UPDATE occupations SET xp=xp+20 WHERE user_id=?').run(userId);
      return `⚖️ *PARDONED* ${victim.name}. Case dismissed.`;
    }
    const extraMins = 10 + rIdx * 5;
    db.prepare('UPDATE occupations SET jailed_until=? WHERE user_id=?').run(new Date(new Date(victimOcc.jailed_until).getTime() + extraMins * 60000).toISOString(), victim.id);
    addXP(userId, 20); db.prepare('UPDATE occupations SET xp=xp+20 WHERE user_id=?').run(userId);
    return `⚖️ *SENTENCED* ${victim.name} to ${extraMins} extra min in jail.`;
  }

  if (cmd === '.bail') {
    const occ = getOcc(userId);
    if (!occ || !occIsJailed(occ)) return `😒 you're not in jail.`;
    const minsLeft = occJailMinsLeft(occ);
    const cost = minsLeft * 100;
    if (!own && u.cash < cost) return `❌ bail is ${fmt(cost)}. You don't have enough.`;
    if (!own) addCash(userId, -cost);
    db.prepare('UPDATE occupations SET jailed_until=NULL WHERE user_id=?').run(userId);
    return `🔓 Paid ${fmt(cost)} bail. You're free.`;
  }

  if (cmd === '.decree') {
    if (!isOwner(userId)) return `❌ President-only command.`;
    const sub = (args[0] || '').toLowerCase();
    if (sub === 'tax') {
      const rate = parseInt(args[1]);
      if (isNaN(rate) || rate < 0 || rate > 50) return `😒 .decree tax <0-50>`;
      setOccKV('occ_tax_rate', rate);
      return `🏛️ Business tax set to ${rate}%.`;
    }
    if (sub === 'pardon') {
      const victim = occResolveTarget(args[1], mentionedJids);
      if (!victim) return `😒 .decree pardon <@mention or name>`;
      db.prepare('UPDATE occupations SET jailed_until=NULL WHERE user_id=?').run(victim.id);
      return `⚖️ Presidential pardon granted to ${victim.name}.`;
    }
    if (sub === 'appoint') {
      const victim = occResolveTarget(args[1], mentionedJids);
      const job = (args[2] || '').toLowerCase();
      if (!victim || !JOBS[job]) return `😒 .decree appoint <@mention> <job>`;
      db.prepare('INSERT INTO occupations (user_id, job, rank, xp, joined_at) VALUES (?,?,0,?,?) ON CONFLICT(user_id) DO UPDATE SET job=excluded.job, xp=excluded.xp')
        .run(victim.id, job, OCC_RANK_XP[OCC_RANK_XP.length - 1], new Date().toISOString());
      return `👑 By presidential decree, ${victim.name} is now ${JOBS[job].label} (${JOBS[job].ranks[JOBS[job].ranks.length - 1]}).`;
    }
    if (sub === 'promote') {
      const victim = occResolveTarget(args[1], mentionedJids);
      if (!victim) return `😒 .decree promote <@mention or name>`;
      const victimOcc = getOcc(victim.id);
      if (!victimOcc) return `❌ ${victim.name} has no job.`;
      const rIdx = occRankIndex(victimOcc.xp);
      if (rIdx >= OCC_RANK_XP.length - 1) return `❌ ${victim.name} is already at max rank.`;
      db.prepare('UPDATE occupations SET xp=? WHERE user_id=?').run(OCC_RANK_XP[rIdx + 1], victim.id);
      return `👑 ${victim.name} promoted to ${JOBS[victimOcc.job].ranks[rIdx + 1]}.`;
    }
    if (sub === 'martiallaw') {
      const state = (args[1] || '').toLowerCase();
      if (!['on', 'off'].includes(state)) return `😒 .decree martiallaw on|off`;
      setOccKV('occ_martial_law', state);
      return `🚨 Martial law is now *${state.toUpperCase()}*.`;
    }
    if (sub === 'treasury') {
      const treasury = parseInt(occKV('occ_treasury', '0'));
      if (args[1] === 'withdraw') {
        setOccKV('occ_treasury', 0);
        addCash(userId, treasury);
        return `🏛️ Withdrew ${fmt(treasury)} from the treasury.`;
      }
      return `🏛️ National treasury: ${fmt(treasury)}\n.decree treasury withdraw — take it for yourself`;
    }
    // ───────── EXTRA PRESIDENTIAL POWERS ─────────
    const _treasury = () => parseInt(occKV('occ_treasury', '0')) || 0;
    const _amt = (x) => { const n = parseInt(x); return Number.isFinite(n) && n > 0 && n <= 1e12 ? n : null; };
    const _fromTreasury = (n) => setOccKV('occ_treasury', _treasury() - n);

    if (sub === 'amnesty') {
      const nowIso = now.toISOString();
      const c = db.prepare('SELECT COUNT(*) c FROM occupations WHERE jailed_until IS NOT NULL AND jailed_until > ?').get(nowIso).c;
      db.prepare('UPDATE occupations SET jailed_until=NULL WHERE jailed_until IS NOT NULL').run();
      return `🕊️ *NATIONAL AMNESTY* — the President has freed ${c} prisoner${c === 1 ? '' : 's'}.`;
    }
    if (sub === 'jail') {
      const victim = occResolveTarget(args[1], mentionedJids);
      const mins = parseInt(args[2]);
      if (!victim || !(mins >= 1 && mins <= 180)) return `😒 .decree jail <@mention> <1-180 minutes>`;
      if (isOwner(victim.id)) return `😒 you can't jail yourself, Mr. President.`;
      db.prepare("INSERT INTO occupations (user_id, job, rank, xp, jailed_until, joined_at) VALUES (?, COALESCE((SELECT job FROM occupations WHERE user_id=?), 'civilian'), 0, COALESCE((SELECT xp FROM occupations WHERE user_id=?), 0), ?, ?) ON CONFLICT(user_id) DO UPDATE SET jailed_until=excluded.jailed_until")
        .run(victim.id, victim.id, victim.id, new Date(now.getTime() + mins * 60000).toISOString(), now.toISOString());
      return `⛓️ By presidential order, *${victim.name}* is jailed for ${mins} min.`;
    }
    if (sub === 'fire') {
      const victim = occResolveTarget(args[1], mentionedJids);
      if (!victim) return `😒 .decree fire <@mention or name>`;
      if (isOwner(victim.id)) return `😒 you can't fire yourself, Mr. President.`;
      const vo = getOcc(victim.id);
      if (!vo) return `😒 ${victim.name} has no job.`;
      db.prepare('DELETE FROM occupations WHERE user_id=?').run(victim.id);
      return `📤 By presidential decree, *${victim.name}* has been removed from the ${JOBS[vo.job]?.label || vo.job} service.`;
    }
    if (sub === 'demote') {
      const victim = occResolveTarget(args[1], mentionedJids);
      if (!victim) return `😒 .decree demote <@mention or name>`;
      const vo = getOcc(victim.id);
      if (!vo || !JOBS[vo.job]) return `😒 ${victim.name} has no job.`;
      const r = occRankIndex(vo.xp);
      if (r <= 0) return `😒 ${victim.name} is already at the lowest rank.`;
      db.prepare('UPDATE occupations SET xp=? WHERE user_id=?').run(OCC_RANK_XP[r - 1], victim.id);
      return `📉 *${victim.name}* demoted to ${JOBS[vo.job].ranks[r - 1]}.`;
    }
    if (sub === 'stimulus' || sub === 'bonus') {
      // stimulus <amount>  = every working citizen · bonus <job> <amount> = one job. Paid from the treasury.
      const jobKey = sub === 'bonus' ? (args[1] || '').toLowerCase() : null;
      const amount = _amt(sub === 'bonus' ? args[2] : args[1]);
      if (sub === 'bonus' && !JOBS[jobKey]) return `😒 .decree bonus <job> <amount>\nJobs: ${Object.keys(JOBS).join(', ')}`;
      if (!amount) return sub === 'bonus' ? `😒 .decree bonus <job> <amount>` : `😒 .decree stimulus <amount each>`;
      const rows = (jobKey ? db.prepare('SELECT user_id FROM occupations WHERE job=?').all(jobKey) : db.prepare("SELECT user_id FROM occupations WHERE job != 'civilian'").all())
        .filter(r => !isOwner(r.user_id));
      if (!rows.length) return `😒 nobody to pay.`;
      const total = amount * rows.length;
      if (total > _treasury()) return `❌ that costs ${fmt(total)} (${rows.length} × ${fmt(amount)}) but the treasury only has ${fmt(_treasury())}.`;
      _fromTreasury(total);
      rows.forEach(r => addCash(r.user_id, amount));
      return `💸 *${sub === 'bonus' ? JOBS[jobKey].label.toUpperCase() + ' BONUS' : 'NATIONAL STIMULUS'}*\n${rows.length} citizen${rows.length === 1 ? '' : 's'} received ${fmt(amount)} each.\n🏦 Treasury left: ${fmt(_treasury())}`;
    }
    if (sub === 'grant') {
      const victim = occResolveTarget(args[1], mentionedJids);
      const amount = _amt(args[2]);
      if (!victim || !amount) return `😒 .decree grant <@mention> <amount>`;
      if (amount > _treasury()) return `❌ the treasury only has ${fmt(_treasury())}.`;
      _fromTreasury(amount); addCash(victim.id, amount);
      return `🎁 The President granted *${victim.name}* ${fmt(amount)} from the treasury.\n🏦 Treasury left: ${fmt(_treasury())}`;
    }
    if (sub === 'holiday') {
      const state = (args[1] || '').toLowerCase();
      if (!['on', 'off'].includes(state)) return `😒 .decree holiday on|off`;
      setOccKV('occ_holiday', state);
      return state === 'on' ? `🎉 *NATIONAL HOLIDAY!* All duty pay is DOUBLED until the President ends it.` : `📅 National holiday is over. Normal pay resumes.`;
    }
    if (sub === 'bounty') {
      const victim = occResolveTarget(args[1], mentionedJids);
      const amount = _amt(args[2]);
      if (!victim || !amount) return `\ud83d\ude12 .decree bounty <@user> <amount>`;
      if (isOwner(victim.id)) return `\ud83d\ude12 you can't put a bounty on yourself, Mr. President.`;
      if (amount > _treasury()) return `\u274c the treasury only has ${fmt(_treasury())}.`;
      const key = 'occ_bounty_' + victim.id;
      const total = (parseInt(occKV(key, '0')) || 0) + amount;
      if (total > 1e9) return `\u274c that bounty would be too large (max 1,000,000,000).`;
      _fromTreasury(amount); setOccKV(key, total);
      return `\ud83c\udfaf *BOUNTY!* ${fmt(total)} on *${victim.name}*\nAny police officer who arrests them collects it. (.bounties to see all)`;
    }
    if (sub === 'bailout') {
      const victim = occResolveTarget(args[1], mentionedJids);
      if (!victim) return `\ud83d\ude12 .decree bailout <@user>`;
      const vo = getOcc(victim.id);
      if (!vo || !occIsJailed(vo)) return `\ud83d\ude12 ${victim.name} isn't in jail.`;
      const cost = occJailMinsLeft(vo) * 100;
      if (cost > _treasury()) return `\u274c bail costs ${fmt(cost)} but the treasury only has ${fmt(_treasury())}.`;
      _fromTreasury(cost);
      db.prepare('UPDATE occupations SET jailed_until=NULL WHERE user_id=?').run(victim.id);
      return `\ud83d\udd13 The state paid ${fmt(cost)} bail \u2014 *${victim.name}* is free.\n\ud83c\udfe6 Treasury left: ${fmt(_treasury())}`;
    }
    if (sub === 'lottery') {
      const prize = _amt(args[1]);
      if (!prize) return `\ud83d\ude12 .decree lottery <prize>`;
      if (prize > _treasury()) return `\u274c the treasury only has ${fmt(_treasury())}.`;
      const pool = db.prepare("SELECT o.user_id id, COALESCE(u.name, o.user_id) name FROM occupations o LEFT JOIN users u ON u.id=o.user_id WHERE o.job != 'civilian'").all().filter(r => !isOwner(r.id));
      if (!pool.length) return `\ud83d\ude12 nobody is eligible \u2014 no working citizens yet.`;
      const w = pool[Math.floor(Math.random() * pool.length)];
      _fromTreasury(prize); addCash(w.id, prize);
      return `\ud83c\udf9f\ufe0f *NATIONAL LOTTERY!* The winner is *${w.name}* \u2014 ${fmt(prize)}!\n(${pool.length} citizens entered)\n\ud83c\udfe6 Treasury left: ${fmt(_treasury())}`;
    }
    if (sub === 'medal') {
      const victim = occResolveTarget(args[1], mentionedJids);
      const xp = args[2] === undefined ? 100 : parseInt(args[2]);
      if (!victim || !(xp >= 1 && xp <= 500)) return `\ud83d\ude12 .decree medal <@user> [1-500 xp]`;
      const vo = getOcc(victim.id);
      if (!vo || !JOBS[vo.job]) return `\ud83d\ude12 ${victim.name} has no job.`;
      db.prepare('UPDATE occupations SET xp=xp+? WHERE user_id=?').run(xp, victim.id);
      const r = occRankIndex(vo.xp + xp);
      return `\ud83c\udf96\ufe0f *MEDAL OF HONOR* awarded to *${victim.name}* (+${xp} XP)${r > occRankIndex(vo.xp) ? `\n\ud83d\udcc8 Promoted to ${JOBS[vo.job].ranks[r]}!` : ''}`;
    }
    if (sub === 'emergency') {
      const t = (args[1] || '').toLowerCase();
      if (t === 'all') {
        db.prepare('UPDATE occupations SET last_duty=NULL').run();
        return `\ud83d\udea8 *STATE OF EMERGENCY!* Everyone's duty cooldown has been reset \u2014 get to work!`;
      }
      const victim = occResolveTarget(args[1], mentionedJids);
      if (!victim) return `\ud83d\ude12 .decree emergency <@user | all>`;
      if (!getOcc(victim.id)) return `\ud83d\ude12 ${victim.name} has no job.`;
      db.prepare('UPDATE occupations SET last_duty=NULL WHERE user_id=?').run(victim.id);
      return `\ud83d\udea8 Emergency order: *${victim.name}* can go on duty again right now.`;
    }
    if (sub === 'address' || sub === 'speech') {
      const speech = args.slice(1).join(' ').trim().slice(0, 600);
      if (!speech) return `😒 .decree address <your message to the nation>`;
      return `📢 *PRESIDENTIAL ADDRESS*\n━━━━━━━━━━━━━━━━━━\n${speech}\n━━━━━━━━━━━━━━━━━━\n— 👑 The President`;
    }
    return `👑 *PRESIDENTIAL DECREES*\n━━━━━━━━━━━━━━━━━━\n*⚖️ Law & order*\n▸ .decree martiallaw on|off\n▸ .decree jail <@user> <mins>\n▸ .decree pardon <@user>\n▸ .decree amnesty — free everyone\n\n*👔 Careers*\n▸ .decree appoint <@user> <job>\n▸ .decree promote <@user> · demote <@user>\n▸ .decree fire <@user>\n\n*💰 Economy*\n▸ .decree tax <0-50>\n▸ .decree treasury [withdraw]\n▸ .decree stimulus <amount> — pay every worker\n▸ .decree bonus <job> <amount>\n▸ .decree grant <@user> <amount>\n▸ .decree holiday on|off — double duty pay\n\n*🎯 Special orders*\n▸ .decree bounty <@user> <amount>\n▸ .decree bailout <@user>\n▸ .decree lottery <prize>\n▸ .decree medal <@user> [xp]\n▸ .decree emergency <@user|all>\n\n*📢 Speech*\n▸ .decree address <message>\n\n▸ .nation · .decrees · .bounties — everyone can see these`;
  }

  return null;
}

// ============ ECONOMY ============
function handleEconomy(cmd, userId, name, chatId, args, mentionedJids=[], rawUserId='') {
  // Phone-based owner detection: if the raw WA sender number matches MY_WA,
  // treat as owner regardless of what resolveId() returned.
  const _rawPhone = String(rawUserId||'').replace(/^wa_/,'').replace(/\D/g,'');
  const _isPhoneOwner = !!_rawPhone && _rawPhone === MY_WA.replace(/\D/g,'');
  if (_isPhoneOwner) ensureOwnerRich(userId, name, true);
  else ensureOwnerRich(userId, name);
  const u = getUser(userId, name);
  const now = new Date();
  const own = (isOwner(userId) || _isPhoneOwner) && OWNER_GOD_MODE;
  const sudo = isSudo(userId);
  const boost = boosterActive[userId] && boosterActive[userId] > Date.now() ? 2 : 1;
  const diamondBonus = diamondUsers.has(userId) ? 1.1 : 1;
  const luckyBoost = luckyActive[userId] && luckyActive[userId] > Date.now() ? 1.3 : 1;

  // ── BALANCE ──
  if (['.bal','.balance','.wallet'].includes(cmd)) {
    const inv=getInventory(userId);
    const lvl=own?9999:(u.level||1), xp=own?999999:(u.xp||0);
    const cash=own?999999999999999:(u.cash||0);
    const bank=own?999999999999999:(u.bank||0);
    const earned=own?999999999999999:(u.total_earned||0);
    const wins=own?999999:(u.wins||0), losses=own?0:(u.losses||0);
    const invLine=inv.length?'\n🎒 '+inv.map(i=>`${i.item}x${i.quantity}`).join(', '):'';
    return `💗 ${u.name}${own?' 👑':sudo?' 🔑':''} · Lv${lvl} [${xp}/${lvl*100}xp]\n💳 ${fmt(cash)}\n🏦 ${fmt(bank)}\n💎 Worth: ${fmt(cash+bank)}\n📈 Earned: ${fmt(earned)}\n🏆 W${wins}·L${losses}${invLine}`;
  }

  // ── PROFILE ──
  if (['.profile','.p','.me','.stats'].includes(cmd)) {
    if(own){try{ensureOwnerRich(userId,name,true);}catch(_){}}
    const lvl=own?9999:(u.level||1),net=own?1999999999999998:(u.cash+u.bank);
    const wr=u.wins+u.losses>0?Math.floor(u.wins/(u.wins+u.losses)*100):0;
    const inv=getInventory(userId);
    const tier=net>=1000000?'💎':net>=100000?'💰':net>=10000?'📈':'💸';
    const isVip=(u.vip_expires&&u.vip_expires>Date.now())||own;
    const hasDia=diamondUsers.has(userId);
    const prestige=u.prestige||0;
    const badges=[own?'👑':'',isVip?'⭐':'',hasDia?'💎':'',prestige>0?`✨P${prestige}`:''].filter(Boolean).join(' ');
    const xpBar=()=>{const f=Math.floor((u.xp||0)/(lvl*100)*10);return '█'.repeat(f)+'░'.repeat(10-f);};
    return `👤 *${u.name}* ${badges}\n━━━━━━━━━━━━━━━\n${tier} Lv${lvl} [${xpBar()}] ${u.xp||0}/${lvl*100}xp\n💳 Cash: ${fmt(u.cash)}\n🏦 Bank: ${fmt(u.bank)}\n💎 Net: ${fmt(net)}\n📈 Earned: ${fmt(u.total_earned)}\n🏆 WR: ${wr}% (W${u.wins}·L${u.losses})\n📝 Bio: ${u.bio||'—'}\n💑 Spouse: ${u.spouse||'—'}\n🎒 Items: ${inv.length?inv.map(i=>`${i.item}×${i.quantity}`).join(', '):'—'}`;
  }

  if (cmd==='.setbio') {
    const bio=args.join(' ');if(!bio) return '😒 .setbio <text>';
    setField(userId,'bio',bio.slice(0,100));return '💗 bio updated.';
  }

  // ── OWNER COMMANDS ──
  if (cmd==='.addcash'&&own) {
    const target=args[0], amt=parseInt(args[1])||parseInt(args[0])||0;
    if(!amt) return '😒 .addcash <name|@> <amount>';
    const receiver=target&&isNaN(args[0])?db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(target):null;
    const targetId=receiver?receiver.id:userId;
    addCash(targetId,amt);
    return `👑 added ${fmt(amt)} to ${receiver?receiver.name:name}`;
  }

  // Turn "2348012345678", "+234 801 234 5678", "@mention" or a Telegram id into the id the bot stores.
  const _sudoTarget = () => {
    const fromWA = String(rawUserId || userId || '').startsWith('wa_');
    const mj = (mentionedJids || []).find(Boolean);
    if (mj) return 'wa_' + String(mj).split('@')[0].split(':')[0].replace(/\D/g, '');
    const joined = args.join('').trim();
    if (!joined) return '';
    if (/^(wa_|tg_)/i.test(joined)) return joined;
    const digits = joined.replace(/\D/g, '');
    if (digits.length < 5) return '';
    return fromWA ? 'wa_' + digits : digits;
  };

  if (cmd==='.sudo'&&own) {
    const target=_sudoTarget();
    if(!target) return '😒 .sudo <phone number>  (example: .sudo 2348012345678)\nOr tag the person: .sudo @person';
    db.prepare('INSERT OR IGNORE INTO sudo_users (id,added_by,added_at) VALUES (?,?,?)').run(target,userId,now.toISOString());
    return `👑 ${target.replace(/^wa_/, '+')} is now sudo.`;
  }

  if (cmd==='.unsudo'&&own) {
    const target=_sudoTarget();
    if(!target) return '😒 .unsudo <phone number>  (or tag the person)';
    db.prepare('DELETE FROM sudo_users WHERE id=?').run(target);
    return `👑 ${target.replace(/^wa_/, '+')} removed from sudo.`;
  }

  if (cmd==='.broadcast'&&sudo) {
    return '😒 .broadcast only works from the console for safety.';
  }

  // ── OWNER ONLY: how many people use the bot ──
  if (['.botusers','.users','.usercount','.subscribers'].includes(cmd)) {
    if (!isOwner(userId)) return '😒 only the owner can see this.';
    const _c = (q, ...a) => { try { return db.prepare(q).get(...a).c || 0; } catch (_) { return 0; } };
    const now = Date.now(), DAY = 86400000;
    const total   = _c('SELECT COUNT(*) AS c FROM bot_visitors');
    const tgAll   = _c("SELECT COUNT(*) AS c FROM bot_visitors WHERE platform='telegram'");
    const waAll   = _c("SELECT COUNT(*) AS c FROM bot_visitors WHERE platform='whatsapp'");
    const entered = _c('SELECT COUNT(*) AS c FROM bot_visitors WHERE started=1');
    const act = d => _c('SELECT COUNT(*) AS c FROM bot_visitors WHERE last_seen>=?', now - d * DAY);
    const nw  = d => _c('SELECT COUNT(*) AS c FROM bot_visitors WHERE first_seen>=?', now - d * DAY);
    const unk = _c('SELECT COUNT(*) AS c FROM bot_visitors WHERE first_seen=0');
    return `📊 *BOT USERS*\n━━━━━━━━━━━━━━━\n👥 Everyone who has used the bot: ${total}\n   ✈️ Telegram: ${tgAll}\n   💬 WhatsApp: ${waAll}\n🚪 Opened the bot in private chat: ${entered}\n\n🔥 *Active users*\n• Today: ${act(1)}\n• Last 7 days: ${act(7)}\n• Last 30 days (monthly): ${act(30)}\n\n🆕 *New people*\n• Today: ${nw(1)}\n• Last 7 days: ${nw(7)}\n• Last 30 days: ${nw(30)}\n\n` + (unk ? `ℹ️ ${unk} of these used the bot before tracking started, so their dates are unknown. They count in the total only; active and new numbers fill in from now on.\n\n` : '') + `🔒 only you, the owner, can see this`;
  }

  if (cmd==='.botinfo'||cmd==='.ping') {
    return `💕 I'm here, awake for ${fmtUptime()}.`;
  }

  // ── AI INFO COMMANDS ──
  if (cmd==='.models') {
    const modelList = [
      '🥇 openai/gpt-oss-120b  — primary (best quality, 500 tok/s)',
      '🥈 openai/gpt-oss-20b   — fallback 1 (fastest, 1000 tok/s)',
      '🥉 groq/compound         — fallback 2',
      '4️⃣  qwen/qwen3.8-27b      — fallback 3 (safety net)',
    ].join('\n');
    return `💕 *The machinery behind me*\n${modelList}\n\n🎤 Voice: whisper-large-v3\n👁️ Vision: openai/gpt-oss-120b\n\nFallbacks activate automatically on timeout, rate-limit, or error.`;
  }

  if (cmd==='.aitest') {
    // Returns a promise — callers that need sync should handle async upstream
    return (async () => {
      const start = Date.now();
      try {
        const res = await groq.chat.completions.create({
          model: 'openai/gpt-oss-120b',
          messages: [{ role: 'user', content: 'Reply with exactly: pong' }],
          max_tokens: 5,
        });
        const ms = Date.now() - start;
        const reply = res.choices[0]?.message?.content?.trim() || '?';
        return `✅ AI online — ${ms}ms\nModel: openai/gpt-oss-120b\nResponse: ${reply}`;
      } catch(e) {
        const ms = Date.now() - start;
        return `❌ AI test failed after ${ms}ms\nError: ${e.message}\nCheck .models for fallback list.`;
      }
    })();
  }

  if (cmd==='.clearhistory') {
    if (!own && !sudo) return '😒 sudo only.';
    const target = args[0] || userId;
    if (userHistory[target]) { delete userHistory[target]; saveHistorySoon(); }
    return `🗑️ AI memory cleared for ${target}.`;
  }

  // ── DAILY ──
  if (cmd==='.daily') {
    const hrs=u.last_daily?(now-new Date(u.last_daily))/3600000:999;
    if(hrs<24&&!own) return `❄️ come back in ${Math.ceil(24-hrs)}h.`;
    const streak=checkStreak(userId);
    const base=own?randomInt(5000000,50000000):randomInt(500,2500);
    const streakBonus=streak>=7?1000:streak>=3?400:0;
    const amt=base+streakBonus;
    addCash(userId,amt); setField(userId,'last_daily',now.toISOString());
    const lv=addXP(userId,own?500:50);
    if (own) {
      return `👑 *LORD'S DAILY*\n\n+${fmt(amt)} dropped.\n🔥 Day ${streak} — the vault never empties.\n${lv?`⬆️ LEVEL UP! Lv${lv}\n`:''}\n_Others grind. You collect._`;
    }
    return `💗 daily claimed!\n+${fmt(amt)}${streakBonus?` (🔥 day ${streak} streak bonus!)`:''}\n${lv?`⬆️ LEVEL UP! Lv${lv}\n`:''}naura: ${fmt(u.cash+amt)}`;
  }

  // ── WORK ──
  if (cmd==='.work') {
    const mins=u.last_work?(now-new Date(u.last_work))/60000:999;
    if(mins<30&&!own) return `😒 rest ${Math.ceil(30-mins)} more min.`;
    const workLines=[
      'Worked a job that exists purely to justify its own existence.',
      'Did content creation for a brand that deserved better.',
      'Showed up. That was already half the battle.',
      'Sold thrift pieces to people who think they discovered vintage.',
      'Tutored someone who probably won\'t remember any of it.',
      'Fixed laptops for people who click yes on everything.',
      'Ran errands for someone who could have done it themselves.',
      'Drove strangers around and kept the aux to themselves.',
      'Managed social media. Felt nothing. Got paid.',
      'Edited a video that will get twelve views and one comment.',
      'Did graphic design for a client who wanted it more poppy.',
      'Sold data bundles at the roadside like a professional.',
      'Cooked, sold food, made peace with the heat.',
      'Did a freelance job nobody else wanted. Standards. Low.',
      'Helped someone move. They had too many boxes. Surprise.',
      'Did a voice-over that sounded better in the brief.',
      'Delivered packages to addresses that didn\'t want to be found.',
    ];
    const job=workLines[randomInt(0,workLines.length-1)];
    const amt=Math.floor(randomInt(200,800)*(u.level||1)*boost*diamondBonus*(own?5:1));
    addCash(userId,amt); setField(userId,'last_work',now.toISOString());
    const lv=addXP(userId,20);
    const bonusTags=[boost>1?'🚀 2x':'',diamondBonus>1?'💎 +10%':''].filter(Boolean).join(' ');
    // Option 1 — 20% passive income cut to boss; track toward quota
    let bossCutLine = '';
    try {
      const staffRow = db.prepare('SELECT hired_by, quota FROM job_staff WHERE user_id=?').get(userId);
      if (staffRow && staffRow.hired_by && !own) {
        const bossCut = Math.floor(amt * 0.20);
        addCash(staffRow.hired_by, bossCut);
        bossCutLine = ` _(👑 boss +${fmt(bossCut)})_`;
      }
      if (staffRow) logJobEarning(userId, amt); // count toward daily quota
    } catch(_) {}
    return `💗 ${job} ${fmt(amt)}.${bonusTags?' ('+bonusTags+')':''}${bossCutLine}${lv?'\n⬆️ Level up — Lv'+lv:''}`;
  }

  // ── CRIME ──
  if (cmd==='.crime') {
    const mins=u.last_crime?(now-new Date(u.last_crime))/60000:999;
    if(mins<60&&!own) return `😒 lay low ${Math.ceil(60-mins)} more min.`;
    setField(userId,'last_crime',now.toISOString());
    const crimeWins=[
      'Did something that would make a lawyer deeply uncomfortable.',
      'Found a gap in the system and walked through it quietly.',
      'Executed a plan that only made sense in the moment.',
      'The risk was real. So was the payout.',
      'It wasn\'t exactly legal but it wasn\'t exactly not.',
      'Nobody saw. That was the whole point.',
      'Ran a scheme that technically worked. Details sealed.',
      'Social engineered a situation into profit. Naturally.',
      'Moved through the city like a rumour. Untraceable.',
    ];
    const crimeLoss=[
      'Got caught doing something that felt smart at the time.',
      'The plan had one flaw. Found it the hard way.',
      'Somebody was watching. They always are.',
      'Almost got away with it. Almost.',
    ];
    if(own||Math.random()<0.55){
      const amt=randomInt(500,4000)*(own?5:1); addCash(userId,amt); addXP(userId,30);
      return `💗 ${crimeWins[randomInt(0,crimeWins.length-1)]} +${fmt(amt)}.`;
    } else {
      const amuletOn=amuletActive[userId]&&amuletActive[userId]>Date.now();
      const fine=Math.floor(randomInt(200,1200)*(amuletOn?0.5:1)); addCash(userId,-fine);
      return `❄️ ${crimeLoss[randomInt(0,crimeLoss.length-1)]} Fined ${fmt(fine)}.${amuletOn?' (🧿 amulet halved fine)':''}`;
    }
  }

  // ── BEG ──
  if (cmd==='.beg') {
    const mins=u.last_beg?(now-new Date(u.last_beg))/60000:999;
    if(mins<15&&!own) return `😒 wait ${Math.ceil(15-mins)} more min.`;
    setField(userId,'last_beg',now.toISOString());
    const begWins=[
      'A group of students pooled together {N} naura out of pity or boredom.',
      'Someone dropped their wallet and didn\'t notice. You noticed.',
      'A stranger looked you in the eyes, sighed, and handed over {N} naura.',
      'Someone had extra. You had need. Transaction complete. {N} naura.',
      'The universe shrugged and threw {N} naura in your direction.',
      'A kind stranger gave you {N} naura and walked away.',
      'An old contact wired {N} naura and asked no follow-up questions.',
    ];
    const begLoss=[
      'Nobody gave anything. Embarrassing sha.',
      'Extended a hand. The hand came back empty.',
      'People walked past like you were furniture.',
      'Tried begging. The street had opinions.',
    ];
    if(own||Math.random()<0.55){
      const amt=randomInt(50,500)*(own?10:1); addCash(userId,amt); addXP(userId,5);
      const line=begWins[randomInt(0,begWins.length-1)].replace('{N}',amt.toLocaleString());
      return `🙏 ${line}`;
    }
    return `❄️ ${begLoss[randomInt(0,begLoss.length-1)]}`;
  }

  // ── BANK ──
  if (['.dep','.deposit'].includes(cmd)) {
    const amt=args[0]==='all'?u.cash:parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .dep <amount|all>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    db.prepare('UPDATE users SET cash=cash-?,bank=bank+? WHERE id=?').run(amt,amt,userId);
    return `🏦 deposited ${fmt(amt)}. bank: ${fmt(u.bank+amt)}`;
  }
  if (['.with','.withdraw'].includes(cmd)) {
    const amt=args[0]==='all'?u.bank:parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .with <amount|all>';
    if(amt>u.bank) return `not enough — bank: ${fmt(u.bank)}`;
    db.prepare('UPDATE users SET cash=cash+?,bank=bank-? WHERE id=?').run(amt,amt,userId);
    return `🪙 withdrew ${fmt(amt)}. naura: ${fmt(u.cash+amt)}`;
  }

  // ── GIVE ──
  if (['.give','.pay','.send'].includes(cmd)) {
    const target=args[0], amt=parseInt(args[1]);
    if(!target||!amt||amt<=0) return '😒 .give <name> <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    // When someone @mentions a user in WhatsApp, the text token is a @lid
    // (a privacy ID, not a real phone number). Use the already-resolved
    // mentionedJids array passed in from the WA handler — it contains the
    // real phone JIDs after lid resolution — so we always get the right user.
    let r;
    if (target.startsWith('@') && mentionedJids.length > 0) {
      const realJid = mentionedJids[0]; // e.g. "2221234567@s.whatsapp.net"
      const realNum = realJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
      const uid = resolveId('wa_' + realNum);
      r = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
        || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + realNum);
    } else if (target.startsWith('@')) {
      // Fallback: no mentionedJids available, strip digits from text token
      const digits = target.replace(/\D/g,'');
      const uid = resolveId('wa_' + digits);
      r = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
        || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + digits);
    } else {
      r = db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(target);
    }
    if(!r) return `❄️ can\'t find "${target}"`;
    if(r.id===userId) return '😒 cannot pay yourself.';
    if(!own) addCash(userId,-amt);
    addCash(r.id,amt); addXP(userId,5);
    return `💗 sent ${fmt(amt)} to ${r.name}`;
  }

  // ── GAMBLING ──
  if (cmd==='.flip') {
    let side=(args[0]||'').toLowerCase(), amt=parseInt(args[1]);
    if(side==='h') side='heads'; if(side==='t') side='tails';
    if(!['heads','tails'].includes(side)||!amt||amt<=0) return '😒 .flip h/t <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    const flipChance=Math.min(0.78,0.5*luckyBoost);
    const result=Math.random()<flipChance?side:(side==='heads'?'tails':'heads');
    if(own||result===side){
      addCash(userId,amt); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); addXP(userId,10);
      return `💗 ${result} — won ${fmt(amt)}!`;
    } else {
      addCash(userId,-amt); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);
      return `❄️ ${result} — lost ${fmt(amt)}.`;
    }
  }

  if (cmd==='.slots') {
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .slots <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    const sym=['🍎','🍋','🍇','💎','7️⃣','🎰','⭐','🔥'];
    const s1=own?'💎':sym[randomInt(0,7)], s2=own?'💎':sym[randomInt(0,7)], s3=own?'💎':sym[randomInt(0,7)];
    const spin=`[ ${s1} | ${s2} | ${s3} ]`;
    if(s1===s2&&s2===s3){
      const mult=s1==='💎'?10:s1==='7️⃣'?7:s1==='🔥'?5:3;
      const win=amt*mult; addCash(userId,win); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); addXP(userId,50);
      return `🎰 ${spin}\nJACKPOT x${mult}! +${fmt(win)}`;
    } else if(s1===s2||s2===s3||s1===s3){
      const win=Math.floor(amt*0.5); addCash(userId,win);
      return `🎰 ${spin}\npartial — +${fmt(win)}`;
    } else {
      addCash(userId,-amt); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);
      return `🎰 ${spin}\nlost ${fmt(amt)}.`;
    }
  }

  if (cmd==='.dice') {
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .dice <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    const roll=own?6:randomInt(1,6), bot=own?1:randomInt(1,6);
    if(roll>bot){ addCash(userId,amt); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); return `🎲 ${roll} vs ${bot} — win! +${fmt(amt)}`; }
    else if(roll<bot){ addCash(userId,-amt); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId); return `🎲 ${roll} vs ${bot} — lose. -${fmt(amt)}`; }
    return `🎲 ${roll} vs ${roll} — tie!`;
  }

  if (cmd==='.rps') {
    const pick=(args[0]||'').toLowerCase(), amt=parseInt(args[1]);
    const opts=['rock','paper','scissors'];
    if(!opts.includes(pick)||!amt||amt<=0) return '😒 .rps rock/paper/scissors <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    const beats={rock:'scissors',paper:'rock',scissors:'paper'};
    const em={rock:'🪨',paper:'📄',scissors:'✂️'};
    const bot=own?beats[pick]:opts[randomInt(0,2)];
    if(pick===bot) return `${em[pick]} vs ${em[bot]} — tie!`;
    if(beats[pick]===bot){ addCash(userId,amt); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); return `${em[pick]} vs ${em[bot]} — win! +${fmt(amt)}`; }
    addCash(userId,-amt); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);
    return `${em[pick]} vs ${em[bot]} — lose. -${fmt(amt)}`;
  }

  // ── ROB ──
  if (cmd==='.rob') {
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .rob <amount>';
    if(!own&&u.cash<=0) return `❄️ you're already broke. nothing to risk.`;
    // Guard patrol protection (Option 3)
    if (!own && groupPatrol[chatId] && groupPatrol[chatId] > Date.now()) {
      const minsLeft = Math.ceil((groupPatrol[chatId] - Date.now()) / 60000);
      return `🛡️ Rob blocked! A Guard has the group under patrol for ${minsLeft} more min.`;
    }
    if(own||Math.random()<0.45){ addCash(userId,amt); addXP(userId,15); return `💗 got away with ${fmt(amt)}`; }
    const fine=Math.floor(amt*0.5); addCash(userId,-fine);
    return `❄️ caught. fined ${fmt(fine)}.`;
  }

  // ── STEAL from person ──
  if (cmd==='.steal') {
    const target=args[0];
    if(!target) return '😒 .steal <name>';
    if (!own && groupPatrol[chatId] && groupPatrol[chatId] > Date.now()) {
      const minsLeft = Math.ceil((groupPatrol[chatId] - Date.now()) / 60000);
      return `🛡️ Steal blocked! Guard patrol active for ${minsLeft} more min.`;
    }
    // Resolve @mention to real user (same pattern as .give and .duel)
    let victim;
    if (target.startsWith('@') && mentionedJids.length > 0) {
      const realJid = mentionedJids[0];
      const realNum = realJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
      const uid = resolveId('wa_' + realNum) || ('wa_' + realNum);
      victim = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
             || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + realNum);
    } else if (target.startsWith('@')) {
      const digits = target.replace(/\D/g,'');
      const uid = resolveId('wa_' + digits) || ('wa_' + digits);
      victim = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
             || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + digits);
    } else {
      victim = db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(target);
    }
    if(!victim) return `❄️ can\'t find "${target}".`;
    if(victim.id===userId) return '😒 cannot steal from yourself.';
    if(isOwner(victim.id)) {
      // Punish the thief — lose 20% of their cash
      const penalty = Math.floor((u.cash||0) * 0.20);
      if (penalty > 0 && !own) addCash(userId, -penalty);
      return `👑 ...you just tried to steal from the LORD.\n\n⚡ Bad move. Really bad.\n${penalty > 0 ? `You lost ${fmt(penalty)} for the audacity.` : ''}\n\n_The crown is untouchable._`;
    }
    if(!own&&hasItem(victim.id,'shield')) return `🛡️ ${victim.name} has a shield. fail.`;
    if(own||Math.random()<0.45){
      const stolen=Math.min(randomInt(100,600),victim.cash);
      if(stolen<=0) return `❄️ ${victim.name} is broke.`;
      addCash(userId,stolen); addCash(victim.id,-stolen); addXP(userId,20);
      return `🦹 ${name} stole ${fmt(stolen)} from ${victim.name}!`;
    }
    const fine=randomInt(100,400); addCash(userId,-fine);
    return `❌ caught stealing from ${victim.name}. fined ${fmt(fine)}.`;
  }

  // ── HEIST ──
  if (cmd==='.heist') {
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .heist <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    if(own||Math.random()<0.4){
      const win=amt*randomInt(2,5); addCash(userId,win); addXP(userId,60); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId);
      return `🏴‍☠️ heist success! +${fmt(win)}`;
    }
    addCash(userId,-amt); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);
    return `❌ heist failed. lost ${fmt(amt)}.`;
  }

  // ── FIGHT ──
  if (cmd==='.fight') {
    const target=args[0]||'someone';
    const moves=['uppercut','spinning kick','headbutt','dropkick','suplex','elbow drop'];
    if(own||Math.random()<0.5){ addXP(userId,30); return `🥊 ${name} hit ${target} with a ${moves[randomInt(0,moves.length-1)]} and won! +30xp`; }
    return `🥊 ${name} tried to fight ${target} and lost. embarrassing.`;
  }


  // ── TALENT ──
  if (cmd==='.talent') {
    const talentLines=[
      'You mimicked everyone in the room without moving your face.',
      'Performed a skill nobody knew you had. They still don\'t know what to do with it.',
      'Did something impressive. The room adjusted.',
      'Your talent showed up, did its thing, and left everyone slightly confused.',
      'Turned on something people didn\'t expect. They clapped eventually.',
      'Made it look easy. It wasn\'t.',
      'The silence after said more than the applause.',
      'Did the thing you always knew you could. Finally.',
      'Performed under pressure. Pressure lost.',
      'Everyone in the room had to recalibrate after that.',
    ];
    const talentFails=[
      'Tried. The room was polite. That\'s all.',
      'Showed up and blanked. It happens.',
      'The talent was there. The timing wasn\'t.',
      'Performance anxiety is real. Today it won.',
    ];
    const mins=u.last_work?(now-new Date(u.last_work))/60000:999;
    if(mins<20&&!own) return `😒 rest ${Math.ceil(20-mins)} more min.`;
    const amt=Math.floor(randomInt(400,4000)*(u.level||1)*boost*(own?5:1));
    if(own||Math.random()<0.65){
      addCash(userId,amt); setField(userId,'last_work',now.toISOString());
      const lv=addXP(userId,25);
      return `💗 ${talentLines[randomInt(0,talentLines.length-1)]} ${fmt(amt)}.${lv?'\n⬆️ Level up — Lv'+lv:''}`;
    }
    return `😒 ${talentFails[randomInt(0,talentFails.length-1)]}`;
  }
  // ── SEARCH ──
  if (cmd==='.search') {
    const places=['under the couch','in old jeans','behind the fridge','in a forgotten wallet','in an old school bag','between sofa cushions','in a cracked piggy bank'];
    if(own||Math.random()<0.5){ const amt=randomInt(50,600)*(own?5:1); addCash(userId,amt); return `🔍 found ${fmt(amt)} ${places[randomInt(0,places.length-1)]}!`; }
    return `🔍 searched ${places[randomInt(0,places.length-1)]} and found nothing.`;
  }

  // ── LOAN ──
  if (cmd==='.loan') {
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .loan <amount>';
    const max=Math.max(1000,(u.level||1)*500);
    if(amt>max) return `❄️ max loan for your level: ${fmt(max)}`;
    addCash(userId,amt);
    return `🏦 loaned ${fmt(amt)}. pay back ${fmt(Math.floor(amt*1.2))} (20% interest).`;
  }

  // ── FISH ──
  if (cmd==='.fish') {
    if(!own&&!hasItem(userId,'fishing')) return `❄️ you need a 🎣 fishing rod.\n.buy fishing (${fmt(500)})`;
    const fishWins=[
      'The pier was empty except for you and whatever\'s below it. {N} naura in fish, and no further questions.',
      'Something pulled. You pulled back. You won. {N} naura.',
      'Caught something worth {N} naura and chose not to name it.',
      'The water gave something up today. {N} naura worth of it.',
      'Sat there long enough that the fish got curious. {N} naura.',
      'Rod said yes. Water said yes. Wallet said yes. {N} naura.',
    ];
    const fishLoss=[
      'The rod is a liar and the river knows it.',
      'Sat there for an hour. The water had opinions. No fish.',
      'Something bit. Wasn\'t a fish. Left immediately.',
      'The fish saw you first.',
    ];
    const fishVals=[200,400,600,800,1200,2000];
    const idx=own?5:randomInt(0,fishVals.length-1);
    const val=own?2000:randomInt(0,10)<4?0:fishVals[idx];
    if(val>0){ addCash(userId,val); addXP(userId,15); try{logJobEarning(userId,val);}catch(_){}
      const line=fishWins[randomInt(0,fishWins.length-1)].replace('{N}',val.toLocaleString());
      return `🎣 ${line}`; }
    return `🎣 ${fishLoss[randomInt(0,fishLoss.length-1)]}`;
  }

  // ── MINE ──
  if (cmd==='.mine') {
    if(!own&&!hasItem(userId,'pickaxe')) return `❄️ you need a ⛏️ pickaxe.\n.buy pickaxe (${fmt(800)})`;
    const mineWins=[
      'The ground gave up {N} naura worth of what it was holding onto.',
      'Went deep. Found something. Came back with {N} naura.',
      'Mining is just asking the earth uncomfortable questions. It answered. {N} naura.',
      'Dug until something valuable answered back. {N} naura.',
      'The rock had secrets. You have {N} naura now.',
      'Found {N} naura underground where nobody thought to look.',
    ];
    const mineLoss=[
      'Dug until the shovel gave up.',
      'The ground said no. Firmly.',
      'Mined for an hour. Found opinions.',
      'Empty vein. Try again later.',
    ];
    const mineVals=[100,200,300,500,800,3000];
    const idx=own?5:randomInt(0,mineVals.length-1);
    const val=own?3000:randomInt(0,10)<3?0:mineVals[idx];
    if(val>0){ addCash(userId,val); addXP(userId,20); try{logJobEarning(userId,val);}catch(_){}
      const line=mineWins[randomInt(0,mineWins.length-1)].replace('{N}',val.toLocaleString());
      return `⛏️ ${line}`; }
    return `⛏️ ${mineLoss[randomInt(0,mineLoss.length-1)]}`;
  }

  // ── DROP ──
  if (cmd==='.drop') {
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .drop <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    if(pendingDrops[chatId]) return '❄️ a drop is already active. .grab to claim it.';
    if(!own) addCash(userId,-amt);
    pendingDrops[chatId]={amount:amt,by:userId,byName:name};
    return `🎁 ${name} dropped ${fmt(amt)} in chat!\nfirst to type .grab claims it!`;
  }
  if (cmd==='.grab') {
    const drop=pendingDrops[chatId];
    if(!drop) return '...nothing to grab.';
    if(drop.by===userId) return '😒 cannot grab your own drop.';
    addCash(userId,drop.amount); addXP(userId,20); delete pendingDrops[chatId];
    return `🎉 ${name} grabbed ${fmt(drop.amount)} from ${drop.byName}!`;
  }

  // ── DUEL ──
  if (cmd==='.duel') {
    const target=args[0], amt=parseInt(args[1]);
    if(!target||!amt||amt<=0) return '😒 .duel <name> <amount>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    if(pendingDuels[chatId]) return '❄️ a duel is already pending.';
    // Resolve @mention to real user so .accept can match by userId
    let targetUserId = null, targetDisplayName = target;
    if (target.startsWith('@') && mentionedJids.length > 0) {
      const realJid = mentionedJids[0];
      const realNum = realJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
      targetUserId = resolveId('wa_' + realNum) || ('wa_' + realNum);
      const tRow = db.prepare('SELECT name FROM users WHERE id=?').get(targetUserId);
      if (tRow) targetDisplayName = tRow.name;
    } else if (target.startsWith('@')) {
      const digits = target.replace(/\D/g,'');
      targetUserId = resolveId('wa_' + digits) || ('wa_' + digits);
      const tRow = db.prepare('SELECT name FROM users WHERE id=?').get(targetUserId);
      if (tRow) targetDisplayName = tRow.name;
    }
    pendingDuels[chatId]={
      challenger:userId, challengerName:name,
      target: targetDisplayName.toLowerCase(),
      targetUserId,
      amount:amt, expires:Date.now()+60000
    };
    return `⚔️ ${name} challenges ${targetDisplayName} to a duel!\nBet: 🪙 ${fmt(amt)} naura\n${targetDisplayName}, type .accept or .decline (60s)`;
  }
  if (cmd==='.accept') {
    const d=pendingDuels[chatId];
    if(!d) return '...no duel to accept.';
    if(Date.now()>d.expires){delete pendingDuels[chatId];return '❄️ duel expired.';}
    // Match by userId (covers @lid mentions) OR by name (covers plain-text duels)
    if(userId!==d.targetUserId && name.toLowerCase()!==d.target) return `...that duel wasn\'t for you.`;
    const tv=getUser(userId,name);
    if(!own&&tv.cash<d.amount) return `not enough to accept. need ${fmt(d.amount)}`;
    delete pendingDuels[chatId];
    const cWins=own||Math.random()<0.5;
    if(cWins){ addCash(d.challenger,d.amount); addCash(userId,-d.amount); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(d.challenger); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId); addXP(d.challenger,50); return `⚔️ ${d.challengerName} vs ${name}\n🏆 ${d.challengerName} wins ${fmt(d.amount)}!`; }
    addCash(userId,d.amount); addCash(d.challenger,-d.amount); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(d.challenger); addXP(userId,50);
    return `⚔️ ${d.challengerName} vs ${name}\n🏆 ${name} wins ${fmt(d.amount)}!`;
  }
  if (cmd==='.decline') {
    const d=pendingDuels[chatId];
    if(!d) return '...no duel pending.';
    if(userId!==d.targetUserId && name.toLowerCase()!==d.target) return `...not your duel.`;
    delete pendingDuels[chatId];
    return `😒 ${name} declined. coward energy.`;
  }

  // ── LOTTERY ──
  if (cmd==='.lottery') {
    const price=500;
    if(!own&&u.cash<price) return `need ${fmt(price)} for a ticket.`;
    if(!lotteryPots[chatId]) lotteryPots[chatId]={tickets:[],pot:0};
    const pot=lotteryPots[chatId];
    if(pot.tickets.find(t=>t.userId===userId)) return '😒 you already have a ticket.';
    if(!own) addCash(userId,-price);
    pot.tickets.push({userId,name}); pot.pot+=price;
    if(pot.tickets.length>=5||own){
      const winner=pot.tickets[randomInt(0,pot.tickets.length-1)];
      const prize=pot.pot; addCash(winner.userId,prize); delete lotteryPots[chatId];
      return `🎰 LOTTERY DRAW!\n${pot.tickets.map(t=>t.name).join(', ')}\n\n🏆 ${winner.name} wins ${fmt(prize)}!`;
    }
    return `🎟️ ${name} bought a ticket!\nPot: ${fmt(pot.pot)} · Players: ${pot.tickets.length}/5\ntype .lottery to join`;
  }

  // ── GIVEAWAY ──
  if (cmd==='.giveaway') {
    if(!own&&!isSudo(userId)) return '❌ only admins/sudo can start giveaways.';
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .giveaway <amount>\ne.g. .giveaway 50000';
    if(!own&&amt>u.cash) return `💗 not enough naura to fund that. you have ${fmt(u.cash)}`;
    if(pendingGiveaways[chatId]) return '❄️ a giveaway is already running here. .endgiveaway to cancel or .winners to draw.';
    if(!own) addCash(userId,-amt);
    pendingGiveaways[chatId]={amount:amt,by:userId,byName:name,entries:[],startedAt:Date.now()};
    setTimeout(()=>{
      const gw=pendingGiveaways[chatId];
      if(!gw||gw.entries.length===0){delete pendingGiveaways[chatId];return;}
    },3600000); // auto-expire after 1hr
    return `🎉 *GIVEAWAY STARTED!*\n\n💰 Prize: ${fmt(amt)}\nSponsored by: ${name}\n\nType .enter to join!\n.winners to draw a winner · .endgiveaway to cancel`;
  }
  if (cmd==='.enter') {
    const gw=pendingGiveaways[chatId];
    if(!gw) return '...no giveaway running. wait for one to start.';
    if(gw.entries.find(e=>e.id===userId)) return '😒 you already entered.';
    gw.entries.push({id:userId,name});
    return `✅ ${name} entered the giveaway! (${gw.entries.length} ${gw.entries.length===1?'entry':'entries'} so far)`;
  }
  if (cmd==='.winners'||cmd==='.drawwinner') {
    if(!own&&!isSudo(userId)) return '❌ only admins/sudo can draw winners.';
    const gw=pendingGiveaways[chatId];
    if(!gw) return '...no active giveaway.';
    if(!gw.entries.length) return '😒 no one entered.';
    const winner=gw.entries[randomInt(0,gw.entries.length-1)];
    addCash(winner.id,gw.amount); addXP(winner.id,100);
    delete pendingGiveaways[chatId];
    return `🎉 *GIVEAWAY OVER!*\n\n🏆 Winner: *${winner.name}*\n💰 Prize: ${fmt(gw.amount)}\n\n${winner.name} wins! congrats.`;
  }
  if (cmd==='.endgiveaway') {
    if(!own&&!isSudo(userId)) return '❌ only admins/sudo can cancel giveaways.';
    if(!pendingGiveaways[chatId]) return '...no active giveaway.';
    const gw=pendingGiveaways[chatId];
    if(!own) addCash(gw.by,gw.amount); // refund
    delete pendingGiveaways[chatId];
    return '💗 giveaway cancelled. prize refunded.';
  }
  if (cmd==='.giveawayinfo'||cmd==='.gwinfo') {
    const gw=pendingGiveaways[chatId];
    if(!gw) return '...no giveaway running.';
    const elapsed=Math.floor((Date.now()-gw.startedAt)/60000);
    return `🎉 *GIVEAWAY INFO*\n\n💰 Prize: ${fmt(gw.amount)}\nBy: ${gw.byName}\n👥 Entries: ${gw.entries.length}\n⏱️ Running: ${elapsed} min\n\n.enter to join · .winners to draw`;
  }

  // ── SHOP ──
  if (cmd==='.shop') {
    return '🛒 SHOP\n\n'+Object.entries(SHOP).map(([k,v])=>`${k} — ${fmt(v.price)}\n${v.desc}`).join('\n\n')+'\n\n.buy <item>';
  }
  if (cmd==='.buy') {
    const item=(args[0]||'').toLowerCase();
    if(!SHOP[item]) return '😒 unknown item. .shop';
    const price=SHOP[item].price;
    if(item==='piggy') return '🐷 piggy bank is free! use .piggy to start saving.';
    if(!own&&u.cash<price) return `not enough. need ${fmt(price)}`;
    if(!own&&price>0) addCash(userId,-price);
    if(item==='booster'){ boosterActive[userId]=Date.now()+3600000; return `🚀 booster active! 2x earnings for 1hr.`; }
    if(item==='lucky'){ luckyActive[userId]=Date.now()+1800000; return `🍀 lucky charm active! +30% win rate for 30 min.`; }
    if(item==='amulet'){ amuletActive[userId]=Date.now()+7200000; return `🧿 amulet active! crime fines halved for 2hr.`; }
    if(item==='diamond'){
      diamondUsers.add(userId);
      return `💎 *DIAMOND* equipped! Permanent +10% work bonus active.`;
    }
    if(item==='vip'){
      const expires=Date.now()+7*24*3600000;
      db.prepare('UPDATE users SET vip_expires=? WHERE id=?').run(own?9999999999999:expires,userId);
      addItem(userId,'vip',1);
      return `⭐ *VIP ACTIVATED!* 7-day VIP status granted.\nPerks: VIP badge on profile, priority drops, 10% shop discount.`;
    }
    if(item==='ticket'){
      if(!lotteryPots[chatId]) lotteryPots[chatId]={tickets:[],pot:0};
      const pot=lotteryPots[chatId];
      if(pot.tickets.find(t=>t.userId===userId)) return '😒 you already have a lottery ticket.';
      pot.tickets.push({userId,name}); pot.pot+=300;
      return `🎟️ lottery ticket bought! Pot: ${fmt(pot.pot)} · Players: ${pot.tickets.length}`;
    }
    if(item==='lootbox'){
      const roll=randomInt(1,10);
      if(roll<=3){const b=randomInt(500,4000);addCash(userId,b);return `📦 lootbox: +${fmt(b)}!`;}
      else if(roll<=5){addItem(userId,'shield',1);return '📦 lootbox: got a 🛡️ shield!';}
      else if(roll<=7){addItem(userId,'booster',1);boosterActive[userId]=Date.now()+3600000;return '📦 lootbox: got a 🚀 booster! active now.';}
      else if(roll<=9){addItem(userId,'scratch',1);return '📦 lootbox: got a 🎰 scratch card!';}
      else{luckyActive[userId]=Date.now()+1800000;return '📦 lootbox: got a 🍀 lucky charm! 30 min luck boost.';}
    }
    if(item==='scratch'){
      // Using a scratch card purchased as item
      addItem(userId,'scratch',1);
      return `🎰 scratch card added to inventory. use .scratch to use it.`;
    }
    addItem(userId,item,1);
    return `💗 bought ${item}${own||price===0?'':` (-${fmt(price)})`}`;
  }
  if (['.inv','.inventory'].includes(cmd)) {
    const inv=getInventory(userId);
    if(!inv.length) return '🎒 inventory empty.';
    return '🎒 '+inv.map(i=>`${i.item} x${i.quantity}`).join(', ');
  }

  // ── LEADERBOARDS ──
  if (['.rich','.top','.lb'].includes(cmd)) {
    const top=db.prepare('SELECT id,name,cash,bank,level FROM users ORDER BY (cash+bank) DESC LIMIT 10').all();
    const ownerRow = OWNER_GOD_MODE && top.find(r => isOwner(r.id));
    const header = ownerRow
      ? `👑 *TOP 10 RICHEST*\n_The throne is taken — good luck._\n\n`
      : `🏆 *TOP 10 RICHEST*\n\n`;
    return header + top.map((r,i)=>{
      const isOwnerRow = OWNER_GOD_MODE && isOwner(r.id);
      const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':`${i+1}.`;
      const crown = isOwnerRow ? ' 👑 LORD' : '';
      const infinity = isOwnerRow ? '∞' : fmt(r.cash+r.bank);
      return `${medal} ${r.name}${crown} (Lv${r.level||1}) — ${infinity}`;
    }).join('\n');
  }
  if (['.levels','.lvl','.toplevel'].includes(cmd)) {
    const top=db.prepare('SELECT name,level,xp FROM users ORDER BY level DESC,xp DESC LIMIT 10').all();
    return '⭐ TOP 10 LEVELS\n\n'+top.map((u,i)=>`${i+1}. ${u.name} — Lv${u.level||1}`).join('\n');
  }
  if (cmd==='.rank') {
    const all=db.prepare('SELECT id,(cash+bank) as net FROM users ORDER BY (cash+bank) DESC').all();
    const pos=all.findIndex(r=>r.id===userId)+1;
    const medal=pos===1?'🥇':pos===2?'🥈':pos===3?'🥉':`#${pos}`;
    return `${medal} ${name} is rank ${pos} of ${all.length}\n💎 ${fmt(u.cash+u.bank)}`;
  }
  if (cmd==='.flex') {
    if (own) {
      return `💅 *${name} is FLEXING — LORD TIER*\n\n` +
        `👑 UNTOUCHABLE · DIVINE\n` +
        `💎 ${fmt(999999999999999)}\n` +
        `⭐ Level 9999 · Prestige 99\n` +
        `🏆 Rank #1 of ${db.prepare('SELECT COUNT(*) as c FROM users').get().c} — permanent\n\n` +
        `_No one competes. No one comes close._`;
    }
    const net=u.cash+u.bank;
    const rank=db.prepare('SELECT COUNT(*)+1 as r FROM users WHERE (cash+bank)>?').get(net);
    const tier=net>=1000000?'💎 BILLIONAIRE':net>=500000?'💰 LOADED':net>=100000?'🤑 GETTING THERE':net>=10000?'📈 GRINDING':'💸 BROKE BUT FLEXING';
    return `💅 ${name} is FLEXING\n\n${tier}\n${fmt(net)}\nRank #${rank.r} · Lv${u.level||1}\n\n_#1 is taken — but keep grinding._`;
  }
  if (cmd==='.streak') {
    const s=checkStreak(userId);
    const bonus=s>=7?500:s>=3?200:0;
    if(bonus>0){addCash(userId,bonus);return `🔥 Day ${s} streak! +${fmt(bonus)} bonus!`;}
    return `🔥 Day ${s} streak. (bonus at day 3 and 7)`;
  }

  // ── NOTES ──
  if (cmd==='.note') {
    const title=args[0], content=args.slice(1).join(' ');
    if(!title||!content) return '😒 .note <title> <content>';
    db.prepare('INSERT INTO notes (user_id,title,content,created_at) VALUES (?,?,?,?)').run(userId,title,content,now.toISOString());
    return `📝 note "${title}" saved.`;
  }
  if (cmd==='.notes') {
    const notes=db.prepare("SELECT id,title FROM notes WHERE user_id=? AND title NOT LIKE '__%%__' ORDER BY id DESC LIMIT 10").all(userId);
    if(!notes.length) return '📝 no notes saved.';
    return '📝 your notes:\n'+notes.map(n=>`#${n.id} ${n.title}`).join('\n')+'\n\n.readnote <id>';
  }
  if (cmd==='.readnote') {
    const id=parseInt(args[0]);
    const note=db.prepare('SELECT * FROM notes WHERE id=? AND user_id=?').get(id,userId);
    if(!note) return '❄️ note not found.';
    const pwRow=db.prepare("SELECT content FROM notes WHERE user_id=? AND title='__notespw__'").get(userId);
    if(pwRow){const exp=_unlockedNotes.get(userId);if(!exp||exp<Date.now()) return '🔒 notes locked. use .npw <password> to unlock.';}
    return `📝 ${note.title}\n\n${note.content}`;
  }
  if (cmd==='.delnote') {
    const id=parseInt(args[0]);
    const pwRow=db.prepare("SELECT content FROM notes WHERE user_id=? AND title='__notespw__'").get(userId);
    if(pwRow){const exp=_unlockedNotes.get(userId);if(!exp||exp<Date.now()) return '🔒 notes locked. use .npw <password> to unlock first.';}
    db.prepare('DELETE FROM notes WHERE id=? AND user_id=?').run(id,userId);
    return `📝 note deleted.`;
  }

  // ── SPIN WHEEL ──
  if (cmd==='.spin') {
    const today=now.toDateString();
    try { db.prepare('INSERT OR IGNORE INTO user_stats (user_id) VALUES (?)').run(userId); } catch(_){}
    const stats=db.prepare('SELECT last_spin FROM user_stats WHERE user_id=?').get(userId);
    if(!own && stats?.last_spin===today) return `🎡 already spun today! come back tomorrow.`;
    const slots=[
      {label:'💎 JACKPOT',chance:2,cash:50000,xp:200},
      {label:'🏆 GRAND PRIZE',chance:4,cash:20000,xp:100},
      {label:'🎉 BIG WIN',chance:8,cash:8000,xp:60},
      {label:'💗 WIN',chance:15,cash:3000,xp:30},
      {label:'✨ SMALL WIN',chance:25,cash:1000,xp:15},
      {label:'🎁 BONUS ITEM',chance:15,cash:0,xp:20,item:'lootbox'},
      {label:'🛡️ SHIELD',chance:10,cash:0,xp:10,item:'shield'},
      {label:'😐 NOTHING',chance:21,cash:0,xp:5},
    ];
    let roll=randomInt(1,100),cumul=0,result=slots[slots.length-1];
    for(const s of slots){cumul+=s.chance;if(roll<=cumul){result=s;break;}}
    if(result.cash>0) addCash(userId,result.cash*(own?3:1));
    if(result.item) addItem(userId,result.item,1);
    const lv=addXP(userId,result.xp);
    db.prepare('INSERT OR REPLACE INTO user_stats (user_id,last_spin,msgs_sent,cmds_used,games_played,ai_chats) VALUES (?,?,COALESCE((SELECT msgs_sent FROM user_stats WHERE user_id=?),0),COALESCE((SELECT cmds_used FROM user_stats WHERE user_id=?),0),COALESCE((SELECT games_played FROM user_stats WHERE user_id=?),0),COALESCE((SELECT ai_chats FROM user_stats WHERE user_id=?),0))').run(userId,today,userId,userId,userId,userId);
    let reply=`🎡 *DAILY SPIN*\n\nRolled: ${roll}/100\n\n${result.label}!`;
    if(result.cash>0) reply+=`\n+${fmt(result.cash*(own?3:1))}`;
    if(result.item) reply+=`\n+1 ${result.item}`;
    if(lv) reply+=`\n⬆️ Level up — Lv${lv}`;
    return reply;
  }

  // ── BLACKJACK ──
  if (['.blackjack','.bj'].includes(cmd)) {
    if(!own&&!hasItem(userId,'spade')) return `❄️ you need a 🃏 card deck to play.\n.buy spade (${fmt(1200)})`;
    const amt=parseInt(args[0]);
    if(!amt||amt<=0) return '😒 .blackjack <bet>';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    const deck=[2,3,4,5,6,7,8,9,10,10,10,10,11];
    const draw=()=>deck[randomInt(0,deck.length-1)];
    const hand=[draw(),draw()];
    const dealer=[draw(),draw()];
    const total=(h)=>{let s=h.reduce((a,b)=>a+b,0);if(s>21&&h.includes(11)){s-=10;}return s;};
    const pTotal=total(hand), dTotal=total(dealer);
    // Natural blackjack check
    if(pTotal===21){
      const win=Math.floor(amt*1.5);
      addCash(userId,own?win:win); db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); addXP(userId,50);
      return `🃏 *BLACKJACK!*\n\nYour hand: ${hand.join(' + ')} = 21\nDealer: ${dealer[0]} + ?\n\n🎉 NATURAL BLACKJACK! +${fmt(win)}`;
    }
    blackjackGames[chatId+'_'+userId]={hand,dealer,bet:amt,userId,name};
    addCash(userId,-amt);
    return `🃏 *BLACKJACK*\n\nYour hand: ${hand.join(' + ')} = ${pTotal}\nDealer shows: ${dealer[0]}\n\n🎴 .bjhit — take a card\n🛑 .bjstand — hold\n(Bet: ${fmt(amt)})`;
  }
  if (cmd==='.bjhit') {
    const g=blackjackGames[chatId+'_'+userId];
    if(!g) return '...no blackjack game for you. .blackjack <bet>';
    const deck=[2,3,4,5,6,7,8,9,10,10,10,10,11];
    const draw=()=>deck[randomInt(0,deck.length-1)];
    const total=(h)=>{let s=h.reduce((a,b)=>a+b,0);if(s>21&&h.includes(11)){s-=10;}return s;};
    g.hand.push(draw()); const pt=total(g.hand);
    if(pt>21){delete blackjackGames[chatId+'_'+userId];db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);return `🃏 Your hand: ${g.hand.join(' + ')} = ${pt}\n\n💥 BUST! Lost ${fmt(g.bet)}.`;}
    if(pt===21){
      // Auto-stand on 21
      let dt=total(g.dealer);
      while(dt<17){g.dealer.push(draw());dt=total(g.dealer);}
      delete blackjackGames[chatId+'_'+userId];
      if(dt>21||pt>dt){addCash(userId,g.bet*2);db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId);addXP(userId,40);return `🃏 Your: ${g.hand.join('+')}=${pt} | Dealer: ${g.dealer.join('+')}=${dt}\n\n🏆 WIN! +${fmt(g.bet*2)}`;}
      if(pt===dt){addCash(userId,g.bet);return `🃏 Your: ${pt} | Dealer: ${dt}\n\n🤝 PUSH — bet returned.`;}
      db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);return `🃏 Your: ${pt} | Dealer: ${dt}\n\n❌ DEALER WINS. Lost ${fmt(g.bet)}.`;
    }
    return `🃏 Your hand: ${g.hand.join(' + ')} = ${pt}\n\n🎴 .bjhit — another card | 🛑 .bjstand — hold`;
  }
  if (cmd==='.bjstand') {
    const g=blackjackGames[chatId+'_'+userId];
    if(!g) return '...no blackjack game. .blackjack <bet>';
    const deck=[2,3,4,5,6,7,8,9,10,10,10,10,11];
    const draw=()=>deck[randomInt(0,deck.length-1)];
    const total=(h)=>{let s=h.reduce((a,b)=>a+b,0);if(s>21&&h.includes(11)){s-=10;}return s;};
    let dt=total(g.dealer);
    while(dt<17){g.dealer.push(draw());dt=total(g.dealer);}
    const pt=total(g.hand);
    delete blackjackGames[chatId+'_'+userId];
    if(dt>21||pt>dt){addCash(userId,g.bet*2);db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId);addXP(userId,40);return `🃏 Your: ${g.hand.join('+')}=${pt} | Dealer: ${g.dealer.join('+')}=${dt>21?'BUST':dt}\n\n🏆 YOU WIN! +${fmt(g.bet*2)}`;}
    if(pt===dt){addCash(userId,g.bet);return `🃏 Your: ${pt} | Dealer: ${dt}\n\n🤝 PUSH — bet returned.`;}
    db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);return `🃏 Your: ${g.hand.join('+')}=${pt} | Dealer: ${g.dealer.join('+')}=${dt}\n\n❌ DEALER WINS. Lost ${fmt(g.bet)}.`;
  }

  // ── SCRATCH CARD ──
  if (cmd==='.scratch') {
    const hasFreeCard=own||hasItem(userId,'scratch');
    const ticketPrice=400;
    if(!hasFreeCard&&u.cash<ticketPrice) return `need ${fmt(ticketPrice)} or buy a scratch card (.buy scratch).`;
    if(!hasFreeCard) addCash(userId,-ticketPrice);
    else if(!own) removeItem(userId,'scratch',1);
    const prizes=[
      ['💎','💎','💎',15000],[' 🥇','🥇','🥇',8000],['💗','💗','💗',4000],
      ['⭐','⭐','⭐',2000],['🔥','🔥','🔥',1000],['💰','💰','💗',500],
      ['💰','💰','⭐',200],['💰','💗','🔥',0],['💗','⭐','💰',0],['⭐','🔥','💎',0],
    ];
    const idx=own?0:randomInt(0,prizes.length-1);
    const [a,b,c,win]=prizes[idx];
    if(win>0){addCash(userId,win);addXP(userId,25);}
    return `🎰 *SCRATCH CARD*\n\n┌──────────────┐\n│  ${a}  │  ${b}  │  ${c}  │\n└──────────────┘\n\n${win>0?`💥 *${fmt(win)} WIN!*`:'😐 no luck. try again.'}`;
  }

  // ── INVEST ──
  if (cmd==='.invest') {
    const amt=parseInt(args[0]);
    if(!amt||amt<500) return '😒 .invest <amount> (min 500 naura)\nReturns after 1 hour. High risk, high reward.';
    if(!own&&amt>u.cash) return `💗 not enough naura. you have ${fmt(u.cash)}`;
    const pending=db.prepare('SELECT id FROM investments WHERE user_id=? AND claimed=0').get(userId);
    if(pending&&!own) return `❄️ you already have an active investment. .myinvest to check.`;
    if(!own) addCash(userId,-amt);
    const mults=[0.0,0.5,1.0,1.5,2.0,3.0,5.0];
    const weights=[10,15,20,25,18,9,3];
    let roll=randomInt(1,100),cum=0,multIdx=mults.length-1;
    for(let i=0;i<weights.length;i++){cum+=weights[i];if(roll<=cum){multIdx=i;break;}}
    const mult=own?5.0:mults[multIdx];
    const fireAt=Date.now()+3600000;
    db.prepare('INSERT INTO investments (user_id,amount,multiplier,returns_at,created_at) VALUES (?,?,?,?,?)').run(userId,amt,mult,fireAt,now.toISOString());
    return `📈 *INVESTMENT PLACED*\n\nAmount: ${fmt(amt)}\nReturns in: 1 hour\n\n.myinvest — check status\n.claiminvest — claim when ready\n\n⚠️ Returns range from 0× to 5× — high risk.`;
  }
  if (cmd==='.myinvest') {
    const inv=db.prepare('SELECT * FROM investments WHERE user_id=? AND claimed=0 ORDER BY id DESC LIMIT 1').get(userId);
    if(!inv) return `📈 no active investment.\n.invest <amount> to start.`;
    const timeLeft=inv.returns_at-Date.now();
    if(timeLeft>0){const m=Math.ceil(timeLeft/60000);return `📈 *INVESTMENT STATUS*\n\nAmount: ${fmt(inv.amount)}\nReturns in: ${m} min\nMultiplier: hidden until maturity\n\n.claiminvest when ready.`;}
    const returns=Math.floor(inv.amount*inv.multiplier);
    return `📈 *INVESTMENT READY!*\n\nAmount: ${fmt(inv.amount)}\nMultiplier: ${inv.multiplier}×\nReturns: ${fmt(returns)}\n\n.claiminvest to collect!`;
  }
  if (cmd==='.claiminvest') {
    const inv=db.prepare('SELECT * FROM investments WHERE user_id=? AND claimed=0 ORDER BY id DESC LIMIT 1').get(userId);
    if(!inv) return `📈 no investment to claim.`;
    if(Date.now()<inv.returns_at&&!own){const m=Math.ceil((inv.returns_at-Date.now())/60000);return `⏳ not ready yet. ${m} min left.`;}
    const returns=Math.floor(inv.amount*(own?5:inv.multiplier));
    db.prepare('UPDATE investments SET claimed=1 WHERE id=?').run(inv.id);
    if(returns>0){addCash(userId,returns);addXP(userId,50);}
    if(returns===0) return `📉 *INVESTMENT RESULT*\nMultiplier: 0×\n\nLost ${fmt(inv.amount)}. That's the market.`;
    const profit=returns-inv.amount;
    return `📈 *INVESTMENT CLAIMED!*\n\nInvested: ${fmt(inv.amount)}\nMultiplier: ${inv.multiplier}×\nReturned: ${fmt(returns)}\n${profit>0?`Profit: +${fmt(profit)}`:`Loss: ${fmt(Math.abs(profit))}`}`;
  }

  // ── PIGGY BANK ──
  if (cmd==='.piggy') {
    const sub=(args[0]||'').toLowerCase();
    try { db.prepare('INSERT OR IGNORE INTO piggybank (user_id) VALUES (?)').run(userId); } catch(_){}
    const pg=db.prepare('SELECT * FROM piggybank WHERE user_id=?').get(userId);
    if(sub==='add'||sub==='save'){
      const amt=args[1]==='all'?u.cash:parseInt(args[1]);
      if(!amt||amt<=0) return '😒 .piggy save <amount|all>';
      if(!own&&amt>u.cash) return `not enough cash.`;
      if(!own) addCash(userId,-amt);
      db.prepare('UPDATE piggybank SET saved=saved+?,last_added=? WHERE user_id=?').run(amt,now.toISOString(),userId);
      const newSaved=(pg.saved||0)+amt;
      return `🐷 saved ${fmt(amt)}!\nPiggy bank: ${fmt(newSaved)}${pg.goal?` / ${fmt(pg.goal)} goal`:''}`;
    }
    if(sub==='break'||sub==='smash'){
      if(!pg||!pg.saved) return `🐷 piggy bank is empty.`;
      const amt=pg.saved; addCash(userId,amt);
      db.prepare('UPDATE piggybank SET saved=0 WHERE user_id=?').run(userId);
      return `🐷💥 piggy bank smashed!\n+${fmt(amt)} to wallet.`;
    }
    if(sub==='goal'){
      const amt=parseInt(args[1]);
      if(!amt||amt<=0) return '😒 .piggy goal <amount>';
      db.prepare('UPDATE piggybank SET goal=? WHERE user_id=?').run(amt,userId);
      return `🐷 goal set: ${fmt(amt)}`;
    }
    const progress=pg?.goal?Math.min(100,Math.floor((pg.saved/pg.goal)*100)):null;
    return `🐷 *PIGGY BANK*\n\nSaved: ${fmt(pg?.saved||0)}${pg?.goal?`\nGoal: ${fmt(pg.goal)} (${progress}%)`:''}\n\n.piggy save <amount|all> — deposit\n.piggy smash — take it all out\n.piggy goal <amount> — set a savings goal`;
  }

  // ── PRESTIGE ──
  if (cmd==='.prestige') {
    if((u.level||1)<100) return `❄️ prestige requires Lv100. you are Lv${u.level||1}.`;
    db.prepare('UPDATE users SET level=1,xp=0,prestige=COALESCE(prestige,0)+1,cash=cash+50000 WHERE id=?').run(userId);
    return `✨ *PRESTIGE!*\n\n${name} has achieved Prestige ${(db.prepare('SELECT prestige FROM users WHERE id=?').get(userId)?.prestige||1)}!\n\nReset to Lv1 with +${fmt(50000)} bonus.\nPrestige badge now shows on your profile.`;
  }

  // ── VIP ──
  if (cmd==='.vip') {
    if(!hasItem(userId,'vip')&&!own){
      const vipEx=u.vip_expires||0;
      if(vipEx&&vipEx>Date.now()) return `⭐ VIP active! expires in ${Math.ceil((vipEx-Date.now())/3600000)}h.`;
      return `⭐ not a VIP. .buy vip (${fmt(5000)}) for 7-day VIP status.`;
    }
    const expires=Date.now()+7*24*3600000;
    db.prepare('UPDATE users SET vip_expires=? WHERE id=?').run(own?9999999999999:expires,userId);
    removeItem(userId,'vip',1);
    return `⭐ *VIP ACTIVATED!*\n\nExpires: ${own?'never':new Date(expires).toDateString()}\nPerks: VIP badge, priority drops, 10% shop discount.`;
  }

  // ── GIFT ──
  if (cmd==='.gift') {
    const target=args[0];
    if(!target) return '😒 .gift <name>';
    if(!own&&u.cash<500) return `not enough. need ${fmt(500)}.`;
    // Resolve @mention to real user (same pattern as .give and .duel)
    let r;
    if (target.startsWith('@') && mentionedJids.length > 0) {
      const realJid = mentionedJids[0];
      const realNum = realJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
      const uid = resolveId('wa_' + realNum) || ('wa_' + realNum);
      r = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
        || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + realNum);
    } else if (target.startsWith('@')) {
      const digits = target.replace(/\D/g,'');
      const uid = resolveId('wa_' + digits) || ('wa_' + digits);
      r = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
        || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + digits);
    } else {
      r = db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(target);
    }
    if(!r) return `❄️ can't find "${target}"`;
    if(r.id===userId) return '😒 cannot gift yourself.';
    const gifts=['fishing','shield','lootbox','scratch','ticket'];
    const chosen=gifts[randomInt(0,gifts.length-1)];
    if(!own) addCash(userId,-500);
    addItem(r.id,chosen,1);
    return `🎁 ${name} gifted a *${chosen}* to ${r.name}!`;
  }

  // ── CHAT STATS ──
  if (['.chatstats','.mystats'].includes(cmd)) {
    try { db.prepare('INSERT OR IGNORE INTO user_stats (user_id) VALUES (?)').run(userId); } catch(_){}
    const st=db.prepare('SELECT * FROM user_stats WHERE user_id=?').get(userId)||{msgs_sent:0,cmds_used:0,games_played:0,ai_chats:0};
    const net=u.cash+u.bank;
    return `📊 *YOUR STATS — ${name}*\n\n💬 Messages sent: ${st.msgs_sent||0}\n⌨️ Commands used: ${st.cmds_used||0}\n🎮 Games played: ${st.games_played||0}\n💕 Conversations with me: ${st.ai_chats||0}\n\n🎖️ Level: ${u.level||1} · XP: ${u.xp||0}/${(u.level||1)*100}\n💎 Net worth: ${fmt(net)}\n🏆 Wins: ${u.wins} · Losses: ${u.losses}\n✨ Prestige: ${u.prestige||0}`;
  }

  // ── SLOTS (naura-gated) ──
  if (cmd === '.slots') {
    const bet = parseInt(args[0]);
    if (!bet || bet <= 0) return `🎰 *.slots <bet>*\n\nSpin 3 reels for matching symbols!\n\nMin bet: ${fmt(500)}\nJackpot (3 💎): 20×\n3 of any symbol: 5×\n2 match: 1.5×\n\nExample: .slots 1000`;
    if (bet < 500) return `❌ minimum bet is ${fmt(500)}.`;
    if (!own && u.cash < bet) return `❌ not enough naura. you have ${fmt(u.cash)}.`;
    const reels = ['🍒','🍋','🔔','⭐','💎','🎰','7️⃣','🍀'];
    const spin = [reels[randomInt(0,reels.length-1)], reels[randomInt(0,reels.length-1)], reels[randomInt(0,reels.length-1)]];
    const row = `${spin[0]} | ${spin[1]} | ${spin[2]}`;
    if (!own) addCash(userId, -bet);
    let payout = 0, resultLine = '';
    if (spin[0]===spin[1]&&spin[1]===spin[2]) {
      if (spin[0]==='💎') { payout=bet*20; resultLine='💎 *JACKPOT! 3 DIAMONDS!*'; }
      else if (spin[0]==='7️⃣') { payout=bet*10; resultLine='7️⃣ *TRIPLE SEVENS!*'; }
      else { payout=bet*5; resultLine=`🎉 *TRIPLE ${spin[0]}!*`; }
    } else if (spin[0]===spin[1]||spin[1]===spin[2]||spin[0]===spin[2]) {
      payout=Math.floor(bet*1.5); resultLine='✨ *Two of a kind!*';
    } else {
      resultLine='❌ No match.';
    }
    if (payout>0) {
      addCash(userId, payout);
      db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId);
      addXP(userId, 20);
      return `🎰 *SLOTS*\n━━━━━━━━━━\n[ ${row} ]\n━━━━━━━━━━\n${resultLine}\n\nBet: ${fmt(bet)}\nPayout: +${fmt(payout)}\nNet: +${fmt(payout-bet)}`;
    } else {
      db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);
      return `🎰 *SLOTS*\n━━━━━━━━━━\n[ ${row} ]\n━━━━━━━━━━\n${resultLine}\n\nBet: ${fmt(bet)}\nLost: -${fmt(bet)}`;
    }
  }

  // ── WHEEL OF FORTUNE (naura-gated) ──
  if (cmd === '.wheel') {
    const bet = parseInt(args[0]);
    if (!bet || bet <= 0) return `🎡 *.wheel <bet>*\n\nSpin the wheel of fortune!\n\nMin bet: ${fmt(300)}\nSegments: 2× · 1.5× · 0.5× · 3× · 0× · 5×\n\nExample: .wheel 500`;
    if (bet < 300) return `❌ minimum bet is ${fmt(300)}.`;
    if (!own && u.cash < bet) return `❌ not enough naura. you have ${fmt(u.cash)}.`;
    const segments = [
      {label:'2×', mult:2, emoji:'🟢'},{label:'1.5×', mult:1.5, emoji:'🔵'},
      {label:'LOSE', mult:0, emoji:'⚫'},{label:'3×', mult:3, emoji:'🟡'},
      {label:'0.5×', mult:0.5, emoji:'🔴'},{label:'5×', mult:5, emoji:'💜'},
      {label:'1×', mult:1, emoji:'⚪'},{label:'LOSE', mult:0, emoji:'⚫'},
    ];
    const landed = segments[randomInt(0, segments.length-1)];
    if (!own) addCash(userId, -bet);
    const payout = Math.floor(bet * landed.mult);
    if (payout > 0) addCash(userId, payout);
    const net = payout - bet;
    const netFmt = net >= 0 ? `+${fmt(net)}` : `-${fmt(Math.abs(net))}`;
    if (payout >= bet) { db.prepare('UPDATE users SET wins=wins+1 WHERE id=?').run(userId); addXP(userId,15); }
    else db.prepare('UPDATE users SET losses=losses+1 WHERE id=?').run(userId);
    return `🎡 *WHEEL OF FORTUNE*\n\n${segments.map(s=>s.emoji+' '+s.label).join('  ')}\n\n🎯 Landed: ${landed.emoji} *${landed.label}*\n\nBet: ${fmt(bet)}\nPayout: ${fmt(payout)}\nNet: ${netFmt}`;
  }

  // ── SCRATCH CARD ──
  if (cmd === '.scratch') {
    if (!hasItem(userId, 'scratch') && !own) return `🎫 no scratch card! .buy scratch (${fmt(300)}) or .bmarket`;
    const grid = Array.from({length:9}, () => {
      const r = randomInt(1,10);
      return r<=2?'💎':r<=5?'⭐':r<=8?'🍀':'💀';
    });
    if (!own) removeItem(userId,'scratch',1);
    const counts = {};
    grid.forEach(s => counts[s]=(counts[s]||0)+1);
    let prize = 0, prizeLabel = '';
    if (counts['💎']>=3){ prize=counts['💎']>=5?8000:counts['💎']===4?4000:2000; prizeLabel=`${counts['💎']}× 💎`; }
    else if (counts['⭐']>=4){ prize=1000; prizeLabel=`${counts['⭐']}× ⭐`; }
    else if (counts['🍀']>=4){ prize=600; prizeLabel=`${counts['🍀']}× 🍀`; }
    if (prize>0) { addCash(userId,prize); addXP(userId,15); }
    const display = grid.reduce((acc,s,i)=>acc+(i%3===0?'\n':' ')+s,'').trim();
    return `🎫 *SCRATCH CARD*\n\n${display}\n\n${prize>0?`🎉 Winner! ${prizeLabel} → +${fmt(prize)}`:'❌ No prize this time.\n.buy scratch for another try'}`;
  }

  // ── MINI JOB (naura-entry, quick task) ──
  if (cmd === '.minijob') {
    const MINIJOB_COST = 200;
    if (!own && u.cash < MINIJOB_COST) return `❌ mini jobs cost ${fmt(MINIJOB_COST)} to attempt (risk vs reward).\nYou have: ${fmt(u.cash)}`;
    const coolKey = '__minijob__' + userId;
    const lastMj = db.prepare("SELECT content FROM notes WHERE user_id=? AND title=?").get(userId, coolKey);
    const minsSince = lastMj ? (Date.now()-new Date(lastMj.content).getTime())/60000 : 999;
    if (minsSince < 15 && !own) return `⏳ mini job cooldown: ${Math.ceil(15-minsSince)} min left.`;
    if (!own) addCash(userId, -MINIJOB_COST);
    db.prepare("INSERT OR REPLACE INTO notes (user_id,title,content,created_at) VALUES (?,?,?,?)").run(userId, coolKey, new Date().toISOString(), new Date().toISOString());
    const jobs = [
      {task:'Fixed someone\'s WiFi router. They still didn\'t tip.',pay:randomInt(400,900)},
      {task:'Edited a 3-minute video for 2 hours. Client said "make it pop".',pay:randomInt(300,700)},
      {task:'Printed 50 flyers at a business centre that barely works.',pay:randomInt(350,800)},
      {task:'Helped load a truck. "Just a few things." There were 40 boxes.',pay:randomInt(500,1100)},
      {task:'Sold recharge cards near a bus stop for 4 hours straight.',pay:randomInt(200,600)},
      {task:'Ran an errand in traffic. Got there. Traffic returned. Chaos.',pay:randomInt(300,750)},
      {task:'Designed a logo. Client wanted "something like Apple but different".',pay:randomInt(600,1400)},
      {task:'Typed a document someone could have typed themselves.',pay:randomInt(250,600)},
      {task:'Charged devices in a shop for 3 hours and did their errands too.',pay:randomInt(400,800)},
    ];
    const j = jobs[randomInt(0,jobs.length-1)];
    const won = Math.random() < 0.70;
    if (won) {
      addCash(userId, j.pay); addXP(userId,10);
      return `🛠️ *MINI JOB*\n\n${j.task}\n\nPaid: +${fmt(j.pay)}\nCost: -${fmt(MINIJOB_COST)}\nNet: +${fmt(j.pay-MINIJOB_COST)}`;
    } else {
      return `🛠️ *MINI JOB FAILED*\n\n${j.task}\n\nClient didn't pay. Classic.\nLost: ${fmt(MINIJOB_COST)}`;
    }
  }

  // ── BUY VIP (naura-gated) ──
  if (cmd === '.buyvip') {
    const VIP_COST = 10000;
    const VIP_DUR  = 7 * 24 * 3600000; // 7 days
    if (!own && u.cash < VIP_COST) return `⭐ VIP costs ${fmt(VIP_COST)} for 7 days.\nYou have: ${fmt(u.cash)}\nEarn more with .work .daily .crime`;
    const existing = u.vip_expires && u.vip_expires > Date.now();
    const expiry   = (existing ? u.vip_expires : Date.now()) + (own ? 0 : VIP_DUR);
    if (!own) addCash(userId, -VIP_COST);
    db.prepare('UPDATE users SET vip_expires=? WHERE id=?').run(own ? 9999999999999 : expiry, userId);
    addXP(userId, 100);
    return `⭐ *VIP ACTIVATED — ${name}!*\n\n${fmt(VIP_COST)} deducted.\nExpires: ${own ? 'never' : new Date(expiry).toDateString()}\n\n✨ VIP Perks:\n• ⭐ VIP badge on profile\n• 💰 +10% daily claim bonus\n• 🏦 Higher robbery protection\n• 🎁 Priority drop access\n• 🎰 Lower slot machine minimum (250)\n\n_Stack renewals before it expires to extend!_`;
  }

  // ── CASINO MENU ──
  if (cmd === '.casino') {
    const vipEx = u.vip_expires && u.vip_expires > Date.now();
    return `🎰 *CASINO*\n━━━━━━━━━━━━━━━\n\n🎰 Slots — .slots <bet> (min ${fmt(500)})\n🎡 Wheel — .wheel <bet> (min ${fmt(300)})\n🎲 Roulette — .roulette <bet> r/b/g (min ${fmt(100)})\n🪙 Flip — .flip h/t <bet>\n🎫 Scratch — .scratch (need scratch card)\n\n💳 Your balance: ${fmt(u.cash)}\n${vipEx ? '⭐ VIP active — enjoy the casino!' : `⭐ Go VIP for perks: .buyvip (${fmt(10000)})`}\n\n_Higher bets = higher risk. Play smart._`;
  }

  // ── JOB STAFF RAISE ──
  if (cmd === '.raise') {
    if (!own && !isSudo(userId)) return '❌ bosses only.';
    const targetName = args[0]; const raiseAmt = parseInt(args[1]);
    if (!targetName || !raiseAmt || raiseAmt <= 0) return '😒 .raise <name> <amount>\nExample: .raise Emeka 200';
    const staff = db.prepare("SELECT * FROM job_staff WHERE LOWER(name)=LOWER(?)").get(targetName);
    if (!staff) return `❌ "${targetName}" is not on staff.`;
    const newPay = (staff.pay||500) + raiseAmt;
    db.prepare('UPDATE job_staff SET pay=? WHERE user_id=?').run(newPay, staff.user_id);
    addCash(staff.user_id, raiseAmt); // immediate bonus
    return `💵 *SALARY RAISE*\n\n${staff.name} (${staff.role})\nOld pay: ${fmt(staff.pay||500)}\nNew pay: ${fmt(newPay)}\nBonus: +${fmt(raiseAmt)} paid now.\n\nGood boss behaviour.`;
  }

  // ── JOB STAFF PROMOTE ──
  if (cmd === '.promo') {
    if (!own && !isSudo(userId)) return '❌ bosses only.';
    const targetName = args[0]; const newRole = args.slice(1).join(' ') || '';
    if (!targetName || !newRole) return '😒 .promo <name> <new role>\nExample: .promo Emeka Manager\nRoles: Guard · Cashier · Dealer · Banker · Recruiter · Manager · Senior · Director';
    const staff = db.prepare("SELECT * FROM job_staff WHERE LOWER(name)=LOWER(?)").get(targetName);
    if (!staff) return `❌ "${targetName}" is not on staff.`;
    db.prepare('UPDATE job_staff SET role=? WHERE user_id=?').run(newRole, staff.user_id);
    addXP(staff.user_id, 200);
    const perk = ROLE_PERKS[newRole.toLowerCase()] || '';
    return `🎖️ *PROMOTION*\n\n${staff.name}: ${staff.role} → *${newRole}*\n${perk ? `🔓 Unlocked command: ${perk}` : ''}\n+200 XP awarded.`;
  }

  // ── PAYDAY CLAIM (for staff) ──
  if (cmd === '.payclaim') {
    const myStaff2 = db.prepare('SELECT * FROM job_staff WHERE user_id=?').get(userId);
    if (!myStaff2) return `❌ you're not on staff. .apply <pitch> to apply for a job.`;
    const lastPaid = myStaff2.last_paid ? new Date(myStaff2.last_paid) : null;
    const hrsSince = lastPaid ? (Date.now()-lastPaid.getTime())/3600000 : 999;
    if (hrsSince < 24 && !own) return `⏳ payday resets every 24h.\nNext pay in: ${Math.ceil(24-hrsSince)}h`;
    const pay = myStaff2.pay || 500;
    addCash(userId, pay);
    addXP(userId, 30);
    db.prepare('UPDATE job_staff SET last_paid=? WHERE user_id=?').run(now.toISOString(), userId);
    logJobEarning(userId, pay);
    return `💵 *PAYDAY!*\n\n${myStaff2.name} — ${myStaff2.role}\nPay: +${fmt(pay)}\nBalance: ${fmt(u.cash + pay)}\n\n_Come back tomorrow for your next pay._`;
  }

  // ══════════════════════════════════════════════════════
  //  NEW FEATURES — LORD MODE · CASHRAIN · HUNT · BOUNTY
  //  AUCTION · THRONE · BLACKOUT · STEAL PROTECTION
  // ══════════════════════════════════════════════════════

  // ── STEAL PROTECTION: owner can never be stolen from ──
  // (already handled by addCash — but add an explicit guard so thieves get a punishment)

  // ── LORDMODE ── Owner command: max out everything + dramatic display ──────
  if (cmd === '.lordmode') {
    if (!own) return `👑 ...that command belongs to the lord alone.`;
    ensureOwnerRich(userId, name);
    const wealth = fmt(999999999999999);
    lordModeActive.add(userId);
    return `👑 *LORD MODE — ${name}*\n\n` +
      `━━━━━━━━━━━━━━━\n` +
      `💎 Cash:  ${wealth}\n` +
      `🏦 Bank:  ${wealth}\n` +
      `📈 Earned: ${wealth}\n` +
      `⭐ Level: 9999 · Prestige: 99\n` +
      `🏆 Wins: 999,999 · Losses: 0\n` +
      `━━━━━━━━━━━━━━━\n\n` +
      `👑 The vault is full. The throne is uncontested.\n` +
      `🌌 ${name} stands above the board — untouchable, unfollowed, unmatched.\n\n` +
      `_No one robs the lord. No one beats the lord._`;
  }

  // ── THRONE ── Shows the owner's dominance card on the leaderboard ─────────
  if (cmd === '.throne') {
    if (!own && !isSudo(userId)) return `👑 .throne is reserved for royalty.`;
    const richRow = db.prepare('SELECT name,cash,bank,level FROM users ORDER BY (cash+bank) DESC LIMIT 1').get();
    const totalUsers = db.prepare('SELECT COUNT(*) as c FROM users').get().c;
    const totalWealth = db.prepare('SELECT SUM(cash+bank) as t FROM users').get().t || 0;
    const lordShare = Math.floor(999999999999999 / Math.max(1, totalWealth) * 100);
    return `👑 *THE THRONE — ${name}*\n\n` +
      `━━━━━━━━━━━━━━━\n` +
      `🏰 UNDISPUTED #1 RICHEST\n` +
      `💎 Net Worth: ${fmt(999999999999999)}\n` +
      `⭐ Level 9999 · Prestige 99\n` +
      `🌌 Realm: Divine\n` +
      `🏆 Win streak: immaculate\n\n` +
      `📊 Server Stats:\n` +
      `👥 Total users: ${totalUsers}\n` +
      `💰 All server wealth: ${fmt(totalWealth)}\n` +
      `📈 Lord's share: ${Math.min(100, lordShare)}%+\n` +
      `━━━━━━━━━━━━━━━\n\n` +
      `_The crown was never up for grabs._`;
  }

  // ── CASHRAIN ── Owner rains cash on EVERYONE in the DB ───────────────────
  if (cmd === '.cashrain') {
    if (!own && !isSudo(userId)) return `❌ only the lord/sudo can make it rain.`;
    const rainAmt = parseInt(args[0]);
    if (!rainAmt || rainAmt <= 0) return `🌧️ .cashrain <amount per person>\nExample: .cashrain 5000\nOwner rains cash on every user in the server.`;
    const allUsers = db.prepare('SELECT id, name FROM users WHERE id!=?').all(userId);
    if (!allUsers.length) return `😒 no other users to rain on.`;
    for (const usr of allUsers) { addCash(usr.id, rainAmt); }
    return `🌧️ *CASHRAIN!*\n\n` +
      `💰 ${fmt(rainAmt)} dropped on every user!\n` +
      `👥 Recipients: ${allUsers.length} people\n` +
      `💸 Total rained: ${fmt(rainAmt * allUsers.length)}\n\n` +
      `_Blessed by ${name}. Don't spend it all at once._`;
  }

  // ── BLACKOUT ── Owner zeroes out a user's cash as punishment ────────────
  if (cmd === '.blackout') {
    if (!own) return `❌ owner only.`;
    if (!args.length) return `😒 .blackout <name>\nZero out a user's wallet as punishment.`;
    let victim;
    let isGhost = false;
    if (mentionedJids.length > 0) {
      // A real @mention always wins, regardless of what text was typed —
      // WhatsApp mention display names can contain spaces/emoji that break
      // simple token parsing (e.g. "@Sean Chandler"), so resolve straight
      // from the JID WhatsApp already gave us instead of guessing from text.
      const realJid = mentionedJids[0];
      const realNum = realJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
      const uid = resolveId('wa_' + realNum);
      victim = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
        || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + realNum);
      if (!victim) {
        // "Ghost member" — WhatsApp resolved a real JID for them, but they've
        // never sent a message so the bot never created a wallet for them.
        // Create one now instead of failing — there's nothing to wipe, but
        // the command should still succeed rather than say "not found".
        const guessName = args.join(' ').replace(/^@+/, '').trim() || 'Unknown';
        victim = getUser('wa_' + realNum, guessName);
        isGhost = true;
      }
    } else if (args[0].startsWith('@')) {
      // Fallback: looks like a mention but WhatsApp gave us no resolved JID
      // (manually typed "@name", not a real tap-to-mention). Strip digits
      // from the whole argument string in case a phone number was typed.
      const digits = args.join('').replace(/\D/g, '');
      const uid = resolveId('wa_' + digits);
      victim = db.prepare('SELECT * FROM users WHERE id=?').get(uid)
        || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + digits);
    } else {
      // Plain name lookup — join all args in case the name has spaces ("John Doe")
      const target = args.join(' ');
      victim = db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(target);
    }
    if (!victim) return `❌ "${args.join(' ')}" not found.`;
    if (isOwner(victim.id)) return `😒 cannot blackout yourself.`;
    if (isGhost) {
      return `⚫ *BLACKOUT*\n\n${victim.name} has never interacted with the bot — no wallet to wipe.\n_Nothing to take from someone with nothing._`;
    }
    const oldCash = victim.cash;
    const oldBank = victim.bank;
    const oldTotal = oldCash + oldBank;
    db.prepare('UPDATE users SET cash=0, bank=0, total_lost=total_lost+? WHERE id=?').run(oldTotal, victim.id);
    return `⚫ *BLACKOUT*\n\n${victim.name}'s wallet AND bank have been wiped clean.\n💸 Cash wiped: ${fmt(oldCash)}\n🏦 Bank wiped: ${fmt(oldBank)}\n💀 Total wiped: ${fmt(oldTotal)}\n\n_The lord giveth. The lord taketh._`;
  }

  // ── HUNT ── Hunting minigame (need rifle) ─────────────────────────────────
  if (cmd === '.hunt') {
    if (!own && !hasItem(userId, 'rifle')) return `🔫 you need a rifle to hunt.\n.buy rifle (${fmt(1000)})`;
    const huntWins = [
      'Tracked something through the bush for an hour. Worth every step. {N} naura.',
      'Clean shot. Quick, quiet, profitable. {N} naura.',
      'Game was fast. You were faster. {N} naura.',
      'Found a big one. Rare. Sold it well. {N} naura.',
      'The forest paid out today. {N} naura in game meat.',
    ];
    const huntLoss = [
      'Waited three hours. Nothing showed up. Classic.',
      'Had a shot. Missed. Rifle is fine. Pride is not.',
      'The trail went cold. Maybe next time.',
      'Something big ran past. Too fast. Gone.',
    ];
    const huntCd = 25; // minutes
    const lastH = u.last_work ? (now - new Date(u.last_work)) / 60000 : 999;
    if (lastH < huntCd && !own) return `🔫 rifle cooling down — ${Math.ceil(huntCd - lastH)} min left.`;
    const vals = [300, 600, 900, 1500, 2500, 5000];
    const val = own ? 5000 : (Math.random() < 0.35 ? 0 : vals[randomInt(0, vals.length - 1)]);
    if (val > 0) {
      addCash(userId, val); addXP(userId, 25); setField(userId, 'last_work', now.toISOString());
      try { logJobEarning(userId, val); } catch(_){}
      return `🔫 ${huntWins[randomInt(0, huntWins.length-1)].replace('{N}', val.toLocaleString())}`;
    }
    setField(userId, 'last_work', now.toISOString());
    return `🔫 ${huntLoss[randomInt(0, huntLoss.length-1)]}`;
  }

  // ── BOUNTY SYSTEM ──────────────────────────────────────────────────────────
  // .bounty set <name> <amount>  — place a bounty on someone
  // .bounty list / .bounties     — see all active bounties
  // .bounty claim <name>         — claim a bounty after you robbed/fought them
  // .bounty cancel <name>        — cancel your own bounty (owner can cancel any)

  if (cmd === '.bounty' || cmd === '.bounties') {
    const sub = (args[0] || '').toLowerCase();

    if (cmd === '.bounties' || sub === 'list' || sub === '') {
      if (!activeBounties[chatId] || !activeBounties[chatId].length)
        return `🎯 *BOUNTIES*\n\nNo active bounties in this chat.\n.bounty set <name> <amount> to place one.`;
      const lines = activeBounties[chatId].map((b, i) =>
        `${i+1}. 🎯 *${b.target}* — ${fmt(b.amount)}\n   Posted by: ${b.byName}`
      ).join('\n\n');
      return `🎯 *ACTIVE BOUNTIES*\n━━━━━━━━━━━━━━━\n\n${lines}\n\n.bounty claim <name> after you defeat them.`;
    }

    if (sub === 'set') {
      const tName = args[1]; const bAmt = parseInt(args[2]);
      if (!tName || !bAmt || bAmt <= 0) return `😒 .bounty set <name> <amount>\nExample: .bounty set John 5000`;
      if (!own && bAmt > u.cash) return `not enough naura. you have ${fmt(u.cash)}`;
      const victim2 = db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(tName);
      if (!victim2) return `❌ "${tName}" not found in server.`;
      if (victim2.id === userId) return `😒 cannot bounty yourself.`;
      if (isOwner(victim2.id)) return `😒 ...the lord cannot be hunted.`;
      if (!own) addCash(userId, -bAmt);
      if (!activeBounties[chatId]) activeBounties[chatId] = [];
      // Replace existing bounty on same target, adding to it
      const existing = activeBounties[chatId].find(b => b.targetId === victim2.id);
      if (existing) {
        existing.amount += bAmt;
        return `🎯 *BOUNTY RAISED!*\n\n🎯 Target: ${victim2.name}\n💰 New total bounty: ${fmt(existing.amount)}\nAdded by: ${name}`;
      }
      activeBounties[chatId].push({ target: victim2.name, targetId: victim2.id, amount: bAmt, by: userId, byName: name, set_at: Date.now() });
      return `🎯 *BOUNTY PLACED!*\n\n🎯 Target: *${victim2.name}*\n💰 Reward: ${fmt(bAmt)}\nPosted by: ${name}\n\n_First to claim gets the pot. Use .bounty claim ${victim2.name} after defeating them._`;
    }

    if (sub === 'claim') {
      const tName = args[1];
      if (!tName) return `😒 .bounty claim <name>`;
      if (!activeBounties[chatId]) return `🎯 no bounties active.`;
      const bIdx = activeBounties[chatId].findIndex(b => b.target.toLowerCase() === tName.toLowerCase());
      if (bIdx === -1) return `❌ no bounty found on "${tName}".`;
      const b = activeBounties[chatId][bIdx];
      if (b.targetId === userId) return `😒 can't claim bounty on yourself.`;
      if (b.by === userId && !own) return `😒 can't claim your own bounty.`;
      // Claiming removes 30% of target's cash as "proof of victory"
      const victim3 = db.prepare('SELECT * FROM users WHERE id=?').get(b.targetId);
      const spoils = victim3 ? Math.floor((victim3.cash || 0) * 0.30) : 0;
      if (victim3 && spoils > 0) addCash(b.targetId, -spoils);
      addCash(userId, b.amount + spoils); addXP(userId, 80);
      activeBounties[chatId].splice(bIdx, 1);
      return `🎯 *BOUNTY CLAIMED!*\n\n🏆 Collected by: *${name}*\n🎯 Target: ${b.target}\n\n💰 Bounty: +${fmt(b.amount)}\n⚔️ Spoils (30% of victim cash): +${fmt(spoils)}\n\n*Total earned: ${fmt(b.amount + spoils)}*\n\n_Bounty board updated._`;
    }

    if (sub === 'cancel') {
      const tName = args[1];
      if (!tName) return `😒 .bounty cancel <name>`;
      if (!activeBounties[chatId]) return `🎯 no bounties active.`;
      const bIdx = activeBounties[chatId].findIndex(b => b.target.toLowerCase() === tName.toLowerCase());
      if (bIdx === -1) return `❌ no bounty found on "${tName}".`;
      const b = activeBounties[chatId][bIdx];
      if (!own && b.by !== userId) return `❌ you didn't place that bounty.`;
      if (!own) addCash(userId, Math.floor(b.amount * 0.8)); // 80% refund
      activeBounties[chatId].splice(bIdx, 1);
      return `🎯 bounty on ${b.target} cancelled. ${!own ? `${fmt(Math.floor(b.amount * 0.8))} refunded (80%).` : ''}`;
    }

    return `🎯 *BOUNTY COMMANDS*\n.bounty set <name> <amt> — place a bounty\n.bounty list — see active bounties\n.bounty claim <name> — collect after defeating them\n.bounty cancel <name> — cancel your bounty`;
  }

  // ── AUCTION SYSTEM ────────────────────────────────────────────────────────
  // .auction <item> <start_price>  — start an auction
  // .bid <amount>                  — place a bid
  // .auctioninfo                   — view current auction
  // .endauction                    — force-close (owner/sudo)

  if (cmd === '.auction') {
    const item = args[0]; const startPrice = parseInt(args[1]);
    if (!item || !startPrice || startPrice <= 0) return `🏷️ .auction <item> <starting price>\nExample: .auction fishing 1000\nStarts a live auction in this chat.`;
    if (pendingAuctions[chatId]) return `❌ an auction is already running here. .auctioninfo to see it.`;
    if (!own && !hasItem(userId, item)) return `❌ you don't have "${item}" in your inventory.`;
    if (!own) removeItem(userId, item, 1);
    const endTime = Date.now() + 5 * 60 * 1000; // 5 minutes
    pendingAuctions[chatId] = { item, currentBid: startPrice, currentBidder: null, currentBidderName: 'Nobody', endTime, by: userId, byName: name, minBid: startPrice };
    // Auto-close after 5 mins
    setTimeout(() => {
      const a = pendingAuctions[chatId];
      if (!a || a.item !== item) return;
      delete pendingAuctions[chatId];
    }, 5 * 60 * 1000);
    return `🏷️ *AUCTION STARTED!*\n\n📦 Item: *${item}*\n💰 Starting bid: ${fmt(startPrice)}\n🏪 Seller: ${name}\n⏰ Ends in: 5 minutes\n\nType .bid <amount> to place a bid!\n.auctioninfo — view status`;
  }

  if (cmd === '.bid') {
    const a = pendingAuctions[chatId];
    if (!a) return `🏷️ no auction running. .auction <item> <price> to start one.`;
    if (Date.now() > a.endTime) { delete pendingAuctions[chatId]; return `⏰ that auction already ended.`; }
    const bidAmt = parseInt(args[0]);
    if (!bidAmt || bidAmt <= 0) return `😒 .bid <amount>`;
    if (!own && bidAmt > u.cash) return `not enough naura. you have ${fmt(u.cash)}`;
    if (bidAmt <= a.currentBid) return `❌ must bid higher than current bid of ${fmt(a.currentBid)}. Try ${fmt(a.currentBid + 100)}+`;
    if (a.currentBidder === userId) return `😒 you're already the highest bidder.`;
    if (a.currentBidder && !isOwner(a.currentBidder)) {
      // Refund previous bidder
      addCash(a.currentBidder, a.currentBid);
    }
    if (!own) addCash(userId, -bidAmt);
    a.currentBid = bidAmt;
    a.currentBidder = userId;
    a.currentBidderName = name;
    const minsLeft = Math.max(1, Math.ceil((a.endTime - Date.now()) / 60000));
    return `🏷️ *NEW BID!*\n\n📦 Item: ${a.item}\n💰 Bid: ${fmt(bidAmt)} by *${name}*\n⏰ ${minsLeft} min left\n\nOutbid with .bid <higher amount>`;
  }

  if (cmd === '.auctioninfo') {
    const a = pendingAuctions[chatId];
    if (!a) return `🏷️ no auction running in this chat.`;
    if (Date.now() > a.endTime) { delete pendingAuctions[chatId]; return `⏰ auction already ended.`; }
    const minsLeft = Math.max(0, Math.ceil((a.endTime - Date.now()) / 60000));
    return `🏷️ *AUCTION STATUS*\n\n📦 Item: *${a.item}*\n💰 Current bid: ${fmt(a.currentBid)}\n🏆 Highest bidder: ${a.currentBidderName}\n🏪 Seller: ${a.byName}\n⏰ Time left: ~${minsLeft} min\n\n.bid <amount> to bid`;
  }

  if (cmd === '.endauction') {
    if (!own && !isSudo(userId)) return `❌ only the owner/sudo can force-end an auction.`;
    const a = pendingAuctions[chatId];
    if (!a) return `🏷️ no auction to end.`;
    delete pendingAuctions[chatId];
    if (!a.currentBidder) {
      // No bids — return item to seller
      if (!isOwner(a.by)) addItem(a.by, a.item, 1);
      return `🏷️ *AUCTION ENDED — NO BIDS*\n\n📦 ${a.item} returned to ${a.byName}.`;
    }
    addItem(a.currentBidder, a.item, 1);
    if (!isOwner(a.by)) addCash(a.by, a.currentBid);
    addXP(a.currentBidder, 40);
    return `🏷️ *AUCTION CLOSED!*\n\n📦 Item: ${a.item}\n🏆 Winner: *${a.currentBidderName}*\n💰 Final bid: ${fmt(a.currentBid)}\n💵 Seller (${a.byName}) received: ${fmt(a.currentBid)}\n\n🎉 Congrats ${a.currentBidderName}!`;
  }

  // ── ADD RIFLE TO SHOP (patched in-place) ──────────────────────────────────
  // (rifle is handled below — add it to shop display if not present)

  // ── DAILY WEALTH REPORT — Owner special ───────────────────────────────────
  if (cmd === '.report' || cmd === '.wealthreport') {
    if (cmd === '.wealthreport') {
      if (!own && !isSudo(userId)) return `❌ owner/sudo only.`;
      const topUsers = db.prepare('SELECT name, cash, bank, level FROM users ORDER BY (cash+bank) DESC LIMIT 5').all();
      const totalW = db.prepare('SELECT SUM(cash+bank) as t FROM users').get().t || 0;
      const activeTx = db.prepare('SELECT COUNT(*) as c FROM users WHERE last_work IS NOT NULL AND last_work > datetime("now", "-1 day")').get().c;
      const lines = topUsers.map((r, i) => {
        const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':`${i+1}.`;
        return `${medal} ${r.name} (Lv${r.level||1}) — ${fmt(r.cash + r.bank)}`;
      });
      return `📊 *WEALTH REPORT*\n━━━━━━━━━━━━━━━\n\n🏆 Top 5:\n${lines.join('\n')}\n\n💰 Server total wealth: ${fmt(totalW)}\n🏃 Active today: ${activeTx} users\n\n👑 Lord's balance: ${fmt(999999999999999)} (immovable)`;
    }
  }

  // ── BOSS FLEX ── Shows your wealth vs the lord ────────────────────────────
  if (cmd === '.bosscheck') {
    if (!own) {
      const net = u.cash + u.bank;
      const lordsWealth = 999999999999999;
      const pct = Math.max(0.0001, net / lordsWealth * 100).toFixed(8);
      return `👑 *BOSS CHECK*\n\nYour net worth: ${fmt(net)}\nThe Lord's net worth: ${fmt(lordsWealth)}\nYou have: ${pct}% of the Lord's wealth\n\n_Keep grinding. The throne isn't available._`;
    }
    return `👑 you ARE the boss. check .throne instead.`;
  }

  // ── PROTECT CMD: if someone tries to steal from owner, punish them ───────
  // (this is handled in .steal above — but add extra message here if triggered)

  // ── JOBS UPDATED MENU ──
  if (['.jobs','.job','.jobmenu'].includes(cmd)) {
    const myStaff3 = db.prepare('SELECT * FROM job_staff WHERE user_id=?').get(userId);
    const myApp    = db.prepare("SELECT status FROM job_applications WHERE user_id=? ORDER BY id DESC LIMIT 1").get(userId);
    const staffCount = db.prepare('SELECT COUNT(*) as c FROM job_staff').get().c;
    const pendingApps = db.prepare("SELECT COUNT(*) as c FROM job_applications WHERE status='pending'").get().c;
    const isB = own || isSudo(userId);

    let statusLine = '';
    if (myStaff3) {
      const todayEarned = db.prepare('SELECT earned FROM job_quota_log WHERE user_id=? AND date=?').get(userId, new Date().toDateString())?.earned || 0;
      const lastPaidLine = myStaff3.last_paid ? `Last paid: ${new Date(myStaff3.last_paid).toDateString()}` : 'Not yet paid';
      statusLine = `\n👔 *YOUR JOB*\nRole: ${myStaff3.role} · Pay: ${fmt(myStaff3.pay||500)}/day\nToday earned: ${fmt(todayEarned)}\n${lastPaidLine}\n.payclaim — collect your daily pay\n`;
    } else if (myApp) {
      statusLine = `\n📋 Application status: *${myApp.status}*\n`;
    } else {
      statusLine = `\n📋 No job yet. Apply below!\n`;
    }

    const bossSection = isB ? `\n👑 *BOSS COMMANDS*\n.applications — review pending (${pendingApps})\n.acceptapp <id> [role] [pay] — hire someone\n.rejectapp <id> — decline\n.roster — view all staff (${staffCount} members)\n.fire <name> — let someone go\n.raise <name> <amount> — give a raise\n.promo <name> <role> — promote staff\n.taskboard — assign/view tasks\n.payday — pay all staff\n` : '';

    return `💼 *JOBS SYSTEM*\n━━━━━━━━━━━━━━━${statusLine}\n📌 *COMMANDS*\n.apply <your pitch> — submit application\n.payclaim — collect daily salary\n.work — earn extra cash every 30 min\n.quota — view your daily earnings progress\n.taskboard — view your assigned tasks\n.roster — see team members\n\n💡 Jobs pay per day + 20% of your .work goes to your boss.\nHigher roles unlock special commands.\n${bossSection}\nStaff total: ${staffCount} · Pending apps: ${pendingApps}`;
  }

  return null;
}

// ============ GAMES ============
function checkStreak(userId) {
  const today=new Date().toDateString(), yesterday=new Date(Date.now()-86400000).toDateString();
  const s=userStreaks[userId]||{date:null,count:0};
  if(s.date===today) return s.count;
  s.count=(s.date===yesterday)?s.count+1:1;
  s.date=today; userStreaks[userId]=s;
  return s.count;
}

function handleGames(cmd, chatId, userId, name, args, mentionedJids=[]) {
  if (cmd==='.hangman') {
    const words=['jollof','fashion','nigeria','bitcoin','diamond','galaxy','sunrise','crystal','laptop','hustle','wahala','pepper','island','market','cinema','pillow','garden','sunset','bridge','twitter','loyalty','betrayal','spotify','netflix'];
    const word=words[randomInt(0,words.length-1)];
    activeGames[chatId]={type:'hangman',word,guessed:[],wrong:0};
    return `💗 HANGMAN\nword: ${word.split('').map(()=>'_').join(' ')} (${word.length} letters)\nwrong left: 6 · type a letter`;
  }

  if (cmd==='.trivia') {
    const qs=[
      {q:'Capital of Nigeria?',a:'abuja'},{q:'Who sang Last Last?',a:'burna boy'},
      {q:'How many states in Nigeria?',a:'36'},
      {q:'15 x 15?',a:'225'},{q:'Largest country in Africa by area?',a:'algeria'},
      {q:'12 x 12?',a:'144'},
      {q:'Capital of Ghana?',a:'accra'},{q:'Currency of Nigeria?',a:'naira'},
      {q:'7 x 8?',a:'56'},{q:'Capital of Kenya?',a:'nairobi'},
      {q:'Capital of South Africa?',a:'pretoria'},{q:'Tallest mountain in Africa?',a:'mount kilimanjaro'},
      {q:'Who wrote Things Fall Apart?',a:'chinua achebe'},{q:'What year did Nigeria gain independence?',a:'1960'},
    ];
    const q=qs[randomInt(0,qs.length-1)];
    activeGames[chatId]={type:'trivia',answer:q.a};
    return `💗 TRIVIA\n\n${q.q}\n\nfirst correct answer wins ${fmt(500)}!`;
  }

  if (cmd==='.quiz') {
    const qs=[
      {q:'What element has symbol Au?',a:'gold'},{q:'Who invented telephone?',a:'alexander graham bell'},
      {q:'Largest planet?',a:'jupiter'},{q:'WW2 ended in?',a:'1945'},
      {q:'Who painted Mona Lisa?',a:'da vinci'},{q:'Japan currency?',a:'yen'},
      {q:'Speed of light (approx km/s)?',a:'300000'},{q:'How many sides on a hexagon?',a:'6'},
    ];
    const q=qs[randomInt(0,qs.length-1)];
    activeGames[chatId]={type:'quiz',answer:q.a,reward:1000};
    return `🧠 QUIZ\n\n${q.q}\n\nfirst correct answer wins ${fmt(1000)}!`;
  }

  if (cmd==='.wordchain') {
    activeGames[chatId]={type:'wordchain',lastWord:null,used:[]};
    return '💗 WORD CHAIN\ntype any word. next word starts with last letter.\n+100 naura per valid word.';
  }
  if (cmd==='.truth') {
    const q=['what is your most embarrassing moment?','who do you have a crush on here?','what is your biggest fear?','have you ever lied to your parents?','what is the worst thing you have done?','who is your least favourite person here?','have you ever stolen something?','what is your biggest secret?','last person you texted and what did you say?','what do you actually think of this group?','what is something you have never told anyone here?'];
    return `💗 TRUTH\n${name}, answer this:\n${q[randomInt(0,q.length-1)]}`;
  }
  if (cmd==='.dare') {
    const d=['send your most recent selfie','say something nice about everyone here','confess something you have never told anyone here','share your last google search','describe yourself in 3 words honestly','say something embarrassing about yourself','send a voice note saying "I love this group"','post your phone battery % and last app used'];
    return `💗 DARE\n${name}, you must:\n${d[randomInt(0,d.length-1)]}`;
  }
  if (cmd==='.tod') return Math.random()<0.5?handleGames('.truth',chatId,userId,name,args,mentionedJids):handleGames('.dare',chatId,userId,name,args,mentionedJids);

  if (cmd==='.8ball') {
    const q=args.join(' ');if(!q) return '😒 .8ball <question>';
    const a=['yes sha','no abeg','maybe later','definitely not','100% yes','ask me again','i doubt it','obviously','no way','signs point to yes',"don\'t count on it",'for sure','not in this life','oya try'];
    return `🎱 "${q}"\n→ ${a[randomInt(0,a.length-1)]}`;
  }
  if (cmd==='.ship') {
    const p1=args[0]||name,p2=args[1]||'someone';
    const pct=randomInt(10,100);
    const bar='❤️'.repeat(Math.floor(pct/10))+'🖤'.repeat(10-Math.floor(pct/10));
    const c=pct>=85?'perfect match':pct>=65?'good vibes':pct>=45?'could work':pct>=25?'needs effort':'not compatible sha';
    return `💘 SHIP\n${p1} + ${p2}\n${bar}\n${pct}% — ${c}`;
  }
  if (cmd==='.rate') {
    const thing=args.join(' ')||name,r=randomInt(1,10);
    const c=r>=9?'GOAT 🐐':r>=7?'top tier':r>=5?'average':r>=3?'needs work':'yikes sha';
    return `⭐ ${thing}\n${r}/10 — ${c}`;
  }
  if (cmd==='.joke') {
    const j=["why did the scarecrow win an award? because he was outstanding in his field.","why don\'t scientists trust atoms? because they make up everything.","what did the ocean say to the beach? nothing, it just waved.","i asked my dog what 2 minus 2 is. he said nothing.","i used to hate facial hair... but then it grew on me.","my mum said nothing when i said i'd be a comedian. biggest laugh i got."];
    return `😄 ${j[randomInt(0,j.length-1)]}`;
  }
  if (cmd==='.quote') {
    const q=["hustle until your haters ask if you\'re hiring.","be so good they can\'t ignore you.","move in silence. let success make noise.","your vibe attracts your tribe.","protect your energy at all costs.","stay low, build up.","the grind don\'t stop.","you didn\'t come this far to only come this far.","discipline beats motivation every time.","nobody is coming to save you. build yourself."];
    return `💬 "${q[randomInt(0,q.length-1)]}"`;
  }
if (cmd==='.riddle') {
    const riddles=[
      {q:"I speak without a mouth and hear without ears. I have no body, but I come alive with wind. What am I?",a:"echo"},
      {q:"The more you take, the more you leave behind. What am I?",a:"footsteps"},
      {q:"I have cities, but no houses live there. Mountains, but no trees grow. Water, but no fish swim. What am I?",a:"map"},
      {q:"What has hands but can't clap?",a:"clock"},
      {q:"I'm light as a feather, yet the strongest person can't hold me for 5 minutes. What am I?",a:"breath"},
      {q:"What can travel around the world while staying in one corner?",a:"stamp"},
      {q:"I have teeth but cannot eat. What am I?",a:"comb"},
      {q:"What has an eye but cannot see?",a:"needle"},
      {q:"The more you have of it, the less you see. What is it?",a:"darkness"},
      {q:"I'm always in front of you but can't be seen. What am I?",a:"future"},
    ];
    const r=riddles[randomInt(0,riddles.length-1)];
    activeGames[chatId]={type:'riddle',answer:r.a,reward:800};
    return `🧩 *RIDDLE*\n\n${r.q}\n\nfirst correct answer wins ${fmt(800)}!`;
  }
  if (cmd==='.marry') {
    const target=args[0]; if(!target) return '😒 .marry <name>';
    if(!isOwner(userId)&&!hasItem(userId,'ring')) return `❄️ need a ring first.\n.buy ring (${fmt(8000)})`;
    // Resolve @mention to real user name (same pattern as .give and .duel)
    let targetName = args.join(' ');
    if (target.startsWith('@') && mentionedJids.length > 0) {
      const realJid = mentionedJids[0];
      const realNum = realJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
      const uid = resolveId('wa_' + realNum) || ('wa_' + realNum);
      const mr = db.prepare('SELECT name FROM users WHERE id=?').get(uid)
               || db.prepare('SELECT name FROM users WHERE id=?').get('wa_' + realNum);
      if (mr) targetName = mr.name;
    } else if (target.startsWith('@')) {
      const digits = target.replace(/\D/g,'');
      const uid = resolveId('wa_' + digits) || ('wa_' + digits);
      const mr = db.prepare('SELECT name FROM users WHERE id=?').get(uid)
               || db.prepare('SELECT name FROM users WHERE id=?').get('wa_' + digits);
      if (mr) targetName = mr.name;
    }
    setField(userId,'spouse',targetName);
    if(hasItem(userId,'ring')) removeItem(userId,'ring');
    return `💍 ${name} and ${targetName} are now married!`;
  }
  if (cmd==='.divorce'){setField(userId,'spouse','');return `💔 divorced. fast sha.`;}
  if (cmd==='.endgame'){if(activeGames[chatId]){delete activeGames[chatId];return '💗 game ended.';}return '...no active game.';}

  if (['.games','.gamemenu'].includes(cmd)) {
    return `🎮 GAMES MENU\n\n◈ social\n.truth · .dare · .tod\n.8ball <q> · .ship <p1> <p2>\n.rate <thing> · .joke · .quote · .riddle\n.marry <name> · .divorce\n\n◈ challenges\n.hangman · .trivia · .quiz\n.scramble · .wordchain · .riddle\n.cull · .wolfout\n\n◈ pvp\n.duel <name> <amt> · .accept · .decline\n.fight <name>\n\n.endgame — stop active game`;
  }

  // ── SCRAMBLE ──
  if (cmd === '.scramble') {
    const words = ['laptop','shadow','market','garden','bridge','island','pillow','cinema','sunset','hustle',
      'galaxy','diamond','crystal','twitter','loyalty','fashion','pepper','nigeria','bitcoin','spotify',
      'fortune','mystery','warrior','balloon','captain','dragon','trophy','silence','freedom','journey'];
    const word = words[randomInt(0, words.length-1)];
    activeGames[chatId] = {type:'scramble', word, scrambled: scramble(word)};
    return `🔤 SCRAMBLE\n\nUnscramble this word:\n🔀 ${activeGames[chatId].scrambled.toUpperCase()}\n\nFirst correct answer wins ${fmt(600)}!\n.endgame to quit`;
  }

  // ── CULL (Rambunctious Rodent) ──
  if (cmd === '.cull') {
    const rodents = ['🐀 A RAT','🐹 A HAMSTER','🐭 A MOUSE','🦫 A BEAVER','🐿️ A SQUIRREL'];
    const rodent = rodents[randomInt(0, rodents.length-1)];
    const reward = randomInt(200, 1000);
    activeGames[chatId] = {type:'cull', reward, rodent};
    setTimeout(() => { if (activeGames[chatId]?.type==='cull') delete activeGames[chatId]; }, 30000);
    return `🐀 RAMBUNCTIOUS RODENT!\n\n${rodent} has appeared!\n\nType .whack to catch it!\nReward: +${fmt(reward)}\n(30 seconds before it escapes!)`;
  }
  if (cmd === '.whack') {
    const g = activeGames[chatId];
    if (!g || g.type !== 'cull') return '...nothing to whack right now.';
    addCash(userId, g.reward); addXP(userId, 25);
    delete activeGames[chatId];
    return `🎯 ${name} whacked ${g.rodent}! +${fmt(g.reward)}`;
  }

  // ── WOLFOUT ──
  if (cmd === '.wolfout') {
    if (wolfGames[chatId]) return '❌ a wolf game is already running. .endwolf to cancel.';
    wolfGames[chatId] = {players: [{id: userId, name}], phase: 'lobby', votes:{}, kills:{}, checks:{}};
    return `🐺 WOLFOUT STARTED!\n\n${name} joined the lobby.\n\n.joinwolf — join\n.startwolf — begin (min 3 players)\n.endwolf — cancel\n\nPlayers: ${name}`;
  }
  if (cmd === '.joinwolf') {
    const wg = wolfGames[chatId];
    if (!wg) return '❌ no wolf game running. .wolfout to start one.';
    if (wg.phase !== 'lobby') return '❌ game already in progress.';
    if (wg.players.find(p => p.id === userId)) return '😒 you already joined.';
    wg.players.push({id: userId, name});
    return `🐺 ${name} joined! Players: ${wg.players.map(p=>p.name).join(', ')}\n(${wg.players.length} players · .startwolf to begin)`;
  }
  if (cmd === '.startwolf') {
    const wg = wolfGames[chatId];
    if (!wg) return '❌ no wolf game. .wolfout to start.';
    if (wg.phase !== 'lobby') return '❌ already started.';
    if (wg.players.length < 3) return `❌ need at least 3 players. Have ${wg.players.length}.`;
    // Assign roles
    const shuffled = [...wg.players].sort(() => Math.random()-0.5);
    const wolfCount = Math.max(1, Math.floor(shuffled.length/4));
    wg.roles = {};
    wg.alive = {};
    shuffled.forEach((p, i) => {
      wg.roles[p.id] = i < wolfCount ? 'wolf' : i === wolfCount ? 'seer' : 'villager';
      wg.alive[p.id] = true;
    });
    wg.phase = 'night';
    const rolesMsg = wg.players.map(p => `${p.name}: ${wg.roles[p.id]==='wolf'?'🐺 Wolf':wg.roles[p.id]==='seer'?'👁️ Seer':'🧑‍🌾 Villager'}`).join('\n');
    return `🐺 WOLFOUT BEGINS!\n\n🎭 Roles assigned:\n${rolesMsg}\n\n🌙 NIGHT PHASE\n🐺 Wolf: .kill @name\n👁️ Seer: .check @name\nAll others wait...\n\nPhase ends in 60 seconds`;
  }
  if (cmd === '.kill') {
    const wg = wolfGames[chatId];
    if (!wg||wg.phase!=='night') return null;
    if (wg.roles[userId]!=='wolf') return '❌ only wolves can kill.';
    const tname = args[0]?.replace('@','').toLowerCase();
    const target = wg.players.find(p=>p.name.toLowerCase()===tname&&p.id!==userId&&wg.alive[p.id]);
    if (!target) return `❌ player "${tname}" not found or not alive.`;
    wg.kills[chatId] = target;
    return `🐺 ${name} chose their target... (votes locked until morning)`;
  }
  if (cmd === '.check') {
    const wg = wolfGames[chatId];
    if (!wg||wg.phase!=='night') return null;
    if (wg.roles[userId]!=='seer') return '❌ only the seer can check.';
    const tname = args[0]?.replace('@','').toLowerCase();
    const target = wg.players.find(p=>p.name.toLowerCase()===tname&&wg.alive[p.id]);
    if (!target) return `❌ player not found.`;
    const role = wg.roles[target.id];
    return `👁️ [Seer] ${target.name} is a ${role==='wolf'?'🐺 WOLF!':'🧑 Villager/Seer (not a wolf).'}`;
  }
  if (cmd === '.vote') {
    const wg = wolfGames[chatId];
    if (!wg||wg.phase!=='day') return '❌ voting only happens during the day.';
    if (!wg.alive[userId]) return '❌ you are eliminated.';
    const tname = args[0]?.replace('@','').toLowerCase();
    const target = wg.players.find(p=>p.name.toLowerCase()===tname&&wg.alive[p.id]&&p.id!==userId);
    if (!target) return `❌ player "${tname}" not found.`;
    wg.votes[userId] = target.id;
    const voteCount = Object.values(wg.votes).filter(v=>v===target.id).length;
    const aliveCount = Object.values(wg.alive).filter(Boolean).length;
    if (voteCount > aliveCount/2) {
      wg.alive[target.id] = false;
      const wolves = wg.players.filter(p=>wg.roles[p.id]==='wolf'&&wg.alive[p.id]).length;
      const villagers = wg.players.filter(p=>wg.roles[p.id]!=='wolf'&&wg.alive[p.id]).length;
      if (wolves === 0) { delete wolfGames[chatId]; return `☀️ ${target.name} was eliminated!\n${target.name} was a ${wg.roles[target.id]==='wolf'?'🐺 WOLF':'🧑 Villager'}!\n\n🏆 VILLAGERS WIN! All wolves eliminated!`; }
      if (wolves >= villagers) { delete wolfGames[chatId]; return `☀️ ${target.name} was eliminated!\n\n🐺 WOLVES WIN! They outnumber the village!`; }
      wg.phase = 'night'; wg.votes = {};
      return `☀️ VOTE RESULT: ${target.name} eliminated! (${wg.roles[target.id]})\n\nGame continues...\n🌙 NIGHT PHASE begins\n🐺 Wolf: .kill @name · 👁️ Seer: .check @name`;
    }
    return `🗳️ ${name} voted for ${target.name}. (${voteCount} votes · need ${Math.floor(aliveCount/2)+1})`;
  }
  if (cmd === '.endwolf') {
    if (wolfGames[chatId]) { delete wolfGames[chatId]; return '🐺 Wolf game ended.'; }
    return '...no wolf game running.';
  }

  // ── POLL ──
  if (cmd==='.poll') {
    const full=args.join(' ');
    const parts=full.split('|').map(s=>s.trim()).filter(Boolean);
    if(parts.length<3) return '😒 .poll <question> | <option1> | <option2> | ...\ne.g. .poll Best food? | Rice | Pasta | Bread';
    const question=parts[0];
    const options=parts.slice(1);
    if(options.length>8) return '😒 max 8 options.';
    db.prepare("DELETE FROM polls WHERE chat_id=? AND closed=0 AND creator_id=?").run(chatId,userId);
    const pollId=db.prepare('INSERT INTO polls (chat_id,creator_id,question,options,created_at) VALUES (?,?,?,?,?)').run(chatId,userId,question,JSON.stringify(options),new Date().toISOString()).lastInsertRowid;
    const optLines=options.map((o,i)=>`${i+1}. ${o}`).join('\n');
    return `📊 *POLL #${pollId}*\n\n${question}\n\n${optLines}\n\n.pollvote ${pollId} <number> — to vote\n.pollresults ${pollId} — see results\n.closepoll ${pollId} — end poll`;
  }
  if (cmd==='.pollvote') {
    const id=parseInt(args[0]), choice=parseInt(args[1]);
    if(!id||!choice) return '😒 .pollvote <poll_id> <option number>';
    const poll=db.prepare('SELECT * FROM polls WHERE id=? AND chat_id=?').get(id,chatId);
    if(!poll) return `❄️ poll #${id} not found in this chat.`;
    if(poll.closed) return `❄️ poll #${id} is closed.`;
    const options=JSON.parse(poll.options);
    if(choice<1||choice>options.length) return `😒 pick a number 1–${options.length}.`;
    const votes=JSON.parse(poll.votes||'{}');
    const prev=votes[userId];
    votes[userId]=choice-1;
    db.prepare('UPDATE polls SET votes=? WHERE id=?').run(JSON.stringify(votes),id);
    return `✅ voted for "${options[choice-1]}"${prev!==undefined?` (changed from "${options[prev]}")`:''}.`;
  }
  if (cmd==='.pollresults') {
    const id=parseInt(args[0]);
    if(!id) return '😒 .pollresults <poll_id>';
    const poll=db.prepare('SELECT * FROM polls WHERE id=? AND chat_id=?').get(id,chatId);
    if(!poll) return `❄️ poll #${id} not found.`;
    const options=JSON.parse(poll.options);
    const votes=JSON.parse(poll.votes||'{}');
    const counts=options.map((_,i)=>Object.values(votes).filter(v=>v===i).length);
    const total=Object.keys(votes).length;
    const lines=options.map((o,i)=>{
      const pct=total>0?Math.round(counts[i]/total*100):0;
      const bar='█'.repeat(Math.round(pct/10))+'░'.repeat(10-Math.round(pct/10));
      return `${i+1}. ${o}\n   [${bar}] ${counts[i]} votes (${pct}%)`;
    }).join('\n\n');
    return `📊 *POLL RESULTS #${id}*\n${poll.closed?'(closed)':'(live)'}\n\n${poll.question}\n\n${lines}\n\nTotal voters: ${total}`;
  }
  if (cmd==='.closepoll') {
    const id=parseInt(args[0]);
    if(!id) return '😒 .closepoll <poll_id>';
    const poll=db.prepare('SELECT * FROM polls WHERE id=? AND chat_id=?').get(id,chatId);
    if(!poll) return `❄️ poll #${id} not found.`;
    if(poll.creator_id!==userId&&!isSudo(userId)) return '❌ only the poll creator or admins can close it.';
    db.prepare('UPDATE polls SET closed=1 WHERE id=?').run(id);
    return `📊 Poll #${id} closed. .pollresults ${id} to see final tally.`;
  }


  // ── NUMBER GUESS ──
  if (cmd==='.guess') {
    const range=parseInt(args[0])||100;
    const secret=randomInt(1,range);
    activeGames[chatId]={type:'numguess',secret,range,attempts:0,maxAttempts:Math.ceil(Math.log2(range))+2};
    return `🔢 *NUMBER GUESS*\n\nI'm thinking of a number between 1 and ${range}.\nYou have ${Math.ceil(Math.log2(range))+2} guesses.\n\nType a number to guess!`;
  }

  const game=activeGames[chatId];
  if(!game) return null;

  if(game.type==='scramble'&&!cmd.startsWith('.')&&/^[a-zA-Z]+$/.test(cmd)){
    if(cmd.toLowerCase()===game.word){
      addCash(userId,600); addXP(userId,40); delete activeGames[chatId];
      return `🎯 ${name} got it! The word was "${game.word}"! +${fmt(600)}`;
    }
    return null; // wrong answer — don\'t reveal, just ignore
  }

  if(['trivia','quiz','riddle'].includes(game.type)&&!cmd.startsWith('.')) {
    const ans=(cmd+' '+args.join(' ')).trim().toLowerCase();
    if(ans===game.answer){
      const reward=game.reward||500; addCash(userId,reward); delete activeGames[chatId]; addXP(userId,30);
      return `💗 correct ${name}! +${fmt(reward)}`;
    }
    return null;
  }

  if(game.type==='hangman'&&!cmd.startsWith('.')&&cmd.length===1&&/[a-zA-Z]/.test(cmd)){
    const letter=cmd.toLowerCase();
    if(game.guessed.includes(letter)) return `...already guessed "${letter}"`;
    game.guessed.push(letter);
    if(!game.word.includes(letter)) game.wrong++;
    const display=game.word.split('').map(l=>game.guessed.includes(l)?l:'_').join(' ');
    if(!display.includes('_')){addCash(userId,500);delete activeGames[chatId];addXP(userId,40);return `💗 ${name} got it! "${game.word}" +${fmt(500)}`;}
    if(game.wrong>=6){delete activeGames[chatId];return `❄️ game over. word was "${game.word}"`;}
    return `💗 ${display}\nwrong: ${game.wrong}/6 · guessed: ${game.guessed.join(' ')}`;
  }

  if(game.type==='wordchain'&&!cmd.startsWith('.')&&/^[a-zA-Z]+$/.test(cmd)){
    const word=cmd.toLowerCase();
    if(game.used.includes(word)) return `❌ "${word}" already used`;
    if(game.lastWord&&word[0]!==game.lastWord[game.lastWord.length-1]) return `❌ must start with "${game.lastWord[game.lastWord.length-1].toUpperCase()}"`;
    game.lastWord=word;game.used.push(word);addCash(userId,100);
    return `✅ ${word} · next: "${word[word.length-1].toUpperCase()}" · ${name} +${fmt(100)}`;
  }

  if(game.type==='numguess'&&!cmd.startsWith('.')&&/^\d+$/.test(cmd)){
    const guess=parseInt(cmd);
    game.attempts++;
    if(guess===game.secret){
      const reward=Math.max(200,1000-game.attempts*100);
      addCash(userId,reward);addXP(userId,30);delete activeGames[chatId];
      return `🔢 *CORRECT!* The number was ${game.secret}!\n${name} got it in ${game.attempts} guess${game.attempts!==1?'es':''}! +${fmt(reward)}`;
    }
    if(game.attempts>=game.maxAttempts){delete activeGames[chatId];return `🔢 *GAME OVER!*\nThe number was ${game.secret}.\nUsed all ${game.maxAttempts} guesses.`;}
    const hint=guess<game.secret?'📈 too low':'📉 too high';
    return `🔢 ${guess} — ${hint}\nGuesses left: ${game.maxAttempts-game.attempts}`;
  }

  return null;
}

