// ── Memory system ──────────────────────────────────────────────────────────────
function handleMemory(cmd, args, userId, name) {
  if (cmd === '.memory') {
    const fact = args.join(' ').trim();
    if (!fact) return '😒 .memory <something you want me to remember>\ne.g. .memory my favourite colour is red';
    db.prepare('INSERT OR IGNORE INTO notes (user_id, title, content, created_at) VALUES (?,?,?,?)').run(
      userId, '__memory__', '', new Date().toISOString()
    );
    // Store as a special note with prefix
    const existing = db.prepare("SELECT content FROM notes WHERE user_id=? AND title='__memory__'").get(userId);
    const prev = existing?.content || '';
    const updated = prev ? prev + '\n• ' + fact : '• ' + fact;
    db.prepare("UPDATE notes SET content=? WHERE user_id=? AND title='__memory__'").run(updated, userId);
    return `🧠 got it, ${name}. I'll remember that.`;
  }
  if (cmd === '.mymemory') {
    const row = db.prepare("SELECT content FROM notes WHERE user_id=? AND title='__memory__'").get(userId);
    if (!row?.content) return `🧠 I don\'t have any memories saved for you yet.\n.memory <fact> to add one.`;
    return `🧠 What I know about ${name}:\n\n${row.content}`;
  }
  if (cmd === '.forgetnow') {
    const fact = args.join(' ').trim();
    if (!fact) return '😒 .forgetnow <the fact to delete>';
    const row = db.prepare("SELECT content FROM notes WHERE user_id=? AND title='__memory__'").get(userId);
    if (!row?.content) return `🧠 no memories to delete.`;
    const lines = row.content.split('\n').filter(l => !l.toLowerCase().includes(fact.toLowerCase()));
    db.prepare("UPDATE notes SET content=? WHERE user_id=? AND title='__memory__'").run(lines.join('\n'), userId);
    return `🧠 forgotten.`;
  }
  return null;
}

// ── Notes password ─────────────────────────────────────────────────────────────
const _unlockedNotes = new Map(); // userId → expiry timestamp
function handleNotesPw(cmd, args, userId) {
  if (cmd === '.resetnpw') {
    const pw = args[0];
    if (!pw) return '😒 .resetnpw <new_password>';
    db.prepare("INSERT OR REPLACE INTO notes (user_id, title, content, created_at) VALUES (?,?,?,?)").run(
      userId, '__notespw__', pw, new Date().toISOString()
    );
    return `🔑 notes password set. Use .npw <password> to unlock.`;
  }
  if (cmd === '.npw') {
    const pw = args[0];
    if (!pw) return '🔒 .npw <password> to unlock your notes';
    const row = db.prepare("SELECT content FROM notes WHERE user_id=? AND title='__notespw__'").get(userId);
    if (!row) return '😒 no password set. Use .resetnpw <password> first.';
    if (row.content !== pw) return '❌ wrong password.';
    _unlockedNotes.set(userId, Date.now() + 1800000); // unlock for 30 min
    return '🔓 notes unlocked for 30 minutes.';
  }
  return null;
}

// ── Settings ───────────────────────────────────────────────────────────────────
// Persisted in the notes table with a special title prefix __setting__<key>
function _getSettingRow(userId, key) {
  return db.prepare("SELECT content FROM notes WHERE user_id=? AND title=?").get(userId, `__setting__${key}`);
}
function _setSetting(userId, key, value) {
  db.prepare("INSERT OR REPLACE INTO notes (user_id, title, content, created_at) VALUES (?,?,?,?)").run(
    userId, `__setting__${key}`, String(value), new Date().toISOString()
  );
}
function getUserSettings(userId) {
  const notif = _getSettingRow(userId, 'notifications');
  const priv  = _getSettingRow(userId, 'privacy');
  return {
    notifications: notif ? notif.content !== 'false' : true,
    privacy:        priv  ? priv.content  === 'true'  : false,
  };
}
function handleSet(args, userId) {
  const key = (args[0]||'').toLowerCase();
  const val = (args[1]||'').toLowerCase();
  if (!key) {
    const s = getUserSettings(userId);
    return `⚙️ YOUR SETTINGS\n\nNotifications: ${s.notifications?'on':'off'}\nPrivacy mode: ${s.privacy?'on':'off'}\n\n.set notifications on/off\n.set privacy on/off`;
  }
  if (key === 'notifications') {
    _setSetting(userId, 'notifications', val !== 'off' ? 'true' : 'false');
    return `⚙️ notifications turned ${val==='off'?'off':'on'}.`;
  }
  if (key === 'privacy') {
    _setSetting(userId, 'privacy', val === 'on' ? 'true' : 'false');
    return `⚙️ privacy mode ${val==='on'?'on':'off'}.`;
  }
  return `😒 unknown setting "${key}". Try: notifications, privacy`;
}

// ── Report ─────────────────────────────────────────────────────────────────────
function handleReport(args, name, chatId) {
  const msg = args.join(' ');
  if (!msg) return '😒 .report <describe the issue>';
  console.log(`[REPORT] from ${name}: ${msg}`);

  // Defer the forwarding so bot_tg and sessions are guaranteed to be defined
  setImmediate(() => {
    try {
      const reportText = `📩 *NEW REPORT (WhatsApp)*\n\n👤 From: ${name}\n💬 Chat: ${chatId || 'DM'}\n\n📝 "${msg}"`;

      // Forward to owner on WhatsApp
      const ownerJid = MY_WA.replace(/\D/g,'') + '@s.whatsapp.net';
      for (const [, s] of sessions.entries()) {
        if (!s || !s.connected || !s.sock) continue;
        s.sock.sendMessage(ownerJid, { text: reportText }).catch(e => console.error('[report fwd WA]', e.message));
        break;
      }

      // Forward to owner on Telegram
      const ownerTgId = _ownerTgIdGet();
      if (ownerTgId && typeof bot_tg !== 'undefined') {
        bot_tg.telegram.sendMessage(ownerTgId, reportText, { parse_mode: 'Markdown' })
          .catch(e => console.error('[report fwd TG]', e.message));
      }
    } catch (e) { console.error('[handleReport fwd]', e.message); }
  });

  return `✅ report sent! The owner will look into:\n"${msg}"\n\nThank you ${name}.`;
}

// ══════════════════════════════════════════════════════════════════════════════
// PROXY SYSTEM
// Supports: http://, https://, socks4://, socks5://
// One proxy per session (or 'global' to apply to every session).
// The proxy is injected into makeWASocket via the `agent` option.
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Build a Node.js HTTP/SOCKS agent from a proxy URL string.
 * Returns null if no suitable agent package is available.
 */
function buildProxyAgent(proxyUrl) {
  if (!proxyUrl) return null;
  const lower = proxyUrl.toLowerCase();
  try {
    if (lower.startsWith('socks4://') || lower.startsWith('socks5://') || lower.startsWith('socks://')) {
      if (SocksProxyAgent) return new SocksProxyAgent(proxyUrl);
      if (ProxyAgent)      return new ProxyAgent(proxyUrl);
    }
    if (lower.startsWith('http://') || lower.startsWith('https://')) {
      if (HttpsProxyAgent) return new HttpsProxyAgent(proxyUrl);
      if (ProxyAgent)      return new ProxyAgent(proxyUrl);
    }
    // Fallback — let proxy-agent auto-detect
    if (ProxyAgent) return new ProxyAgent(proxyUrl);
  } catch (e) { console.error('[proxy buildAgent]', e.message); }
  return null;
}

/**
 * Get the active proxy URL for a session key.
 * Falls back to 'global' if no per-session proxy is set.
 */
function getSessionProxy(sessionKey) {
  const row = db.prepare(`SELECT proxy_url, enabled FROM proxy_config WHERE session_key=? AND enabled=1`).get(sessionKey)
           || db.prepare(`SELECT proxy_url, enabled FROM proxy_config WHERE session_key='global' AND enabled=1`).get();
  return row ? row.proxy_url : null;
}

/**
 * Validate a proxy URL string.
 * Returns { ok, error } — error is null when valid.
 */
function validateProxyUrl(url) {
  try {
    const u = new URL(url);
    const allowed = ['http:', 'https:', 'socks4:', 'socks5:', 'socks:'];
    if (!allowed.includes(u.protocol)) return { ok: false, error: `Unsupported protocol "${u.protocol}". Use http, https, socks4, or socks5.` };
    if (!u.hostname) return { ok: false, error: 'Missing host in proxy URL.' };
    return { ok: true, error: null };
  } catch (e) { return { ok: false, error: `Invalid URL: ${e.message}` }; }
}

/**
 * Test a proxy by making an HTTP request through it to a known endpoint.
 * Returns { ok, ip, ms, error }.
 */
async function testProxy(proxyUrl) {
  const agent = buildProxyAgent(proxyUrl);
  if (!agent) return { ok: false, ip: null, ms: 0, error: 'No proxy agent package available (install https-proxy-agent or socks-proxy-agent).' };
  const start = Date.now();
  try {
    const res = await axios.get('http://api.ipify.org?format=json', {
      httpAgent: agent,
      httpsAgent: agent,
      timeout: 10_000,
    });
    const ms = Date.now() - start;
    return { ok: true, ip: res.data?.ip || '?', ms, error: null };
  } catch (e) {
    return { ok: false, ip: null, ms: Date.now() - start, error: e.message };
  }
}

// ── Auto-rotating proxy pool ──────────────────────────────────────────────────
// Stores a list of backup proxies. If the active one dies, it automatically
// switches to the next working one and restarts the WA session.
const _proxyPool = (() => {
  const POOL_KEY = 'proxy_pool_list';
  function getPool() {
    try { return JSON.parse(kvGet(POOL_KEY) || '[]'); } catch (_) { return []; }
  }
  function setPool(arr) {
    try { kvSet(POOL_KEY, JSON.stringify(arr)); } catch (_) {}
  }
  function addProxy(url) {
    const pool = getPool();
    if (!pool.includes(url)) { pool.push(url); setPool(pool); }
  }
  function removeProxy(url) {
    setPool(getPool().filter(u => u !== url));
  }
  function listProxies() { return getPool(); }
  return { getPool, setPool, addProxy, removeProxy, listProxies };
})();

// Add all 10 Webshare proxies to the pool on startup
(function _seedWebsharePool() {
  const WS_USER = 'splkuxim';
  const WS_PASS = 'rr4nhj1pljfu';
  const WS_IPS = [
    ['45.38.107.97',    6014],
    ['64.137.96.74',    6641],
    ['198.23.243.226',  6361],
    ['38.154.185.97',   6370],
    ['84.247.60.125',   6095],
    ['191.96.254.138',  6185],
    ['198.46.161.42',   5092],
    ['64.137.10.153',   5803],
    ['104.164.49.38',   7693],
    ['23.26.71.145',    5628],
  ];
  for (const [ip, port] of WS_IPS) {
    _proxyPool.addProxy(`socks5://${WS_USER}:${WS_PASS}@${ip}:${port}`);
  }
})();

// Auto health check — runs every 10 minutes.
// If current proxy is dead, tries each pool proxy until one works,
// sets it as the new global proxy, restarts the WA session, and alerts owner.
setInterval(async () => {
  try {
    const currentProxy = getSessionProxy('global');
    if (!currentProxy) return;

    const check = await testProxy(currentProxy);
    if (check.ok) return; // all good

    console.log('[proxy-pool] current proxy dead, rotating...');

    const pool = _proxyPool.getPool().filter(u => u !== currentProxy);
    let switched = false;

    for (const candidate of pool) {
      const res = await testProxy(candidate);
      if (res.ok) {
        // Save new proxy as global
        db.prepare(`INSERT OR REPLACE INTO proxy_config (session_key, proxy_url, enabled, label, added_at) VALUES (?,?,1,?,?)`)
          .run('global', candidate, 'Global (auto-rotated)', Date.now());

        // Restart all WA sessions with the new proxy
        for (const [sessKey, sess] of (sessions || new Map())) {
          try {
            const savedPhone = sess?.phone || null;
            if (sess?.sock) { try { sess.sock.end(); } catch (_) {} }
            sessions.delete(sessKey);
            setTimeout(async () => {
              try { await createSession(sessKey, savedPhone, null, null, { forceNew: false }); }
              catch (e) { console.error('[proxy-pool restart]', e.message); }
            }, 2000);
          } catch (_) {}
        }

        switched = true;
        const ownerTgId = kvGet('owner_tg_id');
        if (ownerTgId) {
          const safe = candidate.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@');
          bot_tg.telegram.sendMessage(ownerTgId,
            `🔄 *Proxy auto-rotated!*\n\n` +
            `Old proxy died. Switched to:\n\`${safe}\`\n\n` +
            `Exit IP: \`${res.ip}\` · Latency: ${res.ms}ms\n` +
            `WA session is restarting automatically.`,
            { parse_mode: 'Markdown' }
          ).catch(() => {});
        }
        break;
      }
    }

    if (!switched) {
      // All proxies dead — alert owner
      const ownerTgId = kvGet('owner_tg_id');
      if (ownerTgId) {
        bot_tg.telegram.sendMessage(ownerTgId,
          `❌ *All proxies are dead!*\n\n` +
          `Every proxy in the pool failed.\n\n` +
          `Go to webshare.io → Proxy List → click "Replace Proxy" to get fresh IPs, then send:\n` +
          `/proxy pool add socks5://splkuxim:rr4nhj1pljfu@NEW_IP:PORT`,
          { parse_mode: 'Markdown' }
        ).catch(() => {});
      }
    }
  } catch (e) {
    console.error('[proxy-pool check]', e.message);
  }
}, 10 * 60 * 1000);

// ── /proxy pool commands ──
// .proxy pool list         → show all proxies in pool
// .proxy pool add <url>    → add a proxy to the pool
// .proxy pool remove <url> → remove a proxy from the pool
// .proxy pool clear        → clear the pool


// ── .proxy command handler ────────────────────────────────────────────────────
async function handleProxyCommand({ args, sock, sessionKey, own, isSudo, userId, rawUserId }) {
  if (!own && !isSudo(userId)) return '❌ Owner/sudo only.';

  const sub = (args[0] || '').toLowerCase();

  // ── .proxy set [session|global] <url> ──
  if (sub === 'set') {
    // .proxy set <url>              → set for this session
    // .proxy set global <url>       → set for ALL sessions
    // .proxy set <sessionKey> <url> → set for a specific session
    let target = sessionKey;
    let urlArg  = args[1] || '';
    if (args[2]) { target = args[1]; urlArg = args[2]; }
    if (!urlArg) return '❌ Usage: `.proxy set <url>` or `.proxy set global <url>`\nExamples:\n  `.proxy set http://user:pass@1.2.3.4:3128`\n  `.proxy set socks5://1.2.3.4:1080`\n  `.proxy set global socks5://user:pass@proxy.example.com:1080`';
    const { ok, error } = validateProxyUrl(urlArg);
    if (!ok) return `❌ ${error}`;

    // Test before saving (only notify via WhatsApp if a socket is available)
    if (sock) {
      await sock.sendMessage(sock._waReplyJid || sock.user?.id?.split('@')[0] + '@s.whatsapp.net', {
        text: `🔄 Testing proxy: \`${urlArg}\`…`,
      }).catch(() => null);
    }

    const result = await testProxy(urlArg);
    if (!result.ok) {
      return (
        `❌ *Proxy test failed* — not saved.\n\n` +
        `🔗 URL: \`${urlArg}\`\n` +
        `❗ Error: ${result.error}\n\n` +
        `Fix the proxy URL and try again.`
      );
    }

    db.prepare(`INSERT OR REPLACE INTO proxy_config (session_key, proxy_url, enabled, label, added_at) VALUES (?,?,1,?,?)`)
      .run(target, urlArg, target === 'global' ? 'Global (all sessions)' : target, Date.now());

    return (
      `✅ *Proxy set & tested successfully!*\n\n` +
      `🔗 URL: \`${urlArg}\`\n` +
      `🌍 Exit IP: \`${result.ip}\`\n` +
      `⚡ Latency: ${result.ms}ms\n` +
      `🎯 Applied to: ${target === 'global' ? '*all sessions*' : `session \`${target}\``}\n\n` +
      `⚠️ *Restart the session* for the proxy to take effect on the WhatsApp connection.\n` +
      `Send \`.proxy restart\` to reconnect with the proxy active.`
    );
  }

  // ── .proxy test [url] ──
  if (sub === 'test') {
    let urlArg = args[1];
    if (!urlArg) {
      urlArg = getSessionProxy(sessionKey);
      if (!urlArg) return '❌ No proxy configured. Use `.proxy set <url>` first, or pass a URL directly: `.proxy test <url>`';
    }
    const { ok, error } = validateProxyUrl(urlArg);
    if (!ok) return `❌ ${error}`;
    const result = await testProxy(urlArg);
    if (result.ok) {
      return (
        `✅ *Proxy is working!*\n\n` +
        `🔗 URL: \`${urlArg}\`\n` +
        `🌍 Exit IP: \`${result.ip}\`\n` +
        `⚡ Latency: ${result.ms}ms`
      );
    }
    return (
      `❌ *Proxy test failed*\n\n` +
      `🔗 URL: \`${urlArg}\`\n` +
      `❗ Error: ${result.error}\n` +
      `⏱ Took: ${result.ms}ms`
    );
  }

  // ── .proxy off / remove ──
  if (sub === 'off' || sub === 'remove' || sub === 'delete') {
    const target = args[1] === 'global' ? 'global' : sessionKey;
    const existed = db.prepare('SELECT 1 FROM proxy_config WHERE session_key=?').get(target);
    if (!existed) return `📋 No proxy configured for \`${target}\`.`;
    db.prepare('DELETE FROM proxy_config WHERE session_key=?').run(target);
    return `🗑️ Proxy removed for \`${target}\`. Reconnect to apply.`;
  }

  // ── .proxy disable / enable ──
  if (sub === 'disable' || sub === 'enable') {
    const target = args[1] === 'global' ? 'global' : sessionKey;
    const flag   = sub === 'enable' ? 1 : 0;
    const existed = db.prepare('SELECT 1 FROM proxy_config WHERE session_key=?').get(target);
    if (!existed) return `📋 No proxy configured for \`${target}\`. Use \`.proxy set\` first.`;
    db.prepare('UPDATE proxy_config SET enabled=? WHERE session_key=?').run(flag, target);
    return `${flag ? '✅ Proxy *enabled*' : '⏸ Proxy *disabled*'} for \`${target}\`. Reconnect to apply.`;
  }

  // ── .proxy list ──
  if (sub === 'list' || sub === 'status' || !sub) {
    const rows = db.prepare('SELECT * FROM proxy_config ORDER BY session_key').all();
    if (!rows.length) return '📋 No proxies configured.\n\nUse `.proxy set <url>` to add one.\nExamples:\n  `.proxy set http://user:pass@1.2.3.4:3128`\n  `.proxy set socks5://1.2.3.4:1080`\n  `.proxy set global socks5://proxy.example.com:1080`';
    const lines = rows.map(r => {
      const st = r.enabled ? '✅' : '⏸';
      const masked = r.proxy_url.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@'); // hide password
      return `${st} \`${r.session_key}\` → ${masked}`;
    });
    const active = getSessionProxy(sessionKey);
    const activeMasked = active ? active.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@') : 'none';
    return (
      `🔌 *PROXY CONFIG*\n━━━━━━━━━━━━━━━\n\n` +
      lines.join('\n') +
      `\n\n🎯 Active for this session: ${activeMasked}\n\n` +
      `Commands:\n` +
      `.proxy set <url> — add / update proxy\n` +
      `.proxy set global <url> — apply to all sessions\n` +
      `.proxy test [url] — test a proxy\n` +
      `.proxy disable / enable — pause without deleting\n` +
      `.proxy off — remove proxy\n` +
      `.proxy restart — reconnect WA with proxy active`
    );
  }

  // ── .proxy restart ──
  if (sub === 'restart') {
    let proxyUrl = null;
    try { proxyUrl = getSessionProxy(sessionKey); } catch (_) {}

    // Find the session to restart — prefer the one tied to this tgUserId, else any active session
    const _tgUid = String(rawUserId || '').replace(/^tg_/, '');
    const _sessEntry = (sessions && _tgUid && sessions.get(_tgUid))
      ? [_tgUid, sessions.get(_tgUid)]
      : (() => { for (const [k, v] of (sessions || new Map())) { if (v) return [k, v]; } return null; })();

    if (!_sessEntry) {
      return (
        `🔄 *Proxy Restart*\n\n` +
        (proxyUrl
          ? `Proxy \`${proxyUrl.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@')}\` is saved.\n\n`
          : `⚠️ No active proxy — will reconnect without proxy.\n\n`) +
        `No WhatsApp session found. Use /pair <number> to start one.`
      );
    }

    const [_rSessKey, _rSess] = _sessEntry;
    const _savedPhone = _rSess.phone || null;

    // Close the old socket cleanly
    try { if (_rSess.sock) { try { _rSess.sock.end(); } catch (_) {} } } catch (_) {}
    try { sessions.delete(_rSessKey); } catch (_) {}

    // Re-create the session after a brief pause (picks up the new proxy automatically)
    setTimeout(async () => {
      try {
        await createSession(_rSessKey, _savedPhone, null, null, { forceNew: false });
      } catch (e) {
        console.error('[proxy restart]', e.message);
      }
    }, 1500);

    return (
      `🔄 *Proxy Restart triggered!*\n\n` +
      (proxyUrl
        ? `✅ Proxy \`${proxyUrl.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@')}\` will be active on reconnect.\n\n`
        : `⚠️ No proxy configured — reconnecting without proxy.\n\n`) +
      `Session for ${_savedPhone ? '+' + _savedPhone : 'key ' + _rSessKey} is restarting…\n` +
      `Use /wastatus in ~10 seconds to check the connection.`
    );
  }

  // ── .proxy pool ──
  if (sub === 'pool') {
    const action = (args[1] || '').toLowerCase();
    const url = args[2] || '';

    if (action === 'list' || !action) {
      const pool = _proxyPool.listProxies();
      if (!pool.length) return '📋 Proxy pool is empty.\n\nAdd one with:\n`.proxy pool add socks5://user:pass@ip:port`';
      const current = getSessionProxy('global') || '';
      const lines = pool.map((u, i) => {
        const safe = u.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@');
        return `${i + 1}. ${safe}${u === current ? ' ✅ *active*' : ''}`;
      });
      return `🔄 *Proxy Pool* (${pool.length} proxies)\n\n${lines.join('\n')}\n\nBot auto-switches if active one dies.`;
    }

    if (action === 'add') {
      if (!url) return '❌ Usage: `.proxy pool add socks5://user:pass@ip:port`';
      const { ok, error } = validateProxyUrl(url);
      if (!ok) return `❌ ${error}`;
      _proxyPool.addProxy(url);
      return `✅ Added to pool. Pool now has ${_proxyPool.listProxies().length} proxies.`;
    }

    if (action === 'remove') {
      if (!url) return '❌ Usage: `.proxy pool remove socks5://user:pass@ip:port`';
      _proxyPool.removeProxy(url);
      return `✅ Removed. Pool now has ${_proxyPool.listProxies().length} proxies.`;
    }

    if (action === 'clear') {
      _proxyPool.setPool([]);
      return '✅ Proxy pool cleared.';
    }

    return '❌ Usage: `.proxy pool list` · `.proxy pool add <url>` · `.proxy pool remove <url>` · `.proxy pool clear`';
  }

  return (
    `😒 Unknown proxy subcommand \`${sub}\`.\n\n` +
    `Available: set · test · off · disable · enable · list · restart · pool`
  );
}

// ── Report a number via WhatsApp's native report mechanism ─────────────────────
// Real flow per cycle: BLOCK → REPORT (while blocked) → UNBLOCK → repeat
async function handleReportNumber({ number, count, reason, reportedBy, reportedByName, groupId, sock, replyJid }) {

  // ── Normalise number ────────────────────────────────────────────────────────
  const clean = String(number || '').replace(/[\s\-\+]/g, '').replace(/^0+/, '');
  if (!clean || !/^\d{6,15}$/.test(clean)) {
    return (
      '❌ Invalid number.\n' +
      'Usage: `.reportnum <number> [times] <reason>`\n' +
      'Example: `.reportnum 2348012345678 10 spamming`'
    );
  }
  if (!reason) {
    return (
      '❌ Include a reason.\n' +
      'Usage: `.reportnum <number> [times] <reason>`'
    );
  }

  const MAX_REPORTS = 50;
  const times = Math.min(Math.max(1, parseInt(count) || 1), MAX_REPORTS);
  const targetJid = `${clean}@s.whatsapp.net`;

  // ── Resolve LID + verify on WA ──────────────────────────────────────────────
  let isOnWA = false;
  let targetLid = null;
  try {
    const onWa = await sock.onWhatsApp(targetJid);
    const entry = onWa?.[0];
    isOnWA = !!entry?.exists;
    if (entry?.lid) targetLid = entry.lid;
  } catch (_) {}
  if (!targetLid) {
    try { const m = lidMap.getLid && lidMap.getLid(clean); if (m) targetLid = m; } catch (_) {}
  }
  if (!isOnWA) {
    return `⚠️ *+${clean}* is not on WhatsApp. Check the number and try again.`;
  }

  // ── BLOCK helper (3 methods, LID-aware) ────────────────────────────────────
  const doBlock = async (action) => {
    if (targetLid) {
      try {
        await sock.query({
          tag: 'iq',
          attrs: { xmlns: 'blocklist', to: 's.whatsapp.net', type: 'set' },
          content: [{ tag: 'item', attrs: { action, jid: targetLid, pn_jid: targetJid } }],
        });
        return true;
      } catch (_) {}
    }
    try {
      await sock.query({
        tag: 'iq',
        attrs: { xmlns: 'blocklist', to: 's.whatsapp.net', type: 'set' },
        content: [{ tag: 'item', attrs: { action, jid: targetJid } }],
      });
      return true;
    } catch (_) {}
    try { await sock.updateBlockStatus(targetJid, action); return true; } catch (_) {}
    return false;
  };

  // ── REPORT helper — fires while the number is blocked (real WA flow) ────────
  // Primary: w:profile spam (LID-aware), fallback: w:spam namespace
  const doReport = async () => {
    // Primary shape — w:profile spam
    try {
      const res = await sock.query({
        tag: 'iq',
        attrs: { xmlns: 'w:profile', to: 's.whatsapp.net', type: 'set', id: sock.generateMessageTag() },
        content: [{
          tag: 'report',
          attrs: targetLid
            ? { jid: targetLid, pn_jid: targetJid, type: 'spam' }
            : { jid: targetJid, type: 'spam' },
        }],
      });
      // WA returns type="result" on success
      if (res?.attrs?.type === 'result' || res != null) return true;
    } catch (_) {}

    // Fallback shape — w:spam namespace
    try {
      await sock.query({
        tag: 'iq',
        attrs: { xmlns: 'w:spam', to: 's.whatsapp.net', type: 'set', id: sock.generateMessageTag() },
        content: [{
          tag: 'report',
          attrs: targetLid
            ? { jid: targetLid, pn_jid: targetJid }
            : { jid: targetJid },
        }],
      });
      return true;
    } catch (_) {}

    return false;
  };

  // ── Start notice ────────────────────────────────────────────────────────────
  try {
    await sock.sendMessage(replyJid, {
      text:
        `🚨 *Report Task Started*\n\n` +
        `📱 Target: *+${clean}*\n` +
        `🔑 LID: ${targetLid ? `_${targetLid}_` : '❌ none (phone JID fallback)'}\n` +
        `🔁 Cycles: *${times}*\n` +
        `💬 Reason: _${reason}_\n` +
        `⚙️ Flow: *block → report → unblock* (×${times})\n\n` +
        `_Running..._`,
    });
  } catch (_) {}

  // ── Main loop: BLOCK → REPORT → UNBLOCK ────────────────────────────────────
  let reported = 0;
  let failed   = 0;
  const ticks  = []; // per-cycle tick marks shown in final summary

  for (let i = 0; i < times; i++) {
    try {
      // ① Block
      let blocked = await doBlock('block');
      if (!blocked) { await sleep(800); blocked = await doBlock('block'); }
      await sleep(800 + Math.random() * 400);

      // ② Report WHILE BLOCKED — this is how WA's native "Report & Block" works
      const ok = await doReport();
      await sleep(500 + Math.random() * 300);

      // ③ Unblock (retry once if it fails)
      let unblocked = await doBlock('unblock');
      if (!unblocked) { await sleep(800); await doBlock('unblock'); }

      if (ok) { reported++; ticks.push('✅'); }
      else     { failed++;   ticks.push('⚠️'); }

      // Progress update every 5 cycles (or every cycle when ≤5 total)
      const every = times <= 5 ? 1 : 5;
      if ((i + 1) % every === 0 && i + 1 < times) {
        const bar = ticks.join('');
        try {
          await sock.sendMessage(replyJid, {
            text:
              `⏳ *${i + 1}/${times} done*\n\n` +
              `${bar}\n\n` +
              `✅ Reported: ${reported}  ⚠️ Failed: ${failed}`,
          });
        } catch (_) {}
      }

      // Human-like gap between cycles (slight ramp to avoid rate-limit)
      if (i < times - 1) await sleep(1500 + i * 60 + Math.random() * 1000);

    } catch (e) {
      failed++;
      ticks.push('❌');
      console.error(`[reportnum cycle ${i + 1}]`, e.message);
      await sleep(3000 + Math.random() * 1000);
    }
  }

  // Always leave the number unblocked
  try { await doBlock('unblock'); } catch (_) {}

  // ── Save to DB ──────────────────────────────────────────────────────────────
  db.prepare(
    `INSERT INTO number_reports (reported_number, reported_by, reported_by_name, reason, group_id, reported_at)
     VALUES (?, ?, ?, ?, ?, ?)`
  ).run(clean, reportedBy, reportedByName, `[x${times}] ${reason}`, groupId || '', Date.now());

  const totalInDb = db.prepare('SELECT COUNT(*) as c FROM number_reports WHERE reported_number=?').get(clean).c;

  // ── Final "task done" message ───────────────────────────────────────────────
  const rate = times > 0 ? Math.round((reported / times) * 100) : 0;
  const tickBar = ticks.join('');
  const summary =
    `🎯 *Task Done!*\n\n` +
    `${tickBar}\n\n` +
    `📱 *+${clean}* has been reported *${reported}* time${reported !== 1 ? 's' : ''}.\n` +
    (targetLid ? `🔑 LID: _${targetLid}_\n` : '') +
    `🔁 Cycles: *${times}* — ✅ ${reported} success, ⚠️ ${failed} failed (${rate}%)\n` +
    `💬 Reason: _${reason}_\n` +
    `📊 Total reports logged for +${clean}: *${totalInDb}*\n\n` +
    `🔓 Number is unblocked. All done.`;

  // ── Notify owner (WA + Telegram) ───────────────────────────────────────────
  setImmediate(() => {
    try {
      const ownerJid = MY_WA.replace(/\D/g, '') + '@s.whatsapp.net';
      sock.sendMessage(ownerJid, { text: summary }).catch(e => console.error('[reportnum owner]', e.message));
      const ownerTgId = _ownerTgIdGet();
      if (ownerTgId && typeof bot_tg !== 'undefined') {
        bot_tg.telegram.sendMessage(ownerTgId, summary, { parse_mode: 'Markdown' })
          .catch(e => console.error('[reportnum tg]', e.message));
      }
    } catch (e) { console.error('[handleReportNumber notify]', e.message); }
  });

  return summary;
}

