// ============ GROUP SETTINGS HELPERS ============
function getGroupSettings(groupId) {
  let s = db.prepare('SELECT * FROM group_settings WHERE group_id=?').get(groupId);
  if (!s) {
    db.prepare('INSERT OR IGNORE INTO group_settings (group_id) VALUES (?)').run(groupId);
    s = db.prepare('SELECT * FROM group_settings WHERE group_id=?').get(groupId);
  }
  return s;
}
function setGroupSetting(groupId, field, value) {
  getGroupSettings(groupId);
  db.prepare(`UPDATE group_settings SET ${field}=? WHERE group_id=?`).run(value, groupId);
}
function addWarning(groupId, targetId, reason, warnedBy) {
  db.prepare('INSERT INTO warnings (group_id,user_id,reason,warned_by,warned_at) VALUES (?,?,?,?,?)').run(groupId, targetId, reason||'', warnedBy, new Date().toISOString());
  return db.prepare('SELECT COUNT(*) as c FROM warnings WHERE group_id=? AND user_id=?').get(groupId, targetId).c;
}
function getWarnings(groupId, targetId) {
  return db.prepare('SELECT * FROM warnings WHERE group_id=? AND user_id=? ORDER BY warned_at DESC').all(groupId, targetId);
}
function clearWarnings(groupId, targetId) {
  db.prepare('DELETE FROM warnings WHERE group_id=? AND user_id=?').run(groupId, targetId);
}
// Check if text contains a link
// Strip tricks spammers use to dodge link filters: invisible characters, full-width dots,
// "example dot com", "example[.]com", "example. com", spaced-out "h t t p s : //".
function _normLinkText(t) {
  let x = String(t || '');
  try { x = x.normalize('NFKC'); } catch (_) {}
  x = x.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF\u00AD\u034F\u061C\u115F\u1160\u3164]/g, '');
  x = x.replace(/[\u3002\uFF0E\uFF61\u2024\u2027\u30FB\u2E31]/g, '.');
  x = x.replace(/\s*[\[\(\{<]\s*(?:\.|dot)\s*[\]\)\}>]\s*/gi, '.');
  x = x.replace(/\b([a-z0-9][a-z0-9-]*)\s+(?:dot|d0t)\s+(com|net|org|xyz|link|gg|app|site|online|club|shop|top|vip|live|store|page)\b/gi, '$1.$2');
  x = x.replace(/\b([a-z0-9][a-z0-9-]*)\.\s+(com|net|org|xyz|link|gg)\b(?!['’])/g, '$1.$2');
  x = x.replace(/h\s*t\s*t\s*p\s*s?\s*:\s*\/\s*\//gi, 'http://');
  return x;
}
const _LINK_RE = /https?:\/\/|www\.|chat\.whatsapp\.com|whatsapp\.com\/(?:channel|invite)|(?<![a-z0-9])wa\.me\b|wa\.link|(?<![a-z0-9])t\.me\b|telegram\.(?:me|dog)|discord(?:\.gg|app\.com\/invite)|bit\.ly|tinyurl|youtu\.be|\b\d{1,3}(?:\.\d{1,3}){3}(?::\d+)?(?:\/\S*)?|\b[a-z0-9-]{2,}\.(?:com|net|org|io|me|co|link|gg|xyz|ng|info|app|site|online|ly|tv|club|shop|top|vip|cc|biz|store|page|live|dev|ai|cloud|click|fun|icu|tk|ml|ga|cf|gq|ru|cn|ws|su|pw|win|bid|loan|work|today|world|space|website|tech|digital|network|group)\b(?:\/\S*)?/i;
function hasLink(text) {
  const raw = String(text || '');
  return _LINK_RE.test(raw) || _LINK_RE.test(_normLinkText(raw));
}

// ============ GROUP TOOLKIT — moderation, admin extras, activity stats ============
// Platform-neutral helpers (DB, durations, flood/bad-word checks) plus WhatsApp and
// Telegram command handlers. WA user keys are 'wa_<phone>', TG user keys are the numeric id
// (same keys the existing warning system already uses).
try {
  db.exec(`CREATE TABLE IF NOT EXISTS muted_users (
    group_id TEXT NOT NULL, user_id TEXT NOT NULL, until INTEGER DEFAULT 0,
    muted_by TEXT DEFAULT '', name TEXT DEFAULT '',
    PRIMARY KEY (group_id, user_id)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS badwords (
    group_id TEXT NOT NULL, word TEXT NOT NULL,
    PRIMARY KEY (group_id, word)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS group_activity (
    group_id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT DEFAULT '',
    msgs INTEGER DEFAULT 0, last_seen INTEGER DEFAULT 0,
    PRIMARY KEY (group_id, user_id)
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS group_bans (
    group_id TEXT NOT NULL, user_id TEXT NOT NULL, reason TEXT DEFAULT '',
    banned_by TEXT DEFAULT '', banned_at TEXT DEFAULT '',
    PRIMARY KEY (group_id, user_id)
  )`);
} catch (e) { console.error('[groupkit db]', e.message); }
for (const _col of ['antiflood_on INTEGER DEFAULT 0', 'warn_limit INTEGER DEFAULT 3', 'badword_on INTEGER DEFAULT 0']) {
  try { db.exec(`ALTER TABLE group_settings ADD COLUMN ${_col}`); } catch (_) {}
}

// ── Generic helpers ───────────────────────────────────────────────────────────
// "10m", "2h", "1d", "1w" (bare number = minutes). Min 1 minute, max 30 days. null = not a duration.
function gtParseDuration(s) {
  const m = /^(\d{1,5})\s*(s|m|h|d|w)?$/i.exec(String(s || '').trim());
  if (!m) return null;
  const mult = { s: 1e3, m: 6e4, h: 36e5, d: 864e5, w: 6048e5 }[(m[2] || 'm').toLowerCase()];
  return Math.max(60000, Math.min(parseInt(m[1], 10) * mult, 30 * 864e5));
}
function gtFmtDuration(ms) {
  const mins = Math.max(1, Math.round(ms / 60000));
  if (mins < 60) return `${mins}m`;
  const h = Math.floor(mins / 60);
  if (h < 24) return `${h}h${mins % 60 ? ' ' + (mins % 60) + 'm' : ''}`;
  const d = Math.floor(h / 24);
  return `${d}d${h % 24 ? ' ' + (h % 24) + 'h' : ''}`;
}
function gtWarnLimit(groupId) {
  const n = parseInt(getGroupSettings(groupId).warn_limit, 10);
  return n >= 1 && n <= 10 ? n : 3;
}
function gtStrike(groupId, userKey, reason) {
  const count = addWarning(groupId, userKey, reason, 'bot');
  const limit = gtWarnLimit(groupId);
  return { count, limit, kick: count >= limit };
}
function gtErr(e) {
  const m = String((e && e.message) || e || 'unknown error');
  if (/not-authorized|forbidden|403|401|not enough rights|administrator|CHAT_ADMIN_REQUIRED/i.test(m)) return 'I need to be a group admin (with the right permissions) to do that.';
  return m;
}
function gtOnOff(v) { return v ? '✅ On' : '❌ Off'; }

// ── Mutes (bot-side, works on WhatsApp where there is no native per-user mute) ──
function gtMuteAdd(groupId, userKey, untilMs, by, name) {
  db.prepare('INSERT OR REPLACE INTO muted_users (group_id,user_id,until,muted_by,name) VALUES (?,?,?,?,?)')
    .run(groupId, userKey, untilMs || 0, by || '', name || '');
}
function gtMuteRemove(groupId, userKey) {
  db.prepare('DELETE FROM muted_users WHERE group_id=? AND user_id=?').run(groupId, userKey);
}
function gtIsMuted(groupId, userKey) {
  const r = db.prepare('SELECT until FROM muted_users WHERE group_id=? AND user_id=?').get(groupId, userKey);
  if (!r) return false;
  if (r.until && Number(r.until) <= Date.now()) { gtMuteRemove(groupId, userKey); return false; }
  return true;
}
function gtMuteList(groupId) {
  db.prepare('DELETE FROM muted_users WHERE group_id=? AND until>0 AND until<=?').run(groupId, Date.now());
  return db.prepare('SELECT * FROM muted_users WHERE group_id=? ORDER BY until').all(groupId);
}

// ── Group blacklist (WA has no native ban — bot re-removes banned users who rejoin) ──
function gtBanAdd(groupId, userKey, reason, by) {
  db.prepare('INSERT OR REPLACE INTO group_bans (group_id,user_id,reason,banned_by,banned_at) VALUES (?,?,?,?,?)')
    .run(groupId, userKey, reason || '', by || '', new Date().toISOString());
}
function gtBanRemove(groupId, userKey) { db.prepare('DELETE FROM group_bans WHERE group_id=? AND user_id=?').run(groupId, userKey); }
function gtIsBanned(groupId, userKey) { return !!db.prepare('SELECT 1 FROM group_bans WHERE group_id=? AND user_id=?').get(groupId, userKey); }

// ============ JOIN REQUESTS: AUTO APPROVE / AUTO REJECT + GOOD / BAD LISTS (WhatsApp) ============
// join_mode: 'approve' = approve every request except bad-list people, 'reject' = reject every request except good-list people.
// The lists always apply: good-list people are approved/added, bad-list people are rejected/removed.
try { db.exec("ALTER TABLE group_settings ADD COLUMN join_mode TEXT DEFAULT ''"); } catch (_) {}
try { db.exec(`CREATE TABLE IF NOT EXISTS join_marks (
  group_id TEXT NOT NULL, digits TEXT NOT NULL, kind TEXT NOT NULL, added_at TEXT DEFAULT '',
  PRIMARY KEY (group_id, digits)
)`); } catch (e) { console.error('[join_marks db]', e.message); }
function jrMark(groupId, digits, kind) { db.prepare('INSERT OR REPLACE INTO join_marks (group_id,digits,kind,added_at) VALUES (?,?,?,?)').run(groupId, digits, kind, new Date().toISOString()); }
function jrUnmark(groupId, digits) { return db.prepare('DELETE FROM join_marks WHERE group_id=? AND digits=?').run(groupId, digits).changes > 0; }
function jrList(groupId) { return db.prepare('SELECT digits, kind FROM join_marks WHERE group_id=? ORDER BY kind, added_at').all(groupId); }
function jrKind(groupId, digitsArr) {
  let good = false;
  for (const d of digitsArr || []) {
    if (!d) continue;
    const r = db.prepare('SELECT kind FROM join_marks WHERE group_id=? AND digits=?').get(groupId, d);
    if (r && r.kind === 'bad') return 'bad';
    if (r && r.kind === 'good') good = true;
  }
  return good ? 'good' : '';
}
function jrDecide(groupId, digitsArr) {
  const k = jrKind(groupId, digitsArr);
  if (k === 'bad') return 'reject';
  if (k === 'good') return 'approve';
  const m = getGroupSettings(groupId).join_mode;
  return m === 'approve' ? 'approve' : m === 'reject' ? 'reject' : null;
}
function jrReqIds(req) {
  if (!req) return [];
  if (typeof req === 'string') return [req];
  return [req.jid, req.phone_number, req.phoneNumber, req.participant, req.participantPn, req.lid, req.id].filter(Boolean);
}
async function jrFindSock(groupJid) {
  const c = _selfCtx.getStore() || {};
  if (c.sess) for (const [, s] of sessions) { if (s && s.connected && s.sock && _abSessKey(s.sock) === c.sess) return s.sock; }
  for (const [, s] of sessions) {
    if (!s || !s.connected || !s.sock) continue;
    try { await s.sock.groupMetadata(groupJid); return s.sock; } catch (_) {}
  }
  return null;
}
// Go through the pending join requests of a group and approve / reject the ones the rules decide on.
async function jrProcessPending(sock, groupJid) {
  const out = { approved: 0, rejected: 0, left: 0, error: '', total: 0 };
  let list = [];
  try { list = await sock.groupRequestParticipantsList(groupJid); }
  catch (e) { out.error = e.message || String(e); return out; }
  out.total = (list || []).length;
  const buckets = { approve: [], reject: [] };
  for (const req of list || []) {
    const ids = jrReqIds(req);
    const dec = jrDecide(groupJid, ids.map(_gtDigits));
    const jid = req.jid || req.phone_number || req.phoneNumber || ids[0];
    if (!dec || !jid) { out.left++; continue; }
    buckets[dec].push(jid);
  }
  for (const act of ['approve', 'reject']) {
    const jids = buckets[act];
    for (let i = 0; i < jids.length; i += 20) {
      const part = jids.slice(i, i + 20);
      try { await sock.groupRequestParticipantsUpdate(groupJid, part, act); out[act === 'approve' ? 'approved' : 'rejected'] += part.length; }
      catch (e) { out.error = e.message || String(e); }
      await sleep(1500);
    }
  }
  return out;
}

// ── Bad-word filter ───────────────────────────────────────────────────────────
function _gtNorm(s) { return String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, ''); }
function gtBadwordAdd(groupId, word) {
  const w = _gtNorm(word).trim().slice(0, 40);
  if (!w) return false;
  db.prepare('INSERT OR IGNORE INTO badwords (group_id,word) VALUES (?,?)').run(groupId, w);
  return true;
}
function gtBadwordRemove(groupId, word) {
  const w = _gtNorm(word).trim();
  const had = !!db.prepare('SELECT 1 FROM badwords WHERE group_id=? AND word=?').get(groupId, w);
  db.prepare('DELETE FROM badwords WHERE group_id=? AND word=?').run(groupId, w);
  return had;
}
function gtBadwordList(groupId) { return db.prepare('SELECT word FROM badwords WHERE group_id=? ORDER BY word').all(groupId).map(r => r.word); }
// Whole-word / whole-phrase match so "class" never trips a filter on "ass".
function gtHasBadword(groupId, text) {
  const words = gtBadwordList(groupId);
  if (!words.length) return null;
  const t = ' ' + _gtNorm(text) + ' ';
  for (const w of words) {
    const esc = w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    try { if (new RegExp(`(^|[^\\p{L}\\p{N}])${esc}([^\\p{L}\\p{N}]|$)`, 'iu').test(t)) return w; } catch (_) {}
  }
  return null;
}

// ── Anti-flood: 7 messages within 8 seconds ──────────────────────────────────
const _gtFlood = new Map();
function gtFloodHit(groupId, userKey, limit = 7, windowMs = 8000) {
  const k = groupId + '|' + userKey, now = Date.now();
  const arr = (_gtFlood.get(k) || []).filter(t => now - t < windowMs);
  arr.push(now);
  if (arr.length >= limit) { _gtFlood.delete(k); return true; }
  _gtFlood.set(k, arr);
  return false;
}
setInterval(() => {
  const now = Date.now();
  for (const [k, a] of _gtFlood) if (!a.length || now - a[a.length - 1] > 60000) _gtFlood.delete(k);
}, 120000).unref();

// ── Activity tracking (buffered in memory, flushed to SQLite in batches) ─────
const _gtAct = new Map();
function gtTrack(groupId, userKey, name) {
  const k = groupId + '|' + userKey;
  const e = _gtAct.get(k) || { groupId, userKey, name: '', n: 0, last: 0 };
  e.n++; e.last = Date.now(); if (name) e.name = name;
  _gtAct.set(k, e);
}
function gtFlushActivity() {
  if (!_gtAct.size) return;
  const batch = [..._gtAct.values()];
  _gtAct.clear();
  for (const e of batch) {
    try {
      db.prepare(`INSERT INTO group_activity (group_id,user_id,name,msgs,last_seen) VALUES (?,?,?,?,?)
        ON CONFLICT(group_id,user_id) DO UPDATE SET msgs=msgs+excluded.msgs, name=CASE WHEN excluded.name<>'' THEN excluded.name ELSE name END, last_seen=excluded.last_seen`)
        .run(e.groupId, e.userKey, e.name || '', e.n, e.last);
    } catch (err) { console.error('[gt flush]', err.message); }
  }
}
setInterval(gtFlushActivity, 20000).unref();
process.on('exit', () => { try { gtFlushActivity(); } catch (_) {} });
function gtStatsText(groupId, limit = 10) {
  gtFlushActivity();
  const rows = db.prepare('SELECT name,msgs FROM group_activity WHERE group_id=? ORDER BY msgs DESC LIMIT ?').all(groupId, limit);
  if (!rows.length) return '📊 No activity recorded yet — stats start counting from now.';
  const total = db.prepare('SELECT SUM(msgs) AS t, COUNT(*) AS c FROM group_activity WHERE group_id=?').get(groupId);
  const medals = ['🥇', '🥈', '🥉'];
  return `📊 MOST ACTIVE MEMBERS\n\n` +
    rows.map((r, i) => `${medals[i] || (i + 1) + '.'} ${r.name || 'unknown'} — ${Number(r.msgs).toLocaleString()} msgs`).join('\n') +
    `\n\n💬 ${Number(total.t || 0).toLocaleString()} messages from ${total.c} members tracked`;
}
function gtSettingsText(groupId) {
  const s = getGroupSettings(groupId);
  return `⚙️ GROUP SETTINGS\n\n` +
    `🔒 Locked: ${s.locked ? 'Yes' : 'No'}\n` +
    `🔗 Anti-link: ${gtOnOff(s.antilink_on)}\n` +
    `👥 Anti-GM: ${gtOnOff(s.antigm_on)}\n` +
    `📛 Anti-status: ${gtOnOff(s.antistatus_on)}\n` +
    `🌊 Anti-flood: ${gtOnOff(s.antiflood_on)}\n` +
    `🤬 Bad-word filter: ${gtOnOff(s.badword_on)} (${gtBadwordList(groupId).length} words)\n` +
    `🎉 Welcome: ${gtOnOff(s.welcome_on)}\n` +
    `👋 Goodbye: ${gtOnOff(s.goodbye_on)}\n` +
    `🖼️ Welcome card: ${gtOnOff(s.welcomecard_on !== 0)}\n` +
    `🚫 No-Bot (block 3rd-party bots): ${gtOnOff(s.antibot_on)}\n` +
    `🛡️ Join captcha: ${gtOnOff(s.captcha_on)}\n` +
    `🌙 Auto lock: ${s.sched_on ? `✅ ${s.sched_close} → ${s.sched_open}` : '❌ Off'}\n` +
    `⚠️ Warn limit: ${gtWarnLimit(groupId)}\n` +
    `🔇 Muted now: ${gtMuteList(groupId).length}\n` +
    `📋 Rules: ${s.rules ? 'set' : 'not set'}`;
}

// ── WhatsApp helpers ──────────────────────────────────────────────────────────
const _gtMetaCache = new Map();
function _gtDigits(j) { return String(j || '').split('@')[0].split(':')[0].replace(/\D/g, ''); }
async function gtWaMeta(sock, jid, fresh = false) {
  const c = _gtMetaCache.get(jid);
  if (!fresh && c && Date.now() - c.t < 30000) return c.meta;
  const meta = await sock.groupMetadata(jid);
  _gtMetaCache.set(jid, { t: Date.now(), meta });
  return meta;
}
function gtWaMetaInvalidate(jid) { _gtMetaCache.delete(jid); }
// Match a participant by ANY of id / lid / phoneNumber so both phone-JID and @lid groups work.
function gtWaFind(meta, jid) {
  const d = _gtDigits(jid);
  if (!d || !meta || !Array.isArray(meta.participants)) return null;
  return meta.participants.find(p => [p.id, p.lid, p.phoneNumber, p.jid].some(x => x && _gtDigits(x) === d)) || null;
}
function gtWaIsAdmin(meta, jid) { const p = gtWaFind(meta, jid); return !!p && (p.admin === 'admin' || p.admin === 'superadmin'); }
function gtWaBotIsAdmin(sock, meta) { return [sock.user && sock.user.id, sock.user && sock.user.lid].some(i => i && gtWaIsAdmin(meta, i)); }
// JID form the API expects for this participant (may be @lid in newer groups).
function gtWaApiJid(meta, jid) { const p = gtWaFind(meta, jid); return (p && p.id) || jid; }
// Stable per-user key ('wa_<phone>') matching what warnings/antilink already use.
function gtWaKey(meta, jid) {
  const p = gtWaFind(meta, jid);
  const cands = [p && p.phoneNumber, p && p.jid, p && p.id, jid].filter(x => x && !/@lid/.test(String(x)));
  return 'wa_' + _gtDigits(cands[0] || jid);
}

// Runs on EVERY group message before anything else. Returns true if the message was consumed.
async function gtWaGate(env) {
  const { sock, jid, msg, senderJid, senderNumber, rawUserId, userId, name, text } = env;
  gtTrack(jid, rawUserId, name);
  if (isSudo(userId)) return false;
  const gs = getGroupSettings(jid);
  const del = async () => { try { await sock.sendMessage(jid, { delete: msg.key }); } catch (_) {} };

  if (gtIsMuted(jid, rawUserId)) { await del(); return true; }

  const flooding = !!gs.antiflood_on && gtFloodHit(jid, rawUserId);
  const badWord = gs.badword_on && text ? gtHasBadword(jid, text) : null;
  if (!flooding && !badWord) return false;

  let meta;
  try { meta = await gtWaMeta(sock, jid); } catch (_) { return false; }
  if (gtWaIsAdmin(meta, senderJid)) return false; // admins are exempt
  await del();
  const st = gtStrike(jid, rawUserId, badWord ? 'banned word' : 'flooding');
  let out = `⚠️ @${senderNumber} ${badWord ? 'that word is not allowed here' : 'slow down, no flooding'}. (Warning ${st.count}/${st.limit})`;
  if (st.kick) {
    try {
      await sock.groupParticipantsUpdate(jid, [gtWaApiJid(meta, senderJid)], 'remove');
      clearWarnings(jid, rawUserId);
      out = `🚫 @${senderNumber} was removed after ${st.limit} warnings.`;
    } catch (_) {}
  }
  try { await sock.sendMessage(jid, { text: out, mentions: [senderJid] }); } catch (_) {}
  return true;
}

// When someone joins a group they were banned from, remove them again.
async function gtWaEnforceBans(sock, groupJid, participants) {
  const list = (participants || []).map(p => (typeof p === 'string' ? p : (p && (p.id || p.jid)))).filter(Boolean);
  if (!list.length) return;
  const meta = await gtWaMeta(sock, groupJid, true);
  for (const pj of list) {
    if (!gtIsBanned(groupJid, gtWaKey(meta, pj)) && jrKind(groupJid, [_gtDigits(pj), _gtDigits(gtWaKey(meta, pj))]) !== 'bad') continue;
    try {
      await sock.groupParticipantsUpdate(groupJid, [gtWaApiJid(meta, pj)], 'remove');
      await sock.sendMessage(groupJid, { text: `🚫 @${_gtDigits(pj)} is not allowed in this group and was removed again.`, mentions: [pj] });
    } catch (e) { console.error('[ban enforce]', e.message); }
  }
}

// ============ JOIN CAPTCHA + AUTO LOCK/OPEN + WELCOME CARD (WhatsApp) ============
// 1) Join captcha: new members must answer a quick maths question or they are removed.
// 2) Auto lock/open: the group locks at night and opens in the morning (per-group times + timezone).
// 3) Welcome card: a generated image with the member's profile photo and name.
const CAPTCHA_MAX_TRIES = 3;
const SCHED_TZ_DEFAULT = process.env.GROUP_TZ || 'Africa/Lagos';
const _captchaPending = new Map();   // groupJid -> Map(key -> record)
const _captchaKicked = new Map();    // groupJid|digits -> expiry (so "left the group" isn't posted for captcha kicks)

function _capKey(groupJid, d) { return groupJid + '|' + d; }
function _capDigitsOf(p) {
  const set = new Set();
  for (const x of [p && p.id, p && p.lid, p && p.phoneNumber, p && p.jid]) { const d = _gtDigits(x); if (d) set.add(d); }
  return set;
}
function captchaWasKicked(groupJid, p) {
  const now = Date.now();
  for (const d of _capDigitsOf(p)) { const t = _captchaKicked.get(_capKey(groupJid, d)); if (t && t > now) return true; }
  return false;
}
function captchaClear(groupJid, participants) {
  const m = _captchaPending.get(groupJid);
  if (!m || !m.size) return;
  for (const p0 of participants || []) {
    const p = typeof p0 === 'string' ? { id: p0 } : p0;
    const ds = _capDigitsOf(p);
    for (const [k, rec] of m) {
      if ([...rec.digits].some(d => ds.has(d))) { clearTimeout(rec.timer); m.delete(k); }
    }
  }
}
async function captchaFail(sock, groupJid, rec, why) {
  const m = _captchaPending.get(groupJid);
  if (m) m.delete(rec.key);
  clearTimeout(rec.timer);
  for (const d of rec.digits) _captchaKicked.set(_capKey(groupJid, d), Date.now() + 90000);
  try {
    const meta = await gtWaMeta(sock, groupJid, true);
    await sock.groupParticipantsUpdate(groupJid, [gtWaApiJid(meta, rec.jid)], 'remove');
    await sock.sendMessage(groupJid, {
      text: `🚫 @${_gtDigits(rec.jid)} was removed — ${why === 'tries' ? 'too many wrong answers' : 'did not complete the verification in time'}.`,
      mentions: [rec.jid],
    });
  } catch (e) { console.error('[captcha kick]', e.message); }
}
// Starts the captcha for the joiners. Returns the list of participants that are now being verified
// (those get their welcome only after they pass). Everyone else is welcomed normally.
async function captchaStart(sock, groupJid, pl, meta, gs, onVerified) {
  const handled = [];
  if (!gtWaBotIsAdmin(sock, meta)) { console.log('[captcha] bot is not admin in', groupJid, '- skipped'); return handled; }
  const mins = Math.max(1, Math.min(30, parseInt(gs.captcha_mins, 10) || 2));
  const targets = [];
  for (const p of pl) {
    const d = _gtDigits(p.id);
    if (!d) continue;
    if (sock.user && [sock.user.id, sock.user.lid].some(i => i && _gtDigits(i) === d)) continue;   // the bot itself
    const found = gtWaFind(meta, p.id);
    if (found && found.admin) continue;
    let key; try { key = gtWaKey(meta, p.id); } catch (_) { key = 'wa_' + d; }
    if (isSudo(key) || gtIsBanned(groupJid, key)) continue;
    targets.push(p);
  }
  if (!targets.length) return handled;

  const a = 2 + Math.floor(Math.random() * 8), b = 2 + Math.floor(Math.random() * 8);
  const mul = Math.random() < 0.4;
  const answer = mul ? a * b : a + b;
  const tags = targets.map(p => '@' + _gtDigits(p.id)).join(' ');
  try {
    await sock.sendMessage(groupJid, {
      text: `🛡️ *VERIFICATION*\n\nHi ${tags}! Prove you're human — reply with the answer:\n\n➡️ *What is ${a} ${mul ? '×' : '+'} ${b}?*\n\n⏳ ${mins} min · ${CAPTCHA_MAX_TRIES} tries, or you will be removed.`,
      mentions: targets.map(p => p.id),
    });
  } catch (e) { console.error('[captcha send]', e.message); return handled; }

  if (!_captchaPending.has(groupJid)) _captchaPending.set(groupJid, new Map());
  const m = _captchaPending.get(groupJid);
  for (const p of targets) {
    const key = _gtDigits(p.id);
    const rec = { key, jid: p.id, p, digits: _capDigitsOf(p), answer, tries: 0, onVerified, timer: null };
    rec.timer = setTimeout(() => { captchaFail(sock, groupJid, rec, 'timeout').catch(() => {}); }, mins * 60000);
    if (rec.timer.unref) rec.timer.unref();
    m.set(key, rec);
    handled.push(p);
  }
  return handled;
}
// Runs on every group message. Returns true when the message came from someone who is still being verified.
async function captchaCheckMessage({ sock, jid, msg, senderJid, text }) {
  const m = _captchaPending.get(jid);
  if (!m || !m.size || msg.key.fromMe) return false;
  const ids = [senderJid, msg.key.participant, msg.key.participantAlt].map(_gtDigits).filter(Boolean);
  const rec = [...m.values()].find(r => ids.some(d => r.digits.has(d)));
  if (!rec) return false;
  try { await sock.sendMessage(jid, { delete: msg.key }); } catch (_) {}   // nothing from unverified members stays in the chat
  const nums = String(text || '').match(/\d+/g);
  if (!nums) return true;                                                  // media / no number: just deleted, no penalty
  if (nums[nums.length - 1] === String(rec.answer)) {
    clearTimeout(rec.timer); m.delete(rec.key);
    try { await sock.sendMessage(jid, { text: `✅ @${_gtDigits(rec.jid)} verified — welcome!`, mentions: [rec.jid] }); } catch (_) {}
    try { if (rec.onVerified) await rec.onVerified(rec.p); } catch (e) { console.error('[captcha welcome]', e.message); }
    return true;
  }
  rec.tries++;
  if (rec.tries >= CAPTCHA_MAX_TRIES) { await captchaFail(sock, jid, rec, 'tries'); return true; }
  try { await sock.sendMessage(jid, { text: `❌ Wrong answer @${_gtDigits(rec.jid)} — ${CAPTCHA_MAX_TRIES - rec.tries} ${CAPTCHA_MAX_TRIES - rec.tries === 1 ? 'try' : 'tries'} left.`, mentions: [rec.jid] }); } catch (_) {}
  return true;
}

// ── Auto lock / open ──────────────────────────────────────────────────────────
// "22:00", "2200", "10pm", "6am", "6:30 am" -> "HH:MM" (null if invalid)
function _schedTime(s) {
  s = String(s || '').trim().toLowerCase();
  let m = /^(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?$/.exec(s);
  if (!m) { const m2 = /^(\d{2})(\d{2})$/.exec(s); if (!m2) return null; m = [null, m2[1], m2[2], undefined]; }
  let h = +m[1]; const mi = +(m[2] || 0); const ap = m[3];
  if (ap) { if (h < 1 || h > 12) return null; if (ap === 'pm' && h < 12) h += 12; if (ap === 'am' && h === 12) h = 0; }
  if (h > 23 || mi > 59) return null;
  return String(h).padStart(2, '0') + ':' + String(mi).padStart(2, '0');
}
function _schedMins(hhmm) { const [h, m] = String(hhmm).split(':').map(Number); return h * 60 + m; }
const _SCHED_OFFSET_RE = /^(?:utc|gmt)?\s*([+-])(\d{1,2})(?::?(\d{2}))?$/i;
function _schedTzOk(tz) {
  if (_SCHED_OFFSET_RE.test(String(tz || '').trim())) return true;
  try { new Intl.DateTimeFormat('en-GB', { timeZone: tz }); return true; } catch (_) { return false; }
}
// current local minutes-since-midnight in a timezone (IANA name like Africa/Lagos, or an offset like +1 / UTC-5)
function _schedNowMins(tz) {
  tz = String(tz || SCHED_TZ_DEFAULT).trim();
  const now = new Date();
  const m = _SCHED_OFFSET_RE.exec(tz);
  if (m) {
    const off = (m[1] === '-' ? -1 : 1) * (+m[2] * 60 + +(m[3] || 0));
    return (((now.getUTCHours() * 60 + now.getUTCMinutes() + off) % 1440) + 1440) % 1440;
  }
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(now);
  return (+parts.find(x => x.type === 'hour').value % 24) * 60 + +parts.find(x => x.type === 'minute').value;
}
function _schedNowStr(tz) { const t = _schedNowMins(tz); return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0'); }
function _schedShouldBeClosed(closeStr, openStr, nowMin) {
  const c = _schedMins(closeStr), o = _schedMins(openStr);
  if (c === o) return false;
  return c < o ? (nowMin >= c && nowMin < o) : (nowMin >= c || nowMin < o);   // window may wrap past midnight
}
const _schedBackoff = new Map();
const _schedWarned = new Set();
async function schedApply(sock, jid, want, gs) {
  try {
    await sock.groupSettingUpdate(jid, want === 'closed' ? 'announcement' : 'not_announcement');
  } catch (e) {
    _schedBackoff.set(jid, Date.now() + 10 * 60000);
    console.error('[autolock] cannot change', jid, e.message);
    if (!_schedWarned.has(jid)) {
      _schedWarned.add(jid);
      try { await sock.sendMessage(jid, { text: '⚠️ I could not run the scheduled lock/open — please make me a group admin.' }); } catch (_) {}
    }
    return false;
  }
  _schedWarned.delete(jid);
  setGroupSetting(jid, 'sched_state', want);
  setGroupSetting(jid, 'locked', want === 'closed' ? 1 : 0);
  gtWaMetaInvalidate(jid);
  const text = want === 'closed'
    ? `🌙 *Group closed for the night*\nOnly admins can send messages until *${gs.sched_open}*. Sleep well! 😴`
    : `☀️ *Good morning!* The group is now open — everyone can send messages.\n🌙 It closes again at *${gs.sched_close}*.`;
  try { await sock.sendMessage(jid, { text }); } catch (_) {}
  return true;
}
async function _schedFindSock(gs) {
  const s = sessions.get(gs.sched_session);
  if (s && s.connected && s.sock) return s.sock;
  for (const [, v] of sessions) {                       // fallback: any connected session that is in this group
    if (!v || !v.connected || !v.sock) continue;
    try { await v.sock.groupMetadata(gs.group_id); return v.sock; } catch (_) {}
  }
  return null;
}
async function schedTick() {
  let rows;
  try { rows = db.prepare('SELECT * FROM group_settings WHERE sched_on=1').all(); } catch (_) { return; }
  for (const gs of rows) {
    try {
      const jid = gs.group_id;
      if (!/@g\.us$/.test(jid) || !gs.sched_close || !gs.sched_open) continue;
      const want = _schedShouldBeClosed(gs.sched_close, gs.sched_open, _schedNowMins(gs.sched_tz)) ? 'closed' : 'open';
      if (gs.sched_state === want) continue;
      if ((_schedBackoff.get(jid) || 0) > Date.now()) continue;
      const sock = await _schedFindSock(gs);
      if (!sock) continue;                              // session offline — retried on the next tick
      await schedApply(sock, jid, want, gs);
    } catch (e) { console.error('[autolock]', e.message); }
  }
}
setInterval(() => { schedTick().catch(() => {}); }, 30000).unref();

// ── Welcome card (image with profile photo + name) ────────────────────────────
let _jimpMod;
function _getJimp() {
  if (_jimpMod === undefined) {
    try { _jimpMod = require(path.resolve('./card-lib/node_modules/jimp')); }
    catch (_) { try { _jimpMod = require('jimp'); } catch (e) { _jimpMod = null; console.error('[welcome card] jimp not available:', e.message); } }
  }
  return _jimpMod;
}
const _latinOnly = s => String(s || '').replace(/[^\x20-\x7E\u00A0-\u00FF]/g, '').replace(/\s+/g, ' ').trim();
const _clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
let _cardFonts = null;
function welcomeCardName(groupJid, p) {
  const d = _gtDigits(p.phoneNumber || p.jid || p.id);
  try {
    for (const k of ['wa_' + d, d]) {
      const r = db.prepare('SELECT name FROM group_activity WHERE group_id=? AND user_id=?').get(groupJid, k);
      if (r && r.name) return r.name;
    }
  } catch (_) {}
  return '+' + d;
}
async function buildWelcomeCard({ avatar, name, group, count }) {
  const Jimp = _getJimp();
  if (!Jimp) return null;
  if (!_cardFonts) {
    _cardFonts = {
      big: await Jimp.loadFont(Jimp.FONT_SANS_64_WHITE),
      mid: await Jimp.loadFont(Jimp.FONT_SANS_32_WHITE),
    };
  }
  const W = 900, H = 400, AV = 220;
  const card = new Jimp(W, H, 0x0f172aff);
  card.scan(0, 0, W, H, function (x, y, idx) {          // navy -> purple diagonal gradient
    const t = (x / W) * 0.6 + (y / H) * 0.4;
    this.bitmap.data[idx] = Math.round(15 + 61 * t);
    this.bitmap.data[idx + 1] = Math.round(23 + 6 * t);
    this.bitmap.data[idx + 2] = Math.round(42 + 107 * t);
    this.bitmap.data[idx + 3] = 255;
  });
  const cleanName = _latinOnly(name) || 'New member';
  // avatar (or a coloured circle with the first letter when the member has no / hidden photo)
  let av = null;
  if (avatar) { try { av = (await Jimp.read(avatar)).cover(AV, AV); } catch (_) { av = null; } }
  if (!av) {
    av = new Jimp(AV, AV, 0x6d28d9ff);
    av.print(_cardFonts.big, 0, 0, { text: (cleanName.replace(/^\+/, '')[0] || '?').toUpperCase(), alignmentX: Jimp.HORIZONTAL_ALIGN_CENTER, alignmentY: Jimp.VERTICAL_ALIGN_MIDDLE }, AV, AV);
  }
  av.circle();
  const ring = new Jimp(AV + 16, AV + 16, 0xfbbf24ff); ring.circle();
  card.composite(ring, 60, 82);
  card.composite(av, 68, 90);
  card.print(_cardFonts.big, 340, 50, 'WELCOME', 540);
  card.composite(new Jimp(240, 5, 0xfbbf24ff), 340, 132);
  const nm = _clip(cleanName, 26);
  card.print(nm.length > 12 ? _cardFonts.mid : _cardFonts.big, 340, nm.length > 12 ? 160 : 148, nm, 540);
  const grp = _clip(_latinOnly(group) || 'the group', 28);
  card.print(_cardFonts.mid, 340, 245, 'to ' + grp, 540);
  if (count) card.print(_cardFonts.mid, 340, 300, 'Member #' + count, 540);
  return await card.quality(90).getBufferAsync(Jimp.MIME_JPEG);
}

const GT_WA_CMDS = new Set(['.tagadmins', '.calladmins', '.setname', '.setdesc', '.link', '.revoke', '.admins', '.hidetag', '.del', '.delete',
  '.badword', '.warnlimit', '.unwarn', '.warnings', '.clearwarns', '.mutelist', '.unban', '.gstats', '.gtop',
  '.settings', '.leavegroup', '.captcha', '.autolock', '.welcomecard']);

async function gtWaCommand(env) {
  const { sock, jid, replyJid, msg, msgKey, cmdWord, args, mentions, quoted, userId, senderJid } = env;
  const send = (text, mentionJids) => humanReplyWA(sock, replyJid, text, { mentionJids, msgKey, quotedMsg: msg });
  let meta;
  try { meta = await gtWaMeta(sock, jid, true); }
  catch (e) { await send(`❌ couldn't read group info: ${gtErr(e)}`); return true; }
  const isAdmin = isGroupMod(userId) || gtWaIsAdmin(meta, senderJid);
  const botAdmin = gtWaBotIsAdmin(sock, meta);
  const adminOnly = async () => { if (isAdmin) return false; await send('❌ admins/sudo only.'); return true; };
  const target = (mentions && mentions[0]) || quoted || null;
  const typedNum = (args.find(a => /^\+?\d{7,15}$/.test(a)) || '').replace(/\D/g, '');
  const keyFor = () => (target ? gtWaKey(meta, target) : (typedNum ? 'wa_' + typedNum : null));
  const label = (key) => '@' + String(key).replace('wa_', '');

  try {
    switch (cmdWord) {
      case '.captcha': {
        const s0 = getGroupSettings(jid);
        const sub = (args[0] || '').toLowerCase();
        if (!sub || sub === 'status') {
          await send(`🛡️ JOIN CAPTCHA\n\nStatus: ${gtOnOff(s0.captcha_on)}\n⏳ Time limit: ${s0.captcha_mins || 2} min · ${CAPTCHA_MAX_TRIES} tries\n\n.captcha on / off\n.captcha time <1-30>  (minutes to answer)\n\nNew members must answer a quick maths question or they are removed. I must be a group admin.`);
          return true;
        }
        if (await adminOnly()) return true;
        if (sub === 'on') {
          if (!botAdmin) { await send('❌ Make me a group admin first, then run .captcha on again.'); return true; }
          setGroupSetting(jid, 'captcha_on', 1);
          await send(`🛡️ Join captcha is ON. New members have ${s0.captcha_mins || 2} min to answer, then they are removed.`); return true;
        }
        if (sub === 'off') { setGroupSetting(jid, 'captcha_on', 0); await send('🛡️ Join captcha turned off.'); return true; }
        if (sub === 'time') {
          const n = parseInt(args[1], 10);
          if (!n || n < 1 || n > 30) { await send('😒 .captcha time <1-30>  (minutes)'); return true; }
          setGroupSetting(jid, 'captcha_mins', n); await send(`⏳ Captcha time limit set to ${n} min.`); return true;
        }
        await send('😒 .captcha on / off / time <minutes>'); return true;
      }
      case '.welcomecard': {
        if (await adminOnly()) return true;
        const v = (args[0] || '').toLowerCase();
        if (!['on', 'off'].includes(v)) { await send(`🖼️ Welcome card: ${gtOnOff(getGroupSettings(jid).welcomecard_on !== 0)}\n\n.welcomecard on/off — image card with the member's photo and name (needs .welcome on)`); return true; }
        setGroupSetting(jid, 'welcomecard_on', v === 'on' ? 1 : 0);
        await send(`🖼️ Welcome card turned ${v}.${getGroupSettings(jid).welcome_on ? '' : ' (Turn welcome messages on with .welcome on)'}`); return true;
      }
      case '.autolock': {
        const s0 = getGroupSettings(jid);
        const tzNow = s0.sched_tz || SCHED_TZ_DEFAULT;
        const usage = `🌙 AUTO LOCK / OPEN\n\n.autolock 22:00 06:00 — lock at 10pm, open at 6am\n.autolock 10pm 6am Africa/Lagos — with a timezone\n.autolock tz <zone> — change timezone (e.g. Africa/Lagos, Europe/London, +1)\n.autolock off — turn off\n\nDefault timezone: ${SCHED_TZ_DEFAULT}. I must be a group admin.`;
        const sub = (args[0] || '').toLowerCase();
        if (!sub || sub === 'status') {
          await send(s0.sched_on
            ? `🌙 AUTO LOCK / OPEN\n\nStatus: ✅ On\n🔒 Closes: ${s0.sched_close}\n🔓 Opens: ${s0.sched_open}\n🌍 Timezone: ${tzNow}\n⏰ Time there now: ${_schedNowStr(tzNow)}\n\n.autolock off — turn off\n.autolock tz <zone> — change timezone`
            : usage);
          return true;
        }
        if (await adminOnly()) return true;
        if (sub === 'off') {
          setGroupSetting(jid, 'sched_on', 0); setGroupSetting(jid, 'sched_state', '');
          await send('🌙 Auto lock turned off. The group stays as it is right now.'); return true;
        }
        if (sub === 'tz') {
          const z = args.slice(1).join(' ').trim();
          if (!z || !_schedTzOk(z)) { await send('😒 .autolock tz <zone> — e.g. Africa/Lagos, Europe/London, America/New_York or +1'); return true; }
          setGroupSetting(jid, 'sched_tz', z); setGroupSetting(jid, 'sched_state', '');
          await send(`🌍 Timezone set to ${z}. Time there now: ${_schedNowStr(z)}`); return true;
        }
        const close = _schedTime(args[0]), open = _schedTime(args[1]);
        if (!close || !open || close === open) { await send(usage); return true; }
        const tz = args.slice(2).join(' ').trim() || s0.sched_tz || SCHED_TZ_DEFAULT;
        if (!_schedTzOk(tz)) { await send('❌ Unknown timezone. Use something like Africa/Lagos, Europe/London or +1'); return true; }
        if (!botAdmin) { await send('❌ Make me a group admin first, then set the schedule again.'); return true; }
        const sessKey = ([...sessions].find(([, v]) => v && v.sock === sock) || [])[0] || '';
        setGroupSetting(jid, 'sched_close', close); setGroupSetting(jid, 'sched_open', open);
        setGroupSetting(jid, 'sched_tz', tz); setGroupSetting(jid, 'sched_session', sessKey);
        setGroupSetting(jid, 'sched_on', 1);
        const closedNow = _schedShouldBeClosed(close, open, _schedNowMins(tz));
        await send(`🌙 Auto lock is ON\n\n🔒 Closes: ${close}\n🔓 Opens: ${open}\n🌍 Timezone: ${tz} (it is ${_schedNowStr(tz)} there now)${closedNow ? '\n\nIt is inside the closed window, so I am locking the group now.' : ''}`);
        if (closedNow) {
          setGroupSetting(jid, 'sched_state', '');
          await schedApply(sock, jid, 'closed', { sched_open: open, sched_close: close });
        } else {
          setGroupSetting(jid, 'sched_state', 'open');   // already in the open window: change nothing now
        }
        return true;
      }
      case '.settings': await send(gtSettingsText(jid)); return true;
      case '.gstats': case '.gtop': await send(gtStatsText(jid)); return true;

      case '.setname': {
        if (await adminOnly()) return true;
        const t = args.join(' ').trim();
        if (!t) { await send('😒 .setname <new group name>'); return true; }
        await sock.groupUpdateSubject(jid, t.slice(0, 100));
        await send('✅ group name updated.'); return true;
      }
      case '.setdesc': {
        if (await adminOnly()) return true;
        const t = args.join(' ').trim();
        if (!t) { await send('😒 .setdesc <new group description>'); return true; }
        await sock.groupUpdateDescription(jid, t.slice(0, 2048));
        await send('✅ group description updated.'); return true;
      }
      case '.link': {
        if (await adminOnly()) return true;
        const code = await sock.groupInviteCode(jid);
        await send(`🔗 https://chat.whatsapp.com/${code}`); return true;
      }
      case '.revoke': {
        if (await adminOnly()) return true;
        const code = await sock.groupRevokeInvite(jid);
        await send(typeof code === 'string' && code ? `✅ old invite link revoked.\n🔗 New: https://chat.whatsapp.com/${code}` : '✅ old invite link revoked. Use .link for the new one.');
        return true;
      }
      case '.tagadmins': case '.calladmins': {
        const adm = meta.participants.filter(p => p.admin).map(p => p.id);
        if (!adm.length) { await send('😒 no admins found in this group.'); return true; }
        const note = args.join(' ').trim().slice(0, 300);
        await send(`🚨 *Admin call* from ${env.name || 'a member'}${note ? ':\n' + note : ''}\n\n${adm.map(j => '@' + String(j).split('@')[0].split(':')[0]).join(' ')}`, adm);
        return true;
      }
      case '.admins': {
        const admins = meta.participants.filter(p => p.admin);
        const lines = admins.map(p => `${p.admin === 'superadmin' ? '👑' : '⭐'} @${String(p.id).split('@')[0].split(':')[0]}`);
        await send(`👮 GROUP ADMINS (${admins.length})\n\n${lines.join('\n')}`, admins.map(p => p.id));
        return true;
      }
      case '.hidetag': {
        if (await adminOnly()) return true;
        const t = args.join(' ').trim() || '📢';
        await sock.sendMessage(jid, { text: t, mentions: meta.participants.map(p => p.id) });
        return true;
      }
      case '.del': case '.delete': {
        if (await adminOnly()) return true;
        const ci = msg.message && msg.message.extendedTextMessage && msg.message.extendedTextMessage.contextInfo;
        if (!ci || !ci.stanzaId) { await send('😒 reply to the message you want deleted with .del'); return true; }
        const pd = _gtDigits(ci.participant);
        const fromMe = !!pd && [_gtDigits(sock.user && sock.user.id), _gtDigits(sock.user && sock.user.lid)].includes(pd);
        if (!fromMe && !botAdmin) { await send('❌ make me a group admin first so I can delete other people\'s messages.'); return true; }
        await sock.sendMessage(jid, { delete: { remoteJid: jid, fromMe, id: ci.stanzaId, participant: ci.participant } });
        try { if (botAdmin) await sock.sendMessage(jid, { delete: msg.key }); } catch (_) {}
        return true;
      }
      case '.badword': {
        if (await adminOnly()) return true;
        const sub = (args[0] || '').toLowerCase();
        const words = args.slice(1).join(' ').split(',').map(w => w.trim()).filter(Boolean);
        if (sub === 'on' || sub === 'off') {
          setGroupSetting(jid, 'badword_on', sub === 'on' ? 1 : 0);
          const n = gtBadwordList(jid).length;
          await send(`🤬 Bad-word filter turned ${sub}.${sub === 'on' ? (n ? ` Watching ${n} word(s). Non-admins get the message deleted + a warning.` : '\n⚠️ The list is empty — add words with .badword add word1, word2') : ''}${sub === 'on' && !botAdmin ? '\n⚠️ I\'m not a group admin, so I can\'t delete messages yet.' : ''}`);
          return true;
        }
        if (sub === 'add') {
          if (!words.length) { await send('😒 .badword add word1, word2, a phrase'); return true; }
          const added = words.filter(w => gtBadwordAdd(jid, w));
          await send(`✅ Added ${added.length} word(s). Total: ${gtBadwordList(jid).length}. (Turn on with .badword on)`); return true;
        }
        if (sub === 'remove' || sub === 'del') {
          if (!words.length) { await send('😒 .badword remove <word>'); return true; }
          const gone = words.filter(w => gtBadwordRemove(jid, w));
          await send(gone.length ? `✅ Removed ${gone.length} word(s).` : '😒 none of those were on the list.'); return true;
        }
        if (sub === 'list' || !sub) {
          const l = gtBadwordList(jid);
          await send(`🤬 Bad-word filter: ${gtOnOff(getGroupSettings(jid).badword_on)}\n\n${l.length ? l.join(', ') : '(empty)'}\n\n.badword add|remove <words> · .badword on|off`); return true;
        }
        await send('😒 .badword on/off · add <words> · remove <words> · list'); return true;
      }
      case '.warnlimit': {
        if (await adminOnly()) return true;
        const n = parseInt(args[0], 10);
        if (!(n >= 1 && n <= 10)) { await send(`⚠️ Current warn limit: ${gtWarnLimit(jid)}\nChange it with .warnlimit <1-10>`); return true; }
        setGroupSetting(jid, 'warn_limit', n);
        await send(`⚠️ Members are now removed after ${n} warning(s).`); return true;
      }
      case '.warnings': {
        const key = keyFor() || ('wa_' + _gtDigits(senderJid));
        const rows = getWarnings(jid, key);
        await send(rows.length
          ? `⚠️ Warnings for ${label(key)} (${rows.length}/${gtWarnLimit(jid)}):\n` + rows.slice(0, 10).map((w, i) => `${i + 1}. ${w.reason || 'no reason'} — ${String(w.warned_at).slice(0, 10)}`).join('\n')
          : `✅ No warnings for ${label(key)}.`, [key.replace('wa_', '') + '@s.whatsapp.net']);
        return true;
      }
      case '.unwarn': {
        if (await adminOnly()) return true;
        const key = keyFor();
        if (!key) { await send('😒 .unwarn @user (or reply to them)'); return true; }
        const last = getWarnings(jid, key)[0];
        if (!last) { await send(`✅ ${label(key)} has no warnings.`); return true; }
        db.prepare('DELETE FROM warnings WHERE id=?').run(last.id);
        await send(`✅ Removed one warning from ${label(key)}. Now ${getWarnings(jid, key).length}/${gtWarnLimit(jid)}.`); return true;
      }
      case '.clearwarns': {
        if (await adminOnly()) return true;
        const key = keyFor();
        if (!key) { await send('😒 .clearwarns @user (or reply to them)'); return true; }
        clearWarnings(jid, key);
        await send(`✅ Warnings cleared for ${label(key)}.`); return true;
      }
      case '.mutelist': {
        if (await adminOnly()) return true;
        const rows = gtMuteList(jid);
        await send(rows.length
          ? `🔇 MUTED (${rows.length})\n\n` + rows.map(r => `• ${label(r.user_id)} — ${r.until ? gtFmtDuration(Number(r.until) - Date.now()) + ' left' : 'until unmuted'}`).join('\n')
          : '🔊 Nobody is muted.'); return true;
      }
      case '.unban': {
        if (await adminOnly()) return true;
        const key = keyFor();
        if (!key) { await send('😒 .unban <number> (or @user)'); return true; }
        const was = gtIsBanned(jid, key);
        gtBanRemove(jid, key);
        await send(was ? `✅ ${label(key)} is no longer banned. They can be added or rejoin.` : `😒 ${label(key)} wasn't on the ban list.`); return true;
      }
      case '.leavegroup': {
        if (!isOwner(userId) && !msg.key.fromMe) { await send('❌ owner only.'); return true; }
        await send('👋 leaving this group. bye.');
        await sleep(1500);
        await sock.groupLeave(jid); return true;
      }
    }
  } catch (e) {
    await send(`❌ ${gtErr(e)}`);
    return true;
  }
  return false;
}

// ── Telegram helpers ──────────────────────────────────────────────────────────
// callApi keeps the payload shape identical across Telegraf versions.
function gtTgBan(ctx, userId, untilSec) {
  const p = { chat_id: ctx.chat.id, user_id: userId };
  if (untilSec) p.until_date = untilSec;
  return ctx.telegram.callApi('banChatMember', p);
}
function gtTgKick(ctx, userId) { return gtTgBan(ctx, userId, Math.floor(Date.now() / 1000) + 40); }
async function gtTgIsAdmin(ctx, uid) {
  try { const m = await ctx.telegram.getChatMember(ctx.chat.id, uid); return ['administrator', 'creator'].includes(m.status); }
  catch (_) { return false; }
}
// Resolve target from reply, text_mention, or @username the bot has seen. Returns {id,name} or {error}.
function gtTgTarget(ctx, text, chatId) {
  const rt = ctx.message.reply_to_message && ctx.message.reply_to_message.from;
  if (rt) return { id: rt.id, name: rt.first_name || String(rt.id) };
  const ent = (ctx.message.entities || []).find(e => e.type === 'mention' || e.type === 'text_mention');
  if (ent) {
    if (ent.user) return { id: ent.user.id, name: ent.user.first_name || String(ent.user.id) };
    const uname = text.substr(ent.offset + 1, ent.length - 1);
    const m = db.prepare('SELECT user_id, first_name FROM group_members WHERE group_id=? AND LOWER(username)=LOWER(?)').get(chatId, uname);
    if (m) return { id: m.user_id, name: m.first_name || uname };
    return { error: `😒 @${uname} needs to send a message first so I can identify them, or reply directly to their message.` };
  }
  return null;
}

// Runs on every group text message. Returns true if the message was removed / consumed.
async function gtTgGate(ctx, env) {
  const { chatId, userId, text } = env;
  if (!ctx.from || ctx.from.is_bot || ctx.message.sender_chat) return false;
  gtTrack(chatId, String(ctx.from.id), ctx.from.first_name || ctx.from.username || '');
  if (isSudo(userId)) return false;
  const gs = getGroupSettings(chatId);
  const flooding = !!gs.antiflood_on && gtFloodHit(chatId, String(ctx.from.id));
  const badWord = gs.badword_on && text ? gtHasBadword(chatId, text) : null;
  if (!flooding && !badWord) return false;
  if (await gtTgIsAdmin(ctx, ctx.from.id)) return false;
  try { await ctx.telegram.deleteMessage(ctx.chat.id, ctx.message.message_id); } catch (_) {}
  const st = gtStrike(chatId, String(ctx.from.id), badWord ? 'banned word' : 'flooding');
  const who = ctx.from.username ? '@' + ctx.from.username : (ctx.from.first_name || 'member');
  try {
    await ctx.telegram.sendMessage(ctx.chat.id, `⚠️ ${who} ${badWord ? 'that word is not allowed here' : 'slow down, no flooding'}. (Warning ${st.count}/${st.limit})`);
    if (st.kick) {
      await gtTgKick(ctx, ctx.from.id);
      clearWarnings(chatId, String(ctx.from.id));
      await ctx.telegram.sendMessage(ctx.chat.id, `🚫 ${who} was removed after ${st.limit} warnings.`);
    }
  } catch (_) {}
  return true;
}

const GT_TG_CMDS = new Set(['.setname', '.setdesc', '.link', '.revoke', '.admins', '.del', '.delete', '.pin', '.unpin',
  '.badword', '.warnlimit', '.unwarn', '.warnings', '.clearwarns', '.mutelist', '.unban', '.gstats', '.gtop',
  '.settings', '.leavegroup']);

async function gtTgCommand(ctx, env) {
  const { chatId, userId, args, cmdWord, text } = env;
  const reply = (t) => humanReplyTG(ctx, t);
  let isAdmin = isSudo(userId);
  if (!isAdmin && ctx.from) isAdmin = await gtTgIsAdmin(ctx, ctx.from.id);
  const adminOnly = async () => { if (isAdmin) return false; await reply('❌ admins/sudo only.'); return true; };
  const tgt = gtTgTarget(ctx, text, chatId);
  const replyMsgId = ctx.message.reply_to_message && ctx.message.reply_to_message.message_id;

  try {
    switch (cmdWord) {
      case '.settings': await reply(gtSettingsText(chatId)); return true;
      case '.gstats': case '.gtop': await reply(gtStatsText(chatId)); return true;

      case '.setname': {
        if (await adminOnly()) return true;
        const t = args.join(' ').trim();
        if (!t) { await reply('😒 /setname <new group name>'); return true; }
        await ctx.telegram.setChatTitle(ctx.chat.id, t.slice(0, 128));
        return true;
      }
      case '.setdesc': {
        if (await adminOnly()) return true;
        const t = args.join(' ').trim();
        if (!t) { await reply('😒 /setdesc <new group description>'); return true; }
        await ctx.telegram.setChatDescription(ctx.chat.id, t.slice(0, 255));
        await reply('✅ group description updated.'); return true;
      }
      case '.link': {
        if (await adminOnly()) return true;
        const c = await ctx.telegram.getChat(ctx.chat.id);
        // exportChatInviteLink REVOKES the previous primary link, so reuse the existing one when there is one.
        const link = c.invite_link || await ctx.telegram.exportChatInviteLink(ctx.chat.id);
        await reply(`🔗 ${link}`); return true;
      }
      case '.revoke': {
        if (await adminOnly()) return true;
        const link = await ctx.telegram.exportChatInviteLink(ctx.chat.id);
        await reply(`✅ old invite link revoked.\n🔗 New: ${link}`); return true;
      }
      case '.admins': {
        const list = (await ctx.telegram.getChatAdministrators(ctx.chat.id)).filter(a => !a.user.is_bot);
        await reply(`👮 GROUP ADMINS (${list.length})\n\n` + list.map(a => `${a.status === 'creator' ? '👑' : '⭐'} ${a.user.username ? '@' + a.user.username : a.user.first_name}`).join('\n'));
        return true;
      }
      case '.del': case '.delete': {
        if (await adminOnly()) return true;
        if (!replyMsgId) { await reply('😒 reply to the message you want deleted with /del'); return true; }
        await ctx.telegram.deleteMessage(ctx.chat.id, replyMsgId);
        try { await ctx.telegram.deleteMessage(ctx.chat.id, ctx.message.message_id); } catch (_) {}
        return true;
      }
      case '.pin': {
        if (await adminOnly()) return true;
        if (!replyMsgId) { await reply('😒 reply to the message you want pinned with /pin'); return true; }
        await ctx.telegram.pinChatMessage(ctx.chat.id, replyMsgId);
        return true;
      }
      case '.unpin': {
        if (await adminOnly()) return true;
        if (replyMsgId) await ctx.telegram.unpinChatMessage(ctx.chat.id, replyMsgId);
        else await ctx.telegram.unpinChatMessage(ctx.chat.id);
        await reply('📌 unpinned.'); return true;
      }
      case '.badword': {
        if (await adminOnly()) return true;
        const sub = (args[0] || '').toLowerCase();
        const words = args.slice(1).join(' ').split(',').map(w => w.trim()).filter(Boolean);
        if (sub === 'on' || sub === 'off') {
          setGroupSetting(chatId, 'badword_on', sub === 'on' ? 1 : 0);
          const n = gtBadwordList(chatId).length;
          await reply(`🤬 Bad-word filter turned ${sub}.${sub === 'on' ? (n ? ` Watching ${n} word(s). Non-admins get the message deleted + a warning.` : '\n⚠️ The list is empty — add words with /badword add word1, word2') : ''}`);
          return true;
        }
        if (sub === 'add') {
          if (!words.length) { await reply('😒 /badword add word1, word2, a phrase'); return true; }
          const added = words.filter(w => gtBadwordAdd(chatId, w));
          await reply(`✅ Added ${added.length} word(s). Total: ${gtBadwordList(chatId).length}. (Turn on with /badword on)`); return true;
        }
        if (sub === 'remove' || sub === 'del') {
          if (!words.length) { await reply('😒 /badword remove <word>'); return true; }
          const gone = words.filter(w => gtBadwordRemove(chatId, w));
          await reply(gone.length ? `✅ Removed ${gone.length} word(s).` : '😒 none of those were on the list.'); return true;
        }
        if (sub === 'list' || !sub) {
          const l = gtBadwordList(chatId);
          await reply(`🤬 Bad-word filter: ${gtOnOff(getGroupSettings(chatId).badword_on)}\n\n${l.length ? l.join(', ') : '(empty)'}\n\n/badword add|remove <words> · /badword on|off`); return true;
        }
        await reply('😒 /badword on/off · add <words> · remove <words> · list'); return true;
      }
      case '.warnlimit': {
        if (await adminOnly()) return true;
        const n = parseInt(args[0], 10);
        if (!(n >= 1 && n <= 10)) { await reply(`⚠️ Current warn limit: ${gtWarnLimit(chatId)}\nChange it with /warnlimit <1-10>`); return true; }
        setGroupSetting(chatId, 'warn_limit', n);
        await reply(`⚠️ Members are now removed after ${n} warning(s).`); return true;
      }
      case '.warnings': case '.unwarn': case '.clearwarns': case '.unban': {
        const needsAdmin = cmdWord !== '.warnings';
        if (needsAdmin && await adminOnly()) return true;
        if (tgt && tgt.error) { await reply(tgt.error); return true; }
        if (!tgt && cmdWord !== '.warnings') { await reply(`😒 Reply to the user's message, or mention them (e.g. /${cmdWord.slice(1)} @username).`); return true; }
        const id = tgt ? tgt.id : ctx.from.id;
        const nm = tgt ? tgt.name : (ctx.from.first_name || 'you');
        const key = String(id);
        if (cmdWord === '.warnings') {
          const rows = getWarnings(chatId, key);
          await reply(rows.length
            ? `⚠️ Warnings for ${nm} (${rows.length}/${gtWarnLimit(chatId)}):\n` + rows.slice(0, 10).map((w, i) => `${i + 1}. ${w.reason || 'no reason'} — ${String(w.warned_at).slice(0, 10)}`).join('\n')
            : `✅ No warnings for ${nm}.`);
        } else if (cmdWord === '.unwarn') {
          const last = getWarnings(chatId, key)[0];
          if (!last) { await reply(`✅ ${nm} has no warnings.`); return true; }
          db.prepare('DELETE FROM warnings WHERE id=?').run(last.id);
          await reply(`✅ Removed one warning from ${nm}. Now ${getWarnings(chatId, key).length}/${gtWarnLimit(chatId)}.`);
        } else if (cmdWord === '.clearwarns') {
          clearWarnings(chatId, key);
          await reply(`✅ Warnings cleared for ${nm}.`);
        } else { // .unban
          await ctx.telegram.callApi('unbanChatMember', { chat_id: ctx.chat.id, user_id: id, only_if_banned: true });
          await reply(`✅ ${nm} has been unbanned and can rejoin.`);
        }
        return true;
      }
      case '.mutelist': {
        if (await adminOnly()) return true;
        const rows = gtMuteList(chatId);
        await reply(rows.length
          ? `🔇 MUTED (${rows.length})\n\n` + rows.map(r => `• ${r.name || r.user_id} — ${r.until ? gtFmtDuration(Number(r.until) - Date.now()) + ' left' : 'until unmuted'}`).join('\n')
          : '🔊 Nobody is muted.'); return true;
      }
      case '.leavegroup': {
        if (!isOwner(userId)) { await reply('❌ owner only.'); return true; }
        await reply('👋 leaving this group. bye.');
        await sleep(1000);
        await ctx.telegram.leaveChat(ctx.chat.id); return true;
      }
    }
  } catch (e) {
    await reply(`❌ ${gtErr(e)}`);
    return true;
  }
  return false;
}

// ── Owner tools that work from any chat (need a linked WhatsApp session) ─────
async function gtOwnerWaCommand(cmd, args, waSockInfo) {
  if (!waSockInfo || !waSockInfo.sock) return '❌ No WhatsApp session active.';
  const sock = waSockInfo.sock;
  if (cmd === '.groups') {
    const all = Object.values(await sock.groupFetchAllParticipating());
    if (!all.length) return '📭 I am not in any WhatsApp groups.';
    all.sort((a, b) => (b.participants || []).length - (a.participants || []).length);
    return `👥 WHATSAPP GROUPS (${all.length})\n\n` + all.slice(0, 40).map((g, i) =>
      `${i + 1}. ${g.subject || 'unnamed'} — ${(g.participants || []).length} members${gtWaBotIsAdmin(sock, g) ? ' · 👮 admin' : ''}`).join('\n') +
      (all.length > 40 ? `\n…and ${all.length - 40} more` : '');
  }
  if (cmd === '.joingroup') {
    const m = /chat\.whatsapp\.com\/([A-Za-z0-9]{10,})/.exec(args.join(' '));
    if (!m) return '😒 .joingroup https://chat.whatsapp.com/XXXXXXXX';
    try { await sock.groupAcceptInvite(m[1]); return '✅ joined the group.'; }
    catch (e) { return `❌ couldn't join: ${gtErr(e)}`; }
  }
  return null;
}
