var $=function(i){return document.getElementById(i)},k='confession',tok=location.pathname.split('/')[2];
$('chips').addEventListener('click',function(e){var x=e.target.closest('.chip');if(!x)return;
 [].forEach.call(document.querySelectorAll('.chip'),function(c){c.classList.remove('on')});x.classList.add('on');k=x.dataset.k});
