function safeCalc(expr) {
  let e = String(expr).replace(/\s+/g, '').replace(/\^/g, '**').replace(/[x×]/g, '*').replace(/÷/g, '/').replace(/,/g, '');
  if (!e || e.length > 120) throw new Error('bad');
  if (!/^[0-9+\-*/%().a-z]+$/i.test(e)) throw new Error('bad');
  const allowed = new Set(['sqrt','abs','sin','cos','tan','log','ln','floor','ceil','round','pi','e','min','max','pow']);
  const words = e.match(/[a-z]+/gi) || [];
  for (const w of words) if (!allowed.has(w.toLowerCase())) throw new Error('bad');
  e = e.replace(/[a-z]+/gi, w => {
    w = w.toLowerCase();
    return w === 'ln' ? 'Math.log' : w === 'log' ? 'Math.log10' : w === 'pi' ? 'Math.PI' : w === 'e' ? 'Math.E' : 'Math.' + w;
  });
  const out = Function('"use strict";return (' + e + ')')();
  if (typeof out !== 'number' || !isFinite(out)) throw new Error('bad');
  return out;
}

const _CRYPTO_IDS = { btc:'bitcoin', eth:'ethereum', sol:'solana', bnb:'binancecoin', xrp:'ripple', doge:'dogecoin',
  ada:'cardano', usdt:'tether', ton:'the-open-network', trx:'tron', ltc:'litecoin', matic:'matic-network', dot:'polkadot', shib:'shiba-inu' };
const _TZ_ALIAS = { lagos:'Africa/Lagos', nigeria:'Africa/Lagos', abuja:'Africa/Lagos', accra:'Africa/Accra', nairobi:'Africa/Nairobi',
  cairo:'Africa/Cairo', johannesburg:'Africa/Johannesburg', london:'Europe/London', paris:'Europe/Paris', berlin:'Europe/Berlin',
  moscow:'Europe/Moscow', dubai:'Asia/Dubai', mumbai:'Asia/Kolkata', delhi:'Asia/Kolkata', india:'Asia/Kolkata', tokyo:'Asia/Tokyo',
  japan:'Asia/Tokyo', seoul:'Asia/Seoul', beijing:'Asia/Shanghai', shanghai:'Asia/Shanghai', singapore:'Asia/Singapore',
  sydney:'Australia/Sydney', 'new york':'America/New_York', ny:'America/New_York', chicago:'America/Chicago',
  'los angeles':'America/Los_Angeles', la:'America/Los_Angeles', toronto:'America/Toronto', 'sao paulo':'America/Sao_Paulo', utc:'UTC' };
let _fxCache = { at: 0, rates: null };

function parseDuration(s) {
  const m = String(s).toLowerCase().match(/^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/);
  if (!m || !s) return null;
  const ms = ((+m[1]||0)*86400 + (+m[2]||0)*3600 + (+m[3]||0)*60 + (+m[4]||0)) * 1000;
  return ms > 0 ? ms : null;
}
function fmtDur(ms) {
  const s = Math.round(ms/1000), d = Math.floor(s/86400), h = Math.floor(s%86400/3600), m = Math.floor(s%3600/60), sec = s%60;
  return [d&&d+'d', h&&h+'h', m&&m+'m', (sec&&!d&&!h)&&sec+'s'].filter(Boolean).join(' ') || '0s';
}

async function deliverReminder(r) {
  const text = `⏰ *REMINDER*\n${r.message}`;
  if (String(r.chat_id).includes('@')) {
    for (const [, s] of sessions.entries()) {
      if (!s || !s.connected || !s.sock) continue;
      try { await s.sock.sendMessage(r.chat_id, { text }); return true; } catch (_) {}
    }
    return false;
  }
  try { await bot_tg.telegram.sendMessage(r.chat_id, text); return true; } catch (_) { return false; }
}
let _remBusy = false;
async function checkReminders() {
  if (_remBusy) return; _remBusy = true;
  try {
    const due = db.prepare('SELECT * FROM reminders WHERE fired=0 AND fire_at<=? ORDER BY fire_at ASC LIMIT 20').all(Date.now());
    for (const r of due) {
      db.prepare('UPDATE reminders SET fired=1 WHERE id=?').run(r.id);
      const ok = await deliverReminder(r);
      // couldn't send (session offline)? retry for up to 1h, then drop
      if (!ok && Date.now() - r.fire_at < 3600000) db.prepare('UPDATE reminders SET fired=0 WHERE id=?').run(r.id);
    }
  } catch (e) { console.error('[reminders]', e.message); }
  finally { _remBusy = false; }
}

async function handleUtilities(cmd, args, userId, name, chatId, rawText) {
  if (!UTIL_CMDS.has(cmd)) return null;
  const rest = args.join(' ').trim();
  try {
    if (['.utilmenu', '.utils', '.utilities'].includes(cmd)) return utilMenu();

    if (cmd === '.calc') {
      if (!rest) return '🧮 .calc <expression>\nex: .calc 12*(3+4)^2 · .calc sqrt(144)+5%3';
      try { const r = safeCalc(rest); return `🧮 ${rest}\n= *${Number.isInteger(r) ? r.toLocaleString() : +r.toPrecision(12)}*`; }
      catch (_) { return '😒 that isn\'t math i can read. use numbers, + - * / ^ % ( ) and sqrt/abs/round/floor/ceil/sin/cos/tan/log/ln/pi.'; }
    }

    if (cmd === '.weather') {
      if (!rest) return '🌤️ .weather <city>';
      const { data } = await axios.get(`https://wttr.in/${encodeURIComponent(rest)}?format=j1`, { timeout: 12000 });
      const c = data.current_condition?.[0]; const a = data.nearest_area?.[0];
      if (!c) return '😒 couldn\'t find that place.';
      const place = `${a?.areaName?.[0]?.value || rest}, ${a?.country?.[0]?.value || ''}`.replace(/, $/, '');
      const days = (data.weather || []).slice(0, 3).map((d, i) => `${['today','tmrw','+2d'][i]}: ${d.mintempC}°–${d.maxtempC}°C`).join(' · ');
      return `🌤️ *${place}*\n${c.weatherDesc?.[0]?.value || ''}\n🌡️ ${c.temp_C}°C (feels ${c.FeelsLikeC}°C)\n💧 humidity ${c.humidity}%  💨 ${c.windspeedKmph} km/h\n📅 ${days}`;
    }

    if (cmd === '.time') {
      const key = rest.toLowerCase();
      const fmtIn = (tz) => new Date().toLocaleString('en-GB', { timeZone: tz, weekday:'short', day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit', hour12:false });
      if (!rest) return `🕒 Lagos: ${fmtIn('Africa/Lagos')}\n🌍 UTC: ${fmtIn('UTC')}`;
      const tz = _TZ_ALIAS[key] || rest.replace(/\s+/g, '_');
      try { return `🕒 *${rest}* → ${fmtIn(tz)}`; }
      catch (_) { return '😒 unknown place. try a city like lagos/london/tokyo or a zone like Asia/Tokyo.'; }
    }

    if (cmd === '.translate' || cmd === '.tr') {
      const lang = args[0]; const text = args.slice(1).join(' ');
      if (!lang || !text) return '🌍 .translate <language> <text>\nex: .translate french good morning';
      const res = await groq.chat.completions.create({
        model: 'openai/gpt-oss-20b',
        messages: [{ role: 'user', content: `Translate the following text into ${lang}. Reply with ONLY the translation, nothing else.\n\n${text}` }],
        max_tokens: 400, temperature: 0.2,
      });
      const out = res.choices[0]?.message?.content?.trim();
      return out ? `🌍 *${lang}*\n${out}` : '😒 translation failed. try again.';
    }

    // ── One girlfriend, all in one ──
    if (['.gf', '.girlfriend', '.pickgf', '.character', '.characters'].includes(cmd)) {
      return isOwner(userId)
        ? `💕 There is only one girlfriend here, and she's all yours.\n\n${GF.introBf}`
        : `💕 I'm *${GF.name}*. There's only one of me, and I'm already taken. 😌`;
    }

    if (cmd === '.ask') {
      if (!rest) return '💕 .ask <question>';
      const res = await groq.chat.completions.create({
        model: 'openai/gpt-oss-20b',
        messages: [
          { role: 'system', content: personaPrompt(userId) + '\n\nThe person used the .ask command. Give the accurate, useful answer first, in under 120 words, in your own voice. Never mention being an AI or a bot.' },
          { role: 'user', content: rest },
        ],
        max_tokens: 350, temperature: 0.7,
      });
      return res.choices[0]?.message?.content?.trim() || '💕 ask me something, I want to help.';
    }

    if (cmd === '.define') {
      const w = args[0]; if (!w) return '📖 .define <word>';
      try {
        const { data } = await axios.get(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(w.toLowerCase())}`, { timeout: 12000 });
        const e = data[0];
        const lines = (e.meanings || []).slice(0, 3).map(m => `▸ _${m.partOfSpeech}_ — ${m.definitions?.[0]?.definition}`);
        return `📖 *${e.word}* ${e.phonetic || ''}\n${lines.join('\n')}`;
      } catch (err) { if (err.response?.status === 404) return `😒 no definition for "${w}".`; throw err; }
    }

    if (cmd === '.wiki') {
      if (!rest) return '📚 .wiki <topic>';
      try {
        const { data } = await axios.get(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(rest.replace(/\s+/g, '_'))}?redirect=true`, { timeout: 12000 });
        if (!data.extract) return `😒 nothing on "${rest}".`;
        const ex = data.extract.length > 600 ? data.extract.slice(0, 600).replace(/\s+\S*$/, '') + '…' : data.extract;
        return `📚 *${data.title}*\n${ex}\n\n🔗 ${data.content_urls?.desktop?.page || ''}`;
      } catch (err) { if (err.response?.status === 404) return `😒 nothing on "${rest}".`; throw err; }
    }

    if (cmd === '.crypto') {
      const q = (args[0] || 'btc').toLowerCase(); const id = _CRYPTO_IDS[q] || q;
      const { data } = await axios.get(`https://api.coingecko.com/api/v3/simple/price?ids=${encodeURIComponent(id)}&vs_currencies=usd,ngn&include_24hr_change=true`, { timeout: 12000 });
      const p = data[id]; if (!p) return `😒 unknown coin "${q}". try btc, eth, sol, bnb, xrp, doge…`;
      const ch = p.usd_24h_change; const arrow = ch >= 0 ? '📈' : '📉';
      return `🪙 *${id.toUpperCase()}*\n💵 $${p.usd.toLocaleString()}\n🇳🇬 ₦${Math.round(p.ngn).toLocaleString()}\n${arrow} 24h: ${ch >= 0 ? '+' : ''}${(ch||0).toFixed(2)}%`;
    }

    if (cmd === '.currency' || cmd === '.convert') {
      const amt = parseFloat(args[0]); const from = (args[1] || '').toUpperCase(); const to = (args[2] || '').toUpperCase();
      if (!amt || !from || !to) return '💱 .currency <amount> <from> <to>\nex: .currency 100 usd ngn';
      if (!_fxCache.rates || Date.now() - _fxCache.at > 3600000) {
        const { data } = await axios.get('https://open.er-api.com/v6/latest/USD', { timeout: 12000 });
        _fxCache = { at: Date.now(), rates: data.rates };
      }
      const R = _fxCache.rates;
      if (!R[from] || !R[to]) return '😒 unknown currency code.';
      const out = amt / R[from] * R[to];
      return `💱 ${amt.toLocaleString()} ${from} = *${out.toLocaleString(undefined, { maximumFractionDigits: 2 })} ${to}*`;
    }

    if (cmd === '.password') {
      const len = Math.min(64, Math.max(8, parseInt(args[0]) || 16));
      const set = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*?';
      let pw = ''; for (let i = 0; i < len; i++) pw += set[_crypto.randomInt(0, set.length)];
      return `🔐 \`${pw}\`\n⚠️ don't reuse this if you generated it in a group chat.`;
    }


    if (cmd === '.shorten') {
      if (!/^https?:\/\//i.test(rest)) return '🔗 .shorten <https://long-link>';
      const { data } = await axios.get(`https://is.gd/create.php?format=simple&url=${encodeURIComponent(rest)}`, { timeout: 12000 });
      return `🔗 ${String(data).trim()}`;
    }


    if (cmd === '.choose') {
      const opts = rest.split(/\s*[|,]\s*/).filter(Boolean);
      if (opts.length < 2) return '🤔 .choose pizza | rice | burger';
      return `🤔 i choose: *${opts[randomInt(0, opts.length - 1)]}*`;
    }

    // ── Reminders ──
    if (cmd === '.remind') {
      const ms = parseDuration((args[0] || '').toLowerCase()); const msg = args.slice(1).join(' ');
      if (!ms || !msg) return '⏰ .remind <time> <message>\nex: .remind 30m drink water · .remind 1h30m call mum · .remind 2d pay rent';
      if (ms < 10000) return '😒 minimum is 10 seconds.';
      if (ms > 90 * 86400000) return '😒 maximum is 90 days.';
      const active = db.prepare('SELECT COUNT(*) c FROM reminders WHERE user_id=? AND fired=0').get(userId).c;
      if (active >= 20) return '😒 you already have 20 pending reminders. .delremind some.';
      const id = db.prepare('INSERT INTO reminders (user_id, chat_id, message, fire_at) VALUES (?,?,?,?)').run(userId, String(chatId), msg.slice(0, 500), Date.now() + ms).lastInsertRowid;
      return `⏰ set for *${fmtDur(ms)}* from now.\n💬 "${msg.slice(0, 80)}"\nID #${id} — .delremind ${id} to cancel.`;
    }
    if (cmd === '.reminders') {
      const rows = db.prepare('SELECT id, message, fire_at FROM reminders WHERE user_id=? AND fired=0 ORDER BY fire_at ASC LIMIT 20').all(userId);
      if (!rows.length) return '⏰ no pending reminders.';
      return `⏰ *YOUR REMINDERS*\n` + rows.map(r => `#${r.id} — in ${fmtDur(Math.max(0, r.fire_at - Date.now()))}: ${r.message.slice(0, 50)}`).join('\n');
    }
    if (cmd === '.delremind') {
      const id = parseInt(args[0]); if (!id) return '⏰ .delremind <id>  (see .reminders)';
      const r = db.prepare('DELETE FROM reminders WHERE id=? AND user_id=? AND fired=0').run(id, userId);
      return r.changes ? `✅ reminder #${id} cancelled.` : '😒 no pending reminder with that ID.';
    }
  } catch (e) {
    console.error(`[util ${cmd}]`, e.message);
    return '😒 that failed — the service may be down or slow. try again in a moment.';
  }
  return null;
}

// ╔══════════════════════════════════════════════════════════════════════╗
// ║  MENU SKIN  +  VOICE  +  small extras                   ║
// ╚══════════════════════════════════════════════════════════════════════╝

// ── Bold Script (cursive) + small-caps fonts ────────────────────────────
// Bold Mathematical Script block is fully contiguous (no missing-codepoint
// exceptions like plain script has for B/E/F/H/I/O), so a straight offset works.
const _SCRIPT_UP = Array.from({ length: 26 }, (_, i) => String.fromCodePoint(0x1D4D0 + i));
const _SCRIPT_LO = Array.from({ length: 26 }, (_, i) => String.fromCodePoint(0x1D4EA + i));
const _SC_LO   = Array.from('ᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡxʏᴢ');

function scriptText(s) { return String(s); }
function smallCapsText(s) { return String(s); }
// "SHADOW REALM" -> "Shadow Realm"  ("KING'S" -> "King's"); real acronyms stay caps
const _SK_ACRONYMS = new Set(['XP','CE','AI','WA','TG','VIP','RCT','JJK','DM','ID','QR','PFP','TTS']);
function _titleCase(s) {
  return s.replace(/[A-Za-z]+(?:'[A-Za-z]+)*/g, w =>
    (w.length > 1 && w === w.toUpperCase() && !_SK_ACRONYMS.has(w)) ? w[0] + w.slice(1).toLowerCase() : w);
}
// Telegram button / heading label: script letters, emoji untouched
function skinButton(label) { return String(label); }

const _SK_RULE = '▬▬▬▬▬▬ ⛧ ▬▬▬▬▬▬';
// Words we must NOT restyle: links, `code`, <args>, [args], @mentions, command + its arguments, short ALLCAPS, numbers
const _SK_PROTECT = new RegExp(
  '(https?:\\/\\/\\S+|`[^`]*`|<[^>\\n]*>|\\[[^\\]\\n]*\\]|@\\w+' +
  '|\\b(?:ex:|e\\.g\\.).*$' +
  '|(?<![\\w])[.\\/][a-z0-9_]+(?:[ \\t]+[^—·\\n]*?)?(?=[ \\t]*(?:—|·|[ \\t]{2}|$))' +
  '|(?<![\\w])[.\\/][a-z0-9_]+' +
  '|\\b[A-Z]{2,4}\\b|\\b\\d+\\w*)|([A-Za-z]+)', 'gmu'
);

// Restyle any menu text: script headings, cursed bullets, small-caps descriptions.
// Commands stay plain ASCII so people can still copy/type them.
function skinMenu(raw) {
  if (typeof raw !== 'string') return raw;
  return botMenu(raw.trim());
  // eslint-disable-next-line no-unreachable
  const out = [];
  for (const line of raw.split('\n')) {
    if (line.startsWith('\u200B')) { out.push(line.slice(1)); continue; }   // pre-styled line
    let l = line.replace(/[\u{1D400}-\u{1D7FF}]/gu, c => c.normalize('NFKC')); // undo the old bold font
    const t = l.trim();
    if (!t) { out.push(''); continue; }

    // 1) pure border lines  ━━━━ ═══ ╔══╗ 💗 ━━ 💗
    const core = t.replace(/[\p{Extended_Pictographic}\uFE0F\u200D\s]/gu, '');
    if (core.length >= 3 && /^[═━─┄┅╔╗╚╝▬\-=~_┈]+$/u.test(core)) { out.push(_SK_RULE); continue; }

    // 2) boxed title  ║  💵  E C O N O M Y  ║
    let boxed = t.match(/^║(.*)║$/u);
    if (boxed) {
      let inner = boxed[1].trim();
      if (/(?:\b[A-Z] ){3,}[A-Z]\b/.test(inner)) inner = inner.split(/ {2,}/).map(w => w.replace(/ /g, '')).join(' ');
      out.push(`⟦ ${scriptText(_titleCase(inner))} ⟧`);
      continue;
    }

    // 3) whole-line bold headings   *TEXT*   /   🩸 *TEXT*   /   *TEXT* _(note)_
    const hd = l.match(/^\s*([^\p{L}*]*)\*([^*\n]+)\*(\s+_[^_\n]+_)?\s*$/u);
    if (hd && !/(^|\s)[.\/][a-z]/.test(hd[2])) {
      const lead = hd[1].trim() ? hd[1].trim() + ' ' : '';
      const note = hd[3] ? ' ' + smallCapsText(hd[3].trim()) : '';
      out.push(`${lead}⟦ ${scriptText(_titleCase(hd[2].trim()))} ⟧${note}`);
      continue;
    }

    // 4) shouting title lines with no command in them  (EMOJI MENU)
    const letters = (t.match(/[A-Za-z]/g) || []);
    if (letters.length >= 4 && !/(^|\s)[.\/][a-z]/.test(t) &&
        letters.filter(c => c === c.toUpperCase()).length / letters.length > 0.75) {
      out.push(scriptText(_titleCase(t)));
      continue;
    }

    // 5) normal lines: cursed bullet + small-caps descriptions
    l = l.replace(/^(\s*)[▸•]\s?/, '$1⛧ ');
    l = l.replace(_SK_PROTECT, (m, keep, word) => word ? smallCapsText(word) : m);
    out.push(l);
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n');
}

// ── VOICE (TTS → plain voice note) ─────
const VOICE_TAG = '__VOICE__';
const _voiceCooldown = new Map();          // userId -> last use (ms)

function _voiceClean(t) {
  return String(t || '')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/[*_~`>#|]/g, '')
    .replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 350);
}

async function _ttsMp3(text) {
  const gtts = require('google-tts-api');
  const parts = await gtts.getAllAudioBase64(text, { lang: 'en', slow: false, timeout: 20000, splitPunct: ',.?!;:' });
  return Buffer.concat(parts.map(p => Buffer.from(p.base64, 'base64')));
}

function _ffmpegBin() { try { return require('ffmpeg-static') || 'ffmpeg'; } catch (_) { return 'ffmpeg'; } }

// Tune these two numbers to taste: lower = deeper. (24000 = the TTS sample rate)
const _VOICE_MAIN_PITCH = 0.65;   // main voice — deeper than before
const _VOICE_LOW_PITCH  = 0.50;   // the second, lower "mouth" — more demonic
function _voiceFilter() {
  // plain voice: just normalise loudness, no pitch shift or echo
  return '[0:a]aresample=24000,loudnorm=I=-16:TP=-1.5:LRA=11,alimiter=limit=0.95';
}

function _ffmpegVoice(mp3) {
  return new Promise((resolve, reject) => {
    const args = ['-hide_banner', '-loglevel', 'error', '-i', 'pipe:0', '-filter_complex', _voiceFilter(),
                  '-c:a', 'libopus', '-b:a', '48k', '-ar', '48000', '-ac', '1', '-f', 'ogg', 'pipe:1'];
    const p = require('child_process').spawn(_ffmpegBin(), args);
    const chunks = []; let err = '';
    const killer = setTimeout(() => { try { p.kill('SIGKILL'); } catch (_) {} reject(new Error('ffmpeg timeout')); }, 30000);
    p.stdout.on('data', d => chunks.push(d));
    p.stderr.on('data', d => { err += d; });
    p.stdin.on('error', () => {});
    p.on('error', e => { clearTimeout(killer); reject(e); });
    p.on('close', code => {
      clearTimeout(killer);
      if (code === 0 && chunks.length) resolve(Buffer.concat(chunks));
      else reject(new Error('ffmpeg exit ' + code + ' ' + err.slice(0, 200)));
    });
    p.stdin.end(mp3);
  });
}

// text -> Buffer (ogg/opus voice note) or null
async function voiceSynth(text) {
  const clean = _voiceClean(text);
  if (!clean) return null;
  try {
    const mp3 = await _ttsMp3(clean);
    if (!mp3.length) return null;
    return await _ffmpegVoice(mp3);
  } catch (e) { console.error('[voice]', e.message); return null; }
}

async function sendVoiceWA(sock, jid, text, quoted, msgKey) {
  try {
    if (msgKey) { try { await sock.readMessages([msgKey]); } catch (_) {} }
    try { await sock.sendPresenceUpdate('recording', jid); } catch (_) {}
    const audio = await voiceSynth(text);
    try { await sock.sendPresenceUpdate('paused', jid); } catch (_) {}
    if (!audio) return false;
    await sock.sendMessage(jid, { audio, mimetype: 'audio/ogg; codecs=opus', ptt: true },
                           quoted && typeof quoted === 'object' ? { quoted } : {});
    return true;
  } catch (e) { console.error('[WA voice send]', e.message); return false; }
}

async function sendVoiceTG(ctx, text) {
  try {
    try { await ctx.sendChatAction('record_voice'); } catch (_) {}
    const audio = await voiceSynth(text);
    if (!audio) return false;
    await ctx.replyWithVoice({ source: audio }, { reply_to_message_id: ctx.message?.message_id });
    return true;
  } catch (e) { console.error('[TG voice send]', e.message); return false; }
}

// One voice note per user every 8s (ffmpeg is CPU-heavy)
function voiceRateLimited(userId) {
  const last = _voiceCooldown.get(userId) || 0;
  if (Date.now() - last < 8000) return true;
  _voiceCooldown.set(userId, Date.now());
  return false;
}

// ── New commands: .say .talk .sumup ──────────────────────────────
async function handleVoiceExtras(cmd, args, userId) {
  const rest = args.join(' ').trim();

  if (['.say', '.speak'].includes(cmd)) {
    if (!rest) return '🎙️ .say <text> — I will speak it in my voice.\nex: .say kneel before me';
    if (voiceRateLimited(userId)) return '🎙️ ...patience. one voice at a time.';
    return VOICE_TAG + rest;
  }

  if (['.talk', '.voiceask'].includes(cmd)) {
    if (!rest) return '🎙️ .talk <question> — I will answer out loud.\nex: .talk what is the meaning of power';
    if (voiceRateLimited(userId)) return '🎙️ ...patience. one voice at a time.';
    const ans = await chat(userId, rest);
    return VOICE_TAG + (ans || 'ask me something, I want to help.');
  }

  if (['.sing', '.karaoke', '.singnow'].includes(cmd)) {
    if (!rest) return '🎤 .sing <song name or topic>\nex: .sing Essence by Wizkid\nI will write a short verse and sing it. Hope you like it 🎶';
    if (voiceRateLimited(userId)) return '🎤 One moment. I am still recording the last one. 💕';
    // Ask the AI to write a short singable verse as she would actually sing it
    let verse = '';
    const _singSys = `You are ${gfChar(userId).name}, singing a short sweet song to the person you care about.
Write a SHORT, singable verse (8-12 lines max) inspired by the song or topic the user names.
Rules:
- Write actual singable lyrics, with melody cues like (verse:) or (chorus:) if helpful
- Warm, playful and romantic, in your own voice
- Write ORIGINAL words inspired by the song's mood and theme. Never copy the real lyrics
- End with one cute line, like a little giggle or a kiss-off
- Plain text only, no markdown, no asterisks. Just the words as they would be sung.`;
    for (const _m of ['openai/gpt-oss-20b', 'openai/gpt-oss-120b']) {
      try {
        const singRes = await Promise.race([
          groq.chat.completions.create({
            model: _m,
            messages: [{ role: 'system', content: _singSys }, { role: 'user', content: `Sing something inspired by: ${rest}` }],
            max_tokens: 300,
            temperature: 0.85,
          }),
          new Promise((_, r) => setTimeout(() => r(new Error('sing timeout')), 20000)),
        ]);
        verse = (singRes.choices[0]?.message?.content || '').trim();
        if (verse) break;
        console.warn(`[sing] ${_m} returned empty (finish_reason=${singRes.choices[0]?.finish_reason})`);
      } catch (e) {
        console.error(`[sing AI error] ${_m}:`, e.message);
      }
    }
    if (!verse) {
      // Last resort: the main chat pipeline has its own model fallback chain
      try { verse = ((await chat(userId, `[Write a short original singable verse (8 lines max, plain text, no markdown) inspired by the song or topic: "${rest}". Don't copy real lyrics. End with one cute line. Just the verse.]`)) || '').trim(); } catch (_) {}
      if (FALLBACKS.includes(verse)) verse = ''; // chat() returns a canned line when every model fails — don't sing that
    }
    if (!verse) return '🎤 my inspiration ran away. try again?';
    return VOICE_TAG + verse;
  }

  if (['.sumup', '.tldr'].includes(cmd)) {
    if (rest.length < 40) return '📜 .sumup <long text> — I will cut it down to the point.';
    const res = await groq.chat.completions.create({
      model: 'openai/gpt-oss-20b',
      messages: [
        { role: 'system', content: 'Summarise the text in 3 short bullet points, max 60 words total. Plain, dry, accurate. No preamble.' },
        { role: 'user', content: rest.slice(0, 6000) },
      ],
      max_tokens: 250, temperature: 0.3,
    });
    return '📜 ' + (res.choices[0]?.message?.content?.trim() || '...nothing worth keeping.');
  }
  return null;
}

// ── menu wrappers (every menu goes through the skin) ──
// ── Main menu in the boxed "┌▣ ◈ NAME MENU ◈" style: info header + every command grouped by menu ──
function _menuCommands(fn) {
  let txt = '';
  try { txt = String(fn() || ''); } catch (_) { return []; }
  const out = [];
  for (const m of txt.matchAll(/(?:^|\n)\s*(?:▸|•|-)\s*\*?\.([a-z][a-z0-9]{1,20})\b|·\s*\*?\.([a-z][a-z0-9]{1,20})\b/g)) {
    const c = m[1] || m[2]; if (c && !out.includes(c)) out.push(c);
  }
  return out;
}
function helpMenu() {
  const os = require('os');
  const t0 = process.hrtime.bigint();
  const sections = [
    ['AI & CHAT', null, ['ask', 'say', 'talk', 'sing', 'sumup', 'tldr']],
    ['OWNER MENU', null, ['sudo', 'unsudo', 'antibug', 'clearbug', 'botusers', 'broadcast', 'ping', 'botinfo', 'ownerinfo']],
    ['FUN MENU', null, ['games', 'smash', 'smashlist', 'smashclear', 'smashauto', 'anon', 'anonoff']],
    ['GROUP MENU', _raw_groupHelp], ['ADMIN MENU', _raw_adminMenu], ['ECONOMY MENU', _raw_economyMenu],
    ['STOCKS MENU', _raw_stocksMenu], ['GUILDS MENU', _raw_guildsMenu], ['GAMES MENU', _raw_newGamesMenu],
    ['DOWNLOAD MENU', _raw_downloadMenu], ['UTIL MENU', _raw_utilMenu], ['TOOLS MENU', _raw_toolsMenu],
    ['NOTES MENU', _raw_notesMenu], ['PERSONAL MENU', _raw_personalHelp], ['PREMIUM MENU', _raw_premiumMenu],
    ['EXTRAS MENU', _raw_extrasMenu],
  ];
  const seen = new Set(), built = [];
  for (const [title, fn, fixed] of sections) {
    const cmds = (fixed || _menuCommands(fn)).filter(c => !seen.has(c));
    cmds.forEach(c => seen.add(c));
    if (cmds.length) built.push({ title, cmds });
  }
  const total = seen.size;
  const ctx = _selfCtx.getStore() || {};
  const isWA = !!ctx.sess;
  const total_gb = Math.round(os.totalmem() / 1073741824);
  const used_mb = Math.round(process.memoryUsage().rss / 1048576);
  const pct = Math.max(1, Math.min(99, Math.round((1 - os.freemem() / os.totalmem()) * 100)));
  const bar = '█'.repeat(Math.round(pct / 10)) + '░'.repeat(10 - Math.round(pct / 10));
  const _e = process.env;
  let host = _e.BOT_HOST ? _e.BOT_HOST
    : _e.RENDER ? 'Render' : _e.RAILWAY_ENVIRONMENT || _e.RAILWAY_PROJECT_ID ? 'Railway' : _e.DYNO ? 'Heroku'
    : _e.KOYEB_APP_NAME ? 'Koyeb' : _e.FLY_APP_NAME ? 'Fly.io' : _e.REPL_ID ? 'Replit' : _e.CODESPACES ? 'Codespaces'
    : _e.P_SERVER_UUID || _e.PTERODACTYL ? 'Panel' : _e.VERCEL ? 'Vercel' : '';
  if (!host) {   // fall back to the machine name, but never show a random container id like 4337f870-6d8d-...
    const hn = String(os.hostname() || '');
    host = (!hn || /^[0-9a-f-]{12,}$/i.test(hn) || /^[0-9a-f]{8,}/i.test(hn) && /\d/.test(hn) && hn.length > 10) ? 'Cloud Server' : hn;
  }
  let mode = 'Public';
  try { if (ctx.sess && kvGet('private_' + ctx.sess) === '1') mode = 'Private'; } catch (_) {}
  const ms = (Number(process.hrtime.bigint() - t0) / 1e6).toFixed(4);
  const head = [
    `┌▣ ◈ ${BOT_NAME.toUpperCase()} ◈`,
    `│ OWNER : ${BOYFRIEND}`,
    `│ PREFIX : [ . ]`,
    `│ HOST : ${host}`,
    `│ COMMANDS : ${total}`,
    `│ MODE : ${mode}`,
    `│ SPEED : ${ms} ms`,
    `│ USAGE : ${used_mb} MB of ${total_gb} GB`,
    `│ RAM : [${bar}] ${pct}%`,
    `└▣`,
  ].join('\n');
  const render = (limit) => built.map(b => {
    const shown = limit ? b.cmds.slice(0, limit) : b.cmds;
    const more = limit && b.cmds.length > limit ? [`⏩ …and ${b.cmds.length - limit} more`] : [];
    return [`┌▣ ◈ ${b.title} ◈`, ...shown.map(c => `⏩ .${c.toUpperCase()}`), ...more, `└▣`].join('\n');
  }).join('\n\n');
  let body = render(0);
  // Telegram can't send more than ~4096 characters in one message
  if (!isWA && (head.length + body.length) > 3900) body = render(8);
  // Bug Bot hint — shown to all but content only revealed on .bugmenu
  const bugHint = `\n\n🐛 *Bug Bot:* Type *.bugmenu* for bug commands.\n_Subscribe via Telegram: t.me/${OWNER_TG}_`;
  return head + '\n\n' + body + (isWA ? bugHint : '\n\nUse .groupmenu, .economymenu, .downloadmenu … to see the full list for each.');
}
const economyMenu = (...a) => skinMenu(_raw_economyMenu(...a));
const groupHelp = (...a) => skinMenu(_raw_groupHelp(...a));
