// ── Force-Join / Forced Subscription ─────────────────────────────────────────
// Users must join ALL of these before using the bot.
const FORCE_JOIN_CHANNEL  = 'lordchandler133';                    // public channel @lordchandler133
const FORCE_JOIN_GROUP_LINK = 'https://t.me/+d2M8aG4YSpRjMzFk'; // private group invite link

// To VERIFY group membership (not just show the button) get the group's numeric
// chat ID by adding @username_to_id_bot to the group, then paste it here.
// Leave as '' to show the button without verifying.
const FORCE_JOIN_GROUP_ID = '-1004385754407';

async function checkForceJoin(ctx, next) {
  try {
    const userId = ctx.from?.id;
    if (!userId) return next();
    // Owner always bypasses
    if (isOwner(String(userId)) || isOwner('tg_' + (ctx.from?.username || ''))) return next();
    // The lock screen is only ever shown in the bot's private chat, never posted in groups
    if (ctx.chat && ctx.chat.type !== 'private') return next();

    const notJoined = [];

    // Check channel
    try {
      const m = await ctx.telegram.getChatMember('@' + FORCE_JOIN_CHANNEL, userId);
      if (['left', 'kicked'].includes(m.status))
        notJoined.push({ label: '✦  JOIN Channel', url: 'https://t.me/' + FORCE_JOIN_CHANNEL });
    } catch (e) {
      console.log('[ForceJoin] channel check error:', e.message);
      notJoined.push({ label: '✦  JOIN Channel', url: 'https://t.me/' + FORCE_JOIN_CHANNEL });
    }

    // Check group
    let groupOk = false;
    if (FORCE_JOIN_GROUP_ID) {
      try {
        const m = await ctx.telegram.getChatMember(FORCE_JOIN_GROUP_ID, userId);
        groupOk = !['left', 'kicked'].includes(m.status);
      } catch (e) { console.log('[ForceJoin] group check error:', e.message); }
    }
    if (!groupOk)
      notJoined.push({ label: '✦  JOIN Group', url: FORCE_JOIN_GROUP_LINK });

    console.log(`[ForceJoin] User ${userId} — not joined: ${notJoined.length ? notJoined.map(x => x.label).join(', ') : 'none (passed)'}`);

    if (!notJoined.length) return next();

    const buttons = notJoined.map(ch => ([{ text: ch.label, url: ch.url }]));
    buttons.push([{ text: '🔄  CHECK JOIN', callback_data: 'force_join_check' }]);

    await ctx.reply(
      '🔒 *ACCESS LOCKED*\n\nJoin all required channels/groups to continue.\n\n📡 STATUS\n└ 🔴 ACCESS PENDING\n\n🔒 PROTECTION\n└ FORCE JOIN ACTIVE\n\nJoin every link below, then press *CHECK JOIN*.',
      { parse_mode: 'Markdown', reply_markup: { inline_keyboard: buttons } }
    );
  } catch (e) {
    console.error('[ForceJoin middleware]', e.message);
    return next(); // fail open — bot keeps working even if Telegram is slow
  }
}

// Must be registered BEFORE bot_tg.start and all other handlers
bot_tg.use(checkForceJoin);

