// ── /pair — Noelia-style pairing panel with inline buttons ────────────
bot_tg.command('pair', async ctx => {
  if (String(process.env.PAIR_DISABLED || '').toLowerCase() === 'true') {
    return ctx.reply('⚙️ Pairing is temporarily under maintenance. Please try again later.', { reply_to_message_id: ctx.message.message_id });
  }
  const tgId = String(ctx.from.id);
  const _rawArg = (ctx.message.text||'').trim().split(/\s+/).slice(1).join(' ');
  const phone = _rawArg ? cleanPairPhone(_rawArg) : undefined;

  // If a number was passed directly (/pair 234xxx), skip the panel and pair immediately
  if (_rawArg) {
    const _prob = pairPhoneProblem(phone);
    if (_prob) return ctx.reply('❌ ' + _prob, {reply_to_message_id: ctx.message.message_id});
  }
  if (phone && phone.length >= 7) {
    // Block re-pair while a code is pending — entering the code takes a session that's mid-handshake
    const lock = _pairingLock.get(tgId);
    if (lock && Date.now() < lock.expiresAt) {
      const secsLeft = Math.ceil((lock.expiresAt - Date.now()) / 1000);
      return ctx.reply(
        `⏳ *A pairing code is still active* for +${lock.phone}\n\nEnter it in WhatsApp now, or wait ${secsLeft}s for it to expire before generating a new one.\n\nTo force a new code: /forcepair ${phone}`,
        {reply_to_message_id: ctx.message.message_id, parse_mode: 'Markdown'}
      );
    }
    const existing = sessions.get(tgId);
    if (existing?.sock) { try { existing.sock.end(); } catch(_){} sessions.delete(tgId); }
    // Set lock for 3 minutes (WhatsApp code expiry window)
    _pairingLock.set(tgId, { phone, expiresAt: Date.now() + 3 * 60 * 1000 });
    await ctx.reply(`💗 Starting session for ${phone}...\n\nWait for pairing code.`, {reply_to_message_id: ctx.message.message_id});
    try { await createSession(tgId, phone, ctx.chat.id, ctx.message.message_id, { forceNew: true }); }
    catch(e) { ctx.reply(`❌ ${e.message}`); }
    return;
  }

  // No number given — show the panel
  const _panelBase = process.env.PUBLIC_URL || _tunnelUrl || kvGet('public_url') || '';
  const _panelWebLine = _panelBase
    ? `\n\n🌐 *Web Pair:* ${_panelBase}/pair`
    : '\n\n⚠️ _Web pair link not ready yet — wait 1-2 min after restart._';
  const _panelKeyboard = [
    [{text:'📱 pair number',   callback_data:'pair_number'},  {text:'🗑 remove pair',   callback_data:'pair_remove'}],
    [{text:'🐛 antibug pair',  callback_data:'pair_antibug'}, {text:'⚡ quick pair',    callback_data:'pair_quick'}],
    [{text:'📊 status',        callback_data:'pair_status'},  {text:'📋 list paired',   callback_data:'pair_list'}],
    [{text:'📁 list groups',   callback_data:'pair_groups'},  {text:'📂 all groups',    callback_data:'pair_allgroups'}],
    [{text:'🥄 submit report', callback_data:'pair_report'}],
  ];
  if (_panelBase) {
    _panelKeyboard.push([{text:'🌐 open web pair page', url: `${_panelBase}/pair`}]);
  }
  await ctx.reply(`💗 pairing panel — what do you need.${_panelWebLine}`, {
    reply_to_message_id: ctx.message.message_id,
    parse_mode: 'Markdown',
    reply_markup: { inline_keyboard: _panelKeyboard },
  });
});

