bot_tg.command('bugadd', async ctx => {
  if (!isOwner('tg_' + ctx.from?.id)) return ctx.reply('❌ Owner only.');
  const parts = ctx.message.text.split(/\s+/).slice(1);
  // /bugadd <number> weekly|monthly [note]
  const [numArg, tierArg, ...noteArr] = parts;
  const clean = _bugValidateNum(numArg);
  if (!clean) return ctx.reply('❌ Usage: /bugadd <number> weekly|monthly [note]\nExample: /bugadd 2348012345678 monthly VIP');
  const tier    = (tierArg || 'weekly').toLowerCase() === 'monthly' ? 'monthly' : 'weekly';
  const expires = grantBugAccess(clean, tier, 'tg_' + ctx.from.id, noteArr.join(' '));
  const expDate = new Date(expires).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  // Notify the user on WhatsApp
  try {
    const _tgCtx2 = _selfCtx.getStore() || {};
    const _tgSock2 = _bugResolveSock(_tgCtx2, sessions);
    const bestSock = _tgSock2 || (() => { for (const [, s] of (sessions || new Map())) { if (s?.connected) return s.sock; } return null; })();
    if (bestSock) {
      await bestSock.sendMessage(`${clean}@s.whatsapp.net`, {
        text:
          `🐛 *Bug Bot Access Granted!*\n\n` +
          `✅ Plan: *${tier === 'monthly' ? '📅 Monthly' : '📆 Weekly'}*\n` +
          `📅 Expires: *${expDate}*\n\n` +
          `Type *.bugmenu* to see all commands.\n\n` +
          `_Welcome to the Bug Bot! 🔥_`,
      });
    }
  } catch (_) {}
  await ctx.reply(
    `✅ *Bug access granted!*\n\n📱 +${clean}\n🎟 Plan: *${tier}*\n📅 Expires: *${expDate}*`,
    { parse_mode: 'Markdown' }
  );
});

bot_tg.command('bugremove', async ctx => {
  if (!isOwner('tg_' + ctx.from?.id)) return ctx.reply('❌ Owner only.');
  const numArg = ctx.message.text.split(/\s+/)[1];
  const clean  = _bugValidateNum(numArg);
  if (!clean) return ctx.reply('❌ Usage: /bugremove <number>');
  const had = getBugAccessInfo(clean);
  if (!had) return ctx.reply(`⚠️ +${clean} doesn't have bug access.`);
  revokeBugAccess(clean);
  try {
    const _tgCtx3 = _selfCtx.getStore() || {};
    const _tgSock3 = _bugResolveSock(_tgCtx3, sessions);
    const bestSock = _tgSock3 || (() => { for (const [, s] of (sessions || new Map())) { if (s?.connected) return s.sock; } return null; })();
    if (bestSock) {
      await bestSock.sendMessage(`${clean}@s.whatsapp.net`, {
        text: `🐛 *Bug Bot Access Revoked*\n\nYour subscription has ended.\nContact the owner to renew.`,
      });
    }
  } catch (_) {}
  await ctx.reply(`✅ Bug access removed for *+${clean}*.`, { parse_mode: 'Markdown' });
});

bot_tg.command('bugusers', async ctx => {
  if (!isOwner('tg_' + ctx.from?.id)) return ctx.reply('❌ Owner only.');
  const users = listBugAccessUsers();
  if (!users.length) return ctx.reply('📋 No bug access users yet.\n\nUse /bugadd <number> weekly|monthly to add one.');
  const now = Date.now();
  const lines = users.map(u => {
    const active  = u.expires_at === 0 || now < u.expires_at;
    const expStr  = u.expires_at === 0 ? 'Lifetime' : new Date(u.expires_at).toLocaleDateString('en-GB');
    const timeLeft = u.expires_at === 0 ? '∞' : active
      ? `${Math.ceil((u.expires_at - now) / (24 * 3600 * 1000))}d left`
      : 'EXPIRED';
    return `${active ? '✅' : '❌'} +${u.id} — ${u.tier} — ${expStr} (${timeLeft})`;
  });
  const active = users.filter(u => u.expires_at === 0 || now < u.expires_at).length;
  await ctx.reply(
    `🐛 *Bug Bot Subscribers*\n\n${lines.join('\n')}\n\n` +
    `Total: ${users.length} | Active: ${active} | Expired: ${users.length - active}`,
    { parse_mode: 'Markdown' }
  );
});

bot_tg.command('bugextend', async ctx => {
  if (!isOwner('tg_' + ctx.from?.id)) return ctx.reply('❌ Owner only.');
  const parts  = ctx.message.text.split(/\s+/).slice(1);
  const clean  = _bugValidateNum(parts[0]);
  if (!clean) return ctx.reply('❌ Usage: /bugextend <number> weekly|monthly');
  const tier   = (parts[1] || 'weekly').toLowerCase() === 'monthly' ? 'monthly' : 'weekly';
  const expires = grantBugAccess(clean, tier, 'tg_' + ctx.from.id);
  const expDate = new Date(expires).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  await ctx.reply(`✅ Extended! +${clean} — ${tier} — expires: *${expDate}*`, { parse_mode: 'Markdown' });
});

