const _tgStickerCool = new Map();
bot_tg.on('sticker', async ctx => {
  try {
    const st = ctx.message.sticker;
    const isGroup = ctx.chat.type === 'group' || ctx.chat.type === 'supergroup';
    if (!st.is_animated && !st.is_video && _botSet.autosticker) {            // collect it for later (only when auto-collect is on)
      try { const fl = await ctx.telegram.getFileLink(st.file_id); const rs = await axios.get(fl.href, { responseType: 'arraybuffer' }); saveAutoSticker(Buffer.from(rs.data)); } catch (_) {}
    }
    if (isGroup && ctx.message.reply_to_message?.from?.username !== BOT_USERNAME) return;   // groups: only when replying to her
    const cid = String(ctx.chat.id);
    if (Date.now() - (_tgStickerCool.get(cid) || 0) < 4000) return;
    _tgStickerCool.set(cid, Date.now());
    const sp = getRandomStickerPath(true);
    if (!sp) return;
    await sleep(randomInt(1000, 2000));
    try { await ctx.sendChatAction('choose_sticker'); } catch (_) {}
    await sleep(randomInt(800, 1500));
    await ctx.replyWithSticker({ source: fs.readFileSync(sp) }, { reply_to_message_id: ctx.message.message_id });
  } catch (e) { console.error('[TG sticker]', e.message); }
});
bot_tg.hears(/^\.(font|autosticker|stickers|stickerpack|addsticker)(?:\s+(\S+))?\s*$/i, async ctx => {
  if ((ctx.from.username || '') !== OWNER_TG) return ctx.reply('Only my owner may change that.');
  const cmd = '.' + ctx.match[1].toLowerCase(), arg = ctx.match[2];
  try {
    if (cmd === '.stickerpack') {
      const name = String(arg || '').replace(/^.*addstickers\//, '');
      if (!/^[A-Za-z0-9_]{3,64}$/.test(name)) return ctx.reply('Usage: .stickerpack <name>\nFrom a link: t.me/addstickers/NAME (picture and video packs).');
      const n = await botLoadPack(name);
      return ctx.reply(_packReport(n, name));
    }
    if (cmd === '.addsticker') {
      const st = ctx.message.reply_to_message?.sticker;
      if (!st) return ctx.reply('Reply to a sticker with .addsticker.');
      if (st.is_animated) return ctx.reply('Those animated (.tgs) stickers cannot be used. Picture and video stickers work.');
      const fl = await ctx.telegram.getFileLink(st.file_id); const rs = await axios.get(fl.href, { responseType: 'arraybuffer' });
      let _b = Buffer.from(rs.data);
      if (st.is_video) { _b = await webmToAnimatedWebp(_b); if (!_b) return ctx.reply('Could not convert that video sticker.'); }
      return ctx.reply(botAddStickerBuf(_b) ? 'Added.' : 'That one is not a usable sticker.');
    }
    const r = botSettingsCmd(cmd, arg);
    return ctx.reply(r || (cmd === '.stickers' ? botStickersStatus() : '💕 .font · .autosticker on/off · .stickers'));
  } catch (e) { return ctx.reply('Failed: ' + e.message); }
});

bot_tg.on('voice', async ctx => {
  try {
    const username=ctx.from.username||'';
    const rawUserId=username===OWNER_TG?'tg_'+OWNER_TG:ctx.from.id.toString();
    const userId=resolveId(rawUserId);
    const name=ctx.from.first_name||'someone';
    getUser(userId,name);

    // Group: only respond if the bot is tagged/mentioned or the voice note is a reply to the bot —
    // same rule as text messages, so it doesn't answer every voice note in a group.
    const isGroup=ctx.chat.type==='group'||ctx.chat.type==='supergroup';
    if (isGroup) {
      const caption=(ctx.message.caption||'').toLowerCase();
      const entities=ctx.message.caption_entities||[];
      const entMention=entities.some(e=>e.type==='mention'&&caption.substr(e.offset,e.length).toLowerCase()==='@'+BOT_USERNAME.toLowerCase());
      const textMention=caption.includes('@'+BOT_USERNAME.toLowerCase())||GF_NAME_RE.test(caption);
      const isReply=ctx.message.reply_to_message?.from?.username===BOT_USERNAME;
      if(!entMention && !textMention && !isReply) return;
    }

    // Always answer a voice note with a voice note back, and never echo the transcript text.
    try {
      const _fl = await ctx.telegram.getFileLink(ctx.message.voice.file_id);
      const _rs = await axios.get(_fl.href, {responseType:'arraybuffer'});
      const _tr = await transcribeAudio(Buffer.from(_rs.data), 'audio/ogg');
      if (!_tr) return humanReplyTG(ctx, '...i heard you but couldn\'t make out what you said.');
      const _rp = await chat(userId, _tr);
      if (await sendVoiceTG(ctx, _rp)) return;
      // Voice synthesis failed — fall back to plain text, still no transcript echo.
      return humanReplyTG(ctx, _rp);
    } catch(e) { console.error('[TG voice]', e.message); return humanReplyTG(ctx, '...couldn\'t process that voice note.'); }
  } catch(e){console.error('[TG voice handler]',e.message);}
});

