bot_tg.on('photo', async ctx => {
  try {
    const username=ctx.from.username||'';
    const rawUserId=username===OWNER_TG?'tg_'+OWNER_TG:ctx.from.id.toString();
    const userId=resolveId(rawUserId);
    const name=ctx.from.first_name||'someone';
    getUser(userId,name);
    const caption=(ctx.message.caption||'').trim();

    // .setpfp — owner saves this photo as her profile pic
    if(caption.toLowerCase()==='.setpfp' && (username===OWNER_TG || isOwner(rawUserId))){
      try{
        const photos=ctx.message.photo;
        const fileId=photos[photos.length-1].file_id;
        const fileLink=await ctx.telegram.getFileLink(fileId);
        const res=await axios.get(fileLink.href,{responseType:'arraybuffer'});
        fs.writeFileSync(BOT_PFP_PATH, Buffer.from(res.data));
        return ctx.reply("📸 done. that's my picture now.");
      }catch(e){ return ctx.reply(`❌ ${e.message}`); }
    }

    await humanReplyTG(ctx, async()=>{
      try {
        const photos=ctx.message.photo;
        const fileId=photos[photos.length-1].file_id;
        const fileLink=await ctx.telegram.getFileLink(fileId);
        const res=await axios.get(fileLink.href,{responseType:'arraybuffer'});
        const buf=Buffer.from(res.data);
        const reply=await analyseImage(buf,caption,name);
        return reply||'...i see it.';
      } catch(e){console.error('[TG photo]',e.message);return '...couldn\'t see that image.';}
    });
  } catch(e){console.error('[TG photo handler]',e.message);}
});





// ── Track members when they JOIN the group (so .tagall catches everyone) ────
bot_tg.on('message', async (ctx, next) => {
  try {
    const chatId = ctx.chat?.id?.toString();
    const joined = ctx.message?.new_chat_members;
    if (joined && Array.isArray(joined) && chatId) {
      const gs = getGroupSettings(chatId);
      for (const u of joined) {
        if (u.is_bot) continue;
        // Track member
        try {
          db.prepare('INSERT OR REPLACE INTO group_members (group_id,user_id,username,first_name) VALUES (?,?,?,?)')
            .run(chatId, u.id, u.username || '', u.first_name || '');
        } catch(_) {}
        // Send welcome message if enabled
        if (gs.welcome_on) {
          const name = u.username ? `@${u.username}` : (u.first_name || 'member');
          let _cnt = ''; try { _cnt = await ctx.telegram.getChatMembersCount(ctx.chat.id); } catch(_) {}
          const _lines = ["So happy you are here. Make yourself at home.","Welcome! Say hi, do not be shy.","A new face! Glad you joined us.","Welcome in. Tell us a little about yourself.","Come on in, we saved you a seat."];
          const welcomeText = gs.welcome_msg
            ? gs.welcome_msg.replace(/\{name\}/gi, name).replace(/\{group\}/gi, ctx.chat.title || 'the group').replace(/\{count\}/gi, String(_cnt))
            : `🌸 Welcome!\n\n${name}, you have joined ${ctx.chat.title || 'the group'}.\n${_cnt ? `You are member #${_cnt}. Glad you're here.\n` : ''}\n💬 ${_lines[Math.floor(Math.random()*_lines.length)]}\n\n💕 Glad to have you.`;
          try {
            // member profile photo (if their privacy allows), else plain text
            const _ph = await ctx.telegram.getUserProfilePhotos(u.id, 0, 1);
            const _fid = _ph?.photos?.[0]?.[_ph.photos[0].length - 1]?.file_id;
            if (_fid) await ctx.telegram.sendPhoto(ctx.chat.id, _fid, { caption: welcomeText.slice(0, 1000) });
            else await ctx.reply(welcomeText);
          } catch(_) { try { await ctx.reply(welcomeText); } catch(__) {} }
        }
      }
    }
    // Remove member + send goodbye when they leave
    const left = ctx.message?.left_chat_member;
    if (left && !left.is_bot && chatId) {
      try {
        db.prepare('DELETE FROM group_members WHERE group_id=? AND user_id=?')
          .run(chatId, left.id);
      } catch(_) {}
      const gs = getGroupSettings(chatId);
      if (gs.goodbye_on) {
        const name = left.username ? `@${left.username}` : (left.first_name || 'member');
        const goodbyeText = gs.goodbye_msg
          ? gs.goodbye_msg.replace(/\{name\}/gi, name).replace(/\{group\}/gi, ctx.chat.title || 'the group')
          : `👋 ${name} has left the group.\nTake care out there — you’ll be missed! 💔`;
        try { await ctx.reply(goodbyeText); } catch(_) {}
      }
    }
  } catch(_) {}
  return next();
});

bot_tg.on('message',async ctx=>{
  try {
    const text=ctx.message?.text||ctx.message?.caption||'';
    if(!text||!text.trim()) return;
    const isGroup=ctx.chat.type==='group'||ctx.chat.type==='supergroup';
    const username=ctx.from.username||'';
    const rawUserId=username===OWNER_TG?'tg_'+OWNER_TG:ctx.from.id.toString();
    const userId=resolveId(rawUserId); // paired accounts share one profile
    const name=ctx.from.first_name||'someone';
    const chatId=ctx.chat.id.toString();

    getUser(userId,name);
    if(username===OWNER_TG) { _learnOwnerTgId(ctx.from.id); ensureOwnerRich(userId,name); }

    // Telegram uses "/" prefix, plus "?" for the number scanner ("? 234...", "?scan 234...")
    const _isQ=/^\?(alive|check|scan)?(\s|$)/i.test(text.trim());
    const isCmd=text.startsWith('/') || _isQ;
    // "/kick@MyBot" (what Telegram's command menu inserts in groups) -> "/kick"
    const _cmdText = _isQ ? text.trim() : isCmd ? text.replace(new RegExp('^(/\\S+?)@'+BOT_USERNAME+'(?=\\s|$)','i'),'$1') : text;
    const cmdWord=_isQ?'?':isCmd?('.'+_cmdText.slice(1).split(/\s+/)[0].toLowerCase()):'';
    const args=_cmdText.trim().split(/\s+/).slice(1); // used by group admin commands below

    // ── /wafind follow-up — user sent a name/username/number to search ──
    const tgId = String(ctx.from.id);
    const wafindState = _wafindPending.get(tgId);
    if (wafindState?.waiting && !isCmd) {
      _wafindPending.delete(tgId);
      const query = text.replace('@','').trim();
      await ctx.reply(`💗 wa account search — "${query}" — searching...`, {reply_to_message_id:ctx.message.message_id});
      const sock = wafindState.sock;
      try {
        // Search by phone number directly
        if (/^\d{7,15}$/.test(query)) {
          const jid = query+'@s.whatsapp.net';
          const [result] = await sock.onWhatsApp(jid);
          if (result?.exists) {
            return ctx.reply(`💗 wa account search — "${query}"\n\n1. +${query} — exists on WhatsApp ✅\n\njid: ${result.jid}`);
          }
          return ctx.reply(`💗 no WhatsApp account found for +${query}`);
        }
        // Search by username — look through DB
        const db_data = db.prepare("SELECT * FROM users WHERE LOWER(name) LIKE LOWER(?) LIMIT 5").all('%'+query+'%');
        if (!db_data.length) return ctx.reply(`💗 no users found matching "${query}" in this bot's database.`);
        const lines = db_data.map((u,i)=>`${i+1}. ${u.name} — id: ${u.id}`);
        return ctx.reply(`💗 wa account search — "${query}"\n\n${lines.join('\n')}\n\nreply with a number (1–${lines.length}) to view.`);
      } catch(e) {
        return ctx.reply(`❌ search failed: ${e.message}`);
      }
    }



    // ── Telegram group admin commands ──────────────────────────────────
    if (isGroup) {
      // Track this member on EVERY message (not just commands) so .tagall works reliably
      try {
        db.prepare('INSERT OR REPLACE INTO group_members (group_id,user_id,username,first_name) VALUES (?,?,?,?)')
          .run(chatId, ctx.from.id, ctx.from.username||'', ctx.from.first_name||'');
        // If this user voted in a .scanmembers poll, clear their pending entry
        try { db.prepare('DELETE FROM scan_voters WHERE user_id=?').run(ctx.from.id); } catch(_){}
      } catch(_){}

      // ── Group moderation gate: anti-flood / bad-word filter / activity stats ──
      try { if (await gtTgGate(ctx, { chatId, userId, text })) return; } catch (e) { console.error('[gtTgGate]', e.message); }

      // ── Group toolkit commands (setname, link, badword, warnlimit, pin, ...) ──
      if (isCmd && GT_TG_CMDS.has(cmdWord)) {
        try { if (await gtTgCommand(ctx, { chatId, userId, args, cmdWord, text })) return; }
        catch (e) { console.error('[gtTgCommand]', e.message); }
      }

      // ── Anti-link check (Telegram) — runs on ALL messages, not just commands ──
      const gs_al = getGroupSettings(chatId);
      if (gs_al.antilink_on && !isSudo(userId) && hasLink(text)) {
        // Allow Telegram group admins to send links freely
        let senderIsAdmin = isSudo(userId);
        if (!senderIsAdmin) {
          try {
            const mem = await ctx.telegram.getChatMember(ctx.chat.id, ctx.from.id);
            senderIsAdmin = ['administrator','creator'].includes(mem.status);
          } catch(_){}
        }
        if (!senderIsAdmin) {
          try { await ctx.telegram.deleteMessage(ctx.chat.id, ctx.message.message_id); } catch(_){}
          const warnCount = addWarning(chatId, String(ctx.from.id), 'posted a link', userId);
          try {
            const _alLimitTg = gtWarnLimit(chatId);
            await ctx.telegram.sendMessage(ctx.chat.id,
              `⚠️ @${ctx.from.username||ctx.from.first_name} links are not allowed here. Only admins can send links. (Warning ${warnCount}/${_alLimitTg})`);
            if (warnCount >= _alLimitTg) {
              await gtTgKick(ctx, ctx.from.id);
              clearWarnings(chatId, String(ctx.from.id));
              await ctx.telegram.sendMessage(ctx.chat.id, `🚫 @${ctx.from.username||ctx.from.first_name} was kicked for repeated link spam.`);
            }
          } catch(_){}
          return;
        }
      }
    }

    // ── /blockall & /unblockall (owner only, run inside the group) ──
    if (isGroup && isCmd && (cmdWord === '.blockall' || cmdWord === '.unblockall')) {
      const _isMeTg = username === OWNER_TG || isOwner(userId);
      if (!_isMeTg) { await ctx.reply('❌ owner only.', {reply_to_message_id: ctx.message.message_id}); return; }
      const _un = cmdWord === '.unblockall';
      const _sub = (args[0] || '').toLowerCase();
      const _k = chatId + '|' + cmdWord;
      const _has = !!db.prepare('SELECT 1 FROM tg_blocked_groups WHERE group_id=?').get(chatId);
      if (_sub !== 'confirm' || !pendingTgBlockAll[_k] || Date.now() - pendingTgBlockAll[_k] > 60000) {
        pendingTgBlockAll[_k] = Date.now();
        let count = '';
        try { count = ` (${await ctx.telegram.getChatMembersCount(ctx.chat.id)} members)`; } catch (_) {}
        await ctx.reply(
          _un
            ? `⚠️ This will stop ignoring the members of "${ctx.chat.title}"${count}.\n\nSend /unblockall confirm within 60 seconds.`
            : `⚠️ This will make the bot ignore every member of "${ctx.chat.title}"${count} when they DM it — including silent/ghost members.\n\n` +
              `ℹ️ Telegram bots can't block people on your personal Telegram account, so this only covers DMs to this bot. ` +
              `To block them on your own account you'd have to do it in Telegram itself.\n\nSend /blockall confirm within 60 seconds.`,
          {reply_to_message_id: ctx.message.message_id});
        return;
      }
      delete pendingTgBlockAll[_k];
      if (_un) db.prepare('DELETE FROM tg_blocked_groups WHERE group_id=?').run(chatId);
      else db.prepare('INSERT OR REPLACE INTO tg_blocked_groups (group_id,title,since) VALUES (?,?,?)').run(chatId, ctx.chat.title || '', Date.now());
      _tgBlockCache.clear();
      await ctx.reply(_un ? '✅ Done — members of this group are no longer ignored in DMs.'
                          : '✅ Done — everyone in this group is now ignored when they DM the bot (you are exempt). Use /unblockall to undo.',
        {reply_to_message_id: ctx.message.message_id});
      return;
    }

    if (isGroup && isCmd) {
      const TG_ADMIN_CMDS = ['.kick','.ban','.promote','.demote','.mute','.unmute','.warn','.tagall','.groupinfo','.lock','.unlock'];
      if (TG_ADMIN_CMDS.includes(cmdWord)) {
        // Check if user is admin/sudo
        let isAdmin = isSudo(userId);
        if (!isAdmin) {
          try {
            const member = await ctx.telegram.getChatMember(ctx.chat.id, ctx.from.id);
            isAdmin = ['administrator','creator'].includes(member.status);
          } catch(_){}
        }

        // ── Commands that need NO target user ───────────────────────
        if (cmdWord === '.groupinfo') {
          try {
            const chat2 = await ctx.telegram.getChat(ctx.chat.id);
            const count = await ctx.telegram.getChatMembersCount(ctx.chat.id);
            const gs = getGroupSettings(chatId);
            const info = `ℹ️ GROUP INFO\n\n📛 ${chat2.title||'Unknown'}\n👥 Members: ${count}\n🔒 Locked: ${gs.locked?'Yes':'No'}\n🔗 Antilink: ${gs.antilink_on?'On':'Off'}\n👥 Anti-GM: ${gs.antigm_on?'On':'Off'}\n📛 Anti-Status: ${gs.antistatus_on?'On':'Off'}\n🎉 Welcome: ${gs.welcome_on?'On':'Off'}`;
            return humanReplyTG(ctx, info);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }

        if (cmdWord === '.tagall') {
          if (!isAdmin) return humanReplyTG(ctx, '❌ admins/sudo only.');
          try {
            const members = db.prepare('SELECT user_id, username, first_name FROM group_members WHERE group_id=?').all(chatId);
            let admins = [];
            try { admins = await ctx.telegram.getChatAdministrators(ctx.chat.id); } catch(_){}
            for (const a of admins) {
              if (!a.user.is_bot && !members.find(m => String(m.user_id) === String(a.user.id))) {
                members.push({ user_id: a.user.id, username: a.user.username || '', first_name: a.user.first_name || '' });
              }
            }
            // Get real total from Telegram API
            let totalCount = members.length;
            try { totalCount = await ctx.telegram.getChatMembersCount(ctx.chat.id); } catch(_){}
            if (!members.length) return humanReplyTG(ctx, `💗 no members tracked yet.\n\nℹ️ Telegram does not let bots fetch all ${totalCount} members directly.\nUse *.scanmembers* to make everyone register, then .tagall will reach them all.`);
            const tgArgs = text.split(/\s+/).slice(1);
            const caption = tgArgs.join(' ') || '📢 Attention everyone!';
            const trackedNote = members.length < totalCount
              ? `\n\n👥 tagging ${members.length} tracked members (${totalCount} total — use .scanmembers to register the rest)`
              : `\n\n👥 tagging all ${members.length} members`;
            await ctx.reply(caption + trackedNote);
            const BATCH = 8;
            const chunks = [];
            for (let i = 0; i < members.length; i += BATCH) chunks.push(members.slice(i, i + BATCH));
            for (const chunk of chunks) {
              const mentions = chunk.map(m => m.username ? `@${m.username}` : `[${m.first_name||'member'}](tg://user?id=${m.user_id})`).join(' ');
              await ctx.reply(mentions, { parse_mode: 'Markdown' }).catch(async () => {
                const plain = chunk.filter(m => m.username).map(m => `@${m.username}`).join(' ');
                if (plain) await ctx.reply(plain).catch(() => {});
              });
              await sleep(600);
            }
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
          return;
        }

        if (cmdWord === '.scanmembers') {
          if (!isAdmin) return humanReplyTG(ctx, '❌ admins/sudo only.');
          try {
            let totalCount = 0;
            try { totalCount = await ctx.telegram.getChatMembersCount(ctx.chat.id); } catch(_){}
            const tracked = db.prepare('SELECT COUNT(*) as c FROM group_members WHERE group_id=?').get(chatId)?.c || 0;
            // Send a poll — everyone who votes gets auto-tracked
            await ctx.telegram.sendPoll(ctx.chat.id,
              `📋 Member Scan — tap to register! (${tracked}/${totalCount} tracked)`,
              ['✅ I\'m here!', '👋 Present!', '💗 Noted.'],
              { is_anonymous: false, allows_multiple_answers: false }
            );
            return humanReplyTG(ctx, `📋 Scan poll sent!\n\nEveryone who votes will be registered for .tagall.\nCurrently tracking *${tracked}* of *${totalCount}* members.`, {parse_mode:'Markdown'});
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
          return;
        }

        if (cmdWord === '.lock') {
          if (!isAdmin) return humanReplyTG(ctx, '❌ admins/sudo only.');
          try {
            await ctx.telegram.setChatPermissions(ctx.chat.id, {can_send_messages:false,can_send_media_messages:false,can_send_polls:false,can_send_other_messages:false,can_add_web_page_previews:false,can_change_info:false,can_invite_users:false,can_pin_messages:false});
            setGroupSetting(chatId,'locked',1);
            return humanReplyTG(ctx, '🔒 Group locked. Only admins can send messages.');
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }

        if (cmdWord === '.unlock') {
          if (!isAdmin) return humanReplyTG(ctx, '❌ admins/sudo only.');
          try {
            await ctx.telegram.setChatPermissions(ctx.chat.id, {can_send_messages:true,can_send_media_messages:true,can_send_polls:true,can_send_other_messages:true,can_add_web_page_previews:true,can_change_info:false,can_invite_users:true,can_pin_messages:false});
            setGroupSetting(chatId,'locked',0);
            return humanReplyTG(ctx, '🔓 Group unlocked. Everyone can send messages.');
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }

        // ── Commands that DO need a target user ─────────────────────
        if (!isAdmin) return humanReplyTG(ctx, '❌ admins/sudo only.');

        const replyTarget = ctx.message.reply_to_message?.from;
        const mentionEntity = (ctx.message.entities||[]).find(e=>e.type==='mention'||e.type==='text_mention');
        let targetId = null, targetName = null;

        if (replyTarget) {
          targetId = replyTarget.id;
          targetName = replyTarget.first_name || String(targetId);
        } else if (mentionEntity) {
          if (mentionEntity.user) {
            targetId = mentionEntity.user.id;
            targetName = mentionEntity.user.first_name || String(targetId);
          } else {
            const uname = text.substr(mentionEntity.offset+1, mentionEntity.length-1);
            // Try to look up from our DB
            const dbMember = db.prepare('SELECT user_id, first_name FROM group_members WHERE group_id=? AND username=?').get(chatId, uname);
            if (dbMember) { targetId = dbMember.user_id; targetName = dbMember.first_name || uname; }
            else return humanReplyTG(ctx, `😒 @${uname} needs to send a message first so I can identify them, or reply directly to their message.`);
          }
        }

        if (!targetId) return humanReplyTG(ctx, '😒 Reply to the target user\'s message, or mention them (e.g. .kick @username).');

        if (cmdWord === '.kick') {
          try {
            await gtTgKick(ctx, targetId);
            db.prepare('DELETE FROM group_members WHERE group_id=? AND user_id=?').run(chatId, targetId);
            return humanReplyTG(ctx, `✅ ${targetName} has been removed from the group.`);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }
        if (cmdWord === '.ban') {
          try {
            await ctx.telegram.banChatMember(ctx.chat.id, targetId);
            db.prepare('DELETE FROM group_members WHERE group_id=? AND user_id=?').run(chatId, targetId);
            return humanReplyTG(ctx, `🚫 ${targetName} has been permanently banned.`);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }
        if (cmdWord === '.promote') {
          const _gs = getGroupSettings(chatId);
          if (_gs.antipromote_on && !isOwner(userId)) return humanReplyTG(ctx, '💗 anti-promote is on. only the owner can promote admins.');
          try {
            await ctx.telegram.promoteChatMember(ctx.chat.id, targetId, {can_manage_chat:true,can_delete_messages:true,can_restrict_members:true,can_promote_members:false,can_change_info:false,can_invite_users:true,can_pin_messages:true});
            return humanReplyTG(ctx, `⭐ ${targetName} has been promoted to admin.`);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }
        if (cmdWord === '.demote') {
          const _gs = getGroupSettings(chatId);
          if (_gs.antidemote_on && !isOwner(userId)) return humanReplyTG(ctx, '💗 anti-demote is on. only the owner can demote admins.');
          try {
            await ctx.telegram.promoteChatMember(ctx.chat.id, targetId, {can_manage_chat:false,can_delete_messages:false,can_restrict_members:false,can_promote_members:false,can_change_info:false,can_invite_users:false,can_pin_messages:false});
            return humanReplyTG(ctx, `⬇️ ${targetName} has been demoted.`);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }
        if (cmdWord === '.mute') {
          try {
            const _dArg = args.find(a => gtParseDuration(a));
            const _durMs = _dArg ? gtParseDuration(_dArg) : 86400000; // default 24h, e.g. /mute @user 2h
            const until = Math.floor((Date.now() + _durMs) / 1000);
            await ctx.telegram.restrictChatMember(ctx.chat.id, targetId, {permissions:{can_send_messages:false,can_send_media_messages:false,can_send_polls:false,can_send_other_messages:false},until_date:until});
            gtMuteAdd(chatId, String(targetId), Date.now() + _durMs, userId, targetName);
            return humanReplyTG(ctx, `🔇 ${targetName} muted for ${gtFmtDuration(_durMs)}.`);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }
        if (cmdWord === '.unmute') {
          try {
            await ctx.telegram.restrictChatMember(ctx.chat.id, targetId, {permissions:{can_send_messages:true,can_send_media_messages:true,can_send_polls:true,can_send_other_messages:true,can_add_web_page_previews:true,can_change_info:false,can_invite_users:true,can_pin_messages:false}});
            gtMuteRemove(chatId, String(targetId));
            return humanReplyTG(ctx, `🔊 ${targetName} has been unmuted.`);
          } catch(e) { return humanReplyTG(ctx, `❌ ${e.message}`); }
        }
        if (cmdWord === '.warn') {
          const reason = args.slice(mentionEntity?1:0).join(' ') || 'no reason given';
          const warnCount = addWarning(chatId, String(targetId), reason, userId);
          const _wlTg = gtWarnLimit(chatId);
          let reply = `⚠️ ${targetName} warned. (${warnCount}/${_wlTg})\nReason: ${reason}`;
          if (warnCount >= _wlTg) {
            try {
              await gtTgKick(ctx, targetId);
              clearWarnings(chatId, String(targetId));
              reply += `\n\n🚫 Auto-kicked after ${_wlTg} warnings.`;
            } catch(_){}
          }
          return humanReplyTG(ctx, reply);
        }
      }
    } else if (!isGroup && isCmd) {
      // Track DM users too (for future reference)
    }

    if(isCmd && cmdWord==='.play'){
      const tgArgs=text.split(/\s+/).slice(1);
      const query=tgArgs.join(' ').trim();
      if(!query){
        return ctx.reply('🎵 *PLAY MUSIC*\n\nUsage: */play <song name>*\n\nExample: /play Blinding Lights\nExample: /play Drake God\'s Plan\n\n_Searches YouTube and sends the audio directly._',{parse_mode:'Markdown',reply_to_message_id:ctx.message.message_id});
      }
      await ctx.reply(`🔍 searching for: *${query}*…`,{parse_mode:'Markdown',reply_to_message_id:ctx.message.message_id});
      const result=await searchAndDownloadMusic(query);
      if(result.error) return ctx.reply(`❌ ${result.error}`);
      try{
        await ctx.sendChatAction('upload_audio');
        await ctx.replyWithAudio(
          {source:result.buffer, filename:`${result.title.replace(/[^\w\s-]/g,'').trim().slice(0,50)}.mp3`},
          {
            title:     result.title,
            performer: result.artist,
            duration:  result.seconds||0,
            caption:   `🎵 *${result.title}*\n🎤 ${result.artist}\n⏱️ ${result.duration}\n\n💗 _enjoy it!_`,
            parse_mode:'Markdown',
          }
        );
      }catch(e){
        ctx.reply(`❌ failed to send audio: ${e.message}`);
      }
      return;
    }

    if(isCmd && /^[./]ping(@\w+)?$/i.test(String(_cmdText).trim())){
      const _t0 = Date.now();
      let _pm = null;
      try { _pm = await ctx.reply('🏓 Pinging...'); } catch (_) {}
      const _ms = Date.now() - _t0;
      const _out = `🏓 Pong!\n⚡ Speed: ${_ms} ms\n⏱️ Uptime: ${fmtUptime()}\n✅ Online`;
      try { if (_pm) await ctx.telegram.editMessageText(_pm.chat.id, _pm.message_id, undefined, _out); else await ctx.reply(_out); }
      catch (_) { try { await ctx.reply(_out); } catch (_) {} }
      return;
    }
    if(isCmd){
      { const _g = _cmdGate(userId); if (_g) { if (_g === 1) { try { await ctx.reply('⏳ slow down — too many commands at once. try again in 20 seconds.'); } catch (_) {} } return; } }
      const reply=await handleCommand(_cmdText,chatId,userId,name,rawUserId);
      if(typeof reply==='string' && reply.startsWith(VOICE_TAG)){
        const _vt = reply.slice(VOICE_TAG.length);
        const _ok = await sendVoiceTG(ctx, _vt);
        if(!_ok) await ctx.reply(`🎙️ my voice failed just now. in text:\n${_vt}`);
        return;
      }
      // Handle pic signal
      if(reply==='__SEND_PIC__'){
        try{
          await ctx.sendChatAction('upload_photo');
          await sleep(randomInt(1500,3000));
          await ctx.replyWithPhoto({source:BOT_PFP_PATH},{caption:getPicCaption()});
        }catch(e){ ctx.reply("...something went wrong sending the pic."); }
        return;
      }
      if(reply) return humanReplyTG(ctx,reply,{isGame:GAME_CMDS.has(cmdWord)});
    }

    // ── Natural-language pic request ──────────────────────────────
    if(!isCmd && isPicRequest(text)){
      const inGroup = isGroup;
      // In groups only respond if bot is mentioned
      const lower=text.toLowerCase();
      const mentioned=lower.includes('@'+BOT_USERNAME.toLowerCase())||GF_NAME_RE.test(lower);
      const isReply=ctx.message.reply_to_message?.from?.username===BOT_USERNAME;
      if(!inGroup || mentioned || isReply){
        if(!fs.existsSync(BOT_PFP_PATH)){
          return humanReplyTG(ctx,"...i don't have a picture set yet.");
        }
        try{
          await ctx.sendChatAction('upload_photo');
          await sleep(randomInt(1500,3500));
          return ctx.replyWithPhoto({source:BOT_PFP_PATH},{caption:getPicCaption()});
        }catch(e){ return humanReplyTG(ctx,"...couldn't send the pic right now."); }
      }
    }

    // ── Duty challenge intercept (all jobs) ─────────────────────────────────
    if (!isCmd) {
      const dc = pendingDutyChallenge[userId];
      if (dc) {
        const typed = text.trim();
        if (Date.now() > dc.expires) {
          delete pendingDutyChallenge[userId];
          return humanReplyTG(ctx,
            `${dc.failFlavor}\n\n❌ Code not entered in time. Duty failed.\n⏳ Cooldown still applies — try again later.`
          );
        }
        if (typed === dc.code) {
          delete pendingDutyChallenge[userId];
          addCash(userId, dc.reward); addXP(userId, 30);
          db.prepare('UPDATE occupations SET xp=xp+30 WHERE user_id=?').run(userId);
          const newRIdx = occRankIndex((getOcc(userId)?.xp || 0));
          const jobObj = JOBS[dc.job] || {};
          const promoLine = jobObj.ranks && newRIdx > dc.rIdx ? `\n⬆️ PROMOTED to ${jobObj.ranks[newRIdx]}!` : '';
          return humanReplyTG(ctx,
            `${dc.successFlavor}\n\n✅ Duty complete! +${fmt(dc.reward)}${dc.taxLine || ''}${promoLine}`
          );
        }
        // Wrong attempt — if it looks like they're trying (has dash, alphanum, or number-only), warn them
        if (typed.includes('-') || typed.includes(' ') || /^[A-Z0-9]{2,}$/i.test(typed)) {
          return humanReplyTG(ctx, `${dc.wrongFlavor}`);
        }
      }
    }
    // ── Math duel answer intercept ──
    if (!isCmd) {
      const mRes = checkMathAnswer(text, chatId, userId, name);
      if (mRes) return humanReplyTG(ctx, mRes, { isGame: true });
    }

    if(!isCmd&&activeGames[chatId]){
      const parts=text.trim().split(/\s+/);
      const gr=handleGames(parts[0].toLowerCase(),chatId,userId,name,parts.slice(1));
      if(gr) return humanReplyTG(ctx,gr,{isGame:true});
    }

    if(isGroup){
      const entities=ctx.message.entities||[];
      // Only respond when actually @mentioned or when replying directly to the bot
      const entMention=entities.some(e=>e.type==='mention'&&text.substr(e.offset,e.length).toLowerCase()==='@'+BOT_USERNAME.toLowerCase());
      const _rf=ctx.message.reply_to_message?.from;
      const isReply=!!_rf&&((ctx.botInfo?.id&&_rf.id===ctx.botInfo.id)||String(_rf.username||'').toLowerCase()===BOT_USERNAME.toLowerCase());
      // Also check for text @mention in case entity isn't set, or the bot's name said anywhere
      const textMention=text.toLowerCase().includes('@'+BOT_USERNAME.toLowerCase())||/\b(?:seana|chandra|shay|chanelle|seanie)\b/i.test(text);
      if(!entMention&&!isReply&&!textMention) return;
      // Anti-loop: if the message is a reply to the bot but has very short/emoji-only content, skip
      const clean=text.replace(new RegExp('@'+BOT_USERNAME,'gi'),'').trim();
      if(!clean) return;
      // Skip replying to very short reactions (emoji-only, 1-3 chars) that are replies to bot messages
      // to prevent infinite ping-pong loops
      const isEmojiOnly=/^[\p{Emoji}\s]{1,6}$/u.test(clean);
      if(isReply && !entMention && !textMention && (isEmojiOnly || clean.length <= 3)) return;
      return humanReplyTG(ctx,()=>chat('tg_grp_'+chatId,`[${name||username} says]: "${clean}"`, userId));
    }

    return humanReplyTG(ctx,()=>chat(userId,text));
  } catch(e){console.error('TG error:',e.message);}
});

bot_tg.launch().then(()=>console.log('💕 Telegram live!')).catch(e=>console.error('TG error:',e.message));
process.once('SIGINT', ()=>bot_tg.stop('SIGINT'));
process.once('SIGTERM',()=>bot_tg.stop('SIGTERM'));
process.once('SIGINT', ()=>lidMap.flush());
process.once('SIGTERM',()=>lidMap.flush());

// Load whatever LID↔phone pairs were learned in previous runs
lidMap.init('./lid-map.json');

// Keep server alive on any unhandled error
process.on('uncaughtException',e=>console.error('💥 uncaughtException:',e.message));
process.on('unhandledRejection',e=>console.error('💥 unhandledRejection:',e?.message||e));

// ── Periodic WA health check — auto-reconnects any dropped session ────────────
// This catches silent WebSocket deaths where connection.update never fires.
// Runs every 3 minutes. Owner session reconnects immediately; others are skipped
// if they've never connected (they need /pair).
setInterval(() => {
  const ownerPhone = MY_WA.replace(/\D/g,'');
  for (const [tgId, session] of sessions.entries()) {
    const ws = session.sock?.ws;
    const isDead = !ws || ws.readyState === 2 || ws.readyState === 3; // CLOSING or CLOSED
    if (!isDead) continue;
    if (session.dead || session._reconnecting || session._awaitingPair) continue; // already handled elsewhere
    const isOwnerSess = tgId === 'tg_' + OWNER_TG
      || tgId === OWNER_TG
      || (session.phone && session.phone.replace(/\D/g,'') === ownerPhone);
    // Only auto-heal sessions that were previously connected OR belong to owner
    if (!session.everConnected && !isOwnerSess) continue;
    console.log(`[healthcheck] session ${tgId} is dead (ws=${ws?.readyState}) — reconnecting…`);
    createSession(tgId, session.phone || null, null, null)
      .catch(e => console.error('[healthcheck reconnect]', e.message));
  }
}, 3 * 60 * 1000); // every 3 minutes


// ── Reminder delivery loop (survives restarts; reads pending rows from DB) ──
setInterval(checkReminders, 15000);

