if(!tok)lock('Open this page from the link in the group chat.');
else fetch('/smash/'+tok+'/me?device='+dev).then(function(r){return r.json()}).then(function(j){if(j.number)lock('You already sent your entry (#'+j.number+'). One per person.')}).catch(function(){});
function ready(){$('go').disabled=!(media&&$('ck').checked)}
$('ck').onchange=ready;
$('pi').onchange=function(){var f=this.files[0];if(!f)return;say('');var im=new Image();im.onload=function(){var s=Math.min(1,1280/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);c.getContext('2d').drawImage(im,0,0,c.width,c.height);
 var d=c.toDataURL('image/jpeg',.85);media={image:d};$('pv').innerHTML='<img src="'+d+'">';$('vi').value='';ready()};im.onerror=function(){say('Could not read that picture.','er')};im.src=URL.createObjectURL(f)};
