const _GAME_META = { smash: 'Smash or Pass', anon: 'Anonymous', truthdare: 'Truth or Dare', wyr: 'Would You Rather' };
function _sendGamesPage(req, res) {
  const slug = String(req.params.game || '').toLowerCase();
  const qs = req.url.includes('?') ? req.url.slice(req.url.indexOf('?')) : '';
  if (slug && !_GAME_META[slug]) return res.redirect('/games' + qs);
  if (slug === 'smash') { res.setHeader('Content-Type', 'text/html; charset=utf-8'); res.setHeader('Cache-Control', 'no-store'); return res.send(SMASH_PAGE); }
  let html;
  try { html = require('fs').readFileSync(require('path').join(__dirname, 'games.html'), 'utf8'); }
  catch (_) { return res.status(500).send('games.html is missing. Upload it next to index.js and restart.'); }
  const title = slug ? `${_GAME_META[slug]} - Game Hub` : 'Game Hub';
  html = html.replace('<title>Game Hub</title>', `<title>${title}</title><meta property="og:title" content="${title}"><meta property="og:description" content="Tap to play">`);
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.send(html);
}
_app.get('/games', _sendGamesPage);
_app.get('/games/:game', _sendGamesPage);
registerSmashRoutes(_app);
try {
  require('./web-pair').register(_app, {
    createSession, sessions, codes: _webPairCodes,
    getBase: () => process.env.PUBLIC_URL || _tunnelUrl,
  });
} catch (e) { console.error('[web-pair] not loaded:', e.message); }
_app.listen(_PORT, () => console.log(`🌐 Express server running on port ${_PORT}`));

// ── Secure https address: free Cloudflare quick tunnel (no ports or root needed) ──
// Starts automatically, downloads cloudflared once, and saves the https link as the bot's web address.
// Turn off with TUNNEL=false. Skipped if PUBLIC_URL is set.
let _tunnelUrl = '';
let _tunnelLog = '';
let _tunnelStatus = 'starting (wait 1-2 min after restart)';
(function startTunnel() {
  if (String(process.env.TUNNEL || 'true').toLowerCase() === 'false' || process.env.PUBLIC_URL) return;
  const fs = require('fs'), path = require('path'), https = require('https'), { spawn } = require('child_process');
  const bin = path.join(__dirname, 'cloudflared');
  const url = `https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-${process.arch === 'arm64' ? 'arm64' : 'amd64'}`;
  function dl(u, cb, n = 0) {
    https.get(u, { headers: { 'User-Agent': 'bot' } }, r => {
      if ([301, 302, 303, 307, 308].includes(r.statusCode) && r.headers.location && n < 6) { r.resume(); return dl(r.headers.location, cb, n + 1); }
      if (r.statusCode !== 200) { r.resume(); return cb(new Error('HTTP ' + r.statusCode)); }
      const f = fs.createWriteStream(bin + '.tmp');
      r.pipe(f);
      f.on('finish', () => f.close(() => { try { fs.renameSync(bin + '.tmp', bin); fs.chmodSync(bin, 0o755); cb(); } catch (e) { cb(e); } }));
      f.on('error', cb);
    }).on('error', cb);
  }
  function run() {
    const p = spawn(bin, ['tunnel', '--no-autoupdate', '--url', 'http://localhost:' + _PORT]);
    const on = d => { _tunnelLog = String(d).trim().split('\n').slice(-2).join(' | ').slice(0, 300); const m = /https:\/\/[a-z0-9-]+\.trycloudflare\.com/.exec(String(d)); if (m && m[0] !== _tunnelUrl) { _tunnelUrl = m[0]; _tunnelStatus = 'ok'; kvSet('public_url', m[0]); console.log('PAIR PAGE LINK:', m[0] + '/pair'); console.log('🔒 secure address:', m[0]); } };
    p.stdout.on('data', on); p.stderr.on('data', on);
    p.on('error', e => { _tunnelStatus = 'cannot run binary: ' + e.message; console.error('[tunnel]', e.message); });
    p.on('exit', c => { _tunnelStatus = 'stopped (code ' + c + '). last output: ' + _tunnelLog; console.log('[tunnel] stopped (' + c + '), retrying in 15s'); setTimeout(run, 15000); });
  }
  if (fs.existsSync(bin)) run();
  else dl(url, e => e ? (_tunnelStatus = 'download failed: ' + e.message + ' (upload cloudflared binary manually)', console.error('[tunnel] download failed:', e.message)) : run());
})();
